#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>

#define MAX_LINE_LENGTH 1024

void display_usage() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  -h, --help          Display detailed usage information.\n");
    printf("  -v, --verbose       Print detailed information about each line processed.\n");
    printf("  -o, --output-file   Specify an output file where the results should be saved.\n");
    printf("  --manpage           Display comprehensive documentation for the tool.\n");
}

void process_line(const char *line, FILE *output_file, int verbose) {
    // Process each line here
    if (verbose) {
        fprintf(stderr, "Processing line: %s", line);
    }
    // Example processing: write to output file
    if (output_file != NULL) {
        fputs(line, output_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    const char *input_file = NULL;
    const char *output_file = NULL;
    int verbose = 0;

    while ((opt = getopt(argc, argv, "hvo:")) != -1) {
        switch (opt) {
            case 'h':
                display_usage();
                return 0;
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", opt);
                display_usage();
                return 1;
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    } else {
        fprintf(stderr, "No input file specified.\n");
        display_usage();
        return 1;
    }

    FILE *input = fopen(input_file, "r");
    if (input == NULL) {
        perror("Failed to open input file");
        return 1;
    }

    FILE *output = output_file ? fopen(output_file, "w") : stdout;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), input)) {
        process_line(line, output, verbose);
    }

    fclose(input);
    if (output != stdout) {
        fclose(output);
    }

    return 0;
}
