#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_DEVICES 100
#define BUFFER_SIZE 256

typedef struct {
    char hostname[BUFFER_SIZE];
    char ip_address[BUFFER_SIZE];
    int port;
} DeviceConfig;

void resolve_hostname(DeviceConfig *device) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(device->hostname, NULL, &hints, &res) != 0) {
        strcpy(device->ip_address, "Invalid hostname");
        return;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), device->ip_address, INET_ADDRSTRLEN);
    freeaddrinfo(res);
}

void validate_config(DeviceConfig *device) {
    if (strcmp(device->ip_address, "Invalid hostname") == 0) {
        printf("Warning: Invalid hostname for %s\n", device->hostname);
    }
    // Add more validation rules as needed
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open config file");
        return EXIT_FAILURE;
    }

    DeviceConfig devices[MAX_DEVICES];
    int device_count = 0;

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        if (device_count >= MAX_DEVICES) {
            fprintf(stderr, "Too many devices in the configuration file\n");
            fclose(file);
            return EXIT_FAILURE;
        }

        sscanf(buffer, "%s %s %d", devices[device_count].hostname, devices[device_count].ip_address, &devices[device_count].port);
        resolve_hostname(&devices[device_count]);
        validate_config(&devices[device_count]);

        device_count++;
    }

    fclose(file);

    for (int i = 0; i < device_count; i++) {
        printf("Device %d: Hostname=%s, IP Address=%s, Port=%d\n", i + 1, devices[i].hostname, devices[i].ip_address, devices[i].port);
    }

    return EXIT_SUCCESS;
}
