#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 10000

int* read_integers_from_file(const char* file_path, int* size) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int* array = (int*)malloc(MAX_SIZE * sizeof(int));
    if (!array) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    *size = 0;
    while (*size < MAX_SIZE && fscanf(file, "%d", &array[*size]) == 1) {
        (*size)++;
    }

    fclose(file);
    return array;
}

int find_largest_integer(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Array is empty\n");
        return INT_MIN; // Assuming all integers are negative
    }
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int is_sorted(int* array, int size) {
    for (int i = 1; i < size; i++) {
        if (array[i - 1] > array[i]) {
            return i;
        }
    }
    return -1; // Array is sorted
}

void free_array(int* array) {
    free(array);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file_path>\n", argv[0]);
        return 1;
    }

    int size;
    int* array = read_integers_from_file(argv[1], &size);
    if (!array) {
        return 1;
    }

    int largest = find_largest_integer(array, size);
    printf("Largest integer: %d\n", largest);

    int sort_index = is_sorted(array, size);
    if (sort_index != -1) {
        printf("Array is not sorted at index: %d\n", sort_index);
    } else {
        printf("Array is sorted\n");
    }

    free_array(array);
    return 0;
}
