#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

// Function to generate a random IV
int generate_iv(unsigned char *iv, int iv_len) {
    return RAND_bytes(iv, iv_len);
}

// High-level API for encrypting data
int encrypt_data(const unsigned char *key, int key_len,
                 const unsigned char *iv, int iv_len,
                 const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// High-level API for decrypting data
int decrypt_data(const unsigned char *key, int key_len,
                 const unsigned char *iv, int iv_len,
                 const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Example usage
int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[sizeof(plaintext)];
    unsigned char decryptedtext[sizeof(plaintext)];

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !generate_iv(iv, sizeof(iv))) {
        return -1;
    }

    // Encrypt data
    int encrypted_len = encrypt_data(key, sizeof(key), iv, sizeof(iv),
                                     plaintext, strlen((char *)plaintext), ciphertext);
    if (encrypted_len < 0) {
        return -1;
    }

    // Decrypt data
    int decrypted_len = decrypt_data(key, sizeof(key), iv, sizeof(iv),
                                     ciphertext, encrypted_len, decryptedtext);
    if (decrypted_len < 0) {
        return -1;
    }

    decryptedtext[decrypted_len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    return 0;
}
```

