void* handle_request(void *arg) {
    int request_type = *(int *)arg;
    if (request_type == 0) {
        int count;
        HashFunction *hashes = get_available_hash_functions(&count);
        // Process hash functions
        free(hashes);
    } else if (request_type == 1) {
        int count;
        BlockCipher *ciphers = get_available_block_ciphers(&count);
        // Process block ciphers
        free(ciphers);
    }
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[2];
    int request_types[] = {0, 1};

    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, handle_request, &request_types[i]);
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
