typedef struct {
    char *profile_name;
    char *cipher_algorithm;
    char *key_path;
    char *iv_path;
} EncryptionProfile;

int load_encryption_profile(const char *file_path, EncryptionProfile **profiles, int *num_profiles) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return -1;
    }

    json_object *root = json_tokener_parse_file(file_path);
    fclose(file);

    if (!root || !json_is_array(root)) {
        fprintf(stderr, "Invalid JSON format in file: %s\n", file_path);
        json_object_put(root);
        return -1;
    }

    *num_profiles = json_array_length(root);
    *profiles = (EncryptionProfile *)malloc(*num_profiles * sizeof(EncryptionProfile));
    if (!*profiles) {
        fprintf(stderr, "Memory allocation failed for profiles.\n");
        json_object_put(root);
        return -1;
    }

    for (int i = 0; i < *num_profiles; i++) {
        json_object *profile_obj = json_array_get_idx(root, i);
        if (!json_is_object(profile_obj)) {
            fprintf(stderr, "Invalid profile format in file: %s\n", file_path);
            free(*profiles);
            json_object_put(root);
            return -1;
        }

        json_object *name_obj = json_object_object_get_ex(profile_obj, "profile_name", NULL);
        json_object *cipher_obj = json_object_object_get_ex(profile_obj, "cipher_algorithm", NULL);
        json_object *key_obj = json_object_object_get_ex(profile_obj, "key_path", NULL);
        json_object *iv_obj = json_object_object_get_ex(profile_obj, "iv_path", NULL);

        if (!name_obj || !cipher_obj || !key_obj || !iv_obj) {
            fprintf(stderr, "Missing required fields in profile %d.\n", i);
            free(*profiles);
            json_object_put(root);
            return -1;
        }

        (*profiles)[i].profile_name = strdup(json_object_get_string(name_obj));
        (*profiles)[i].cipher_algorithm = strdup(json_object_get_string(cipher_obj));
        (*profiles)[i].key_path = strdup(json_object_get_string(key_obj));
        (*profiles)[i].iv_path = strdup(json_object_get_string(iv_obj));
    }

    json_object_put(root);
    return 0;
}

