#include <random>
#include <thread>
#include <mutex>

namespace ServerUtils {
    class ServerRandom {
    public:
        struct Config {
            unsigned int initialSeed;
            size_t maxConcurrentThreads;
        };

        ServerRandom(const Config& config) : seed_(config.initialSeed), maxThreads_(config.maxConcurrentThreads) {
            rngs_.resize(maxThreads_);
            for (size_t i = 0; i < maxThreads_; ++i) {
                rngs_[i].seed(seed_ + i);
            }
        }

        void reseed(unsigned int newSeed) {
            std::lock_guard<std::mutex> lock(mutex_);
            seed_ = newSeed;
            for (auto& rng : rngs_) {
                rng.seed(seed_);
            }
        }

        template<typename T>
        T generateRandom() {
            static thread_local size_t threadIndex = [](){
                static std::atomic<size_t> index(0);
                return index.fetch_add(1) % maxThreads_;
            }();
            return rngs_[threadIndex]();
        }

    private:
        unsigned int seed_;
        size_t maxThreads_;
        std::vector<std::mt19937> rngs_;
        std::mutex mutex_;
    };
}
