using System;
using System.Data;
using System.Data.SqlClient;

public class PaginationHelper
{
    public static IDataReader GetPagedData(string sqlCommand, SqlConnection connection, int pageNumber, int pageSize, string schemaVersion)
    {
        if (string.IsNullOrEmpty(sqlCommand) || connection == null || pageNumber < 1 || pageSize < 1)
        {
            throw new ArgumentException("Invalid input parameters.");
        }

        using (SqlCommand command = new SqlCommand(sqlCommand, connection))
        {
            command.CommandType = CommandType.Text;

            if (schemaVersion == "New")
            {
                // Use ROW_NUMBER() for newer schema versions
                string rowNumberSql = $"SELECT * FROM (SELECT *, ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) AS RowNum FROM ({sqlCommand}) AS SubQuery) AS Result WHERE RowNum BETWEEN {(pageNumber - 1) * pageSize + 1} AND {pageNumber * pageSize}";
                command.CommandText = rowNumberSql;
            }
            else
            {
                // Use OFFSET FETCH for older schema versions
                string offsetFetchSql = $"{sqlCommand} ORDER BY (SELECT NULL) OFFSET {(pageNumber - 1) * pageSize} ROWS FETCH NEXT {pageSize} ROWS ONLY";
                command.CommandText = offsetFetchSql;
            }

            try
            {
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (SqlException ex)
            {
                // Handle database exceptions, log them, and rethrow if necessary
                throw new Exception("Database error occurred during pagination.", ex);
            }
        }
    }
}
```

