using System;
using System.IO;
using System.Xml.XPath;

public class DirectoryCreator
{
    public static string CreateDirectoryFromXml(string xmlContent, string elementName)
    {
        XPathDocument doc = new XPathDocument(new StringReader(xmlContent));
        XPathNavigator navigator = doc.CreateNavigator();

        // Find all elements with the specified name
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        if (nodes.Count > 1)
        {
            Console.WriteLine("Error: Multiple elements found with the same name.");
            return string.Empty;
        }

        if (!nodes.MoveNext())
        {
            Console.WriteLine("Warning: No element found with the specified name.");
            return string.Empty;
        }

        XPathNavigator node = nodes.Current;
        string directoryName = node.Value;

        // Check if environment variable is already set
        if (Environment.GetEnvironmentVariable(directoryName) != null)
        {
            Console.WriteLine("Error: Environment variable already set.");
            return string.Empty;
        }

        // Check if directory already exists
        string path = Path.Combine(Environment.CurrentDirectory, directoryName);
        if (Directory.Exists(path))
        {
            Console.WriteLine("Error: Directory already exists.");
            return string.Empty;
        }

        // Create the new directory
        Directory.CreateDirectory(path);

        // Set the environment variable
        Environment.SetEnvironmentVariable(directoryName, path);

        return path;
    }
}
