import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {

    private static final int MAX_RETRIES = 3;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public List<String> hashStringsAsync(List<String> inputStrings) {
        List<CompletableFuture<String>> futures = new ArrayList<>();
        for (String input : inputStrings) {
            CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> processInput(input), executorService);
            futures.add(future);
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(v -> futures.stream()
                        .map(CompletableFuture::join)
                        .collect(Collectors.toList()))
                .join();
    }

    private String processInput(String input) {
        if (input == null || input.isEmpty()) {
            System.out.println("Warning: Invalid input detected. Skipping.");
            return null;
        }
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error: MD5 algorithm not found.");
            return null;
        }
    }

    public static void main(String[] args) {
        MD5Hasher hasher = new MD5Hasher();
        List<String> inputStrings = Arrays.asList("example", "data", "", null, "test");
        List<String> hashResults = hasher.hashStringsAsync(inputStrings);
        System.out.println(hashResults);
    }
}
```

