["```javascript
const fs = require('fs').promises;
const path = require('path');

async function readFilesRecursively(directory, extensions, maxDepth = 10) {
    const results = [];

    async function traverse(dir, depth) {
        if (depth > maxDepth) return;

        try {
            const files = await fs.readdir(dir);
            for (const file of files) {
                const filePath = path.join(dir, file);
                const stats = await fs.stat(filePath);

                if (stats.isDirectory()) {
                    await traverse(filePath, depth + 1);
                } else if (extensions.includes(path.extname(file))) {
                    try {
                        const content = await fs.readFile(filePath, 'utf8');
                        results.push({ fileName: filePath, content });
                    } catch (error) {
                        console.error(`Error reading file ${filePath}:`, error);
                    }
                }
            }
        } catch (error) {
            console.error(`Error traversing directory ${dir}:`, error);
        }
    }

    await traverse(directory, 0);
    return results;
}

// Example usage:
const directoryPath = '/path/to/directory';
const fileExtensions = ['.txt', '.json'];

readFilesRecursively(directoryPath, fileExtensions)
    .then(files => {
        console.log('Processed files:', files);
    })
    .catch(error => {
        console.error('Error processing files:', error);
    });
```

This code defines an asynchronous function `readFilesRecursively` that reads multiple files from a specified directory and its subdirectories, filtering by file extensions. It uses the Node.js `fs.promises` module for asynchronous file operations and handles errors gracefully. The function limits recursion depth to prevent stack overflow and processes files in a streaming manner to minimize memory usage."]

