function renderFooterScripts(scriptObjects) {
    const maxScriptLength = 500;
    const maxRenderRate = 10; // scripts per second
    let renderedScripts = [];
    let scriptCount = 0;

    function isValidScript(script) {
        try {
            new Function(script);
            return true;
        } catch (e) {
            console.error('Invalid JavaScript:', e.message);
            return false;
        }
    }

    function truncateScript(script, maxLength) {
        if (script.length > maxLength) {
            console.warn(`Truncated script to ${maxLength} characters.`);
            return script.slice(0, maxLength);
        }
        return script;
    }

    function renderScript(scriptObject) {
        const { key, script, origin, version } = scriptObject;
        if (!isValidScript(script)) return;

        const truncatedScript = truncateScript(script, maxScriptLength);
        const scriptTag = `<script id="${key}" data-origin="${origin || 'unknown'}" data-version="${version || '1.0'}">${truncatedScript}</script>`;
        renderedScripts.push(scriptTag);
        scriptCount++;
    }

    function throttleRender() {
        if (scriptCount >= maxRenderRate) return;
        const nextScript = scriptObjects.shift();
        if (nextScript) renderScript(nextScript);
        setTimeout(throttleRender, 100); // 10 scripts per second
    }

    scriptObjects.forEach(renderScript);
    throttleRender();

    return renderedScripts.join('\n');
}
