import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StreamingDataProcessor {
    private ExecutorService dataCollectorExecutor;
    private ExecutorService serviceManagerExecutor;
    private MessageBroker messageBroker;

    public StreamingDataProcessor(int numCollectors, int numManagers) {
        this.dataCollectorExecutor = Executors.newFixedThreadPool(numCollectors);
        this.serviceManagerExecutor = Executors.newFixedThreadPool(numManagers);
        this.messageBroker = new MessageBroker();
    }

    public void startProcessing() {
        for (int i = 0; i < dataCollectorExecutor.getMaximumPoolSize(); i++) {
            dataCollectorExecutor.submit(new DataCollector(messageBroker));
        }
        serviceManagerExecutor.submit(new ServiceManager(messageBroker));
    }

    public void pauseProcessing() {
        dataCollectorExecutor.shutdown();
        serviceManagerExecutor.shutdown();
    }

    public void resumeProcessing() {
        startProcessing();
    }

    public void stopProcessing() {
        pauseProcessing();
        try {
            if (!dataCollectorExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
                dataCollectorExecutor.shutdownNow();
            }
            if (!serviceManagerExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
                serviceManagerExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            dataCollectorExecutor.shutdownNow();
            serviceManagerExecutor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        StreamingDataProcessor processor = new StreamingDataProcessor(5, 3);
        processor.startProcessing();

        // Simulate application running for some time
        try {
            TimeUnit.MINUTES.sleep(10);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        processor.pauseProcessing();
        System.out.println("Processing paused");

        // Resume processing after a while
        try {
            TimeUnit.SECONDS.sleep(5);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        processor.resumeProcessing();
        System.out.println("Processing resumed");

        // Stop processing gracefully
        processor.stopProcessing();
    }
}

