function loadAndExecuteScripts(scripts, onComplete) {
    let executedCount = 0;
    const totalScripts = scripts.length;

    function executeScript(index) {
        if (index >= totalScripts) {
            onComplete();
            return;
        }

        const script = document.createElement('script');
        script.src = scripts[index];
        script.onload = () => {
            executedCount++;
            console.log(`Script ${scripts[index]} loaded and executed.`);
            executeScript(index + 1);
        };
        script.onerror = (error) => {
            console.error(`Failed to load or execute script ${scripts[index]}.`, error);
            retryScript(index);
        };

        document.head.appendChild(script);
    }

    function retryScript(index, retries = 3) {
        if (retries === 0) {
            console.error(`Max retries reached for script ${scripts[index]}.`);
            executeScript(index + 1);
            return;
        }

        setTimeout(() => {
            console.log(`Retrying script ${scripts[index]}...`);
            document.head.removeChild(document.querySelector(`script[src="${scripts[index]}"]`));
            executeScript(index);
        }, 2000); // Retry after 2 seconds
    }

    executeScript(0);
}

function modifyFileName(fileName) {
    const uniqueChars = new Set(fileName.replace(/[^a-zA-Z0-9]/g, ''));
    const numDigits = uniqueChars.size;
    const suffix = sprintf("%0*d", numDigits, uniqueChars.size);
    const fileType = fileName.split('.').pop();
    return `${fileName.slice(0, -fileType.length)}_${suffix}.${fileType}`;
}

// Example usage:
const scripts = [
    'path/to/script1.js',
    'path/to/script2.js',
    // Add more script paths as needed
];

loadAndExecuteScripts(scripts, () => {
    console.log('All scripts executed.');
    const lastScriptName = scripts[scripts.length - 1];
    const modifiedFileName = modifyFileName(lastScriptName);
    console.log(`Modified file name: ${modifiedFileName}`);
});
