// Caching Mechanism with Eviction Policies
class ThemeCache {
    private Map<String, Bitmap> cache;
    private BitmapRecyclingPolicy policy;

    public ThemeCache(BitmapRecyclingPolicy policy) {
        this.cache = new HashMap<>();
        this.policy = policy;
    }

    public void put(String key, Bitmap bitmap) {
        if (cache.size() >= getMaxSize()) {
            evict(policy);
        }
        cache.put(key, bitmap);
    }

