use reqwest::{Client, RequestBuilder, Error};
use std::time::Duration;
use log::{info, error};

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: Client::new(),
        }
    }

    pub async fn request<B>(&self, method: reqwest::Method, url: &str, body: B) -> Result<reqwest::Response, Error>
    where
        B: serde::Serialize + Send,
    {
        let builder = self.client.request(method, url);
        let response = builder.json(&body).send().await?;
        Ok(response)
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    env_logger::init();
    let client = HttpClient::new();

    let url = "https://api.example.com/data";
    let body = serde_json::json!({
        "key": "value"
    });

    match client.request(reqwest::Method::POST, url, body).await {
        Ok(response) => {
            info!("Response status: {}", response.status());
            let data = response.json::<serde_json::Value>().await?;
            info!("Response data: {:?}", data);
        }
        Err(e) => error!("Request failed: {}", e),
    }

    Ok(())
}
