use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use sysinfo::{System, SystemExt, ProcessExt};
use log::{info, error, LevelFilter, SetLoggerError};
use lazy_static::lazy_static;

#[derive(Debug)]
enum Error {
    CompilationFailed,
    MemoryMeasurementFailed,
    LoggingFailed,
}

fn compile_rust_project(config: &Config) -> Result<(), Error> {
    let start_time = Instant::now();
    let mut child = Command::new("cargo")
        .arg("build")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|_| Error::CompilationFailed)?;

    let output = child.wait_with_output().map_err(|_| Error::CompilationFailed)?;
    if !output.status.success() {
        return Err(Error::CompilationFailed);
    }

    let elapsed_time = start_time.elapsed();
    info!("Compilation time: {:?}", elapsed_time);

    let memory_usage = get_memory_usage();
    match memory_usage {
        Some(memory) => info!("Memory usage: {} bytes", memory),
        None => error!("Failed to measure memory usage"),
    }

    log_to_central_server(&output.stdout, config.logging_level, config.output_format)
        .map_err(|_| Error::LoggingFailed)?;

    Ok(())
}

fn get_memory_usage() -> Option<usize> {
    let mut sys = System::new_all();
    sys.refresh_processes();

    for (pid, process) in sys.processes() {
        if process.name().contains("cargo") {
            return Some(process.memory());
        }
    }

    None
}

fn log_to_central_server(log_data: &[u8], level: LevelFilter, format: &str) -> Result<(), Error> {
    // Implement logging to central server logic here
    // Use the provided level and format for logging
    Ok(())
}

struct Config {
    logging_level: LevelFilter,
    output_format: String,
}

fn main() {
    let config = Config {
        logging_level: LevelFilter::Info,
        output_format: "json".to_string(),
    };

    if let Err(err) = compile_rust_project(&config) {
        error!("Error during compilation: {:?}", err);
    }
}
