    Metadata meta = { "Unknown", "Unknown" };
    return meta;
}

void init_window(SlidingWindow *window) {
    window->head = 0;
    window->tail = 0;
    pthread_mutex_init(&window->lock, NULL);
}

int is_full(SlidingWindow *window) {
    return (window->tail + 1) % MAX_PACKETS == window->head;
}

void enqueue_packet(SlidingWindow *window, Packet packet) {
    pthread_mutex_lock(&window->lock);
    if (is_full(window)) {
        window->head = (window->head + 1) % MAX_PACKETS;
    }
    window->packets[window->tail] = packet;
    window->tail = (window->tail + 1) % MAX_PACKETS;
    pthread_mutex_unlock(&window->lock);
}

Packet dequeue_packet(SlidingWindow *window) {
    pthread_mutex_lock(&window->lock);
    Packet packet = window->packets[window->head];
    window->head = (window->head + 1) % MAX_PACKETS;
    pthread_mutex_unlock(&window->lock);
    return packet;
}

int filter_packets(SlidingWindow *window, int max_size, uint32_t min_checksum) {
    Packet valid_packets[MAX_PACKETS];
    int count = 0;

    for (int i = window->head; i != window->tail; i = (i + 1) % MAX_PACKETS) {
        Packet packet = window->packets[i];
        if (packet.size <= max_size && packet.checksum >= min_checksum) {
            valid_packets[count++] = packet;
        }
    }

    for (int i = 0; i < count; i++) {
        Packet packet = valid_packets[i];
        Metadata meta = get_metadata(packet.timestamp);
        printf("Timestamp: %llu, Size: %zu, Checksum: %u, Location: %s, Protocol: %s\n",
               packet.timestamp, packet.size, packet.checksum, meta.location, meta.protocol);
    }

    return count;
}

void *process_packets(void *arg) {
    SlidingWindow *window = (SlidingWindow *)arg;

    // Simulate receiving packets
    for (int i = 0; i < 10000; i++) {
        Packet packet = { time(NULL), rand() % 1500, rand() % UINT32_MAX };
        enqueue_packet(window, packet);
    }

    filter_packets(window, 1460, 1000);

    return NULL;
}

int main() {
    SlidingWindow window;
    init_window(&window);

    pthread_t thread;
    pthread_create(&thread, NULL, process_packets, &window);
    pthread_join(thread, NULL);

    return 0;
}
