class Character {
public:
    Character(int maxHealth) : health(maxHealth), lastAttackTime(0), cooldown(5) {}

    std::string selectAttack() {
        std::lock_guard<std::mutex> lock(mutex);
        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() < cooldown) {
            return "Cooldown";
        }

        int attackIndex;
        do {
            attackIndex = distribution(generator);
        } while (attackHistory.size() > 0 && attackHistory.back() == attackIndex);

        lastAttackTime = now;
        attackHistory.push_back(attackIndex);
        if (attackHistory.size() > 1) {
            attackHistory.erase(attackHistory.begin());
        }

        cooldown = std::max(5, std::min(15, static_cast<int>(health * 0.2)));
        return attacks[attackIndex];
    }

private:
    int health;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime;
    int cooldown;
    std::vector<std::string> attacks = {"Fireball", "Ice Lance", "Thunderbolt"};
    std::uniform_int_distribution<> distribution(0, attacks.size() - 1);
    std::mutex mutex;
    std::vector<int> attackHistory;
};

int main() {
    Character character(100);
    for (int i = 0; i < 20; ++i) {
        std::cout << "Attack: " << character.selectAttack() << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
    return 0;
}
