public class DynamicValueGenerator
{
    private Random _random = new Random();
    private object _lock = new object();
    private (int Min, int Max) _integerRange = (0, 100);
    private (float Min, float Max) _floatRange = (0.0f, 1.0f);
    private List<string> _log = new List<string>();

    public void SetIntegerRange(int min, int max)
    {
        lock (_lock)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
            _integerRange = (min, max);
            Log($"Integer range set to: {_integerRange}");
        }
    }

    public void SetFloatRange(float min, float max)
    {
        lock (_lock)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
            _floatRange = (min, max);
            Log($"Float range set to: {_floatRange}");
        }
    }

    public int GetRandomInteger()
    {
        lock (_lock)
        {
            if (_integerRange.Min > _integerRange.Max)
                return 0; // Default value
            return _random.Next(_integerRange.Min, _integerRange.Max + 1);
        }
    }

    public float GetRandomFloat()
    {
        lock (_lock)
        {
            if (_floatRange.Min > _floatRange.Max)
                return 0.0f; // Default value
            return (float)_random.NextDouble() * (_floatRange.Max - _floatRange.Min) + _floatRange.Min;
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Integer Range: {_integerRange}, Float Range: {_floatRange}";
        }
    }

    private void Log(string message)
    {
        lock (_lock)
        {
            _log.Add($"{DateTime.Now}: {message}");
        }
    }

    public List<string> GetLog()
    {
        lock (_lock)
        {
            return new List<string>(_log);
        }
    }
}
