class DataProcessingPipeline {
  constructor(initialValue) {
    this.initialValue = initialValue;
    this.pipelineStages = [];
  }

  addStage(predicate, reductionCallback) {
    this.pipelineStages.push({ predicate, reductionCallback });
  }

  async process(data, timeout = Infinity) {
    let result = this.initialValue;
    const startTime = Date.now();

    for (const stage of this.pipelineStages) {
      if (Date.now() - startTime > timeout) {
        throw new Error('Pipeline processing exceeded the specified timeout');
      }

      for (const item of data) {
        if (!stage.predicate(item)) continue;

        try {
          result = await stage.reductionCallback(result, item);
        } catch (error) {
          console.error(`Error processing item: ${error.message}`);
        }
      }
    }

    return result;
  }
}

// Example usage:
const pipeline = new DataProcessingPipeline(0);

pipeline.addStage(
  (item) => typeof item === 'number',
  async (acc, num) => acc + num
);

pipeline.addStage(
  (item) => typeof item === 'string' && !isNaN(item),
  async (acc, str) => acc + parseInt(str)
);

try {
  const result = await pipeline.process([1, '2', 3, '4', 'five'], 500);
  console.log('Pipeline result:', result); // Output: Pipeline result: 10
} catch (error) {
  console.error('Error in pipeline processing:', error.message);
}
