#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ConfigNode {
    char *key;
    char *value;
    struct ConfigNode **children;
    int num_children;
    pthread_mutex_t lock;
} ConfigNode;

ConfigNode* create_config_node(const char *key, const char *value) {
    ConfigNode *node = (ConfigNode*)malloc(sizeof(ConfigNode));
    node->key = strdup(key);
    node->value = strdup(value);
    node->children = NULL;
    node->num_children = 0;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void destroy_config_node(ConfigNode *node) {
    if (node == NULL) return;
    for (int i = 0; i < node->num_children; i++) {
        destroy_config_node(node->children[i]);
    }
    free(node->key);
    free(node->value);
    free(node->children);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

ConfigNode* find_or_create_child(ConfigNode *parent, const char *key) {
    for (int i = 0; i < parent->num_children; i++) {
        if (strcmp(parent->children[i]->key, key) == 0) {
            return parent->children[i];
        }
    }
    ConfigNode *child = create_config_node(key, NULL);
    parent->children = realloc(parent->children, (parent->num_children + 1) * sizeof(ConfigNode*));
    parent->children[parent->num_children++] = child;
    return child;
}

void set_config_value(ConfigNode *node, const char *key, const char *value) {
    pthread_mutex_lock(&node->lock);
    ConfigNode *target_node = find_or_create_child(node, key);
    free(target_node->value);
    target_node->value = strdup(value);
    pthread_mutex_unlock(&node->lock);
}

const char* get_config_value(ConfigNode *node, const char *key) {
    pthread_mutex_lock(&node->lock);
    ConfigNode *target_node = find_or_create_child(node, key);
    const char *value = target_node->value;
    pthread_mutex_unlock(&node->lock);
    return value;
}

void load_module_config(ConfigNode *root, const char *module_name) {
    // Simulate loading module configuration
    set_config_value(root, module_name, "loaded");
}

void unload_module_config(ConfigNode *root, const char *module_name) {
    // Simulate unloading module configuration
    set_config_value(root, module_name, "unloaded");
}

int main() {
    ConfigNode *config_root = create_config_node("root", NULL);

    load_module_config(config_root, "module1");
    printf("Module1 loaded: %s\n", get_config_value(config_root, "module1"));

    unload_module_config(config_root, "module1");
    printf("Module1 unloaded: %s\n", get_config_value(config_root, "module1"));

    destroy_config_node(config_root);
    return 0;
}
