#include <regex.h>
#include <string.h>

char* trimAndAppendSlash(const char* input, size_t limit) {
    regex_t pattern;
    int ret;

    // Compile the regular expression pattern
    if (regcomp(&pattern, "^\\w+$", REG_EXTENDED) != 0) {
        return NULL; // Pattern compilation failed
    }

    // Match the input string against the pattern
    ret = regexec(&pattern, input, 0, NULL, 0);
    if (ret != 0) {
        regfree(&pattern);
        return NULL; // Input does not match the pattern
    }

    // Check if the length of the input is within the limit
    if (strlen(input) >= limit) {
        regfree(&pattern);
        return NULL; // String exceeds size limit
    }

    // Append a forward slash to the string
    char* result = malloc(strlen(input) + 2); // +1 for '/', +1 for null terminator
    if (result == NULL) {
        regfree(&pattern);
        return NULL; // Memory allocation failed
    }
    strcpy(result, input);
    strcat(result, "/");

    regfree(&pattern);
    return result;
}
