using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class ImageInfo
{
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public int ExtraSamples { get; set; }
}

public class ProcessImageAndTextResult
{
    public ImageInfo ImageInfo { get; set; }
    public string TextHash { get; set; }
    public bool IsChecksumValid { get; set; }
}

public class ImageProcessor
{
    public static ProcessImageAndTextResult ProcessImageAndText(string imagePath, string inputText, bool performDetailedAnalysis)
    {
        try
        {
            using (var imageStream = new FileStream(imagePath, FileMode.Open, FileAccess.Read))
            {
                var tiffParser = new TiffParser(imageStream);
                var imageInfo = tiffParser.ParseImageMetadata();
                if (!IsSupportedBitsPerSample(imageInfo.BitsPerSample))
                {
                    return new ProcessImageAndTextResult
                    {
                        ImageInfo = null,
                        TextHash = null,
                        IsChecksumValid = false,
                        ErrorMessage = "Unsupported bits per sample"
                    };
                }

                var textHash = GenerateSha256Hash(inputText);

                if (performDetailedAnalysis)
                {
                    string checksum = GetChecksumFromExternalSource(imagePath);
                    bool isChecksumValid = ValidateChecksum(checksum, imageStream);
                    return new ProcessImageAndTextResult
                    {
                        ImageInfo = imageInfo,
                        TextHash = textHash,
                        IsChecksumValid = isChecksumValid
                    };
                }

                return new ProcessImageAndTextResult
                {
                    ImageInfo = imageInfo,
                    TextHash = textHash,
                    IsChecksumValid = true
                };
            }
        }
        catch (Exception ex)
        {
            return new ProcessImageAndTextResult
            {
                ImageInfo = null,
                TextHash = null,
                IsChecksumValid = false,
                ErrorMessage = ex.Message
            };
        }
    }

    private static bool IsSupportedBitsPerSample(int bitsPerSample)
    {
        return bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16;
    }

    private static string GenerateSha256Hash(string inputText)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(inputText));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }

    private static string GetChecksumFromExternalSource(string imagePath)
    {
        // Simulate fetching checksum from an external source
        return "expected_checksum";
    }

    private static bool ValidateChecksum(string expectedChecksum, FileStream imageStream)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] hashBytes = md5.ComputeHash(imageStream);
            string actualChecksum = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
            return actualChecksum == expectedChecksum;
        }
    }
}

