#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

#define MAX_FILENAME_LENGTH 256

char* generate_modified_filename(const char* filename, const char* directory_path, int max_length) {
    struct stat file_stat;
    if (stat(filename, &file_stat) != 0) {
        perror("Error: File does not exist");
        return NULL;
    }

    char* base_name = strdup(filename);
    char* extension = strrchr(base_name, '.');
    if (extension == NULL) {
        extension = base_name + strlen(base_name);
    }
    *extension = '\0';

    unsigned long hash_value = 5381;
    for (int i = 0; i < strlen(base_name); ++i) {
        hash_value = ((hash_value << 5) + hash_value) + base_name[i];
    }

    char* new_filename = malloc(MAX_FILENAME_LENGTH);
    if (new_filename == NULL) {
        perror("Error: Memory allocation failed");
        free(base_name);
        return NULL;
    }

    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s_%lu%s", base_name, hash_value % max_length, extension);

    free(base_name);
    return new_filename;
}

int main() {
    const char* filename = "example.txt";
    const char* directory_path = "/path/to/directory";
    int max_length = 10;

    char* modified_filename = generate_modified_filename(filename, directory_path, max_length);
    if (modified_filename != NULL) {
        printf("Modified Filename: %s\n", modified_filename);
        free(modified_filename);
    }

    return 0;
}
