// Define custom symmetric encryption mode structure
typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    int current_cipher;
} CustomSymmetricMode;

// Initialize custom symmetric encryption mode
void init_custom_symmetric_mode(CustomSymmetricMode *mode) {
    mode->aes_ctx = EVP_CIPHER_CTX_new();
    mode->camellia_ctx = EVP_CIPHER_CTX_new();
    mode->current_cipher = 0; // Start with AES
}

// Switch between AES and Camellia based on performance metrics
void switch_cipher(CustomSymmetricMode *mode, int new_cipher) {
    if (new_cipher != mode->current_cipher) {
        EVP_CIPHER_CTX_free(mode->aes_ctx);
        EVP_CIPHER_CTX_free(mode->camellia_ctx);
        mode->aes_ctx = EVP_CIPHER_CTX_new();
        mode->camellia_ctx = EVP_CIPHER_CTX_new();
        mode->current_cipher = new_cipher;
    }
}

// Encrypt data using custom symmetric encryption mode
int encrypt_data(CustomSymmetricMode *mode, unsigned char *in, int in_len, unsigned char *out) {
    if (mode->current_cipher == 0) {
        return EVP_EncryptUpdate(mode->aes_ctx, out, &out_len, in, in_len);
    } else {
        return EVP_EncryptUpdate(mode->camellia_ctx, out, &out_len, in, in_len);
    }
}

// Decrypt data using custom symmetric encryption mode
int decrypt_data(CustomSymmetricMode *mode, unsigned char *in, int in_len, unsigned char *out) {
    if (mode->current_cipher == 0) {
        return EVP_DecryptUpdate(mode->aes_ctx, out, &out_len, in, in_len);
    } else {
        return EVP_DecryptUpdate(mode->camellia_ctx, out, &out_len, in, in_len);
    }
}

// Initialize MD5 digest
void init_md5_digest(unsigned char *digest) {
    MD5_Init((MD5_CTX *)digest);
}

// Update MD5 digest with data
void update_md5_digest(unsigned char *digest, unsigned char *data, int len) {
    MD5_Update((MD5_CTX *)digest, data, len);
}

// Finalize MD5 digest
void finalize_md5_digest(unsigned char *digest, unsigned char *result) {
    MD5_Final(result, (MD5_CTX *)digest);
}

// Initialize SHA digest
void init_sha_digest(unsigned char *digest) {
    SHA1_Init((SHA_CTX *)digest);
}

// Update SHA digest with data
void update_sha_digest(unsigned char *digest, unsigned char *data, int len) {
    SHA1_Update((SHA_CTX *)digest, data, len);
}

// Finalize SHA digest
void finalize_sha_digest(unsigned char *digest, unsigned char *result) {
    SHA1_Final(result, (SHA_CTX *)digest);
}

// Generate RSA key pair with SHA1 signature
RSA *generate_rsa_key_pair(int bits) {
    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);
    RSA_generate_key_ex(rsa, bits, e, NULL);
    BN_free(e);
    return rsa;
}

// Sign data using RSA with SHA1
int sign_data(RSA *key, unsigned char *data, int len, unsigned char *signature) {
    return RSA_sign(NID_sha1, data, len, signature, &signature_len, key);
}

// Verify signature using RSA with SHA1
int verify_signature(RSA *key, unsigned char *data, int len, unsigned char *signature, int siglen) {
    return RSA_verify(NID_sha1, data, len, signature, siglen, key);
}

// Thread-safe logging function
void log_message(const char *message) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&mutex);
}
