#include <string.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[16];
    unsigned char key[32];
} AESCipherContext;

AESCipherContext* init_aes_cipher(const char *password, int iterations) {
    AESCipherContext *context = (AESCipherContext*)malloc(sizeof(AESCipherContext));
    if (!context) return NULL;

    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) {
        free(context);
        return NULL;
    }

    unsigned char derived_key[32];
    size_t derived_key_len = sizeof(derived_key);

    if (PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), derived_key_len, derived_key) != 1) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
        return NULL;
    }

    memcpy(context->key, derived_key, sizeof(derived_key));
    memset(derived_key, 0, sizeof(derived_key));

    if (RAND_bytes(context->iv, sizeof(context->iv)) != 1) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
        return NULL;
    }

    if (EVP_EncryptInit_ex(context->ctx, EVP_aes_256_cbc(), NULL, context->key, context->iv) != 1) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
        return NULL;
    }

    return context;
}

