#include <iostream>
#include <fstream>
#include <string>
#include <stdexcept>
#include <thread>
#include <mutex>

class ImageConversionException : public std::runtime_error {
public:
    explicit ImageConversionException(const std::string& message) : std::runtime_error(message) {}
};

std::mutex conversionMutex;

void convertImageToPDF(const std::string& imagePath, const std::string& pdfPath) {
    std::lock_guard<std::mutex> lock(conversionMutex);

    if (!std::filesystem::exists(imagePath)) {
        throw ImageConversionException("Input image file does not exist.");
    }

    if (std::filesystem::is_directory(pdfPath)) {
        throw ImageConversionException("Output path is a directory.");
    }

    std::string command = "convert " + imagePath + " " + pdfPath;
    int result = system(command.c_str());

    if (result != 0) {
        throw ImageConversionException("Failed to convert image to PDF.");
    }
}

std::vector<unsigned char> serializePDF(const std::string& pdfPath) {
    std::ifstream file(pdfPath, std::ios::binary);
    if (!file.is_open()) {
        throw ImageConversionException("Failed to open PDF file for reading.");
    }

    file.seekg(0, std::ios::end);
    size_t fileSize = file.tellg();
    file.seekg(0, std::ios::beg);

    std::vector<unsigned char> pdfData(fileSize);
    if (!file.read(reinterpret_cast<char*>(pdfData.data()), fileSize)) {
        throw ImageConversionException("Failed to read PDF file.");
    }

    return pdfData;
}

std::vector<unsigned char> convertImageToPDF(const std::string& imagePath, const std::string& outputPdfPath) {
    try {
        convertImageToPDF(imagePath, outputPdfPath);
        return serializePDF(outputPdfPath);
    } catch (const ImageConversionException& e) {
        throw;
    }
}
