#include <signal.h>
#include <time.h>

#define MAX_COMMANDS 100
#define TIMEOUT 30

void handle_sigchld(int signum) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

int execute_commands(char *commands[], int num_commands) {
    pid_t pids[MAX_COMMANDS];
    struct timespec start_time, end_time;
    int status;

    signal(SIGCHLD, handle_sigchld);

    for (int i = 0; i < num_commands; i++) {
        if ((pids[i] = fork()) == -1) {
            perror("fork");
            return -1;
        } else if (pids[i] == 0) {
            execl("/bin/sh", "sh", "-c", commands[i], NULL);
            perror("execl");
            exit(EXIT_FAILURE);
        }
    }

    clock_gettime(CLOCK_REALTIME, &start_time);

    for (int i = 0; i < num_commands; i++) {
        if (waitpid(pids[i], &status, WNOHANG) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &end_time) == -1) {
                perror("clock_gettime");
                return -1;
            }
            double elapsed = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
            if (elapsed > TIMEOUT) {
                kill(pids[i], SIGKILL);
                waitpid(pids[i], &status, 0);
            }
        } else if (WIFEXITED(status)) {
            printf("Command %d exited with status %d\n", i, WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Command %d terminated by signal %d\n", i, WTERMSIG(status));
        }
    }

    return 0;
}

int main() {
    char *commands[] = {"sleep 10", "sleep 20", "sleep 5"};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    if (execute_commands(commands, num_commands) == -1) {
        fprintf(stderr, "Failed to execute commands\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
