public class DataProcessor
{
    public static (int affectedRows, string errorLog) processByteArray(byte[] byteArray)
    {
        string pattern = @"^\d{3}-\d{2}-\d{4}$"; // Example pattern for SSN
        if (!Regex.IsMatch(BitConverter.ToString(byteArray), pattern))
        {
            return (0, "Invalid byte array format");
        }

        using (SqlConnection connection = new SqlConnection("YourConnectionString"))
        {
            try
            {
                connection.Open();
                string[] queries = { "UPDATE Table1 SET Column1 = @Value WHERE Condition", "UPDATE Table2 SET Column2 = @Value WHERE Condition" };
                int totalAffectedRows = 0;
                foreach (var query in queries)
                {
                    using (SqlCommand command = new SqlCommand(query, connection))
                    {
                        command.Parameters.AddWithValue("@Value", BitConverter.ToString(byteArray));
                        totalAffectedRows += command.ExecuteNonQuery();
                    }
                }
                return (totalAffectedRows, "");
            }
            catch (Exception ex)
            {
                return (0, ex.Message);
            }
        }
    }
}
