#include <regex.h>
#include <stdlib.h>

char* trimAndAppendSlash(const char* input, size_t maxSize) {
    regex_t pattern;
    if (regcomp(&pattern, "^\\w+$", REG_EXTENDED)) {
        return NULL;
    }

    regmatch_t matches[1];
    if (regexec(&pattern, input, 1, matches, 0) != 0) {
        regfree(&pattern);
        return NULL;
    }

    size_t length = strlen(input);
    if (length >= maxSize - 1) {
        regfree(&pattern);
        return NULL;
    }

    char* result = malloc(maxSize * sizeof(char));
    if (!result) {
        regfree(&pattern);
        return NULL;
    }

    strcpy(result, input);
    result[length] = '/';
    result[length + 1] = '\0';

    regfree(&pattern);
    return result;
}
