function collectMatchingElements(node, selector) {
    let elements = [];
    function traverse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE && currentNode.matches(selector)) {
            elements.push(currentNode);
        }
        for (let child of currentNode.childNodes) {
            traverse(child);
        }
    }
    traverse(node);
    return elements;
}
