using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageProcessor
{
    public Dictionary<int, string> ProcessMessages(List<(string base64Message, byte[] key, byte[] iv, string sourceSystem, DateTime timestamp)> messages)
    {
        var decryptedMessages = new Dictionary<int, string>();

        Parallel.ForEach(messages, (message, state) =>
        {
            try
            {
                var decryptedContent = DecryptMessage(message.base64Message, message.key, message.iv);
                if (IsValidAscii(decryptedContent))
                {
                    decryptedMessages.Add(state.Ordinal, decryptedContent);
                }
                else
                {
                    LogInvalidMessage(message);
                }
            }
            catch (Exception ex)
            {
                LogError(ex, message);
            }
        });

        return decryptedMessages;
    }

    private string DecryptMessage(string base64Message, byte[] key, byte[] iv)
    {
        using (var des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            var encryptedBytes = Convert.FromBase64String(base64Message);
            using (var ms = new MemoryStream(encryptedBytes))
            using (var cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read))
            {
                return Encoding.ASCII.GetString(cs.ToArray());
            }
        }
    }

    private bool IsValidAscii(string content)
    {
        foreach (char c in content)
        {
            if (!Char.IsControl(c) && !Char.IsWhiteSpace(c) && !Char.IsLetterOrDigit(c))
            {
                return false;
            }
        }
        return true;
    }

    private void LogInvalidMessage((string base64Message, byte[] key, byte[] iv, string sourceSystem, DateTime timestamp) message)
    {
        Console.WriteLine($"Invalid ASCII content detected. Source: {message.sourceSystem}, Timestamp: {message.timestamp}");
    }

    private void LogError(Exception ex, (string base64Message, byte[] key, byte[] iv, string sourceSystem, DateTime timestamp) message)
    {
        Console.WriteLine($"Error processing message. Exception: {ex.Message}. Source: {message.sourceSystem}, Timestamp: {message.timestamp}");
    }
}
