using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DataTransformationService : IDisposable
{
    private readonly int _keySize;
    private readonly byte[] _iv;
    private readonly ICryptoTransform _encryptor;
    private readonly ICryptoTransform _decryptor;
    private readonly ILogger _logger;

    public DataTransformationService(int keySize, ILogger logger)
    {
        if (keySize < 128 || keySize > 256 || keySize % 8 != 0)
            throw new ArgumentException("Key size must be between 128 and 256 bits and a multiple of 8.");

        _keySize = keySize;
        _iv = GenerateRandomIV();
        _logger = logger;

        using (Aes aes = Aes.Create())
        {
            aes.KeySize = keySize;
            aes.IV = _iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            _encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
            _decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        }
    }

    public byte[] Encode(byte[] data)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, _encryptor, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }

            byte[] encodedData = ms.ToArray();
            byte[] checksum = GenerateChecksum(encodedData);

            _logger.Log("Encode", DateTime.Now, $"Encoded {data.Length} bytes with IV: {_iv.ToBase64String()}");

            return CombineArrays(encodedData, checksum);
        }
    }

    public byte[] Decode(byte[] encodedData)
    {
        byte[] dataWithoutChecksum = new byte[encodedData.Length - 16];
        Array.Copy(encodedData, dataWithoutChecksum, dataWithoutChecksum.Length);

        byte[] receivedChecksum = new byte[16];
        Array.Copy(encodedData, dataWithoutChecksum.Length, receivedChecksum, 0, receivedChecksum.Length);

        if (!ValidateChecksum(dataWithoutChecksum, receivedChecksum))
            throw new InvalidOperationException("Checksum validation failed.");

        using (MemoryStream ms = new MemoryStream(dataWithoutChecksum))
        {
            using (CryptoStream cs = new CryptoStream(ms, _decryptor, CryptoStreamMode.Read))
            {
                byte[] decodedData = new byte[dataWithoutChecksum.Length];
                cs.Read(decodedData, 0, decodedData.Length);
                return decodedData;
            }
        }
    }

    public void Dispose()
    {
        // Implement IDisposable pattern if necessary
    }

    private static byte[] GenerateRandomIV()
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] iv = new byte[16];
            rng.GetBytes(iv);
            return iv;
        }
    }

    private static byte[] GenerateChecksum(byte[] data)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(data);
        }
    }

    private static bool ValidateChecksum(byte[] data, byte[] receivedChecksum)
    {
        byte[] computedChecksum = GenerateChecksum(data);
        return computedChecksum.SequenceEqual(receivedChecksum);
    }

    private static byte[] CombineArrays(byte[] array1, byte[] array2)
    {
        byte[] result = new byte[array1.Length + array2.Length];
        Buffer.BlockCopy(array1, 0, result, 0, array1.Length);
        Buffer.BlockCopy(array2, 0, result, array1.Length, array2.Length);
        return result;
    }
}

public interface ILogger
{
    void Log(string operation, DateTime timestamp, string message);
}
