const { exec } = require('child_process');
const axios = require('axios');

async function executeHealthCheck() {
  const command = 'systemctl status'; // Example health check command
  const maxRetries = 3;
  let retryCount = 0;

  while (retryCount < maxRetries) {
    try {
      const { stdout, stderr } = await exec(command);
      const response = await axios.post('https://monitoring-service.com/log', {
        healthCheckResult: stdout,
        error: stderr
      });
      console.log(`Health check successful. Response status: ${response.status}`);
      return;
    } catch (error) {
      retryCount++;
      if (retryCount === maxRetries) {
        console.error('Max retries reached. Health check failed.');
        return;
      }
      const delay = Math.pow(2, retryCount) * 1000; // Exponential backoff
      console.log(`Health check failed. Retrying in ${delay}ms...`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}

executeHealthCheck();
