use tokio::task;
use std::collections::HashMap;
use std::error::Error;
use std::fmt;
use std::sync::{Arc, Mutex};
use log::{info, error};

// Define a trait for command handlers
trait CommandHandler {
    fn execute(&self, args: Vec<String>) -> Result<(), Box<dyn Error>>;
}

// Implement the trait for each specific command
struct GreetCommand;
impl CommandHandler for GreetCommand {
    fn execute(&self, args: Vec<String>) -> Result<(), Box<dyn Error>> {
        if let Some(name) = args.get(0) {
            info!("Hello, {}!", name);
        } else {
            error!("Missing name argument");
        }
        Ok(())
    }
}

struct AddCommand;
impl CommandHandler for AddCommand {
    fn execute(&self, args: Vec<String>) -> Result<(), Box<dyn Error>> {
        if let (Some(a), Some(b)) = (args.get(0).and_then(|s| s.parse::<i32>().ok()), args.get(1).and_then(|s| s.parse::<i32>().ok())) {
            info!("Result: {}", a + b);
        } else {
            error!("Invalid arguments for addition");
        }
        Ok(())
    }
}

// Command registry
struct CommandRegistry {
    handlers: HashMap<String, Box<dyn CommandHandler>>,
}

impl CommandRegistry {
    fn new() -> Self {
        let mut handlers = HashMap::new();
        handlers.insert("greet".to_string(), Box::new(GreetCommand));
        handlers.insert("add".to_string(), Box::new(AddCommand));
        CommandRegistry { handlers }
    }

    fn execute(&self, command: &str, args: Vec<String>) -> Result<(), Box<dyn Error>> {
        if let Some(handler) = self.handlers.get(command) {
            handler.execute(args)
        } else {
            error!("Unknown command: {}", command);
            Ok(())
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    // Initialize logging
    env_logger::init();

    // Create a shared registry of commands
    let registry = Arc::new(Mutex::new(CommandRegistry::new()));

    // Simulate receiving command line arguments asynchronously
    let args = vec![
        "greet".to_string(),
        "Alice".to_string(),
        "add".to_string(),
        "5".to_string(),
        "3".to_string(),
    ];

    for arg in args {
        if let Some(command) = arg.split_whitespace().next() {
            let registry_clone = Arc::clone(&registry);
            task::spawn(async move {
                if let Err(e) = registry_clone.lock().unwrap().execute(command, vec![]) {
                    error!("Error executing command: {}", e);
                }
            });
        }
    }

    Ok(())
}
