#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    int data;
    NFAPI_CRC_INDICATION_PDU pdu;
    struct Node* next;
} Node;

Node* createNode(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = value;
    newNode->pdu.RX_UE_INFORMATION_TAG = value; // Example usage
    newNode->pdu.RNTI = value; // Example usage
    newNode->pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    newNode->next = NULL;
    return newNode;
}

void insertNode(Node** head, int value) {
    Node* newNode = createNode(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void printLargest(Node* head) {
    int max = INT_MIN;
    while (head != NULL) {
        if (head->data > max) {
            max = head->data;
        }
        head = head->next;
    }
    printf("Largest integer: %d\n", max);
}

void freeList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "File not found\n");
        return 1;
    }

    Node* head = NULL;
    int value;
    while (fscanf(file, "%d", &value) != EOF) {
        insertNode(&head, value);
    }

    printLargest(head);

    freeList(head);
    fclose(file);

    return 0;
}
