#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    INTERFACE_TYPE_ETHERNET,
    INTERFACE_TYPE_WIFI,
    INTERFACE_TYPE_UNKNOWN
} InterfaceType;

typedef struct {
    InterfaceType type;
    int bandwidth; // in Mbps
    double frequency; // in GHz
} NetworkInterfaceConfig;

typedef struct {
    NetworkInterfaceConfig *interfaces;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NetworkInterfacePool;

NetworkInterfacePool* create_network_interface_pool(size_t initial_capacity) {
    NetworkInterfacePool *pool = (NetworkInterfacePool*)malloc(sizeof(NetworkInterfacePool));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed for network interface pool.\n");
        return NULL;
    }
    pool->interfaces = (NetworkInterfaceConfig*)calloc(initial_capacity, sizeof(NetworkInterfaceConfig));
    if (!pool->interfaces) {
        free(pool);
        fprintf(stderr, "Memory allocation failed for network interface array.\n");
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_network_interface_pool(NetworkInterfacePool *pool) {
    if (pool) {
        free(pool->interfaces);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_network_interface(NetworkInterfacePool *pool, NetworkInterfaceConfig config) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        NetworkInterfaceConfig *new_interfaces = (NetworkInterfaceConfig*)realloc(pool->interfaces, new_capacity * sizeof(NetworkInterfaceConfig));
        if (!new_interfaces) {
            pthread_mutex_unlock(&pool->lock);
            fprintf(stderr, "Memory reallocation failed for network interface array.\n");
            return -1;
        }
        pool->interfaces = new_interfaces;
        pool->capacity = new_capacity;
    }
    pool->interfaces[pool->size++] = config;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Additional functions for resizing, caching, logging, and compatibility can be implemented here.
```

