SSL_CTX* initialize_ssl_context(const char* ca_file_path) {
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return NULL;
    }

    // Load CA certificates from file
    if (SSL_CTX_load_verify_locations(ctx, ca_file_path, NULL) != 1) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Set verification mode to require peer certificate and verify it
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

    return ctx;
}

int validate_ssl_connection(SSL_CTX* ctx, const char* hostname) {
    int ret = 0;
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        return -1;
    }

    // Set the hostname for certificate verification
    if (SSL_set_tlsext_host_name(ssl, hostname) != 1) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        return -1;
    }

    // Perform SSL handshake
    ret = SSL_connect(ssl);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
    }

    SSL_free(ssl);
    return ret;
}

