public class StringHasher {
    private final ExecutorService executorService;
    private final Map<String, String> cache = new ConcurrentHashMap<>();
    private final int threadPoolSize;

    public StringHasher(int threadPoolSize) {
        this.threadPoolSize = threadPoolSize;
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void setTargetEnvironment(String environment) {
        // Implement logic to adjust thread pool size based on environment
    }

    public String hashString(String input, boolean useCustomAlgorithm) throws InterruptedException, ExecutionException {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }
        Callable<String> task = () -> computeHash(input, useCustomAlgorithm);
        Future<String> future = executorService.submit(task);
        String result = future.get();
        cache.put(input, result);
        return result;
    }

    private String computeHash(String input, boolean useCustomAlgorithm) {
        try {
            if (useCustomAlgorithm) {
                // Implement custom hash algorithm
                return "custom_hash_" + input;
            } else {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] messageDigest = md.digest(input.getBytes());
                BigInteger no = new BigInteger(1, messageDigest);
                StringBuilder hashtext = new StringBuilder(no.toString(16));
                while (hashtext.length() < 32) {
                    hashtext.insert(0, "0");
                }
                return hashtext.toString();
            }
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hash algorithm not found", e);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }

