#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 10000

typedef struct Packet {
    int id;
    size_t payload_size;
    clock_t arrival_time;
    struct Packet* next;
} Packet;

Packet* packet_buffer[MAX_PACKETS];
int buffer_head = 0, buffer_tail = 0, buffer_count = 0;
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_not_full = PTHREAD_COND_INITIALIZER, buffer_not_empty = PTHREAD_COND_INITIALIZER;

void add_packet_to_buffer(Packet* packet) {
    pthread_mutex_lock(&buffer_lock);
    while (buffer_count == MAX_PACKETS) {
        pthread_cond_wait(&buffer_not_full, &buffer_lock);
    }
    packet_buffer[buffer_tail] = packet;
    buffer_tail = (buffer_tail + 1) % MAX_PACKETS;
    buffer_count++;
    pthread_cond_signal(&buffer_not_empty);
    pthread_mutex_unlock(&buffer_lock);
}

Packet* remove_packet_from_buffer() {
    Packet* packet = NULL;
    pthread_mutex_lock(&buffer_lock);
    while (buffer_count == 0) {
        pthread_cond_wait(&buffer_not_empty, &buffer_lock);
    }
    packet = packet_buffer[buffer_head];
    buffer_head = (buffer_head + 1) % MAX_PACKETS;
    buffer_count--;
    pthread_cond_signal(&buffer_not_full);
    pthread_mutex_unlock(&buffer_lock);
    return packet;
}

void* process_packets(void* arg) {
    while (1) {
        Packet* packet = remove_packet_from_buffer();
        if (packet == NULL) break;

        // Process the packet
        clock_t current_time = clock();
        double latency = (double)(current_time - packet->arrival_time) / CLOCKS_PER_SEC * 1000;
        printf("Packet ID: %d, Payload Size: %zu bytes, Latency: %.2f ms\n", packet->id, packet->payload_size, latency);

        // Free the packet
        free(packet);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_packets, NULL);
    }

    // Simulate receiving packets
    for (int i = 0; i < 20000; i++) {
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        packet->id = i;
        packet->payload_size = rand() % 1000 + 1;
        packet->arrival_time = clock();
        add_packet_to_buffer(packet);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
