    size_t capacity;
    size_t size;
} DynamicArray_T;

DynamicArray_T* create_dynamic_array(size_t initial_capacity) {
    DynamicArray_T* array = (DynamicArray_T*)malloc(sizeof(DynamicArray_T));
    if (!array) return NULL;
    array->array = (UE_Status_Report_T*)calloc(initial_capacity, sizeof(UE_Status_Report_T));
    if (!array->array) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray_T* array) {
    if (array) {
        free(array->array);
        free(array);
    }
}

int add_ue_status(DynamicArray_T* array, LTE_MME_UE_S1AP_ID_t ue_id, RRC_Connexion_State rrc_state, int nas_message_count) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UE_Status_Report_T* new_array = (UE_Status_Report_T*)realloc(array->array, new_capacity * sizeof(UE_Status_Report_T));
        if (!new_array) return -1;
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size].ue_id = ue_id;
    array->array[array->size].rrc_state = rrc_state;
    array->array[array->size].nas_message_count = nas_message_count;
    array->size++;
    return 0;
}

UE_Status_Report_T* filter_ue_statuses(DynamicArray_T* array, int threshold) {
    static UE_Status_Report_T filtered_array[1024]; // Static buffer for filtering
    size_t filtered_size = 0;

    for (size_t i = 0; i < array->size; i++) {
        if (array->array[i].nas_message_count > threshold) {
            filtered_array[filtered_size++] = array->array[i];
        }
    }

    return filtered_array;
}
