using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;

    public DynamicValueGenerator(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public float GetRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomIntInclusive()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public int GetRandomIntExclusive()
    {
        return _random.Next(_minValue, _maxValue);
    }

    public Task ExecuteCommandAsync(string command)
    {
        return Task.Run(() =>
        {
            try
            {
                Process process = new Process();
                process.StartInfo.FileName = "cmd.exe";
                process.StartInfo.Arguments = $"/c {command}";
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.CreateNoWindow = true;

                process.OutputDataReceived += (sender, e) => Console.WriteLine(e.Data);
                process.BeginOutputReadLine();

                process.Start();
                process.WaitForExit();
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error executing command: {ex.Message}");
            }
        });
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
