#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

typedef struct MemoryPool {
    void* pool[MAX_POOL_SIZE];
    int size;
    int index;
} MemoryPool;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

Node* allocate_node(MemoryPool* pool) {
    if (pool->index >= MAX_POOL_SIZE) {
        printf("Memory pool is full\n");
        return NULL;
    }
    Node* node = (Node*)pool->pool[pool->index++];
    return node;
}

void free_node(Node* node, MemoryPool* pool) {
    int index = ((char*)node - (char*)pool->pool) / sizeof(Node);
    if (index >= 0 && index < MAX_POOL_SIZE) {
        pool->index = index;
    } else {
        printf("Invalid node pointer\n");
    }
}

void insert_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    pthread_mutex_unlock(&list->lock);
}

void* find_largest_integer(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    Node* current = list->head;
    int largest = INT_MIN;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG > largest) {
            largest = current->data.RX_UE_INFORMATION_TAG;
        }
        current = current->next;
    }
    printf("Largest integer: %d\n", largest);
    return NULL;
}

void read_and_process_data(DoublyLinkedList* list, MemoryPool* pool, FILE* file) {
    int num;
    while (fscanf(file, "%d", &num) == 1) {
        Node* node = allocate_node(pool);
        if (node != NULL) {
            node->data.RX_UE_INFORMATION_TAG = num;
            node->data.RNTI = rand() % 1024; // Random RNTI
            node->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
            insert_node(list, node);
        }
    }
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    DoublyLinkedList* list = create_doubly_linked_list();
    MemoryPool pool;

    // Initialize memory pool
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        pool.pool[i] = malloc(sizeof(Node));
    }
    pool.size = MAX_POOL_SIZE;
    pool.index = 0;

    read_and_process_data(list, &pool, file);

    pthread_t thread;
    pthread_create(&thread, NULL, find_largest_integer, list);
    pthread_join(thread, NULL);

    // Clean up
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current, &pool);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    fclose(file);

    return 0;
}
