        fprintf(stderr, "Error: Requested number of structures exceeds maximum limit.\n");
        return;
    }

    *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(*numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
