#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= MAX_LIST_SIZE) return -1; // List is full
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failed

    pthread_mutex_lock(&list->mutex);
    new_node->data = data;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int remove_element(List* list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;

    while (current) {
        if (current->data.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (!current->next) {
                list->tail = prev;
            }
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // Element not found
}

size_t get_count(List* list) {
    size_t count;
    pthread_mutex_lock(&list->mutex);
    count = list->count;
    pthread_mutex_unlock(&list->mutex);
    return count;
}
