#include <arpa/inet.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN 16
#define MAX_INPUT_SIZE 1024

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), INET_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

int read_and_validate_integers(int *array, int max_size) {
    char input[MAX_INPUT_SIZE];
    int count = 0;

    while (fgets(input, sizeof(input), stdin)) {
        if (sscanf(input, "%d", &array[count]) != 1) {
            fprintf(stderr, "Invalid input: %s\n", input);
            continue;
        }
        if (count >= max_size - 1) {
            fprintf(stderr, "Input array is full.\n");
            break;
        }
        count++;
    }

    return count;
}

int find_largest_integer(int *array, int size) {
    if (size == 0) {
        fprintf(stderr, "Empty input array.\n");
        return -1;
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void handle_signal(int signum) {
    log_error("Signal received.");
    exit(signum);
}

int main() {
    u_char ip_address[MAX_IP_LEN];
    int integers[MAX_INPUT_SIZE];
    int count;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (resolve_hostname("example.com", ip_address) == 0) {
        printf("IP Address: %s\n", inet_ntoa(*(struct in_addr *)ip_address));
    }

    count = read_and_validate_integers(integers, MAX_INPUT_SIZE);
    if (count > 0) {
        int largest = find_largest_integer(integers, count);
        printf("Largest Integer: %d\n", largest);
    }

    return 0;
}
