const crypto = require('crypto');

function extendCryptoLibrary(moduleLabel) {
    if (!moduleLabel) {
        throw new Error('Module label is required');
    }

    const moduleState = {};

    function loadOpenSSL() {
        // Simulate loading OpenSSL library
        console.log(`Loading OpenSSL for module: ${moduleLabel}`);
    }

    function configureCiphers() {
        // Add AES, Camellia block ciphers
        crypto.getCipherInfo('aes-256-cbc');
        crypto.getCipherInfo('camellia-128-cbc');
    }

    function configureDigests() {
        // Add MD5, SHA-256
        crypto.createHash('md5');
        crypto.createHash('sha256');
    }

    function configureRSA() {
        // RSA with SHA-256
        crypto.createSign('SHA256');
        crypto.createVerify('SHA256');
    }

    function resetLibraryState() {
        // Reset library state for the module
        console.log(`Resetting OpenSSL state for module: ${moduleLabel}`);
    }

    function configureModule() {
        loadOpenSSL();
        configureCiphers();
        configureDigests();
        configureRSA();
    }

    function extendCrypto() {
        try {
            resetLibraryState();
            configureModule();
            moduleState[moduleLabel] = true;
            console.log(`Module ${moduleLabel} configured successfully`);
        } catch (error) {
            console.error(`Error configuring module ${moduleLabel}:`, error);
        }
    }

    return extendCrypto;
}

// Example usage:
const extendLib1 = extendCryptoLibrary('module1');
extendLib1();

const extendLib2 = extendCryptoLibrary('module2');
