#include <string.h>

EVP_CIPHER_CTX *initialize_aes_cipher(const char *password, int iv_length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        fprintf(stderr, "Failed to generate random salt\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    size_t key_len = EVP_MAX_KEY_LENGTH;

    // Derive key and IV using SHA-1
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1(password, strlen(password), hash);

    memcpy(key, hash, sizeof(hash));
    if (iv_length < 16 || iv_length > 32) {
        iv_length = 16; // Default to 16 bytes if out of range
    }
    memcpy(iv, hash + sizeof(hash) - iv_length, iv_length);

    // Set key length based on user choice
    if (iv_length == 32) {
        fprintf(stderr, "Warning: SHA-256 selected with truncated key material\n");
        key_len = 32;
    }

    // Initialize cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
