['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define LOG_LEVEL_DEBUG 3
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    int log_level;
    time_t last_integrity_check;
} ListManager;

void log_message(int level, const char *message) {
    if (level <= LOG_LEVEL_DEBUG) {
        printf("DEBUG: %s\n", message);
    } else if (level == LOG_LEVEL_INFO) {
        printf("INFO: %s\n", message);
    } else if (level == LOG_LEVEL_ERROR) {
        printf("ERROR: %s\n", message);
    }
}

void initialize_list_manager(ListManager *manager, int log_level) {
    manager->list = malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->log_level = log_level;
    manager->last_integrity_check = time(NULL);
}

void add_to_list(ListManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        // Resize the list
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(manager->list, manager->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            log_message(LOG_LEVEL_ERROR, "Failed to resize list");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->list = new_list;
        manager->capacity *= 2;
    }
    // Add a new item
    NFAPI_CRC_INDICATION_PDU_T new_item;
    new_item.RX_UE_INFORMATION_TAG = rand() % 1000;
    new_item.RNTI = rand() % 1000;
    new_item.CRC_INDICATION_REL8_TAG = rand() % 2;
    manager->list[manager->size++] = new_item;
    pthread_mutex_unlock(&manager->mutex);
}

void check_integrity(ListManager *manager) {
    time_t now = time(NULL);
    if (now - manager->last_integrity_check > 60) { // Check every minute
        for (size_t i = 0; i < manager->size; ++i) {
            if (manager->list[i].RX_UE_INFORMATION_TAG == 0 || manager->list[i].RNTI == 0 || manager->list[i].CRC_INDICATION_REL8_TAG > 1) {
                log_message(LOG_LEVEL_ERROR, "Invalid entry in list");
                // Discard corrupted entry
                pthread_mutex_lock(&manager->mutex);
                for (size_t j = i; j < manager->size - 1; ++j) {
                    manager->list[j] = manager->list[j + 1];
                }
                --manager->size;
                pthread_mutex_unlock(&manager->mutex);
            }
        }
        manager->last_integrity_check = now;
    }
}

void *thread_function(void *arg) {
    ListManager *manager = (ListManager *)arg;
    while (1) {
        add_to_list(manager);
        check_integrity(manager);
        sleep(1); // Simulate work
    }
    return NULL;
}

int main() {
    ListManager manager;
    initialize_list_manager(&manager, LOG_LEVEL_DEBUG);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, thread_function, &manager);
    pthread_create(&thread2, NULL, thread_function, &manager);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free(manager.list);
    return 0;
}
