Device_Status_T* filter_devices(Device_Status_T* devices, int num_devices, float battery_threshold, float min_lat, float max_lat, float min_lon, float max_lon, int* result_size) {
    if (devices == NULL || num_devices <= 0 || battery_threshold < 0 || min_lat > max_lat || min_lon > max_lon) {
        return NULL;
    }

    Device_Status_T* filtered_devices = (Device_Status_T*)malloc(MAX_DEVICES * sizeof(Device_Status_T));
    if (filtered_devices == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    int count = 0;
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].Current_Battery_Level < battery_threshold &&
            devices[i].Location_LATITUDE >= min_lat && devices[i].Location_LATITUDE <= max_lat &&
            devices[i].Location_LONGITUDE >= min_lon && devices[i].Location_LONGITUDE <= max_lon) {
            filtered_devices[count++] = devices[i];
        }
    }

    *result_size = count;
    return filtered_devices;
}

int main() {
    // Example usage
    Device_Status_T devices[MAX_DEVICES] = {
        {1, 20.5, 34.0522, -118.2437},
        {2, 15.0, 40.7128, -74.0060},
        // Add more devices as needed
    };
    int num_devices = 2;
    float battery_threshold = 18.0;
    float min_lat = 33.0, max_lat = 35.0, min_lon = -120.0, max_lon = -116.0;
    int result_size;

    Device_Status_T* filtered_devices = filter_devices(devices, num_devices, battery_threshold, min_lat, max_lat, min_lon, max_lon, &result_size);
    if (filtered_devices != NULL) {
        printf("Filtered Devices:\n");
        for (int i = 0; i < result_size; i++) {
            printf("Device ID: %d, Battery Level: %.2f, Latitude: %.4f, Longitude: %.4f\n",
                   filtered_devices[i].Device_ID,
                   filtered_devices[i].Current_Battery_Level,
                   filtered_devices[i].Location_LATITUDE,
                   filtered_devices[i].Location_LONGITUDE);
        }
        free(filtered_devices);
    }

    return 0;
}
