typedef struct {
    LTE_RRC_Connection_Status_T* statuses;
    size_t capacity;
    size_t count;
} LTE_RRC_Connection_Array_T;

LTE_RRC_Connection_Array_T* create_connection_array(size_t initial_capacity) {
    LTE_RRC_Connection_Array_T* array = (LTE_RRC_Connection_Array_T*)malloc(sizeof(LTE_RRC_Connection_Array_T));
    if (!array) return NULL;

    array->statuses = (LTE_RRC_Connection_Status_T*)calloc(initial_capacity, sizeof(LTE_RRC_Connection_Status_T));
    if (!array->statuses) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void destroy_connection_array(LTE_RRC_Connection_Array_T* array) {
    if (array) {
        free(array->statuses);
        free(array);
    }
}

int add_connection_status(LTE_RRC_Connection_Array_T* array, LTE_MME_UE_S1AP_ID_t ue_id, int phy_signal_strength, RRC_State current_state, double downlink_throughput) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_RRC_Connection_Status_T* new_statuses = (LTE_RRC_Connection_Status_T*)realloc(array->statuses, new_capacity * sizeof(LTE_RRC_Connection_Status_T));
        if (!new_statuses) return -1;

        array->statuses = new_statuses;
        array->capacity = new_capacity;
    }

    array->statuses[array->count].ue_id = ue_id;
    array->statuses[array->count].phy_signal_strength = phy_signal_strength;
    array->statuses[array->count].current_state = current_state;
    array->statuses[array->count].downlink_throughput = downlink_throughput;
    array->count++;

    return 0;
}

LTE_RRC_Connection_Status_T* filter_by_throughput(LTE_RRC_Connection_Array_T* array, double threshold) {
    LTE_RRC_Connection_Status_T* filtered_statuses = (LTE_RRC_Connection_Status_T*)malloc(array->count * sizeof(LTE_RRC_Connection_Status_T));
    if (!filtered_statuses) return NULL;

    size_t filtered_count = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (array->statuses[i].downlink_throughput < threshold) {
            filtered_statuses[filtered_count++] = array->statuses[i];
        }
    }

    // Resize the filtered array to fit exactly
    filtered_statuses = realloc(filtered_statuses, filtered_count * sizeof(LTE_RRC_Connection_Status_T));
    return filtered_statuses;
}
