                profileName = argv[++i];
            } else {
                fprintf(stderr, "Error: Missing argument for -p option\n");
                usage();
                return 1;
            }
        } else if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            usage();
            return 0;
        } else if (!inputFile) {
            inputFile = fopen(argv[i], "r");
            if (!inputFile) {
                fprintf(stderr, "Error: Unable to open input file %s\n", argv[i]);
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Unexpected argument %s\n", argv[i]);
            usage();
            return 1;
        }
    }

    // Load processing module based on profile
    if (strcmp(profileName, "default") == 0) {
        module = &processFile;
    } else {
        fprintf(stderr, "Error: Unknown profile %s\n", profileName);
        return 1;
    }

