#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_IDENTIFIER 1024
#define MAX_SYMBOLS 1024

typedef struct {
    int UE_IDENTIFIER;
    int symbols[MAX_SYMBOLS];
} NFAPI_L1_RX_PDU_T;

void* process_rx_pdu(void* arg) {
    NFAPI_L1_RX_PDU_T* pdu = (NFAPI_L1_RX_PDU_T*)arg;
    // Process the received PDU
    printf("Processing PDU for UE %d\n", pdu->UE_IDENTIFIER);
    return NULL;
}

void initialize_and_configure_pdus(int num_pdus, int buffer_size, int max_threads) {
    NFAPI_L1_RX_PDU_T* pdus = (NFAPI_L1_RX_PDU_T*)malloc(num_pdus * sizeof(NFAPI_L1_RX_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    pthread_t threads[max_threads];
    int thread_count = 0;

    for (int i = 0; i < num_pdus; i++) {
        pdus[i].UE_IDENTIFIER = i % MAX_UE_IDENTIFIER;
        // Initialize symbols based on buffer_size
        for (int j = 0; j < buffer_size && j < MAX_SYMBOLS; j++) {
            pdus[i].symbols[j] = rand() % 256;
        }

        if (thread_count < max_threads) {
            pthread_create(&threads[thread_count], NULL, process_rx_pdu, &pdus[i]);
            thread_count++;
        } else {
            // Handle load balancing
            for (int j = 0; j < thread_count; j++) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 1;
            pthread_create(&threads[0], NULL, process_rx_pdu, &pdus[i]);
        }

        if (i % max_threads == 0 && i != 0) {
            // Reap threads to manage memory and cache utilization
            for (int j = 0; j < thread_count; j++) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }
    }

    // Join remaining threads
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    free(pdus);
}

int main() {
    int num_pdus = 1000;
    int buffer_size = 256;
    int max_threads = 32;

    initialize_and_configure_pdus(num_pdus, buffer_size, max_threads);

    return 0;
}
