    Node* tail;
    size_t size;
    size_t max_size;
} RollingBuffer;

RollingBuffer* init_rolling_buffer(size_t max_size) {
    if (max_size == 0 || max_size > 1024) {
        return NULL; // Invalid max size
    }

    RollingBuffer* buffer = (RollingBuffer*)malloc(sizeof(RollingBuffer));
    if (!buffer) {
        return NULL; // Memory allocation failed
    }

    buffer->head = buffer->tail = NULL;
    buffer->size = 0;
    buffer->max_size = max_size;

    srand(time(NULL)); // Initialize random seed

    return buffer;
}

void add_to_buffer(RollingBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    if (buffer->size == buffer->max_size) {
        if (buffer->head == buffer->tail) {
            free(buffer->head);
            buffer->head = buffer->tail = new_node;
        } else {
            Node* temp = buffer->head;
            buffer->head = buffer->head->next;
            free(temp);
            buffer->tail->next = new_node;
            buffer->tail = new_node;
        }
    } else {
        if (buffer->head == NULL) {
            buffer->head = buffer->tail = new_node;
        } else {
            buffer->tail->next = new_node;
            buffer->tail = new_node;
        }
        buffer->size++;
    }

    // Set CRCFLAG based on random seed
    data.crc_indication.CRCFLAG = rand() % 2; // Example: Randomly set to 0 or 1
}

void free_buffer(RollingBuffer* buffer) {
    Node* current = buffer->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(buffer);
}
