#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeNode(LinkedList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

int findLargestInteger(LinkedList* list) {
    int largest = INT_MIN;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG > largest) {
            largest = current->data.RX_UE_INFORMATION_TAG;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return largest;
}

void* readAndProcessFile(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    int num;
    while (fscanf(file, "%d", &num) == 1) {
        NFAPI_CRC_INDICATION_PDU_T data = {num, rand() % 1000, rand() % 2};
        insertNode(list, data);
    }

    fclose(file);
    return NULL;
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    pthread_t thread;
    if (pthread_create(&thread, NULL, readAndProcessFile, &list) != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_join(thread, NULL);

    int largest = findLargestInteger(&list);
    printf("Largest integer: %d\n", largest);

    // Clean up
    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
