typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    int max_size;
    double age_to_lifetime_ratio;
    pthread_mutex_t mutex;
} RollingBuffer;

RollingBuffer* init_buffer(int max_size, double age_to_lifetime_ratio) {
    RollingBuffer* buffer = (RollingBuffer*)malloc(sizeof(RollingBuffer));
    if (!buffer) {
        return NULL; // Handle memory allocation failure
    }
    buffer->head = buffer->tail = NULL;
    buffer->size = 0;
    buffer->max_size = max_size;
    buffer->age_to_lifetime_ratio = age_to_lifetime_ratio;
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void add_to_buffer(RollingBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&buffer->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&buffer->mutex);
        return; // Handle memory allocation failure
    }
    new_node->data = data;
    new_node->next = NULL;

    if (buffer->size == buffer->max_size) {
        Node* temp = buffer->head;
        buffer->head = buffer->head->next;
        free(temp);
        buffer->size--;
    }

    if (!buffer->tail) {
        buffer->head = buffer->tail = new_node;
    } else {
        buffer->tail->next = new_node;
        buffer->tail = new_node;
    }
    buffer->size++;
    pthread_mutex_unlock(&buffer->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_buffer(RollingBuffer* buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (!buffer->head) {
        pthread_mutex_unlock(&buffer->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = &buffer->head->data;
    Node* temp = buffer->head;
    buffer->head = buffer->head->next;
    free(temp);
    buffer->size--;
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

void adjust_age_to_lifetime_ratio(RollingBuffer* buffer, double new_ratio) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->age_to_lifetime_ratio = new_ratio;
    pthread_mutex_unlock(&buffer->mutex);
}

