#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int ue_id;
    int PHY_RRC_ksi;
    char NAS_MESSAGE[1024];
    time_t last_updated;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArrayManager;

DynamicArrayManager* create_manager(size_t initial_capacity) {
    DynamicArrayManager *manager = (DynamicArrayManager*)malloc(sizeof(DynamicArrayManager));
    manager->contexts = (UEContext*)calloc(initial_capacity, sizeof(UEContext));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(DynamicArrayManager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_context(DynamicArrayManager *manager, UEContext context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->contexts = (UEContext*)realloc(manager->contexts, new_capacity * sizeof(UEContext));
        manager->capacity = new_capacity;
    }
    manager->contexts[manager->size++] = context;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_context(DynamicArrayManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int update_context(DynamicArrayManager *manager, int ue_id, UEContext new_context) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            manager->contexts[i] = new_context;
            manager->contexts[i].last_updated = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

UEContext* get_context(DynamicArrayManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->contexts[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}
