typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->count = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(array);
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!array) return -1;

    Node* current = array->head;
    while (current) {
        if (current->data.RNTI == new_data.RNTI) {
            // Update existing entry
            memcpy(&current->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return 0;
        }
        current = current->next;
    }

    // Add new element
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;
    memcpy(&new_node->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    return 0;
}

int remove_element(DynamicArray* array, int RNTI) {
    if (!array || RNTI < 0) return -1;

    Node* current = array->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                array->head = current->next;
            }
            free(current);
            array->count--;
            return 0;
        }
        prev = current;
        current = current->next;
    }

    return -1; // RNTI not found
}

void iterate_dynamic_array(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!array || !callback) return;

    Node* current = array->head;
    while (current) {
        callback(&current->data);
        current = current->next;
    }
}

// Example usage
void print_element(NFAPI_CRC_INDICATION_PDU_T* data) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG, data->CRCFLAG);
}

int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) return -1;

    NFAPI_CRC_INDICATION_PDU_T new_data = {1, 2, 3, 4};
    add_element(array, new_data);

    iterate_dynamic_array(array, print_element);

    destroy_dynamic_array(array);
    return 0;
}
