    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_unique(NFAPI_CRC_INDICATION_PDU_T *head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->RNTI == RNTI) return 0;
        current = current->next;
    }
    return 1;
}

int insert_entry(LinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    if (is_unique(list->head, RNTI)) {
        NFAPI_CRC_INDICATION_PDU_T *new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_entry->RNTI = RNTI;
        new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        new_entry->CRCFLAG = CRCFLAG;
        new_entry->next = list->head;
        list->head = new_entry;
    } else {
        pthread_mutex_unlock(&list->lock);
        return 0; // Duplicate RNTI
    }
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void delete_entry(LinkedList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_list(LinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList *list = create_list();
    if (!list) return 1;

    srand(time(NULL));
    for (int i = 0; i < MAX_ENTRIES; i++) {
        int RX_UE_INFORMATION_TAG = rand() % 1000;
        int RNTI = rand() % 1000;
        int CRC_INDICATION_REL8_TAG = rand() % 1000;
        int CRCFLAG = rand() % 2;
        insert_entry(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
    }

    delete_list(list);
    return 0;
}
