typedef struct {
    int value;
} record;

long* offset_values;
int* keys;
record** records;
int total_records = 0;
pthread_mutex_t records_mutex;

void initialize_data_structures(int num_records, int min_value, int max_value) {
    pthread_mutex_init(&records_mutex, NULL);

    offset_values = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    records = (record**)malloc(num_records * sizeof(record*));

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        offset_values[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;

        records[i] = (record*)malloc(sizeof(record));
        pthread_mutex_lock(&records_mutex);
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        total_records++;
        pthread_mutex_unlock(&records_mutex);
    }
}

void* update_record(void* arg) {
    int index = *(int*)arg;

    pthread_mutex_lock(&records_mutex);
    records[index]->value += rand() % 10; // Increment by a random value between 0 and 9
    pthread_mutex_unlock(&records_mutex);

    return NULL;
}

void free_data_structures() {
    for (int i = 0; i < total_records; i++) {
        free(records[i]);
    }
    free(offset_values);
    free(keys);
    free(records);
    pthread_mutex_destroy(&records_mutex);
}
