#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPI_PDUS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_NFAPI_PDUS];
    int count;
    pthread_mutex_t lock;
} PduManager;

PduManager pdu_manager = {0};

void init_pdu_manager() {
    pthread_mutex_init(&pdu_manager.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    pdu->RNTI = rand() % 256; // Example initialization
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu);
    }
}

int create_pdu() {
    pthread_mutex_lock(&pdu_manager.lock);
    if (pdu_manager.count >= MAX_NFAPI_PDUS) {
        printf("Maximum number of PDUs reached\n");
        pthread_mutex_unlock(&pdu_manager.lock);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu();
    if (!pdu) {
        pthread_mutex_unlock(&pdu_manager.lock);
        return -1;
    }
    pdu_manager.pdus[pdu_manager.count++] = pdu;
    pthread_mutex_unlock(&pdu_manager.lock);
    printf("PDU created successfully\n");
    return 0;
}

void destroy_pdu(int index) {
    if (index < 0 || index >= pdu_manager.count) {
        printf("Invalid PDU index\n");
        return;
    }
    pthread_mutex_lock(&pdu_manager.lock);
    free_pdu(pdu_manager.pdus[index]);
    for (int i = index; i < pdu_manager.count - 1; i++) {
        pdu_manager.pdus[i] = pdu_manager.pdus[i + 1];
    }
    pdu_manager.count--;
    pthread_mutex_unlock(&pdu_manager.lock);
}

void* thread_function(void *arg) {
    for (int i = 0; i < 100; i++) {
        create_pdu();
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    init_pdu_manager();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < pdu_manager.count; i++) {
        destroy_pdu(i);
    }

    pthread_mutex_destroy(&pdu_manager.lock);

    return 0;
}
