#include <iostream>
#include <forward_list>
#include <algorithm>
#include <cctype>
#include <string>

// Helper function to perform case-insensitive comparison
bool iequals(const std::string &a, const std::string &b) {
    return std::equal(a.begin(), a.end(), b.begin(), b.end(),
                      [](char a, char b){ return std::tolower(a) == std::tolower(b); });
}

// Function to insert string after first occurrence of target
bool insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = std::find_if(list.begin(), list.end(), [&target](const std::string& str) { return iequals(str, target); });

    if (it != list.end()) {
        // Insert after the first occurrence
        it++;
        list.insert_after(it, insertion);
        return true;
    } else {
        // Append to the end if not found
        list.push_back(insertion);
        return true;
    }
}

// Example usage
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    std::string target = "Banana";
    std::string insertion = "Blueberry";

    if (insertAfterFirstOccurrence(myList, target, insertion)) {
        for (const auto& item : myList) {
            std::cout << item << " ";
        }
    } else {
        std::cerr << "Failed to insert string." << std::endl;
    }

    return 0;
}
