typedef struct {
    long offset;
    int key;
    double value;
    char* str;
} record;

record** allocate_records(int num_records) {
    if (num_records > MAX_RECORDS) {
        // Log error and handle gracefully
        return NULL;
    }

    size_t total_size = num_records * sizeof(record*);
    if (total_size > MAX_MEMORY) {
        // Log error and handle gracefully
        return NULL;
    }

    record** records = (record**)malloc(total_size);
    if (!records) {
        // Log memory allocation failure
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // Free previously allocated records and log error
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = 0;
        records[i]->key = 0;
        records[i]->value = 0.0;
        records[i]->str = NULL;
    }

    return records;
}

void free_records(record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]->str) {
            free(records[i]->str);
        }
        free(records[i]);
    }
    free(records);
}

