#define MAX_ENODEB_CELLS 1024

typedef enum {
    CELL_STATUS_ACTIVE,
    CELL_STATUS_INACTIVE,
    CELL_STATUS_MAINTENANCE
} LTE_CELL_STATUS_T;

typedef struct LTE_ENODEB_API_CELL_STATUS_T {
    int CELL_ID;
    int PCI;
    LTE_CELL_STATUS_T OPERATIONAL_STATE;
    int STATE_FLAG;
} LTE_ENODEB_API_CELL_STATUS_T;

LTE_ENODEB_API_CELL_STATUS_T* cell_pool[MAX_ENODEB_CELLS];
int pool_index = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

LTE_ENODEB_API_CELL_STATUS_T* allocate_cell(int cell_id, int pci, LTE_CELL_STATUS_T state) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= MAX_ENODEB_CELLS) {
        printf("Allocation error: Cell pool is full.\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    LTE_ENODEB_API_CELL_STATUS_T* cell = malloc(sizeof(LTE_ENODEB_API_CELL_STATUS_T));
    if (cell == NULL) {
        printf("Allocation error: Failed to allocate memory for cell.\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    cell->CELL_ID = cell_id;
    cell->PCI = pci;
    cell->OPERATIONAL_STATE = state;
    cell->STATE_FLAG = (state == CELL_STATUS_ACTIVE) ? 1 : 0;
    cell_pool[pool_index++] = cell;
    pthread_mutex_unlock(&pool_lock);
    return cell;
}

void free_cell(LTE_ENODEB_API_CELL_STATUS_T* cell) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_index; i++) {
        if (cell_pool[i] == cell) {
            free(cell);
            cell_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void* update_cells(void* arg) {
    int* updates = (int*)arg;
    for (int i = 0; i < updates[0]; i++) {
        LTE_ENODEB_API_CELL_STATUS_T* cell = allocate_cell(updates[i + 1], updates[i + 2], updates[i + 3]);
        if (cell != NULL) {
            printf("Cell %d updated successfully.\n", cell->CELL_ID);
        }
    }
    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[4];
    int update_data[] = {5, 101, 201, CELL_STATUS_ACTIVE, 102, 202, CELL_STATUS_INACTIVE, 103, 203, CELL_STATUS_MAINTENANCE};
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, update_cells, (void*)update_data);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
