void initialize_aes_cipher(const char* password, int iv_length, unsigned char** key, unsigned char** iv) {
    if (!password || strlen(password) < 16) {
        fprintf(stderr, "Invalid password\n");
        exit(EXIT_FAILURE);
    }

    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        perror("Failed to generate random salt");
        exit(EXIT_FAILURE);
    }

    unsigned char* hashed_password = (unsigned char*)malloc(32);
    SHA256((unsigned char*)password, strlen(password), hashed_password);

    *key = (unsigned char*)malloc(32);
    memcpy(*key, hashed_password, 32);

    if (iv_length < MIN_IV_LENGTH || iv_length > MAX_IV_LENGTH) {
        fprintf(stderr, "Invalid IV length\n");
        exit(EXIT_FAILURE);
    }

    *iv = (unsigned char*)malloc(iv_length);
    if (RAND_bytes(*iv, iv_length) != 1) {
        perror("Failed to generate random IV");
        exit(EXIT_FAILURE);
    }
}

void cleanup(unsigned char* key, unsigned char* iv) {
    free(key);
    free(iv);
}
