import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessor {

    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

    public Map<String, String> processFilePaths(List<String> filePaths) {
        Map<String, String> fileHashes = new HashMap<>();
        for (String filePath : filePaths) {
            executorService.submit(() -> {
                try {
                    URL url = new URL(filePath);
                    byte[] fileContent = fetchFileContent(url);
                    String md5Hash = computeMD5(fileContent);
                    fileHashes.put(filePath, md5Hash);
                } catch (IOException | NoSuchAlgorithmException e) {
                    System.err.println("Error processing file: " + filePath + ". Reason: " + e.getMessage());
                }
            });
        }
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return fileHashes;
    }

    private byte[] fetchFileContent(URL url) throws IOException {
        // Simulate network call to fetch file content
        // Replace with actual implementation using a library like Apache HttpClient or OkHttp
        return new byte[0];
    }

    private String computeMD5(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executorService.shutdownNow();
    }
}
