import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class EncryptionAndUnionFind {

    public static void main(String[] args) {
        // Example usage
        int[] data = {1, 2, 3, 4, 5};
        String charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        String password = "myPassword";
        int stringLength = 10;

        long startTime = System.currentTimeMillis();
        performOperations(data, charset, password, stringLength);
        long endTime = System.currentTimeMillis();

        System.out.println("Total time taken: " + (endTime - startTime) + " ms");
    }

    public static void performOperations(int[] data, String charset, String password, int stringLength) {
        try {
            // Encryption
            SecretKey secretKey = generateSecretKey();
            byte[][] encryptedData = encryptData(data, secretKey);

            // Union-Find
            Map<Integer, Integer> disjointPairs = findDisjointPairs(data);
            for (Map.Entry<Integer, Integer> entry : disjointPairs.entrySet()) {
                String randomString = generateRandomString(charset, stringLength);
                String hash = hashPassword(password + randomString);
                System.out.println("Pair: " + Arrays.toString(new int[]{entry.getKey(), entry.getValue()}) +
                                   ", Random String: " + randomString + ", Hash: " + hash);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static SecretKey generateSecretKey() throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256); // AES-256
        return keyGen.generateKey();
    }

    private static byte[][] encryptData(int[] data, SecretKey secretKey) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[16];
        random.nextBytes(iv);
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);
        byte[][] encryptedData = new byte[data.length][];
        for (int i = 0; i < data.length; i++) {
            byte[] input = intToByteArray(data[i]);
            encryptedData[i] = cipher.update(input);
        }
        encryptedData[data.length - 1] = cipher.doFinal();

        return encryptedData;
    }

    private static Map<Integer, Integer> findDisjointPairs(int[] data) {
        UnionFind uf = new UnionFind(data.length);
        for (int i = 0; i < data.length; i++) {
            for (int j = i + 1; j < data.length; j++) {
                if (data[i] != data[j]) {
                    uf.union(i, j);
                }
            }
        }

        Map<Integer, Integer> disjointPairs = new HashMap<>();
        for (int i = 0; i < data.length; i++) {
            int root = uf.find(i);
            disjointPairs.put(root, i);
        }

        return disjointPairs;
    }

    private static String generateRandomString(String charset, int length) {
        SecureRandom random = new SecureRandom();
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            int index = random.nextInt(charset.length());
            sb.append(charset.charAt(index));
        }
        return sb.toString();
    }

    private static String hashPassword(String password) throws Exception {
        // Example using SHA-256
        java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = md.digest(password.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static byte[] intToByteArray(int value) {
        return new byte[]{
                (byte) (value >>> 24),
                (byte) (value >>> 16),
                (byte) (value >>> 8),
                (byte) value
        };
    }
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}
