typedef struct {
    int *offsets;
    int *keys;
    int **records;
    size_t capacity;
    size_t size;
} DataStructure;

DataStructure* create_data_structure(size_t initial_capacity) {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = (int*)calloc(initial_capacity, sizeof(int));
    ds->keys = (int*)calloc(initial_capacity, sizeof(int));
    ds->records = (int**)calloc(initial_capacity, sizeof(int*));
    ds->capacity = initial_capacity;
    ds->size = 0;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds);
        return NULL;
    }

    return ds;
}

void destroy_data_structure(DataStructure *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

int resize_data_structure(DataStructure *ds, size_t new_capacity) {
    int *new_offsets = (int*)realloc(ds->offsets, new_capacity * sizeof(int));
    int *new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    int **new_records = (int**)realloc(ds->records, new_capacity * sizeof(int*));

    if (!new_offsets || !new_keys || !new_records) {
        return -1;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;

    return 0;
}

int add_record(DataStructure *ds, int key, int value) {
    if (ds->size == ds->capacity) {
        if (resize_data_structure(ds, ds->capacity * 2) != 0) {
            return -1;
        }
    }

    ds->keys[ds->size] = key;
    ds->records[ds->size] = (int*)malloc(sizeof(int));
    if (!ds->records[ds->size]) {
        return -1;
    }
    *ds->records[ds->size] = value;

    ds->offsets[ds->size] = ds->size;
    ++ds->size;

    return 0;
}

void* thread_function(void *arg) {
    DataStructure *ds = (DataStructure*)arg;
    // Simulate adding records from multiple threads
    for (int i = 0; i < 1000; ++i) {
        add_record(ds, i, i * 2);
    }
    return NULL;
}

int main() {
    DataStructure *ds = create_data_structure(10);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, thread_function, ds);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_data_structure(ds);

    return 0;
}
