<?php

class RandomStringGenerator {
    public static function generate($length = 10, $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $specialChars = false) {
        if ($length <= 0 || empty($characters)) {
            return "Error: Invalid input length or character set.";
        }

        $result = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = mt_rand(0, strlen($characters) - 1);
            $result .= $characters[$randomIndex];
        }

        if ($specialChars && mt_rand(0, 1)) {
            $result .= chr(mt_rand(33, 47)); // Add a special character
        }

        return $result;
    }
}

class PasswordHasher {
    public static function hash($password, $algorithm = 'bcrypt', $cost = 12) {
        if (empty($password)) {
            return "Error: Empty password.";
        }

        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT, ['cost' => $cost]);
            case 'argon2':
                return password_hash($password, PASSWORD_ARGON2I);
            case 'sha256':
                return hash('sha256', $password);
            default:
                return "Error: Unsupported algorithm.";
        }
    }

    public static function verify($password, $hash) {
        if (empty($password) || empty($hash)) {
            return false;
        }

        return password_verify($password, $hash);
    }
}

// Example usage
$randomString = RandomStringGenerator::generate(12, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', true);
echo "Random String: " . $randomString . "\n";

$passwordHash = PasswordHasher::hash('mySecretPassword');
echo "Password Hash: " . $passwordHash . "\n";

$isValid = PasswordHasher::verify('mySecretPassword', $passwordHash);
echo "Password Valid: " . ($isValid ? 'Yes' : 'No') . "\n";
?>
