#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_TRANSACTIONS 15000

typedef struct {
    int transaction_id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_CONCURRENT_TRANSACTIONS];
    int head, tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} TransactionQueue;

void init_transaction_queue(TransactionQueue *queue) {
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

int enqueue_transaction(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->tail + 1) % MAX_CONCURRENT_TRANSACTIONS == queue->head) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->transactions[queue->tail] = transaction;
    queue->tail = (queue->tail + 1) % MAX_CONCURRENT_TRANSACTIONS;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_transaction(TransactionQueue *queue, Transaction *transaction) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    *transaction = queue->transactions[queue->head];
    queue->head = (queue->head + 1) % MAX_CONCURRENT_TRANSACTIONS;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void process_transactions(TransactionQueue *queue, double weight_threshold) {
    Transaction transaction;
    while (1) {
        dequeue_transaction(queue, &transaction);
        if (time(NULL) - transaction.timestamp > 3) {
            continue; // Skip old transactions
        }
        if (count_recent_transactions(queue, transaction.transaction_id) > 2) {
            continue; // Skip frequent transactions
        }
        if (calculate_weighted_sum(queue) > weight_threshold) {
            continue; // Skip high-weight transactions
        }
        process_transaction(transaction);
        update_metrics(transaction);
        log_transaction(transaction);
    }
}

int count_recent_transactions(TransactionQueue *queue, int transaction_id) {
    int count = 0;
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_CONCURRENT_TRANSACTIONS) {
        if (queue->transactions[i].transaction_id == transaction_id) {
            count++;
        }
    }
    return count;
}

double calculate_weighted_sum(TransactionQueue *queue) {
    double sum = 0.0;
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_CONCURRENT_TRANSACTIONS) {
        sum += queue->transactions[i].weight;
    }
    return sum;
}

void process_transaction(Transaction transaction) {
    // Process the transaction
}

void update_metrics(Transaction transaction) {
    // Update metrics
}

void log_transaction(Transaction transaction) {
    // Log the transaction details
}
