using System;
using System.Collections.Generic;
using System.Linq;

public class NetworkServiceConfig
{
    private Dictionary<string, Setting> settings = new Dictionary<string, Setting>();
    private Dictionary<string, string> environmentOverrides = new Dictionary<string, string>();

    public void AddSetting(string name, object defaultValue, object minValue, object maxValue)
    {
        if (settings.ContainsKey(name))
            throw new ArgumentException("Setting already exists.");

        settings[name] = new Setting
        {
            Name = name,
            DefaultValue = defaultValue,
            MinValue = minValue,
            MaxValue = maxValue
        };
    }

    public void UpdateSetting(string name, object value)
    {
        if (!settings.ContainsKey(name))
            throw new ArgumentException("Setting does not exist.");

        var setting = settings[name];
        if (value < setting.MinValue || value > setting.MaxValue)
            throw new ArgumentOutOfRangeException("value", "Value is out of acceptable range.");

        setting.Value = value;
    }

    public object GetSetting(string name)
    {
        if (!settings.ContainsKey(name))
            throw new ArgumentException("Setting does not exist.");

        var setting = settings[name];
        return environmentOverrides.ContainsKey(name) ? environmentOverrides[name] : setting.Value;
    }

    public void ValidateConfiguration()
    {
        foreach (var setting in settings.Values)
        {
            if (setting.Value < setting.MinValue || setting.Value > setting.MaxValue)
                throw new InvalidOperationException($"Validation error: {setting.Name} is out of acceptable range.");
        }
    }

    public override string ToString()
    {
        var validationStatus = ValidateConfiguration();
        return $"NetworkServiceConfig - Validation Status: {validationStatus}\n" +
               settings.Select(s => $"{s.Key}: {GetSetting(s.Key)}").Aggregate((a, b) => a + "\n" + b);
    }

    private class Setting
    {
        public string Name { get; set; }
        public object DefaultValue { get; set; }
        public object MinValue { get; set; }
        public object MaxValue { get; set; }
        public object Value { get; set; } = null;
    }
}
