import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class EncryptionHelper {
    private static final Map<String, SecretKeySpec> keyCache = new HashMap<>();
    private static final String ALGORITHM = "AES-256-CBC";
    private static final int KEY_SIZE = 32; // 256 bits
    private static final int IV_SIZE = 16; // 128 bits

    public static String encrypt(String data, String password) {
        try {
            SecretKeySpec key = getKey(password);
            byte[] iv = generateIV();
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv));
            byte[] encryptedData = cipher.doFinal(data.getBytes());
            return Base64.getEncoder().encodeToString(encryptedData) + ":" + Base64.getEncoder().encodeToString(iv);
        } catch (Exception e) {
            // Log error and handle failure gracefully
            System.err.println("Encryption failed: " + e.getMessage());
            return null;
        }
    }

    public static String decrypt(String encryptedData, String password) {
        try {
            String[] parts = encryptedData.split(":");
            byte[] encryptedBytes = Base64.getDecoder().decode(parts[0]);
            byte[] ivBytes = Base64.getDecoder().decode(parts[1]);
            SecretKeySpec key = getKey(password);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(ivBytes));
            return new String(cipher.doFinal(encryptedBytes));
        } catch (Exception e) {
            // Log error and handle failure gracefully
            System.err.println("Decryption failed: " + e.getMessage());
            return null;
        }
    }

    private static SecretKeySpec getKey(String password) throws Exception {
        if (!keyCache.containsKey(password)) {
            byte[] keyBytes = new byte[KEY_SIZE];
            SecureRandom.getInstanceStrong().nextBytes(keyBytes);
            keyCache.put(password, new SecretKeySpec(keyBytes, "AES"));
        }
        return keyCache.get(password);
    }

    private static byte[] generateIV() throws Exception {
        byte[] iv = new byte[IV_SIZE];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        return iv;
    }

    public static void main(String[] args) {
        String password = "mySecretPassword";
        String data = "Hello, World!";
        String encrypted = encrypt(data, password);
        System.out.println("Encrypted: " + encrypted);
        String decrypted = decrypt(encrypted, password);
        System.out.println("Decrypted: " + decrypted);
    }
}
