import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;
import java.util.stream.Collectors;

public class PokemonReportGenerator {

    private static final int MAX_CONCURRENT_REQUESTS = 1000;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long BACKOFF_INITIAL_DELAY = 500L;
    private static final long BACKOFF_MULTIPLIER = 2;

    private final ExecutorService executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    private final Map<String, Pokemon> cache = new ConcurrentHashMap<>();
    private final PokemonApiClient apiClient;

    public PokemonReportGenerator(PokemonApiClient apiClient) {
        this.apiClient = apiClient;
    }

    public List<PokemonReport> generateReports(List<String> pokemonNames) throws InterruptedException, ExecutionException {
        CompletionService<PokemonReport> completionService = new ExecutorCompletionService<>(executorService);

        for (String name : pokemonNames) {
            completionService.submit(() -> fetchAndGenerateReport(name));
        }

        List<PokemonReport> reports = new ArrayList<>();
        for (int i = 0; i < pokemonNames.size(); i++) {
            Future<PokemonReport> future = completionService.take();
            reports.add(future.get());
        }

        return reports;
    }

    private PokemonReport fetchAndGenerateReport(String name) throws InterruptedException, ExecutionException {
        Pokemon pokemon = cache.computeIfAbsent(name, this::fetchPokemon);
        if (pokemon == null) {
            throw new IllegalArgumentException("Unknown Pokemon: " + name);
        }
        return generateReport(pokemon);
    }

    private Pokemon fetchPokemon(String name) {
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            try {
                return apiClient.getPokemon(name);
            } catch (Exception e) {
                if (attempt == RETRY_ATTEMPTS - 1) {
                    throw new RuntimeException("Failed to fetch Pokemon data after " + RETRY_ATTEMPTS + " attempts", e);
                }
                long backoff = BACKOFF_INITIAL_DELAY * Math.pow(BACKOFF_MULTIPLIER, attempt);
                Thread.sleep(backoff);
            }
        }
        return null;
    }

    private PokemonReport generateReport(Pokemon pokemon) {
        // Generate report based on Pokemon's weaknesses, resistances, and immunities
        return new PokemonReport(pokemon.getName(), pokemon.getWeaknesses(), pokemon.getResistances(), pokemon.getImmunities());
    }

    public static class PokemonReport {
        private final String name;
        private final List<String> weaknesses;
        private final List<String> resistances;
        private final List<String> immunities;

        public PokemonReport(String name, List<String> weaknesses, List<String> resistances, List<String> immunities) {
            this.name = name;
            this.weaknesses = weaknesses;
            this.resistances = resistances;
            this.immunities = immunities;
        }

        // Getters and toString method
    }
}

interface PokemonApiClient {
    Pokemon getPokemon(String name) throws Exception;
}

