void* processNFAPI(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    // Simulate processing
    printf("Processing PDU with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
    return NULL;
}

void processAndConfigureNFAPI(int maxTasks) {
    pthread_t threads[MAX_CONCURRENT_TASKS];
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_CONCURRENT_TASKS];

    // Initialize environment variables and load vendor autoloader
    setenv("APP_ENV", "production", 1);
    system("php -r 'require_once __DIR__ . \"/vendor/autoload.php\";");

    // Load configuration file dynamically
    void* config = dlopen("./config.so", RTLD_LAZY);
    if (!config) {
        fprintf(stderr, "Failed to load config library: %s\n", dlerror());
        return;
    }

    // Simulate NFAPI processing tasks
    for (int i = 0; i < maxTasks; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 1000;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        if (pthread_create(&threads[i], NULL, processNFAPI, &pdus[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < maxTasks; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up and close configuration library
    dlclose(config);
}

int main(int argc, char* argv[]) {
    int maxTasks = MAX_CONCURRENT_TASKS;
    if (argc > 1) {
        maxTasks = atoi(argv[1]);
    }
    processAndConfigureNFAPI(maxTasks);
    return 0;
}
