#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_COLLECTION_T;

NFAPI_COLLECTION_T* nfaapi_collection_init() {
    NFAPI_COLLECTION_T *collection = (NFAPI_COLLECTION_T*)malloc(sizeof(NFAPI_COLLECTION_T));
    if (!collection) return NULL;
    collection->data = NULL;
    collection->capacity = 0;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void nfaapi_collection_add(NFAPI_COLLECTION_T *collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    collection->data[collection->size++] = pdu;
    pthread_mutex_unlock(&collection->mutex);
}

void nfaapi_collection_update(NFAPI_COLLECTION_T *collection, uint16_t RX_UE_INFORMATION_TAG, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (collection->data[i].RNTI != pdu.RNTI) {
                pthread_mutex_unlock(&collection->mutex);
                return;
            }
            collection->data[i] = pdu;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void nfaapi_collection_remove(NFAPI_COLLECTION_T *collection, uint16_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            memmove(&collection->data[i], &collection->data[i + 1], (collection->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --collection->size;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void nfaapi_collection_free(NFAPI_COLLECTION_T *collection) {
    if (collection->data) free(collection->data);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int nfaapi_collection_serialize(const NFAPI_COLLECTION_T *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;
    fwrite(&collection->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->size; ++i) {
        fwrite(&collection->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
    return 0;
}

int nfaapi_collection_deserialize(NFAPI_COLLECTION_T *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    if (size > MAX_RNTI) {
        fclose(file);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(collection->data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fclose(file);
        return -1;
    }
    collection->data = new_data;
    collection->capacity = size;
    for (size_t i = 0; i < size; ++i) {
        fread(&collection->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
    collection->size = size;
    return 0;
}
