#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_LIST;

void init_crc_list(CRC_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_to_crc_list(CRC_LIST *list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->ue_info_tag = ue_info_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_node->crcflag = crcflag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_from_crc_list(CRC_LIST *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;

    while (current != NULL && current->rnti != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

void destroy_crc_list(CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
