#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_RACH_REQUEST_PDU_T {
    RACH_CONFIG_PRACH config;
    RACH_REQUEST_T request;
    uint8_t* preambleBuffer;
    size_t bufferLength;
} NFAPI_RACH_REQUEST_PDU_T;

typedef struct RequestNode {
    NFAPI_RACH_REQUEST_PDU_T data;
    struct RequestNode* next;
} RequestNode;

typedef struct RequestList {
    RequestNode* head;
    pthread_mutex_t lock;
    size_t count;
    size_t maxRequests;
    uint32_t maxProcessingTime;
} RequestList;

void initRequestList(RequestList* list, size_t maxRequests, uint32_t maxProcessingTime) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->maxRequests = maxRequests;
    list->maxProcessingTime = maxProcessingTime;
}

void addRequest(RequestList* list, NFAPI_RACH_REQUEST_PDU_T request) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->maxRequests) {
        // Handle error or limit exceeded
        pthread_mutex_unlock(&list->lock);
        return;
    }
    RequestNode* newNode = (RequestNode*)malloc(sizeof(RequestNode));
    newNode->data = request;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void removeRequest(RequestList* list, NFAPI_RACH_REQUEST_PDU_T request) {
    pthread_mutex_lock(&list->lock);
    RequestNode* current = list->head;
    RequestNode* prev = NULL;
    while (current != NULL) {
        if (current->data == request) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void processRequests(RequestList* list) {
    pthread_mutex_lock(&list->lock);
    RequestNode* current = list->head;
    while (current != NULL) {
        // Process each request
        // Ensure processing time does not exceed maxProcessingTime
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyRequestList(RequestList* list) {
    pthread_mutex_lock(&list->lock);
    RequestNode* current = list->head;
    while (current != NULL) {
        RequestNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
