#define MAX_ELEMENTS 1000
#define COOLDOWN_SECONDS 9

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crcList[MAX_ELEMENTS];
int listSize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int stopCooldown = 0;

void* cooldownThread(void* arg) {
    time_t start = time(NULL);
    while (time(NULL) - start < COOLDOWN_SECONDS && !stopCooldown) {
        int action = rand() % 2;
        if (action == 0) {
            pthread_mutex_lock(&mutex);
            if (listSize < MAX_ELEMENTS) {
                NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                newElement->RX_UE_INFORMATION_TAG = rand() % 100;
                newElement->RNTI = rand() % 1000;
                newElement->CRCFLAG = rand() % 2;
                crcList[listSize++] = newElement;
            }
            pthread_mutex_unlock(&mutex);
        } else {
            printf("Stopping cooldown\n");
            stopCooldown = 1;
        }
        sleep(1);
    }
    return NULL;
}

void populateNFACRCList() {
    srand(time(NULL));
    pthread_t thread;
    pthread_create(&thread, NULL, cooldownThread, NULL);

    while (listSize < MAX_ELEMENTS && !stopCooldown) {
        NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newElement->RX_UE_INFORMATION_TAG = rand() % 100;
        newElement->RNTI = rand() % 1000;
        newElement->CRCFLAG = rand() % 2;
        pthread_mutex_lock(&mutex);
        crcList[listSize++] = newElement;
        pthread_mutex_unlock(&mutex);
    }

    pthread_join(thread, NULL);

    for (int i = 0; i < listSize; i++) {
        free(crcList[i]);
    }
}
