#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>

#define MAX_LIST_SIZE 1024
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    char RX_UE_INFORMATION_TAG[64];
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
} NetworkStruct;

typedef struct {
    NetworkStruct *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NetworkList;

int resolveDNS(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ip_address, ipstr);
        break; // we're done
    }

    freeaddrinfo(res); // all done with this structure

    return 0;
}

int initNetworkList(NetworkList *list) {
    list->data = (NetworkStruct *)malloc(MAX_LIST_SIZE * sizeof(NetworkStruct));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    list->size = 0;
    list->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void destroyNetworkList(NetworkList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

int addToList(NetworkList *list, const NetworkStruct *newItem) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        fprintf(stderr, "List is full\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(&list->data[list->size], newItem, sizeof(NetworkStruct));
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void logEvent(int level, const char *message) {
    if (level == LOG_LEVEL_DEBUG) {
        printf("DEBUG: %s\n", message);
    } else if (level == LOG_LEVEL_INFO) {
        printf("INFO: %s\n", message);
    }
}
