#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define a structure to hold HTTP request details
typedef struct {
    char *url;
    char *method;
    char **headers;
    int header_count;
    void *data;
    size_t data_size;
} HttpRequest;

// Define a structure to hold HTTP response details
typedef struct {
    char *body;
    size_t body_size;
    CURLcode result;
} HttpResponse;

// Callback function for receiving data from the server
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    HttpResponse *response = (HttpResponse *)userp;
    response->body = realloc(response->body, response->body_size + realsize + 1);
    if (response->body == NULL) {
        // Handle memory allocation failure
        return 0;
    }
    memcpy(&(response->body[response->body_size]), contents, realsize);
    response->body_size += realsize;
    response->body[response->body_size] = '\0';
    return realsize;
}

// Function to perform an HTTP request asynchronously
HttpResponse *perform_http_request(HttpRequest *request) {
    CURL *curl;
    CURLcode res;
    HttpResponse *response;

    // Initialize the response structure
    response = (HttpResponse *)malloc(sizeof(HttpResponse));
    if (response == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    response->body = NULL;
    response->body_size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, request->url);
        curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, request->method);

        // Set custom headers
        for (int i = 0; i < request->header_count; i++) {
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, request->headers[i]));
        }

        // Set data to send with the request
        if (request->data != NULL) {
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, request->data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, request->data_size);
        }

        // Set callback function for receiving response data
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)response);

        // Perform the request
        res = curl_easy_perform(curl);

        // Check for errors
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        // Clean up
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return response;
}

// Example usage
int main() {
    HttpRequest request = {
        .url = "https://api.example.com/data",
        .method = "GET",
        .headers = (char *[]){"Authorization: Bearer YOUR_TOKEN", NULL},
        .header_count = 1,
        .data = NULL,
        .data_size = 0
    };

    HttpResponse *response = perform_http_request(&request);
    if (response != NULL) {
        printf("Response body: %s\n", response->body);
        free(response->body);
        free(response);
    }

    return 0;
}
```

This code provides a basic structure for performing HTTP requests asynchronously using libcurl in C. It includes error handling, custom headers, and a callback function to handle the response data. The example usage demonstrates how to set up an HTTP GET request with an authorization header. You can extend this code to support other HTTP methods, additional headers, and more complex request structures as needed for your specific API.']

