#define MAX_LIST_SIZE 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) {
        // Evict least recently used entry
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->size--;
    }

    Node* new_node = create_node(data);
    if (new_node == NULL) {
        return -1; // Memory allocation failed
    }

    if (list->tail != NULL) {
        list->tail->next = new_node;
    }
    list->tail = new_node;

    if (list->head == NULL) {
        list->head = new_node;
    }

    list->size++;
    return 0;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

// Example usage
int main() {
    List crc_list;
    init_list(&crc_list);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Populate pdu with data

    if (add_to_list(&crc_list, pdu) == 0) {
        // Successfully added to list
    } else {
        // Handle error
    }

    free_list(&crc_list);
    return 0;
}
```

