#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the network interface configuration structure
typedef struct {
    char *name;
    int ip_address;
    // Add other fields as needed
} NetworkInterfaceConfig;

// Define the dynamic array structure
typedef struct {
    NetworkInterfaceConfig **configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NetworkInterfaceArray;

// Initialize the dynamic array
void network_interface_array_init(NetworkInterfaceArray *array) {
    array->configs = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

// Add a configuration to the dynamic array
void network_interface_array_add(NetworkInterfaceArray *array, NetworkInterfaceConfig *config) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        NetworkInterfaceConfig **new_configs = realloc(array->configs, new_capacity * sizeof(NetworkInterfaceConfig *));
        if (new_configs == NULL) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->configs = new_configs;
        array->capacity = new_capacity;
    }
    array->configs[array->count++] = config;
    pthread_mutex_unlock(&array->mutex);
}

// Remove a configuration from the dynamic array
void network_interface_array_remove(NetworkInterfaceArray *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    free(array->configs[index]);
    for (size_t i = index; i < array->count - 1; ++i) {
        array->configs[i] = array->configs[i + 1];
    }
    array->count--;
    pthread_mutex_unlock(&array->mutex);
}

// Free the dynamic array and its contents
void network_interface_array_free(NetworkInterfaceArray *array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        free(array->configs[i]);
    }
    free(array->configs);
    array->configs = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

// Serialize the dynamic array to a file
void network_interface_array_serialize(NetworkInterfaceArray *array, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&array->mutex);
    fprintf(file, "%zu\n", array->count);
    for (size_t i = 0; i < array->count; ++i) {
        fprintf(file, "%s %d\n", array->configs[i]->name, array->configs[i]->ip_address);
    }
    pthread_mutex_unlock(&array->mutex);
    fclose(file);
}

// Deserialize the dynamic array from a file
void network_interface_array_deserialize(NetworkInterfaceArray *array, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    pthread_mutex_lock(&array->mutex);
    size_t count;
    fscanf(file, "%zu\n", &count);
    network_interface_array_init(array);
    array->capacity = count;
    array->configs = malloc(count * sizeof(NetworkInterfaceConfig *));
    if (array->configs == NULL) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&array->mutex);
        fclose(file);
        return;
    }
    for (size_t i = 0; i < count; ++i) {
        NetworkInterfaceConfig *config = malloc(sizeof(NetworkInterfaceConfig));
        if (config == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&array->mutex);
            fclose(file);
            return;
        }
        fscanf(file, "%ms %d\n", &config->name, &config->ip_address);
        array->configs[i] = config;
    }
    array->count = count;
    pthread_mutex_unlock(&array->mutex);
    fclose(file);
}
