#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <condition_variable>

class Preference {
public:
    std::string key;
    std::string defaultValue;
    std::string currentValue;
    std::string dataType;
    bool configurable;
    bool persistent;
    bool deprecated;

    Preference(std::string k, std::string dv, std::string dt, bool c, bool p, bool d)
        : key(k), defaultValue(dv), currentValue(dv), dataType(dt), configurable(c), persistent(p), deprecated(d) {}
};

class PreferenceManager {
private:
    std::map<std::string, Preference> preferences;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void setPreference(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex);
        if (preferences.find(key) != preferences.end()) {
            preferences[key].currentValue = value;
            cv.notify_all();
        }
    }

    std::string getPreference(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (preferences.find(key) != preferences.end()) {
            return preferences[key].currentValue;
        }
        return "";
    }

    void addPreference(const Preference& pref) {
        std::lock_guard<std::mutex> lock(mutex);
        preferences[pref.key] = pref;
    }

    void removePreference(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (preferences.find(key) != preferences.end()) {
            preferences.erase(key);
            cv.notify_all();
        }
    }

    void waitForChange() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !preferences.empty(); });
    }
};

int main() {
    PreferenceManager manager;
    manager.addPreference(Preference("theme", "light", "string", true, true, false));
    manager.setPreference("theme", "dark");
    std::cout << "Current theme: " << manager.getPreference("theme") << std::endl;

    manager.waitForChange();
    return 0;
}
