import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class LogProcessor {

    private static final int MAX_MEMORY_USAGE = 1024 * 1024 * 5; // 5 MB
    private static final SimpleDateFormat TIMESTAMP_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    private ConcurrentHashMap<String, String> cache;
    private long currentMemoryUsage;

    public LogProcessor() {
        this.cache = new ConcurrentHashMap<>();
        this.currentMemoryUsage = 0;
    }

    public void processLogFile(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                processLine(line);
            }
        } catch (IOException e) {
            handleFileReadException(e);
        }
    }

    private void processLine(String line) {
        if (currentMemoryUsage + estimateMemoryUsage(line) > MAX_MEMORY_USAGE) {
            flushCache();
        }
        String timestamp = TIMESTAMP_FORMAT.format(new Date());
        String processedLine = timestamp + " " + line.toUpperCase();
        cache.put(processedLine, processedLine);
        currentMemoryUsage += estimateMemoryUsage(processedLine);
    }

    private int estimateMemoryUsage(String line) {
        return (int) (line.length() * 2); // Approximate memory usage for string storage
    }

    private void flushCache() {
        cache.forEach((key, value) -> executorService.submit(() -> sendToExternalLoggingService(value)));
        currentMemoryUsage = 0;
        cache.clear();
    }

    private void handleFileReadException(IOException e) {
        // Log the exception or take appropriate action
        System.err.println("Error reading file: " + e.getMessage());
    }

    private void sendToExternalLoggingService(String logEntry) {
        // Code to asynchronously send log entry to external logging service
        System.out.println("Sending log entry to external service: " + logEntry);
    }
}
