typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} CRC_List;

void init_crc_list(CRC_List *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

void free_crc_list(CRC_List *list) {
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
        list->size = 0;
        list->capacity = 0;
    }
}

int add_to_crc_list(CRC_List *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == RNTI) {
            fprintf(stderr, "Duplicate RNTI detected\n");
            return -1;
        }
    }

    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->size++;

    return 0;
}

int main() {
    CRC_List crc_list;
    init_crc_list(&crc_list);

    srand(time(NULL));
    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        int RX_UE_INFORMATION_TAG = rand();
        int RNTI = rand();
        if (add_to_crc_list(&crc_list, RX_UE_INFORMATION_TAG, RNTI) != 0) {
            break;
        }
    }

    free_crc_list(&crc_list);
    return 0;
}
