typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, int crc_flag) {
    pthread_mutex_lock(&list->mutex);

    // Check for duplicate RNTI
    for (size_t i = 0; i < list->count; ++i) {
        if (list->list[i].rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate RNTI found
        }
    }

    // Resize the list if necessary
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Add the new CRC indication
    list->list[list->count].ue_info_tag = ue_info_tag;
    list->list[list->count].rnti = rnti;
    list->list[list->count].crc_indication_rel8_tag.CRCFLAG = crc_flag;
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int validate_crc_flags(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        // Perform CRC flag validation logic here
        // Example: Check if the CRC flag is consistent with the data in ue_info_tag and rnti
        if (!is_crc_flag_valid(list->list[i].ue_info_tag, list->list[i].rnti, list->list[i].crc_indication_rel8_tag.CRCFLAG)) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // CRC flag validation failed
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

