    } else if (strcmp(cipherMode, "EDE3") == 0) {
        cipher = EVP_aes_192_cbc();
    } else if (strcmp(cipherMode, "CFB") == 0) {
        cipher = EVP_aes_256_cfb();
    } else if (strcmp(cipherMode, "NULL") == 0) {
        return NULL;
    }

    if (!cipher) return NULL;

    for (int i = 0; i < N; ++i) {
        pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
