typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

uint32_t rollingChecksum(uint32_t previousChecksum, uint32_t newTag) {
    return (previousChecksum + newTag) % 0xFFFFFFFF;
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateNFAPDUList(size_t N) {
    if (N == 0 || N > 1000000) {
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    uint32_t checksum = 0;
    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand();

        if (i > 0 && list[i].RNTI == list[i - 1].RNTI) {
            free(list);
            return NULL; // Duplicate RNTI detected
        }

        checksum = rollingChecksum(checksum, list[i].RX_UE_INFORMATION_TAG);
        checksum = rollingChecksum(checksum, list[i].RNTI);

        if (checksum % 2 == 0) {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }

    return list;
}

void freeNFAPDUList(NFAPI_CRC_INDICATION_PDU_T* list, size_t N) {
    if (list) {
        free(list);
    }
}
