["```javascript
const fs = require('fs');
const path = require('path');

async function processFiles(directory, extension) {
  const results = [];
  const stream = fs.createReadStream(directory);

  return new Promise((resolve, reject) => {
    let buffer = '';
    stream.on('data', (chunk) => {
      buffer += chunk.toString();
      while (true) {
        const index = buffer.indexOf(`.${extension}`);
        if (index === -1) break;
        const endIndex = buffer.indexOf('\n', index);
        if (endIndex === -1) break;
        results.push(buffer.slice(index, endIndex + 1));
        buffer = buffer.slice(endIndex + 1);
      }
    });

    stream.on('end', () => {
      resolve(results);
    });

    stream.on('error', (err) => {
      reject(err);
    });
  });
}

// Example usage:
processFiles('/path/to/directory', 'txt')
  .then((files) => {
    console.log(files);
  })
  .catch((err) => {
    console.error(err);
  });
```

This code snippet demonstrates how to asynchronously process files from a specified directory, filtering them based on a specific extension. It uses Node.js's `fs` module to create a readable stream of the directory and processes the data in chunks. The function returns a promise that resolves with an array of file names matching the specified extension. This approach ensures efficient memory usage by processing large files in chunks and dynamically adapting to varying file sizes and types."]

