    NFAPI_L1_RX_PDU_T* pdu = (NFAPI_L1_RX_PDU_T*)arg;
    // Simulate symbol processing
    for (int i = 0; i < MAX_SYMBOLS; i++) {
        pdu->received_symbols[pdu->symbol_count++] = i % 256;
    }
    return NULL;
}

void configure_thread_pool(NFAPI_L1_RX_PDU_T** pdus, int N) {
    pthread_t* threads = (pthread_t*)malloc(N * sizeof(pthread_t));
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, process_symbols, &(*pdus)[i]);
    }
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

