#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RANGE 1000
#define MIN_RANGE -1000

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
    sem_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    sem_init(&array->lock, 0, 1);
}

void freeDynamicArray(DynamicArray *array) {
    sem_wait(&array->lock);
    if (array->data != NULL) {
        free(array->data);
        array->data = NULL;
    }
    sem_post(&array->lock);
    sem_destroy(&array->lock);
}

int addToArray(DynamicArray *array, int value) {
    sem_wait(&array->lock);
    if (value < MIN_RANGE || value > MAX_RANGE) {
        sem_post(&array->lock);
        return -1;
    }
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        int *new_data = realloc(array->data, new_capacity * sizeof(int));
        if (new_data == NULL) {
            sem_post(&array->lock);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = value;
    sem_post(&array->lock);
    return 0;
}

int getMaxValue(DynamicArray *array) {
    sem_wait(&array->lock);
    if (array->size == 0) {
        sem_post(&array->lock);
        return -1; // No valid values
    }
    int max_value = array->data[0];
    for (size_t i = 1; i < array->size; ++i) {
        if (array->data[i] > max_value) {
            max_value = array->data[i];
        }
    }
    sem_post(&array->lock);
    return max_value;
}

void *monitorDataFeed(void *arg) {
    // Simulate data feed monitoring
    while (1) {
        // Check for disconnections and notify main logic
        sleep(1); // Placeholder for actual monitoring logic
    }
    return NULL;
}

int main() {
    DynamicArray array;
    initDynamicArray(&array);

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitorDataFeed, &array) != 0) {
        fprintf(stderr, "Failed to create monitor thread\n");
        freeDynamicArray(&array);
        return EXIT_FAILURE;
    }

    // Simulate adding values from data feed
    for (int i = -1500; i <= 1500; ++i) {
        if (addToArray(&array, i) != 0) {
            fprintf(stderr, "Failed to add value %d\n", i);
        }
    }

    int max_value = getMaxValue(&array);
    printf("Max value: %d\n", max_value);

    freeDynamicArray(&array);
    pthread_join(monitor_thread, NULL);
    return EXIT_SUCCESS;
}
