typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t N) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->allocated_size = N;
    list->used_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < N; ++i) {
        list->data[i].RX_UE_INFORMATION_TAG = rand();
        list->data[i].RNTI = rand();
        list->data[i].CRC_INDICATION_REL8_TAG = rand();
        list->data[i].CRCFLAG = rand() % 2;
    }

    return list;
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
