typedef struct {
    int CRCFLAG;
    // Other fields as per NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t capacity;
} List;

void initList(List* list) {
    list->head = NULL;
    list->count = 0;
    list->capacity = 16; // Initial capacity
}

void freeList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    list->capacity = 16; // Reset capacity
}

void addElement(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        Node** newNodes = realloc(list->head, list->capacity * sizeof(Node));
        if (newNodes == NULL) {
            // Handle memory allocation failure
            return;
        }
        list->head = newNodes;
    }

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

void removeElement(List* list, size_t index) {
    if (index >= list->count) {
        return; // Index out of bounds
    }

    Node* current = list->head;
    Node* prev = NULL;

    for (size_t i = 0; i < index; i++) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;
}

void refreshList(List* list, ExternalDataSource* dataSource) {
    // Implement logic to fetch updated RNTI values from the external data source
    // Update the CRCFLAG for each element in the list while ensuring no two consecutive elements have the same CRCFLAG value
    // Handle synchronization and periodic data refreshes
}

void optimizeMemory(List* list) {
    if (list->count * 4 < list->capacity) {
        list->capacity /= 2;
        Node** newNodes = realloc(list->head, list->capacity * sizeof(Node));
        if (newNodes == NULL) {
            // Handle memory allocation failure
            return;
        }
        list->head = newNodes;
    }
}
