#define MAX_RNTI 4095

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list[MAX_RAN];
} NFAPI_CRC_INDICATION_LIST_T;

void initialize_ran_configurations(NFAPI_CRC_INDICATION_LIST_T *ran_configs) {
    // Initialize RAN configurations here
}

int validate_rnti(int rnti, int ran_id) {
    // Validate RNTI for the given RAN ID
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int ran_id) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    pdu->RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
    while (!validate_rnti(pdu->RNTI, ran_id)) {
        pdu->RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
    }
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void* create_ran_pdu_thread(void *arg) {
    NFAPI_CRC_INDICATION_LIST_T *ran_configs = (NFAPI_CRC_INDICATION_LIST_T *)arg;
    int ran_id = pthread_self() % MAX_RAN;

    pthread_mutex_lock(&ran_configs->mutex);
    if (ran_configs->pdu_list[ran_id] == NULL) {
        ran_configs->pdu_list[ran_id] = create_crc_indication_pdu(ran_id);
        // Log creation of PDU for auditing
    }
    pthread_mutex_unlock(&ran_configs->mutex);

    return NULL;
}

void initialize_ran_pdu_list(NFAPI_CRC_INDICATION_LIST_T *ran_configs, int num_threads) {
    pthread_t threads[num_threads];
    srand(time(NULL));

    initialize_ran_configurations(ran_configs);
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, create_ran_pdu_thread, ran_configs);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log completion of PDU creation
}

void cleanup_ran_pdu_list(NFAPI_CRC_INDICATION_LIST_T *ran_configs) {
    for (int i = 0; i < MAX_RAN; i++) {
        if (ran_configs->pdu_list[i] != NULL) {
            free(ran_configs->pdu_list[i]);
            ran_configs->pdu_list[i] = NULL;
        }
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T ran_configs;
    pthread_mutex_init(&ran_configs.mutex, NULL);

    initialize_ran_pdu_list(&ran_configs, 10);
    // Perform operations with the PDU list
    cleanup_ran_pdu_list(&ran_configs);

    pthread_mutex_destroy(&ran_configs.mutex);
    return 0;
}
