#define MAX_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_SIZE];
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicList *list, size_t index) {
    if (index >= list->count) {
        return NULL; // Index out of bounds
    }
    return list->elements[index];
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
