#include <time.h>

typedef struct {
    int key;
    int value;
} record;

void initialize_records(record **records, int *size) {
    printf("Enter the number of records: ");
    scanf("%d", size);
    *records = (record *)malloc(*size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void populate_records(record *records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }
}

void sort_records(record *records, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (records[j].key > records[j + 1].key) {
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void update_values(record *records, int size, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void print_records(record *records, int size) {
    for (int i = 0; i < size; i++) {
        printf("Key: %d, Value: %d\n", records[i].key, records[i].value);
    }
}

int main() {
    record *records;
    int size;

    initialize_records(&records, &size);
    populate_records(records, size);
    sort_records(records, size);

    printf("Records before update:\n");
    print_records(records, size);

    int min_value, max_value;
    printf("Enter the minimum and maximum values for updating: ");
    scanf("%d %d", &min_value, &max_value);
    update_values(records, size, min_value, max_value);

    printf("Records after update:\n");
    print_records(records, size);

    free(records);
    return 0;
}
