    if (new_user == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_user->id = id;
    strcpy(new_user->name, name);
    strcpy(new_user->email, email);
    strcpy(new_user->password, password);
    new_user->next = NULL;
    return new_user;
}

void update_user(User* user, const char* name, const char* email, const char* password) {
    if (user != NULL) {
        if (name != NULL) strcpy(user->name, name);
        if (email != NULL) strcpy(user->email, email);
        if (password != NULL) strcpy(user->password, password);
    }
}

void delete_user(User** user) {
    if (*user != NULL) {
        free(*user);
        *user = NULL;
    }
}
