<?php
// PHP code for managing user account database

class UserAccountManager {
    private $users;

    public function __construct() {
        $this->users = [];
    }

    public function createUser($id, $name, $email, $password) {
        if (!isset($this->users[$id])) {
            $this->users[$id] = [
                'name' => $name,
                'email' => $email,
                'password' => $password
            ];
            return true;
        }
        return false;
    }

    public function updateUser($id, $name = null, $email = null, $password = null) {
        if (isset($this->users[$id])) {
            if ($name !== null) $this->users[$id]['name'] = $name;
            if ($email !== null) $this->users[$id]['email'] = $email;
            if ($password !== null) $this->users[$id]['password'] = $password;
            return true;
        }
        return false;
    }

    public function deleteUser($id) {
        if (isset($this->users[$id])) {
            unset($this->users[$id]);
            return true;
        }
        return false;
    }
}

// Example usage
