    return manager;
}

void network_manager_add_interface(NetworkManager *manager, NetworkInterfaceConfig config) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        manager->interfaces = realloc(manager->interfaces, manager->capacity + CHUNK_SIZE);
        manager->crc_indications = realloc(manager->crc_indications, manager->capacity + CHUNK_SIZE);
        manager->capacity += CHUNK_SIZE;
    }
    manager->interfaces[manager->count] = config;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void network_manager_update_crc(NetworkManager *manager, NFAPI_CRC_INDICATION_PDU_T indication) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        manager->interfaces = realloc(manager->interfaces, manager->capacity + CHUNK_SIZE);
        manager->crc_indications = realloc(manager->crc_indications, manager->capacity + CHUNK_SIZE);
        manager->capacity += CHUNK_SIZE;
    }
    manager->crc_indications[manager->count] = indication;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void network_manager_free(NetworkManager *manager) {
    free(manager->interfaces);
    free(manager->crc_indications);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
