#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define MESSAGE_SIZE 256

typedef struct {
    long timestamp;
    double measurement;
    char message[MESSAGE_SIZE];
} log_entry;

void load_log_data(log_entry **entries, int *num_entries) {
    FILE *file = fopen("log_data.csv", "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    *num_entries = 0;
    while (*num_entries < MAX_ENTRIES && fgets(entries[*num_entries]->message, MESSAGE_SIZE, file)) {
        char *timestamp_str = strtok(entries[*num_entries]->message, ",");
        char *measurement_str = strtok(NULL, ",");

        if (timestamp_str && measurement_str) {
            entries[*num_entries]->timestamp = atol(timestamp_str);
            entries[*num_entries]->measurement = atof(measurement_str);
            snprintf(entries[*num_entries]->message, MESSAGE_SIZE, "Timestamp: %ld, Measurement: %.2f", entries[*num_entries]->timestamp, entries[*num_entries]->measurement);
        }

        (*num_entries)++;
    }

    fclose(file);
}

void initialize_log_data(log_entry **entries, int *num_entries) {
    srand(time(NULL));
    *num_entries = 0;

    while (*num_entries < MAX_ENTRIES) {
        entries[*num_entries] = (log_entry *)malloc(sizeof(log_entry));
        if (!entries[*num_entries]) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        entries[*num_entries]->timestamp = time(NULL);
        entries[*num_entries]->measurement = ((double)rand() / RAND_MAX) * 100.0; // Random measurement between 0 and 100
        snprintf(entries[*num_entries]->message, MESSAGE_SIZE, "Timestamp: %ld, Measurement: %.2f", entries[*num_entries]->timestamp, entries[*num_entries]->measurement);

        (*num_entries)++;
    }
}

void free_log_data(log_entry **entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(entries[i]);
    }
}

int main() {
    log_entry *entries[MAX_ENTRIES];
    int num_entries;

    initialize_log_data(entries, &num_entries);
    // Alternatively, load_log_data(entries, &num_entries);

    for (int i = 0; i < num_entries; i++) {
        printf("Entry %d: %s\n", i, entries[i]->message);
    }

    free_log_data(entries, num_entries);

    return 0;
}
