#define MAX_SIZE 1000
#define MIN_VALUE -1000
#define MAX_VALUE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int process_stream(int *buffer, int *count, pthread_mutex_t *mutex) {
    int input;
    while (scanf("%d", &input) != EOF) {
        if (pthread_mutex_lock(mutex) != 0) {
            perror("Mutex lock failed");
            return -1;
        }
        if (*count < MAX_SIZE && input >= MIN_VALUE && input <= MAX_VALUE) {
            buffer[*count] = input;
            (*count)++;
        } else if (input < MIN_VALUE || input > MAX_VALUE) {
            fprintf(stderr, "Error: Input %d out of range\n", input);
        }
        pthread_mutex_unlock(mutex);
    }
    return 0;
}

void find_and_print_largest(int *buffer, int count) {
    if (count == 0) {
        printf("No valid integers found.\n");
        return;
    }
    int largest = buffer[0];
    for (int i = 1; i < count; i++) {
        if (buffer[i] > largest) {
            largest = buffer[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

int main() {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int *buffer = malloc(MAX_SIZE * sizeof(int));
    if (buffer == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int count = 0;
    process_stream(buffer, &count, &mutex);
    find_and_print_largest(buffer, count);

    free(buffer);
    pthread_mutex_destroy(&mutex);

    return 0;
}
