#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    int checksum;
} NFAPI_CRC_ARRAY_T;

void init_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    array->array = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->checksum = 0;
}

int add_to_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->count++] = element;
    array->checksum += element.CRC_INDICATION_REL8_TAG;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void validate_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    int expected_checksum = 0;
    for (size_t i = 0; i < array->count; i++) {
        expected_checksum += array->array[i].CRC_INDICATION_REL8_TAG;
    }
    if (expected_checksum != array->checksum) {
        fprintf(stderr, "Checksum validation failed. Terminating gracefully.\n");
        exit(EXIT_FAILURE);
    }
}

void free_nfaapi_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

int main() {
    NFAPI_CRC_ARRAY_T array;
    init_nfaapi_crc_array(&array);

    // Example usage
    for (size_t i = 0; i < MAX_ELEMENTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T element = {i, i * 10, rand() % 2};
        if (add_to_nfaapi_crc_array(&array, element) != 0) {
            fprintf(stderr, "Failed to add element to array.\n");
            break;
        }
    }

    validate_nfaapi_crc_array(&array);
    free_nfaapi_crc_array(&array);

    return 0;
}
