        total_rnti += (*array)[i].RNTI;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Example initialization

        // Probabilistic CRCFLAG based on network load and latency
        int network_load = rand() % 100; // Simulated network load percentage
        int latency = rand() % 100; // Simulated latency in milliseconds
        (*array)[i].CRCFLAG = (network_load < 50 && latency < 20) ? 1 : 0;

        // Logging for performance monitoring
