} CRCArray;

CRCArray* create_crc_array(size_t initial_capacity) {
    CRCArray *array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(CRCArray *array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->array);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int resize_crc_array(CRCArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->mutex);

    if (new_capacity <= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    array->array = new_array;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int add_to_crc_array(CRCArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        int result = resize_crc_array(array, array->capacity * 2);
        if (result != 0) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }

    array->array[array->size++] = item;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}
