    list->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        perror("Failed to allocate memory for CRC list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

bool is_valid_tag(int tag, int min_value, int max_value) {
    return tag >= min_value && tag <= max_value;
}

void add_crc_indication(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu, int tag_min, int tag_max) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Failed to reallocate memory for CRC list");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    if (is_valid_tag(pdu.RX_UE_INFORMATION_TAG, tag_min, tag_max) && is_valid_tag(pdu.RNTI, tag_min, tag_max)) {
        list->list[list->count++] = pdu;
    } else {
        fprintf(stderr, "Invalid tag encountered: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
    }

    pthread_mutex_unlock(&list->mutex);
}

void *process_crc_indications(void *arg) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)arg;
    for (size_t i = 0; i < list->count; ++i) {
        // Process each CRC indication here
        printf("Processing RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               list->list[i].RX_UE_INFORMATION_TAG,
               list->list[i].RNTI,
               list->list[i].CRCFLAG);
    }
    return NULL;
}
