['```javascript
function renderFooterScripts(scripts, config = {}) {
    const maxScripts = 10;
    let renderedScripts = [];
    let deferredScripts = [];
    const excludedTypes = config.excludeTypes || [];

    scripts.forEach(script => {
        if (excludedTypes.includes(script.type)) return;

        try {
            new Function(`(${script.code})`); // Validate script syntax
            if (renderedScripts.length < maxScripts) {
                renderedScripts.push(script);
            } else {
                deferredScripts.push(script);
            }
        } catch (e) {
            console.warn(`Invalid script: ${script.src}`);
            deferredScripts.push(script);
        }
    });

    const renderScript = script => `
        <script type="${script.type}" src="${script.src}" async defer></script>
    `;

    const renderFooter = () => renderedScripts.map(renderScript).join('');
    const renderDeferred = () => deferredScripts.map(renderScript).join('');

    return {
        footerHTML: renderFooter(),
        deferredHTML: renderDeferred()
    };
}
