#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIMIT 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t mutex;
} CRC_Indication_List;

void init_list(CRC_Indication_List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(CRC_Indication_List* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_LIMIT) {
        printf("Warning: Maximum limit reached. Cannot add more elements.\n");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    CRC_Indication_List list;
    init_list(&list);

    srand(time(NULL));
    for (int i = 0; i < 1500; i++) {
        add_to_list(&list, rand(), rand(), rand());
    }

    free_list(&list);
    return 0;
}
