    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PDCP_LIST;

void init_pdcp_list(PDCP_LIST* list) {
    list->contexts = (LTE_PDCP_CONTEXT*)malloc(MAX_PDCP_CONTEXTS * sizeof(LTE_PDCP_CONTEXT));
    if (!list->contexts) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_PDCP_CONTEXTS;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_pdcp_list(PDCP_LIST* list) {
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
}

int add_pdcp_context(PDCP_LIST* list, LTE_PDCP_CONTEXT context) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Resize the list
        size_t new_capacity = list->capacity * 2;
        LTE_PDCP_CONTEXT* new_contexts = (LTE_PDCP_CONTEXT*)realloc(list->contexts, new_capacity * sizeof(LTE_PDCP_CONTEXT));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            // Handle memory allocation failure
            return -1;
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }
    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_pdcp_list(PDCP_LIST* list, void (*update_func)(LTE_PDCP_CONTEXT*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        update_func(&list->contexts[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
