    if (dynamic_array == NULL) {
        dynamic_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (dynamic_array == NULL) {
