function traverseDOM(ancestorNode, selector, timeout = 5000) {
    const cache = new Map();
    let timeoutId;

    function traverse(node) {
        if (node === null || node === undefined) return [];

        if (timeoutId) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            throw new Error('Recursion limit exceeded');
        }, timeout);

        const matches = [];
        if (node.matches(selector)) {
            matches.push(node);
        }

        for (let child of node.children) {
            matches.push(...traverse(child));
        }

        return matches;
    }

    function fetchMetadata(element) {
        // Simulate API call
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                const metadata = cache.get(element);
                if (metadata) resolve(metadata);
                else {
                    const newMetadata = { /* Fetch metadata from API */ };
                    cache.set(element, newMetadata);
                    resolve(newMetadata);
                }
            }, Math.random() * 1000); // Simulate varying response times
        });
    }

    function processElements(elements) {
        return Promise.all(elements.map(async element => {
            const metadata = await fetchMetadata(element);
            // Process element with metadata
            return { element, metadata };
        }));
    }

    try {
        const elements = traverse(ancestorNode);
        return processElements(elements);
    } catch (error) {
        console.error(error.message);
        return [];
    }
}
