['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8;

typedef union {
    RX_UE_INFORMATION rx_ue_info;
    CRC_INDICATION_REL8 crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int parent;
    int rank;
} UnionFindElement;

UnionFindElement* createUnionFind(int size) {
    UnionFindElement* uf = (UnionFindElement*)malloc(size * sizeof(UnionFindElement));
    for (int i = 0; i < size; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(UnionFindElement* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void unionElements(UnionFindElement* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateArray(int N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        array[i].rx_ue_info.RX_UE_INFORMATION_TAG = i;
        array[i].rx_ue_info.RNTI = rand() % 1000;
        array[i].crc_ind_rel8.CRCFLAG = rand() % 2;
    }

    return array;
}

void checkDisjointness(NFAPI_CRC_INDICATION_PDU_T* array, UnionFindElement* uf) {
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (array[i].rx_ue_info.RX_UE_INFORMATION_TAG != array[j].rx_ue_info.RX_UE_INFORMATION_TAG) {
                clock_t start = clock();
                unionElements(uf, i, j);
                clock_t end = clock();
                double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
                printf("Disjointness check between elements %d and %d took %.6f milliseconds\n", i, j, time_taken * 1000);
            }
        }
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = createAndPopulateArray(N);
    UnionFindElement* uf = createUnionFind(N);

    checkDisjointness(array, uf);

    free(array);
    free(uf);

    return 0;
}
