typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
} LinkedList;

int addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list == NULL) {
        return -1; // Invalid list
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return -2; // Memory allocation failed
    }

    newNode->data = pdu;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->data.RNTI != pdu.RNTI) {
            current = current->next;
        }
        if (current->next != NULL) {
            free(newNode);
            printf("Error: Duplicate RNTI detected.\n");
            return -3; // Duplicate RNTI
        }
        current->next = newNode;
    }

    return 0; // Success
}

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL; // Memory allocation failed
    }
    list->head = NULL;
    return list;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
