#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

void init_crc_array(NFAPI_CRC_ARRAY *array, size_t initial_size) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    array->allocated_size = initial_size;
    array->used_size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void free_crc_array(NFAPI_CRC_ARRAY *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->allocated_size = 0;
    array->used_size = 0;
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

bool add_crc_indication(NFAPI_CRC_ARRAY *array, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&array->mutex);
    if (array->used_size >= array->allocated_size) {
        size_t new_size = array->allocated_size ? array->allocated_size * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for CRC array");
            pthread_mutex_unlock(&array->mutex);
            return false;
        }
        array->array = new_array;
        array->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *indication = &array->array[array->used_size++];
    indication->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    indication->RNTI = RNTI;
    indication->CRCFLAG = (RNTI % 5 == 0) ? true : ((RNTI % 7 == 0) ? false : true);

    pthread_mutex_unlock(&array->mutex);
    return true;
}

void process_crc_indications(NFAPI_CRC_ARRAY *array, size_t batch_size) {
    for (size_t i = 0; i < array->used_size; i += batch_size) {
        size_t end = i + batch_size > array->used_size ? array->used_size : i + batch_size;
        for (size_t j = i; j < end; ++j) {
            // Process each CRC indication here
            printf("Processing RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %s\n",
                   array->array[j].RX_UE_INFORMATION_TAG,
                   array->array[j].RNTI,
                   array->array[j].CRCFLAG ? "true" : "false");
        }
    }
}
