#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

void init_crc_list(NFAPI_CRC_LIST_T *list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->entries);
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void add_crc_entry(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        // Handle capacity exceeded
        exit(EXIT_FAILURE);
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->mutex);
}

void serialize_crc_list(NFAPI_CRC_LIST_T *list, FILE *file) {
    pthread_mutex_lock(&list->mutex);
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->mutex);
}

int deserialize_crc_list(NFAPI_CRC_LIST_T *list, FILE *file) {
    pthread_mutex_lock(&list->mutex);
    size_t count = fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    if (count > list->capacity) {
        // Handle capacity exceeded
        exit(EXIT_FAILURE);
    }
    list->count = count;
    pthread_mutex_unlock(&list->mutex);
    return count;
}
