    double throughput;
} FlowStatistics;

typedef struct {
    TrafficFlow *flows;
    size_t count;
    size_t capacity;
} TrafficFlowArray;

TrafficFlowArray* createTrafficFlowArray() {
    TrafficFlowArray *array = (TrafficFlowArray*)malloc(sizeof(TrafficFlowArray));
    array->flows = NULL;
    array->count = 0;
    array->capacity = 0;
    return array;
}

void resizeTrafficFlowArray(TrafficFlowArray *array, size_t newCapacity) {
    TrafficFlow *newFlows = (TrafficFlow*)realloc(array->flows, newCapacity * sizeof(TrafficFlow));
    if (newFlows == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    array->flows = newFlows;
    array->capacity = newCapacity;
}

void addTrafficFlow(TrafficFlowArray *array, TrafficFlow flow) {
    if (array->count >= array->capacity) {
        resizeTrafficFlowArray(array, array->capacity == 0 ? 1 : array->capacity * 2);
    }
    array->flows[array->count++] = flow;
}

void serializeTrafficFlowArray(TrafficFlowArray *array, FILE *file) {
    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->flows[i].flowID, sizeof(int), 1, file);
        fwrite(array->flows[i].header.data, sizeof(char), array->flows[i].header.length, file);
        // Serialize FlowStatistics
    }
}

void deserializeTrafficFlowArray(TrafficFlowArray *array, FILE *file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    resizeTrafficFlowArray(array, count);
    for (size_t i = 0; i < count; ++i) {
        fread(&array->flows[i].flowID, sizeof(int), 1, file);
        size_t length;
        fread(&length, sizeof(size_t), 1, file);
        array->flows[i].header.data = (char*)malloc(length * sizeof(char));
        fread(array->flows[i].header.data, sizeof(char), length, file);
        array->flows[i].header.length = length;
        // Deserialize FlowStatistics
    }
}

void freeTrafficFlowArray(TrafficFlowArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->flows[i].header.data);
    }
    free(array->flows);
    free(array);
}
