PHY_TASK_QUEUE_T* phy_task_queue_create() {
    PHY_TASK_QUEUE_T *queue = (PHY_TASK_QUEUE_T*)malloc(sizeof(PHY_TASK_QUEUE_T));
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void phy_task_queue_destroy(PHY_TASK_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->lock);
    PHY_TASK_QUEUE_NODE_T *current = queue->head;
    while (current != NULL) {
        PHY_TASK_QUEUE_NODE_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int phy_task_queue_add(PHY_TASK_QUEUE_T *queue, PHY_TASK_QUEUE_ITEM_T item) {
    pthread_mutex_lock(&queue->lock);
    PHY_TASK_QUEUE_NODE_T *current = queue->head;
    while (current != NULL) {
        if (current->item.SEQ_NUM == item.SEQ_NUM) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Duplicate SEQ_NUM
        }
        current = current->next;
    }
    PHY_TASK_QUEUE_NODE_T *new_node = (PHY_TASK_QUEUE_NODE_T*)malloc(sizeof(PHY_TASK_QUEUE_NODE_T));
    new_node->item = item;
    new_node->next = queue->head;
    queue->head = new_node;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int phy_task_queue_remove(PHY_TASK_QUEUE_T *queue, uint32_t seq_num) {
    pthread_mutex_lock(&queue->lock);
    PHY_TASK_QUEUE_NODE_T *current = queue->head;
    PHY_TASK_QUEUE_NODE_T *prev = NULL;
    while (current != NULL) {
        if (current->item.SEQ_NUM == seq_num) {
            if (prev == NULL) {
                queue->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&queue->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&queue->lock);
    return -1; // SEQ_NUM not found
}

// Serialization and deserialization functions would be implemented here

