#include <string.h>
#include <pthread.h>

typedef struct NL_DU {
    int mac_entity_id;
    int sequence_number;
    int payload_length;
    char *payload;
    struct NL_DU *next;
} NL_DU;

typedef struct LinkedList {
    NL_DU *head;
    pthread_mutex_t lock;
    size_t max_size;
    size_t current_size;
} LinkedList;

NL_DU* create_nldu(int mac_entity_id, int sequence_number, int payload_length) {
    NL_DU *nldu = (NL_DU*)malloc(sizeof(NL_DU));
    if (!nldu) return NULL;

    nldu->mac_entity_id = mac_entity_id;
    nldu->sequence_number = sequence_number;
    nldu->payload_length = payload_length;
    nldu->payload = (char*)malloc(payload_length);
    if (!nldu->payload) {
        free(nldu);
        return NULL;
    }

    // Fill payload with random data
    for (int i = 0; i < payload_length; i++) {
        nldu->payload[i] = rand() % 256;
    }

    nldu->next = NULL;
    return nldu;
}

void destroy_nldu(NL_DU *nldu) {
    free(nldu->payload);
    free(nldu);
}

int insert_nldu(LinkedList *list, int mac_entity_id, int sequence_number, int payload_length) {
    pthread_mutex_lock(&list->lock);

    if (list->max_size > 0 && list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    NL_DU *new_nldu = create_nldu(mac_entity_id, sequence_number, payload_length);
    if (!new_nldu) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_nldu->next = list->head;
    list->head = new_nldu;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int delete_nldu(LinkedList *list, int mac_entity_id) {
    pthread_mutex_lock(&list->lock);

    NL_DU *current = list->head;
    NL_DU *previous = NULL;

    while (current != NULL) {
        if (current->mac_entity_id == mac_entity_id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }

            destroy_nldu(current);
            list->current_size--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // NLDU not found
}

void init_linked_list(LinkedList *list, size_t max_size) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;
    list->current_size = 0;
}

void destroy_linked_list(LinkedList *list) {
    NL_DU *current = list->head;
    while (current != NULL) {
        NL_DU *next = current->next;
        destroy_nldu(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
}
