} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} PDU_LIST_MANAGER;

PDU_LIST_MANAGER* create_pdu_manager(size_t initial_size) {
    PDU_LIST_MANAGER *manager = (PDU_LIST_MANAGER*)malloc(sizeof(PDU_LIST_MANAGER));
    if (!manager) return NULL;

    manager->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        free(manager);
        return NULL;
    }

    manager->allocated_size = initial_size;
    manager->used_size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_pdu_manager(PDU_LIST_MANAGER *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->pdu_list);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_random_pdu(PDU_LIST_MANAGER *manager, size_t N) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used_size + N > manager->allocated_size) {
        size_t new_size = manager->allocated_size ? manager->allocated_size * 2 : 1;
        while (new_size < manager->used_size + N) new_size *= 2;

