import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class BackgroundProcessingManager {
    private static final String CONFIG_FILE = "config.properties";
    private static final int DEFAULT_SERVICE_COUNT = 5;
    private ExecutorService executorService;
    private Properties configProperties;

    public BackgroundProcessingManager() throws IOException {
        loadConfig();
        initializeServices();
    }

    private void loadConfig() throws IOException {
        configProperties = new Properties();
        try (FileInputStream fis = new FileInputStream(CONFIG_FILE)) {
            configProperties.load(fis);
        }
    }

    private int getServiceCount() {
        return Integer.parseInt(configProperties.getProperty("service.count", String.valueOf(DEFAULT_SERVICE_COUNT)));
    }

    private void initializeServices() {
        executorService = Executors.newFixedThreadPool(getServiceCount());
        for (int i = 0; i < getServiceCount(); i++) {
            executorService.submit(new BackgroundService(i));
        }
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    private static class BackgroundService implements Runnable {
        private final int id;

        public BackgroundService(int id) {
            this.id = id;
        }

        @Override
        public void run() {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    // Simulate job execution with exponential distribution
                    double mean = 10.0;
                    double randomTime = -mean * Math.log(Math.random());
                    TimeUnit.SECONDS.sleep((long) randomTime);
                    System.out.println("Service " + id + " completed a job.");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }
    }

    public static void main(String[] args) {
        try {
            BackgroundProcessingManager manager = new BackgroundProcessingManager();
            // Simulate application running for some time
            TimeUnit.MINUTES.sleep(5);
            manager.shutdown();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

