#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NL_DU {
    int mac_entity_id;
    int sequence_number;
    int payload_length;
    char *payload;
    time_t timestamp;
    struct NL_DU *prev;
    struct NL_DU *next;
} NL_DU;

NL_DU* create_nldu(int mac_entity_id, int sequence_number, int payload_length) {
    NL_DU *nldu = (NL_DU *)malloc(sizeof(NL_DU));
    if (nldu == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    nldu->mac_entity_id = mac_entity_id;
    nldu->sequence_number = sequence_number;
    nldu->payload_length = payload_length;
    nldu->payload = (char *)malloc(payload_length);
    if (nldu->payload == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(nldu);
        return NULL;
    }
    for (int i = 0; i < payload_length; i++) {
        nldu->payload[i] = rand() % 256;
    }
    nldu->timestamp = time(NULL);
    nldu->prev = NULL;
    nldu->next = NULL;
    return nldu;
}

void insert_nldu(NL_DU **head, NL_DU *nldu) {
    if (*head == NULL || nldu->sequence_number < (*head)->sequence_number) {
        nldu->next = *head;
        if (*head != NULL)
            (*head)->prev = nldu;
        *head = nldu;
    } else {
        NL_DU *current = *head;
        while (current->next != NULL && current->next->sequence_number < nldu->sequence_number) {
            current = current->next;
        }
        nldu->next = current->next;
        if (current->next != NULL)
            current->next->prev = nldu;
        current->next = nldu;
        nldu->prev = current;
    }
}

void remove_nldu(NL_DU **head, int mac_entity_id) {
    NL_DU *current = *head;
    while (current != NULL) {
        if (current->mac_entity_id == mac_entity_id) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            free(current->payload);
            free(current);
            return;
        }
        current = current->next;
    }
}

void merge_lists(NL_DU **head1, NL_DU *head2) {
    while (head2 != NULL) {
        NL_DU *temp = head2->next;
        insert_nldu(head1, head2);
        head2 = temp;
    }
}

int calculate_total_payload_size(NL_DU *head) {
    int total_size = 0;
    NL_DU *current = head;
    while (current != NULL) {
        total_size += current->payload_length;
        current = current->next;
    }
    return total_size;
}

void prune_old_nldus(NL_DU **head, time_t threshold) {
    NL_DU *current = *head;
    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > threshold) {
            NL_DU *temp = current;
            current = current->next;
            remove_nldu(head, temp->mac_entity_id);
            free(temp);
        } else {
            current = current->next;
        }
    }
}

void destroy_list(NL_DU **head) {
    while (*head != NULL) {
        NL_DU *temp = *head;
        *head = (*head)->next;
        free(temp->payload);
        free(temp);
    }
}
