#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct MQTT_Packet {
    char* topic;
    int qos;
    int retain;
    char* payload;
    size_t payload_size;
    struct MQTT_Packet* prev;
    struct MQTT_Packet* next;
} MQTT_Packet;

typedef struct MQTT_List {
    MQTT_Packet* head;
    MQTT_Packet* tail;
    size_t count;
    size_t max_packets;
    size_t min_payload_size;
    pthread_mutex_t lock;
} MQTT_List;

MQTT_List* create_mqtt_list(size_t max_packets, size_t min_payload_size) {
    MQTT_List* list = (MQTT_List*)malloc(sizeof(MQTT_List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    list->max_packets = max_packets;
    list->min_payload_size = min_payload_size;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_mqtt_list(MQTT_List* list) {
    MQTT_Packet* current = list->head;
    while (current) {
        MQTT_Packet* next = current->next;
        free(current->topic);
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_mqtt_packet(MQTT_List* list, const char* topic, int qos, int retain, size_t payload_size) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_packets) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    MQTT_Packet* packet = (MQTT_Packet*)malloc(sizeof(MQTT_Packet));
    if (!packet) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    packet->topic = strdup(topic);
    packet->qos = qos;
    packet->retain = retain;
    packet->payload_size = payload_size > list->min_payload_size ? payload_size : list->min_payload_size;
    packet->payload = (char*)malloc(packet->payload_size);
    if (!packet->payload) {
        free(packet->topic);
        free(packet);
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < packet->payload_size; ++i) {
        packet->payload[i] = rand() % 256;
    }

    packet->prev = list->tail;
    packet->next = NULL;

    if (list->tail) {
        list->tail->next = packet;
    } else {
        list->head = packet;
    }
    list->tail = packet;
    ++list->count;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void remove_mqtt_packet(MQTT_List* list, MQTT_Packet* packet) {
    pthread_mutex_lock(&list->lock);

    if (packet->prev) {
        packet->prev->next = packet->next;
    } else {
        list->head = packet->next;
    }

    if (packet->next) {
        packet->next->prev = packet->prev;
    } else {
        list->tail = packet->prev;
    }

    free(packet->topic);
    free(packet->payload);
    free(packet);
    --list->count;

    pthread_mutex_unlock(&list->lock);
}
