#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_UE_INFO_TAGS 1000
#define MAX_RNTI_VALUES 1000
#define MAX_CRC_INDICATIONS 5000

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int parent[MAX_UE_INFO_TAGS];
    int rank[MAX_UE_INFO_TAGS];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int areDisjoint(UnionFind *uf, int x, int y) {
    return find(uf, x) != find(uf, y);
}

void generateCRCIndications(NFAPI_CRC_INDICATION_PDU_T *crc_indications, UnionFind *uf, int max_crc_indications, SystemHealthMonitor *monitor, int max_batch_size) {
    srand(time(NULL));
    int num_crc_indications = 0;

    while (num_crc_indications < max_crc_indications) {
        int rx_ue_info_tag = rand() % MAX_UE_INFO_TAGS;
        int rnti = rand() % MAX_RNTI_VALUES;
        int crcflag = rand() % 2; // Randomly set CRCFLAG

        if (areDisjoint(uf, rx_ue_info_tag, rnti)) {
            unionSets(uf, rx_ue_info_tag, rnti);
            crc_indications[num_crc_indications].rx_ue_info_tag = rx_ue_info_tag;
            crc_indications[num_crc_indications].rnti = rnti;
            crc_indications[num_crc_indications].crcflag = crcflag;
            num_crc_indications++;

            if (num_crc_indications % max_batch_size == 0) {
                // Cooldown mechanism
                int decision = monitor->evaluateSystemHealth();
                if (decision == CONTINUE) {
                    printf("Continuing CRC indication generation.\n");
                } else {
                    printf("Pausing CRC indication generation for cooldown.\n");
                    sleep(1); // Simulate pause
                }
            }
        }

        // Assess impact on system performance metrics
        monitor->updatePerformanceMetrics();
    }
}
