typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_t lock;
} Element;

typedef struct {
    Element* pool;
    size_t pool_size;
    size_t used_elements;
    pthread_mutex_t pool_lock;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool(size_t initial_size) {
    memory_pool.pool = (Element*)malloc(initial_size * sizeof(Element));
    if (!memory_pool.pool) {
        // Handle allocation failure
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_elements = 0;
    pthread_mutex_init(&memory_pool.pool_lock, NULL);
}

void* allocate_element() {
    pthread_mutex_lock(&memory_pool.pool_lock);
    if (memory_pool.used_elements >= memory_pool.pool_size) {
        // Handle pool full
        pthread_mutex_unlock(&memory_pool.pool_lock);
        return NULL;
    }
    Element* element = &memory_pool.pool[memory_pool.used_elements++];
    pthread_mutex_init(&element->lock, NULL);
    pthread_mutex_unlock(&memory_pool.pool_lock);
    return element;
}

void deallocate_element(Element* element) {
    pthread_mutex_destroy(&element->lock);
    pthread_mutex_lock(&memory_pool.pool_lock);
    // Find and replace the element with the last one in the pool
    memory_pool.used_elements--;
    if (element != &memory_pool.pool[memory_pool.used_elements]) {
        *element = memory_pool.pool[memory_pool.used_elements];
        pthread_mutex_init(&element->lock, NULL);
    }
    pthread_mutex_unlock(&memory_pool.pool_lock);
}

void* manage_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* data) {
    Element* element = allocate_element();
    if (!element) {
        // Handle allocation failure
        return NULL;
    }
    pthread_mutex_lock(&element->lock);
    element->data = *data;
    pthread_mutex_unlock(&element->lock);
    return element;
}

void free_nfaapi_crc_indication_pdu(void* handle) {
    Element* element = (Element*)handle;
    deallocate_element(element);
}
