typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFO;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION;

typedef union {
    RX_UE_INFO rx_ue_info;
    CRC_INDICATION crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int parent;
    int rank;
} UnionFindElement;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        array[i].rx_ue_info.RX_UE_INFORMATION_TAG = i;
        array[i].rx_ue_info.RNTI = rand() % 1024;
        array[i].crc_indication.CRCFLAG = rand() % 2;
    }

    return array;
}

void union_find_init(UnionFindElement* uf, int N) {
    for (int i = 0; i < N; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

int find(UnionFindElement* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void union_set(UnionFindElement* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    free(array);
}
