#include <stdexcept>

enum class InterfaceType { Ethernet, Wi-Fi };
enum class BandwidthUnit { Mbps, Gbps };

class NetworkInterfaceConfig {
public:
    InterfaceType type;
    double bandwidth; // in Mbps or Gbps
    int frequency; // in MHz

    NetworkInterfaceConfig(InterfaceType t, double b, int f) : type(t), bandwidth(b), frequency(f) {}
};

class NetworkManager {
private:
    std::vector<NetworkInterfaceConfig> configs;

public:
    void insertConfig(const NetworkInterfaceConfig& config) {
        // Insert based on bandwidth priority
        auto it = std::lower_bound(configs.begin(), configs.end(), config,
                                   [](const NetworkInterfaceConfig& a, const NetworkInterfaceConfig& b) {
                                       return a.bandwidth < b.bandwidth;
                                   });
        configs.insert(it, config);
    }

    void updateConfig(const NetworkInterfaceConfig& newConfig) {
        // Update based on external data sources
        for (auto& config : configs) {
            if (config.type == newConfig.type && config.frequency == newConfig.frequency) {
                config.bandwidth = newConfig.bandwidth;
                return;
            }
        }
        throw std::runtime_error("Configuration not found to update");
    }

    double averageBandwidth() const {
        if (configs.empty()) return 0.0;
        double sum = 0.0;
        for (const auto& config : configs) {
            sum += config.bandwidth;
        }
        return sum / configs.size();
    }

    int mostCommonFrequency() const {
        std::map<int, int> frequencyCount;
        for (const auto& config : configs) {
            frequencyCount[config.frequency]++;
        }
        if (frequencyCount.empty()) return 0;
        return std::max_element(frequencyCount.begin(), frequencyCount.end(),
                               [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                                   return a.second < b.second;
                               })->first;
    }

    void handleSystemDependencies() {
        // Placeholder for handling system dependencies
        std::cout << "Handling system dependencies..." << std::endl;
    }

    void gracefulDegradation() {
        // Placeholder for graceful degradation mechanism
        std::cout << "Implementing graceful degradation..." << std::endl;
    }
};

int main() {
    NetworkManager manager;
    manager.insertConfig(NetworkInterfaceConfig(InterfaceType::Ethernet, 100.0, 2400));
    manager.insertConfig(NetworkInterfaceConfig(InterfaceType::Wi-Fi, 50.0, 5000));

    try {
        manager.updateConfig(NetworkInterfaceConfig(InterfaceType::Ethernet, 150.0, 2400));
    } catch (const std::runtime_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    std::cout << "Average Bandwidth: " << manager.averageBandwidth() << " Mbps" << std::endl;
    std::cout << "Most Common Frequency: " << manager.mostCommonFrequency() << " MHz" << std::endl;

    manager.handleSystemDependencies();
    manager.gracefulDegradation();

    return 0;
}
