    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = (struct record *)malloc(sizeof(struct record));
        if (!records[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->value = rand() % 1000;
    }

    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        // Free previously allocated memory
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
    }

    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        // Free previously allocated memory
        free(offsets);
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand() % 1000;
    }

    // Free temporary arrays
    free(offsets);
    free(keys);

    return records;
}
