DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size++] = element;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool dynamic_list_remove(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i] == element) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->elements[j] = list->elements[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

