    if (N < 1 || N > 1000) {
        fprintf(stderr, "Invalid input: N must be between 1 and 1000.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfaPduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        nfaPduArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        nfaPduArray[i].RNTI = rand() % 1000;
        nfaPduArray[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    char** file_hashes = (char**)malloc(num_files * sizeof(char*));
    if (!file_hashes) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(nfaPduArray);
        return NULL;
    }

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", file_paths[i]);
            continue;
        }

        fseek(file, 0, SEEK_END);
        long file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        unsigned char* buffer = (unsigned char*)malloc(file_size);
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed.\n");
            fclose(file);
            continue;
        }

        fread(buffer, 1, file_size, file);
        fclose(file);

        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, buffer, file_size);
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5_Final(hash, &md5);

        file_hashes[i] = (char*)malloc(33); // 32 characters for the hash + 1 for null terminator
        if (!file_hashes[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(buffer);
            continue;
        }

        for (int j = 0; j < MD5_DIGEST_LENGTH; j++) {
            sprintf(file_hashes[i] + j * 2, "%02x", hash[j]);
        }
        file_hashes[i][32] = '\0';

        free(buffer);
    }

    // Simulate access tier determination and caching logic here

    return nfaPduArray;
}
