typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_and_populate_pdus(int N, int buffer_size) {
    if (N <= 0 || buffer_size <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    int produced = 0;
    int consumed = 0;

    srand(time(NULL));

    while (produced < N) {
        pthread_mutex_lock(&mutex);
        while (produced - consumed >= buffer_size) {
            pthread_cond_wait(&cond, &mutex);
        }
        pdus[produced].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[produced].RNTI = rand() % 1000;
        pdus[produced].CRC_INDICATION_REL8_TAG = rand() % 100;
        pdus[produced].CRCFLAG = rand() % 2;
        produced++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }

    return pdus;
}
