    pthread_mutex_lock(&mutex);

    if (N > MAX_MEMORY_LIMIT || (current_count + N) > MAX_MEMORY_LIMIT) {
        // Not enough memory available
        pthread_mutex_unlock(&mutex);
        return NULL;
