#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDUS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_list[MAX_PDUS];
int pdu_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void init_log() {
    log_file = fopen("pdu_log.txt", "w");
}

void log_error(const char* message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        log_error("Failed to allocate memory for PDU");
        return NULL;
    }
    pthread_mutex_lock(&mutex);
    if (pdu_count >= MAX_PDUS) {
        log_error("PDU list is full");
        free(pdu);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    pdu_list[pdu_count++] = pdu;
    pthread_mutex_unlock(&mutex);
    return pdu;
}

void populate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL) {
        log_error("Invalid PDU pointer");
        return;
    }
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu->CRCFLAG = rand() % 2;
}

void* process_pdus(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
        if (pdu != NULL) {
            populate_pdu(pdu);
            // Process PDU here
        }
    }
    return NULL;
}

int main() {
    init_log();
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_pdus, NULL);
    pthread_join(thread_id, NULL);
    fclose(log_file);
    return 0;
}
