import time
from collections import defaultdict, deque

def process_transactions(stream, page_size=100):
    """
    Process a stream of user transactions, filtering and summarizing valid transactions.

    :param stream: Generator yielding transaction dictionaries.
    :param page_size: Number of transactions to process per page.
    :return: Dictionary containing summary statistics.
    """
    valid_transactions = []
    transaction_types_count = defaultdict(int)
    total_amount = 0
    start_time = time.time()

    for i, transaction in enumerate(stream):
        if (i + 1) % page_size == 0:
            process_page(valid_transactions, transaction_types_count, total_amount)
            valid_transactions.clear()
            transaction_types_count.clear()
            total_amount = 0

        try:
            if is_valid_transaction(transaction):
                valid_transactions.append(transaction)
                transaction_type = transaction.get('type')
                if transaction_type:
                    transaction_types_count[transaction_type] += 1
                amount = transaction.get('amount')
                if amount is not None and isinstance(amount, (int, float)):
                    total_amount += amount
        except Exception as e:
            print(f"Error processing transaction: {e}")

    process_page(valid_transactions, transaction_types_count, total_amount)

    summary = {
        "total_valid_transactions": len(valid_transactions),
        "average_transaction_amount": total_amount / len(valid_transactions) if valid_transactions else 0,
        "most_frequent_transaction_type": max(transaction_types_count, key=transaction_types_count.get)
    }

    if time.time() - start_time >= 3600:
        print(summary)
        start_time = time.time()

    return summary

def is_valid_transaction(transaction):
    """
    Check if the transaction meets predefined validation rules.

    :param transaction: Dictionary representing a user transaction.
    :return: True if valid, False otherwise.
    """
    required_fields = {'id', 'type', 'amount'}
    return required_fields.issubset(transaction) and isinstance(transaction['amount'], (int, float))

def process_page(transactions, types_count, total_amount):
    for transaction in transactions:
        try:
            amount = transaction.get('amount')
            if amount is not None and isinstance(amount, (int, float)):
                total_amount += amount
            transaction_type = transaction.get('type')
            if transaction_type:
                types_count[transaction_type] += 1
        except Exception as e:
            print(f"Error processing transaction in page: {e}")
