#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->count++] = item;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int validate_item(NFAPI_CRC_INDICATION_PDU_T item) {
    if (item.RNTI < 0 || item.RNTI > MAX_RNTI) return -1;
    if ((item.CRC_INDICATION_REL8_TAG & 1) != item.CRC_INDICATION_REL8_TAG) return -2;
    return 0;
}

void* update_list(void *arg) {
    DynamicList *list = (DynamicList*)arg;

    while (1) {
        // Simulate periodic updates from an external data source
        NFAPI_CRC_INDICATION_PDU_T item;
        // Populate item with new data...

        if (validate_item(item) == 0) {
            add_to_list(list, item);
        }

        // Sleep for a short period before the next update
        sleep(1);
    }

    return NULL;
}

int main() {
    DynamicList *list = create_dynamic_list(10);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, update_list, list) != 0) {
        destroy_dynamic_list(list);
        return -1;
    }

    // Simulate concurrent access from multiple threads
    for (int i = 0; i < 5; i++) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, update_list, list) != 0) {
            destroy_dynamic_list(list);
            return -1;
        }
    }

    // Wait for all threads to finish
    pthread_join(thread_id, NULL);

    destroy_dynamic_list(list);
    return 0;
}
