typedef struct {
    LTE_MME_UE_S1AP_ID_t ue_id;
    RRC_connection_state rrc_state;
    int nas_message_count;
} UE_Status_Report_T;

typedef struct {
    time_t timestamp;
    double measurement;
    char message[256];
} log_entry;

void manage_dynamic_arrays(int num_entries, int nas_threshold) {
    if (num_entries <= 0 || nas_threshold < 0) {
        fprintf(stderr, "Invalid input values.\n");
        return;
    }

    UE_Status_Report_T *ue_reports = malloc(num_entries * sizeof(UE_Status_Report_T));
    long *timestamps = malloc(num_entries * sizeof(long));
    double *measurements = malloc(num_entries * sizeof(double));
    log_entry *logs = malloc(num_entries * sizeof(log_entry));

    if (!ue_reports || !timestamps || !measurements || !logs) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(ue_reports);
        free(timestamps);
        free(measurements);
        free(logs);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < num_entries; ++i) {
        ue_reports[i].ue_id = rand() % 100000;
        ue_reports[i].rrc_state = (RRC_connection_state)(rand() % 3);
        ue_reports[i].nas_message_count = rand() % 100;

        timestamps[i] = time(NULL);
        measurements[i] = ((double)rand() / RAND_MAX) * 100.0;
        snprintf(logs[i].message, sizeof(logs[i].message), "Timestamp: %ld, Measurement: %.2f", timestamps[i], measurements[i]);

        if (ue_reports[i].nas_message_count > nas_threshold) {
            printf("UE ID: %d, NAS Message Count: %d\n", ue_reports[i].ue_id, ue_reports[i].nas_message_count);
        }
    }

    free(ue_reports);
    free(timestamps);
    free(measurements);
    free(logs);
}

int main() {
    manage_dynamic_arrays(100, 50);
    return 0;
}
