#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/rand.h>

// Define a structure to hold encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} EncryptionContext;

// Function to initialize encryption context
EncryptionContext* init_encryption_context(const char *key, int key_len) {
    EncryptionContext *ctx = malloc(sizeof(EncryptionContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    ctx->cipher = EVP_aes_256_cbc();
    return ctx;
}

// Function to encrypt data
int encrypt_data(EncryptionContext *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if (1 != EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Failed to update encryption\n");
        return -1;
    }
    int ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Failed to finalize encryption\n");
        return -1;
    }
    ciphertext_len += len;
    return ciphertext_len;
}

// Function to free encryption context
void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int main() {
    unsigned char key[32];
    if (!RAND_bytes(key, sizeof(key))) {
        fprintf(stderr, "Failed to generate random key\n");
        return 1;
    }

    EncryptionContext *ctx = init_encryption_context(key, sizeof(key));
    if (!ctx) {
        return 1;
    }

    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[128];
    int ciphertext_len;

    ciphertext_len = encrypt_data(ctx, plaintext, plaintext_len, ciphertext);
    if (ciphertext_len < 0) {
        free_encryption_context(ctx);
        return 1;
    }

    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    free_encryption_context(ctx);
    return 0;
}
