typedef struct {
    int ueContextId;
    time_t timestamp;
    int sequenceNumber;
} NFDataRecord;

typedef struct Node {
    NFDataRecord data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
}

void insertRecord(DynamicArray* array, NFDataRecord record) {
    pthread_mutex_lock(&array->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = record;
    newNode->next = array->head;
    array->head = newNode;
    pthread_mutex_unlock(&array->lock);
}

void purgeOldRecords(DynamicArray* array, time_t cutoff) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (difftime(current->data.timestamp, cutoff) > 0) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void* purgeThread(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    time_t cutoff = time(NULL) - 3600; // Purge records older than 1 hour
    purgeOldRecords(array, cutoff);
    return NULL;
}
