#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000
#define COOLDOWN_SECONDS 9

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t lock;
} MemoryPool;

void initMemoryPool(MemoryPool *pool) {
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocateElement(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&pool->lock);
    pool->elements[pool->count++] = element;
    pthread_mutex_unlock(&pool->lock);
    return element;
}

void freeMemoryPool(MemoryPool *pool) {
    for (int i = 0; i < pool->count; i++) {
        free(pool->elements[i]);
    }
    pthread_mutex_destroy(&pool->lock);
}

void* generateElements(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    srand(time(NULL));
    int stopProbability = rand() % 100;

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (stopProbability == 0) {
            break;
        }
        allocateElement(pool);
        stopProbability = rand() % 100;
    }

    return NULL;
}

void* cooldownPeriod(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    srand(time(NULL));

    for (int i = 0; i < COOLDOWN_SECONDS; i++) {
        int addElement = rand() % 2;
        if (addElement == 1) {
            allocateElement(pool);
        }
        sleep(1);
    }

    return NULL;
}

void logPerformanceMetrics(MemoryPool *pool, FILE *logFile) {
    pthread_mutex_lock(&pool->lock);
    fprintf(logFile, "Total elements generated: %d\n", pool->count);
    pthread_mutex_unlock(&pool->lock);
}

int main(int argc, char *argv[]) {
    MemoryPool pool;
    initMemoryPool(&pool);

    pthread_t generateThread, cooldownThread;
    if (pthread_create(&generateThread, NULL, generateElements, &pool) != 0 ||
        pthread_create(&cooldownThread, NULL, cooldownPeriod, &pool)) {
        perror("Failed to create threads");
        exit(EXIT_FAILURE);
    }

    pthread_join(generateThread, NULL);
    pthread_join(cooldownThread, NULL);

    FILE *logFile = fopen("performance_metrics.log", "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        freeMemoryPool(&pool);
        exit(EXIT_FAILURE);
    }

    logPerformanceMetrics(&pool, logFile);
    fclose(logFile);

    freeMemoryPool(&pool);
    return 0;
}
