typedef struct {
    char *certificate;
    char *private_key;
} CertificateData;

// Function to load certificate and private key from a file
CertificateData* load_certificate_and_key(const char *config_path) {
    CertificateData *data = (CertificateData *)malloc(sizeof(CertificateData));
    if (!data) {
        perror("Failed to allocate memory for CertificateData");
        return NULL;
    }

    // Open the configuration file
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        free(data);
        return NULL;
    }

    // Read certificate and private key from the file
    data->certificate = (char *)malloc(1024); // Adjust size as needed
    data->private_key = (char *)malloc(1024); // Adjust size as needed
    if (!data->certificate || !data->private_key) {
        perror("Failed to allocate memory for certificate or private key");
        fclose(file);
        free(data);
        return NULL;
    }

    if (fgets(data->certificate, 1024, file) == NULL || fgets(data->private_key, 1024, file) == NULL) {
        perror("Failed to read certificate or private key from file");
        fclose(file);
        free(data->certificate);
        free(data->private_key);
        free(data);
        return NULL;
    }

    // Close the file
    fclose(file);

    return data;
}

// Function to free the memory allocated for CertificateData
void free_certificate_data(CertificateData *data) {
    if (data) {
        free(data->certificate);
        free(data->private_key);
        free(data);
    }
}
