#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t max_size;
    size_t current_size;
} List;

List* create_list(size_t max_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_size = max_size;
    list->current_size = 0;
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Out of memory
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Out of memory
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void verify_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG < 0 || current->data.RNTI < 0 || current->data.CRC_INDICATION_REL8_TAG != 0 && current->data.CRC_INDICATION_REL8_TAG != 1) {
            // Log error: Invalid entry
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void log_runtime_info(List* list) {
    pthread_mutex_lock(&list->mutex);
    printf("Current size: %zu, Max size: %zu\n", list->current_size, list->max_size);
    pthread_mutex_unlock(&list->mutex);
}
