    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        pthread_mutex_unlock(&cache_manager->lock);
        return NULL;
    }
    memcpy(pdu_array, cache_manager->cache, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&cache_manager->lock);
    return pdu_array;
}

void initialize_cache(CacheManager *cache_manager, size_t initial_size) {
    cache_manager->cache = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cache_manager->cache) {
        return;
    }
    cache_manager->cache_size = initial_size;
    cache_manager->cache_count = 0;
    pthread_mutex_init(&cache_manager->lock, NULL);
}

void destroy_cache(CacheManager *cache_manager) {
    free(cache_manager->cache);
    pthread_mutex_destroy(&cache_manager->lock);
}
