#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *array[MAX_STRUCTURES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* populate_structures(void* arg) {
    int start_index = *(int*)arg;
    int end_index = start_index + MAX_STRUCTURES / 4;

    for (int i = start_index; i < end_index && i < MAX_STRUCTURES; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        pthread_mutex_lock(&mutex);
        array[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        array[i]->RNTI = rand() % 65536; // Unique RNTI values
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 100;
        array[i]->CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[4];
    int indices[4] = {0, MAX_STRUCTURES / 4, MAX_STRUCTURES / 2, 3 * MAX_STRUCTURES / 4};

    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, populate_structures, &indices[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(1);
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (array[i]) {
            free(array[i]);
        }
    }

    return 0;
}
