import subprocess
import os

def update_config(config_list, search_key, new_setting, env_config, encryption_function):
    try:
        # Replace placeholders in the config file using sed commands
        for key, value in env_config.items():
            command = f"sed -i 's/{key}/{value}/g' config.ks"
            subprocess.run(command, shell=True, check=True)

        # Encrypt user-defined password and add to the configuration
        encrypted_password = encryption_function(input("Enter your password: "))
        new_setting += f"\npassword={encrypted_password}"

        # Insert new setting after the first occurrence of search_key
        index = next((i for i, item in enumerate(config_list) if search_key in item), -1)
        if index != -1:
            config_list.insert(index + 1, new_setting)
        else:
            config_list.append(new_setting)

        # Write updated configuration to file safely
        with open('config.ks', 'w') as file:
            for line in config_list:
                file.write(line + '\n')

    except subprocess.CalledProcessError as e:
        raise Exception(f"Subprocess error: {e}")
    except KeyError as e:
        print(f"Missing required input: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return '\n'.join(config_list)
```

