void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->last_cleanup_time = time(NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_entry(DynamicList *list, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            list->entries[i] = new_entry;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
