    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void cleanup_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    time_t current_time = time(NULL);
    if (current_time - list->last_cleanup_time >= 300) { // 5 minutes in seconds
        for (int i = 0; i < list->count; i++) {
            if (current_time - list->entries[i].RX_UE_INFORMATION_TAG > 300) {
                for (int j = i; j < list->count - 1; j++) {
                    list->entries[j] = list->entries[j + 1];
                }
                list->count--;
                i--; // Adjust index after removal
            }
        }
        list->last_cleanup_time = current_time;
    }
    pthread_mutex_unlock(&list->lock);
}

