    for (int i = 0; i < list->count; i++) {
        if (time(NULL) - list->entries[i].RX_UE_INFORMATION_TAG <= 300) {
            active_entries++;
            crc_sum += list->entries[i].CRC_INDICATION_REL8_TAG;
