#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000000
#define CLEANUP_INTERVAL 300 // 5 minutes in seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t last_accessed;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation, int RNTI) {
    // Implement logging mechanism here
}

void add_entry(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&lock);
    if (entry_count < MAX_ENTRIES) {
        entries[entry_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        entries[entry_count].RNTI = RNTI;
        entries[entry_count].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRC flag
        entries[entry_count].last_accessed = time(NULL);
        entry_count++;
        log_operation("Add", RNTI);
    } else {
        printf("Error: Maximum number of entries reached.\n");
    }
    pthread_mutex_unlock(&lock);
}

void update_entry(int RNTI) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RNTI == RNTI) {
            entries[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRC flag
            entries[i].last_accessed = time(NULL);
            log_operation("Update", RNTI);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void remove_entry(int RNTI) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RNTI == RNTI) {
            entries[i] = entries[entry_count - 1];
            entry_count--;
            log_operation("Remove", RNTI);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void cleanup_entries() {
    pthread_mutex_lock(&lock);
    time_t now = time(NULL);
    for (int i = 0; i < entry_count; i++) {
        if (now - entries[i].last_accessed > CLEANUP_INTERVAL) {
            entries[i] = entries[entry_count - 1];
            entry_count--;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* cleanup_thread(void* arg) {
    while (1) {
        sleep(CLEANUP_INTERVAL);
        cleanup_entries();
    }
    return NULL;
}

int main() {
    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, NULL);

    // Example usage
    add_entry(1001, 12345);
    update_entry(12345);
    remove_entry(12345);

    pthread_join(cleanup_tid, NULL);
    return 0;
}
