#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_ATTEMPTS 5
#define RETRY_INTERVAL 1000 // in milliseconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(p->ai_family, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
        freeaddrinfo(res); // free the linked list
        return 0;
    }

    fprintf(stderr, "No valid IP address found for hostname\n");
    freeaddrinfo(res);
    return -1;
}

int populate_nfaapi_structures(NFAPI_CRC_INDICATION_PDU_T *structs, int N) {
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        structs[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structs[i].RNTI = rand() % 1000;

        NFAPI_CRC_INDICATION_REL8_TAG *crc_tag = malloc(sizeof(NFAPI_CRC_INDICATION_REL8_TAG));
        if (crc_tag == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        structs[i].crc_tag = crc_tag;
    }

    return 0;
}

int initialize_and_populate(NFAPI_CRC_INDICATION_PDU_T **structs, int N, const char *hostname, u_char *ip_address) {
    *structs = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*structs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
        int status = resolve_hostname(hostname, ip_address);
        if (status == 0) {
            break;
        }
        usleep(RETRY_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    if (attempt == MAX_ATTEMPTS) {
        fprintf(stderr, "Failed to resolve hostname after %d attempts\n", MAX_ATTEMPTS);
        free(*structs);
        return -1;
    }

    status = populate_nfaapi_structures(*structs, N);
    if (status != 0) {
        free(*structs);
        return -1;
    }

    return 0;
}

int main() {
    int N = 5;
    NFAPI_CRC_INDICATION_PDU_T *structs;
    u_char ip_address[INET_ADDRSTRLEN];

    int status = initialize_and_populate(&structs, N, "example.com", ip_address);
    if (status != 0) {
        fprintf(stderr, "Initialization and population failed\n");
        return -1;
    }

    // Use the populated structures...

    for (int i = 0; i < N; i++) {
        free(structs[i].crc_tag);
    }
    free(structs);

    return 0;
}
