import socket

def create_crc_list_and_resolve_ip(interface_configs):
    max_pdus = 1024
    crc_list = []

    for config in interface_configs:
        if len(crc_list) >= max_pdus:
            raise ValueError("Maximum number of PDUs exceeded")

        hostname = config.get('hostname')
        ip_address = config.get('ip_address')

        if not ip_address:
            try:
                ip_address = socket.gethostbyname(hostname)
                config['ip_address'] = ip_address
            except socket.gaierror:
                raise ValueError(f"DNS resolution failed for {hostname}")

        crc_list.append((config, ip_address))

    return crc_list
