#include <atomic>

class SpatialHashGrid {
public:
    struct Entity {
        int id;
        float x, y, z;
        // Add more entity properties as needed
    };

    using Grid = std::unordered_map<int, std::vector<Entity>>;

    SpatialHashGrid(int resolution, size_t initialCapacity)
        : resolution(resolution), grid(initialCapacity) {}

    ~SpatialHashGrid() {
        // Clean up resources if necessary
    }

    void addEntity(const Entity& entity) {
        int bucket = getBucket(entity.x, entity.y);
        std::lock_guard<std::mutex> lock(mutexes[bucket]);
        grid[bucket].push_back(entity);
    }

    void removeEntity(int id) {
        for (auto& [bucket, entities] : grid) {
            auto it = std::find_if(entities.begin(), entities.end(), [id](const Entity& e) { return e.id == id; });
            if (it != entities.end()) {
                std::lock_guard<std::mutex> lock(mutexes[bucket]);
                entities.erase(it);
                break;
            }
        }
    }

    std::vector<Entity> query(float x, float y, float radius) const {
        std::vector<Entity> results;
        int startX = static_cast<int>(x / resolution);
        int startY = static_cast<int>(y / resolution);
        for (int i = startX - 1; i <= startX + 1; ++i) {
            for (int j = startY - 1; j <= startY + 1; ++j) {
                int bucket = getBucket(i * resolution, j * resolution);
                std::lock_guard<std::mutex> lock(mutexes[bucket]);
                for (const auto& entity : grid[bucket]) {
                    if (distance(entity.x, entity.y, x, y) <= radius) {
                        results.push_back(entity);
                    }
                }
            }
        }
        return results;
    }

private:
    int resolution;
    Grid grid;
    std::vector<std::mutex> mutexes;

    int getBucket(float x, float y) const {
        return static_cast<int>(x / resolution) * 1000 + static_cast<int>(y / resolution);
    }

    float distance(float x1, float y1, float x2, float y2) const {
        return std::sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    }
};

int main() {
    SpatialHashGrid grid(0.1f, 1000000);
    // Example usage
    grid.addEntity({1, 0.5f, 0.5f, 0.5f});
    auto entities = grid.query(0.5f, 0.5f, 0.2f);
    for (const auto& entity : entities) {
        std::cout << "Entity ID: " << entity.id << ", Position: (" << entity.x << ", " << entity.y << ", " << entity.z << ")" << std::endl;
    }
    return 0;
}
