#include <netdb.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define MAX_RETRIES 5
#define RETRY_INTERVAL 100 // milliseconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *structures;
    int count;
} SharedData;

void* populate_structures(void* arg) {
    SharedData *data = (SharedData*)arg;
    for (int i = 0; i < data->count; i++) {
        pthread_mutex_lock(&data->mutex);
        data->structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        data->structures[i].RNTI = rand() % 65536;
        data->structures[i].CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&data->mutex);
    }
    return NULL;
}

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(p->ai_family, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
        freeaddrinfo(res); // free the linked list
        return 0;
    }

    freeaddrinfo(res); // free the linked list on error
    return -1;
}

int main() {
    SharedData data;
    pthread_t threads[MAX_STRUCTURES];
    u_char ip_address[INET_ADDRSTRLEN];

    if (pthread_mutex_init(&data.mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return -1;
    }

    data.structures = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data.structures) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&data.mutex);
        return -1;
    }

    data.count = MAX_STRUCTURES;

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pthread_create(&threads[i], NULL, populate_structures, &data) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            free(data.structures);
            pthread_mutex_destroy(&data.mutex);
            return -1;
        }
    }

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Thread join failed\n");
            free(data.structures);
            pthread_mutex_destroy(&data.mutex);
            return -1;
        }
    }

    if (resolve_hostname("example.com", ip_address) == 0) {
        printf("IP address: %s\n", ip_address);
    } else {
        fprintf(stderr, "Hostname resolution failed\n");
    }

    free(data.structures);
    pthread_mutex_destroy(&data.mutex);

    return 0;
}
