    { id: 2, value: 20 },
    // Add more profiles as needed
];

async function testProcessProfiles() {
    try {
        const results = await processProfiles(sampleProfiles);
        console.log('Test Results:', results);
    } catch (error) {
        console.error('Test failed:', error);
    }
}

testProcessProfiles();
```

This test will help you verify that the function processes profiles correctly, handles errors gracefully, and performs well under stress conditions."]

