} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int size;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->size++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_entry(DynamicList *list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].rnti == rnti) {
            list->entries[i] = new_entry;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

