    int size;
    pthread_mutex_lock(&list->lock);
    size = list->size;
    pthread_mutex_unlock(&list->lock);
    return size;
}

void prune_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    if (list->size > MAX_ENTRIES) {
        for (int i = 0; i < list->size - MAX_ENTRIES; i++) {
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        list->size = MAX_ENTRIES;
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list, sizeof(DynamicList), 1, file);
    fclose(file);
}

