    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    int is_crc_valid;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_LIST_T;

void crc_list_init(CRC_LIST_T *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void crc_list_add(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* crc_list_remove(CRC_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_info_tag) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL) {
        if (current->rx_ue_info_tag == rx_ue_info_tag) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void crc_list_free(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

