    int front, rear;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} EventQueue;

void init_event_queue(EventQueue *queue) {
    queue->front = queue->rear = -1;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

int is_full(EventQueue *queue) {
    return (queue->rear + 1) % MAX_EVENTS == queue->front;
}

int is_empty(EventQueue *queue) {
    return queue->front == -1;
}

void enqueue_event(EventQueue *queue, Event event) {
    pthread_mutex_lock(&queue->mutex);
    while (is_full(queue)) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    if (is_empty(queue)) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % MAX_EVENTS;
    }
    queue->events[queue->rear] = event;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

Event dequeue_event(EventQueue *queue) {
    Event event;
    pthread_mutex_lock(&queue->mutex);
    while (is_empty(queue)) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    event = queue->events[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % MAX_EVENTS;
    }
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

void *event_handler(void *arg) {
    EventQueue *queue = (EventQueue *)arg;
    while (1) {
        Event event = dequeue_event(queue);
        // Process the event
    }
    return NULL;
}

int main() {
    EventQueue queue;
    init_event_queue(&queue);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, event_handler, &queue);
    }

    // Enqueue events
    for (int i = 0; i < MAX_EVENTS; i++) {
        Event event;
        event.timestamp = time(NULL);
        event.type = i % 5;
        event.payload_size = rand() % PAYLOAD_THRESHOLD;
        event.payload = malloc(event.payload_size);
        // Populate payload
        enqueue_event(&queue, event);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
