#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERS 10000
#define MAX_LINE_LENGTH 256

typedef struct {
    int userId;
    long activityTimestamp;
    int durationMs;
} LogEntry;

typedef struct {
    LogEntry *entries;
    int count;
} UserCache;

UserCache* createUserCache() {
    UserCache *cache = (UserCache*)malloc(sizeof(UserCache));
    cache->entries = (LogEntry*)calloc(MAX_USERS, sizeof(LogEntry));
    cache->count = 0;
    return cache;
}

void freeUserCache(UserCache *cache) {
    free(cache->entries);
    free(cache);
}

int getUserIndex(UserCache *cache, int userId) {
    for (int i = 0; i < cache->count; i++) {
        if (cache->entries[i].userId == userId) {
            return i;
        }
    }
    return -1;
}

void addUserEntry(UserCache *cache, LogEntry entry) {
    if (cache->count >= MAX_USERS) {
        printf("Cache overflow!\n");
        return;
    }
    cache->entries[cache->count++] = entry;
}

double calculateAverageDuration(UserCache *cache, int userId) {
    int index = getUserIndex(cache, userId);
    if (index == -1) {
        return 0.0;
    }
    int count = 0;
    double totalDuration = 0.0;
    for (int i = index; i >= 0 && count < 5; i--) {
        if (cache->entries[i].userId == userId) {
            totalDuration += cache->entries[i].durationMs;
            count++;
        }
    }
    return count > 0 ? totalDuration / count : 0.0;
}

int main() {
    FILE *file = fopen("user_activity.csv", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    UserCache *cache = createUserCache();

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        LogEntry entry;
        if (sscanf(line, "%d,%ld,%d", &entry.userId, &entry.activityTimestamp, &entry.durationMs) != 3) {
            printf("Malformed log entry: %s\n", line);
            continue;
        }
        addUserEntry(cache, entry);
    }

    fclose(file);

    // Example usage of the cache
    int userId = 12345;
    double averageDuration = calculateAverageDuration(cache, userId);
    printf("User %d average activity duration: %.2f ms\n", userId, averageDuration);

    freeUserCache(cache);

    return EXIT_SUCCESS;
}
```

This code provides a basic structure for processing a CSV file containing user activity logs and calculating the average activity duration for each user over the last five entries. It includes dynamic memory allocation for log entries and a simple cache mechanism to store user data. The program handles malformed entries gracefully and ensures that all allocated memory is freed after processing.']

