NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(int N, int *expected_crc_values, int max_retries) {
    if (N <= 0 || !expected_crc_values) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
