        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 256;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 100;

        int retries = 0;
        while (retries < max_retries) {
            pdus[i].CRCFLAG = (rand() % 2);
            if (validate_crc_flag(&pdus[i], expected_crc_values[i])) {
                break;
            }
            ++retries;
