#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int validateCRC(int crcValue) {
    // Implement CRC validation logic here
    return (crcValue > 100 && crcValue < 900); // Example threshold
}

void* processPDU(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Simulate receiving PDU data
    pdu.RX_UE_INFORMATION_TAG = 12345;
    pdu.RNTI = 1001;
    pdu.CRC_INDICATION_REL8_TAG = 500;

    if (validateCRC(pdu.CRC_INDICATION_REL8_TAG)) {
        addNode(list, pdu);
    }

    return NULL;
}

void sortList(LinkedList* list, int ascending) {
    pthread_mutex_lock(&list->lock);
    // Implement sorting logic here
    // Example: Bubble sort for simplicity
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        while (next != NULL) {
            if ((ascending && current->data.RNTI > next->data.RNTI) || (!ascending && current->data.RNTI < next->data.RNTI)) {
                NFAPI_CRC_INDICATION_PDU_T temp = current->data;
                current->data = next->data;
                next->data = temp;
            }
            next = next->next;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, processPDU, &list);
    pthread_create(&thread2, NULL, processPDU, &list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    sortList(&list, 1); // Sort in ascending order

    Node* current = list.head;
    while (current != NULL) {
        printf("RNTI: %d\n", current->data.RNTI);
        current = current->next;
    }

    freeList(&list);
    return 0;
}
