#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
};

class NFAPICRCManager {
public:
    void addEntry(int rnti, bool crcFlag) {
        std::lock_guard<std::mutex> lock(mutex_);
        entries_[rnti] = {0, rnti, crcFlag};
        cv_.notify_all();
    }

    void updateEntry(int rnti, bool crcFlag) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (entries_.find(rnti) != entries_.end()) {
            entries_[rnti].CRC_INDICATION_REL8_TAG = crcFlag;
        }
        cv_.notify_all();
    }

    void removeEntry(int rnti) {
        std::lock_guard<std::mutex> lock(mutex_);
        entries_.erase(rnti);
        cv_.notify_all();
    }

    void cleanupOldEntries() {
        std::unique_lock<std::mutex> lock(mutex_);
        auto now = std::chrono::system_clock::now();
        entries_.erase(std::remove_if(entries_.begin(), entries_.end(),
                                      [now](const std::pair<int, NFAPI_CRC_INDICATION_PDU_T>& entry) {
                                          return (now - entry.second.RX_UE_INFORMATION_TAG) > std::chrono::minutes(5);
                                      }),
                      entries_.end());
    }

    void synchronizeWithExternalSource() {
        // Simulate synchronization with external data source
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    void printStatistics() {
        std::lock_guard<std::mutex> lock(mutex_);
        int totalEntries = entries_.size();
        int activeEntries = 0;
        double crcSum = 0.0;

        for (const auto& entry : entries_) {
            if ((std::chrono::system_clock::now() - entry.second.RX_UE_INFORMATION_TAG) <= std::chrono::minutes(5)) {
                ++activeEntries;
                crcSum += entry.second.CRC_INDICATION_REL8_TAG ? 1.0 : 0.0;
            }
        }

        double averageCRC = totalEntries > 0 ? crcSum / totalEntries : 0.0;

        std::cout << "Total Entries: " << totalEntries << std::endl;
        std::cout << "Active Entries (last 5 minutes): " << activeEntries << std::endl;
        std::cout << "Average CRC Flag Value: " << averageCRC << std::endl;
    }

    void selectRandomAttack() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 2);

        int attack = dis(gen);
        std::cout << "Selected Attack: " << attack << std::endl;

        // Simulate cooldown period
        std::this_thread::sleep_for(std::chrono::seconds(9));
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::unordered_map<int, NFAPI_CRC_INDICATION_PDU_T> entries_;
};

int main() {
    NFAPICRCManager manager;

    // Example usage
    manager.addEntry(12345, true);
    manager.updateEntry(12345, false);
    manager.removeEntry(12345);

    manager.cleanupOldEntries();
    manager.synchronizeWithExternalSource();
    manager.printStatistics();

    for (int i = 0; i < 10; ++i) {
        manager.selectRandomAttack();
    }

    return 0;
}
