#include <iostream>
#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/property_tree/ptree.hpp>
#include <chrono>
#include <thread>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

// Function to send HTTP POST request
void send_post_request(tcp::resolver& resolver, beast::flat_buffer& buffer, http::request<http::string_body>& req) {
    auto const results = resolver.resolve("example.com", "80");
    net::connect(stream_, results.begin(), results.end());

    // Set up the HTTP POST request
    req.method(http::verb::post);
    req.url("/metrics");
    req.version(11);
    req.set(http::field::host, "example.com");
    req.set(http::field::content_type, "application/json");
    req.body() = R"({"key":"value"})";
    req.prepare_payload();

    // Send the request
    http::write(stream_, req);

    // Read the response
    http::response<http::string_body> res;
    http::read(stream_, buffer, res);
}

int main() {
    try {
        net::io_context ioc;

        tcp::resolver resolver(ioc);
        beast::flat_buffer buffer;
        http::request<http::string_body> req;

        // Set configurable interval for sending requests
        std::chrono::seconds interval(10);

        while (true) {
            send_post_request(resolver, buffer, req);
            std::this_thread::sleep_for(interval);
        }
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
