DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int dynamic_list_add(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;

        list->data = new_data;
        list->capacity = new_capacity;
    }

    pthread_mutex_lock(&list->lock);
    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->data[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->data[list->size].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_unlock(&list->lock);

    list->size++;
    return 0;
}

void dynamic_list_process(DynamicList *list, void (*process_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        process_func(&list->data[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

void example_process_func(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Example processing function
    if (pdu->RNTI >= 100 && pdu->RNTI <= 200) {
        pdu->CRCFLAG = !pdu->CRCFLAG; // Toggle CRCFLAG based on RNTI range
    }
}

int main() {
    DynamicList *list = dynamic_list_create(10);
    if (!list) return -1;

    for (int i = 0; i < 25; i++) {
        if (dynamic_list_add(list, i, rand() % 300, i + 100) != 0) {
            dynamic_list_destroy(list);
            return -1;
        }
    }

    dynamic_list_process(list, example_process_func);

    dynamic_list_destroy(list);
    return 0;
}
