#include <time.h>

#define MAX_CONCURRENT_OPERATIONS 10

typedef struct {
    int ue_id;
    int signal_strength;
    time_t timestamp;
} LTE_Measurement_Report;

typedef struct {
    LTE_Measurement_Report *reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int operation_count;
} LTE_Measurement_Collection;

LTE_Measurement_Collection* create_collection(size_t initial_capacity) {
    LTE_Measurement_Collection *collection = (LTE_Measurement_Collection*)malloc(sizeof(LTE_Measurement_Collection));
    collection->reports = (LTE_Measurement_Report*)calloc(initial_capacity, sizeof(LTE_Measurement_Report));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    collection->operation_count = 0;
    return collection;
}

void destroy_collection(LTE_Measurement_Collection *collection) {
    free(collection->reports);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

int add_report(LTE_Measurement_Collection *collection, LTE_Measurement_Report report) {
    pthread_mutex_lock(&collection->lock);
    while (collection->operation_count >= MAX_CONCURRENT_OPERATIONS) {
        pthread_cond_wait(&collection->cond, &collection->lock);
    }
    collection->operation_count++;
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        LTE_Measurement_Report *new_reports = (LTE_Measurement_Report*)realloc(collection->reports, new_capacity * sizeof(LTE_Measurement_Report));
        if (!new_reports) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->reports = new_reports;
        collection->capacity = new_capacity;
    }
    collection->reports[collection->count++] = report;
    collection->operation_count--;
    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Additional functions for retrieving, updating, and deleting reports can be implemented here
```

