uint16_t derive_rnti(uint32_t rx_ue_info_tag) {
    // Implement a fast hash function to derive RNTI from RX_UE_INFORMATION_TAG
    uint16_t rnti = 0;
    for (int i = 0; i < sizeof(rx_ue_info_tag); ++i) {
        rnti ^= ((rx_ue_info_tag >> (i * 8)) & 0xFF);
    }
    return rnti;
}

