import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class LoggingTool {
    private static final int MAX_CONCURRENT_PROCESSES = 50;
    private static final long COMMAND_TIMEOUT = 10_000; // 10 seconds

    public static void main(String[] args) {
        Path configDir = Paths.get("./config");
        if (Files.exists(configDir)) {
            try {
                Files.deleteIfExists(Paths.get("./config/config.txt"));
                System.out.println("Deleted config.txt");
            } catch (IOException e) {
                System.err.println("Failed to delete config.txt: " + e.getMessage());
            }
        }

        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_PROCESSES);
        BlockingQueue<String> commandQueue = new LinkedBlockingQueue<>();

        // Simulate adding commands to the queue
        for (int i = 0; i < 100; i++) {
            commandQueue.add("tail -f ./config/log.txt");
        }

        while (!commandQueue.isEmpty()) {
            String command = commandQueue.poll();
            if (command != null) {
                executor.submit(() -> executeCommand(command, configDir));
            }
        }

        executor.shutdown();
    }

    private static void executeCommand(String command, Path configDir) {
        ProcessBuilder processBuilder = new ProcessBuilder("sh", "-c", command);
        processBuilder.directory(configDir.toFile());

        try (Process process = processBuilder.start()) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing command: " + e.getMessage());
        }
    }
}
