        size_t bytesRead;
        while ((bytesRead = fread(buffer, 1, sizeof(buffer), stdin)) > 0) {
            fwrite(buffer, 1, bytesRead, file);
        }

        fclose(file);

        if (verboseMode) {
            printf("Number of lines: %zu\n", countLines(outputFile));
        }
    }

    // Free allocated memory
    free(hashFunctions);
    free(blockCiphers);

    return 0;
}

// Function to count the number of lines in a file
size_t countLines(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return 0;
    }

    size_t lineCount = 0;
    int c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            lineCount++;
        }
    }

    fclose(file);
    return lineCount;
}
