void initialize_measurement_collection() {
    for (int i = 0; i < MAX_UE_ID; i++) {
        measurement_collection.reports[i] = NULL;
    }
    pthread_mutex_init(&measurement_collection.lock, NULL);
    measurement_collection.report_count = 0;
    measurement_collection.concurrent_operations = 0;
}

void add_measurement_report(int ue_id, int signal_strength, int frequency_band, int cell_id) {
    pthread_mutex_lock(&measurement_collection.lock);
    if (measurement_collection.concurrent_operations >= MAX_CONCURRENT_OPERATIONS) {
        printf("Too many concurrent operations. Please try again later.\n");
        pthread_mutex_unlock(&measurement_collection.lock);
        return;
    }
    measurement_collection.concurrent_operations++;
    LTE_Measurement_Report *report = (LTE_Measurement_Report *)malloc(sizeof(LTE_Measurement_Report));
    report->ue_id = ue_id;
