#define MAX_EVENTS 200000
#define MAX_CLIENTS 300
#define MAX_EVENT_SIZE 1024
#define MAX_MEMORY_POOL_SIZE 2 * 1024 * 1024 * 1024 // 2 GB

typedef struct {
    time_t timestamp;
    int event_id;
    char message[MAX_EVENT_SIZE];
} LOG_EVENT_RECORD;

typedef struct {
    LOG_EVENT_RECORD events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
} EVENT_QUEUE;

EVENT_QUEUE event_queue;
pthread_mutex_t memory_pool_lock;
char *memory_pool;
int memory_pool_size = 0;
int memory_pool_used = 0;

void init_event_queue() {
    pthread_mutex_init(&event_queue.lock, NULL);
    event_queue.count = 0;
}

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool_lock);
    if (memory_pool_used + size > MAX_MEMORY_POOL_SIZE) {
        printf("Memory pool overflow\n");
        return NULL;
    }
    char *ptr = memory_pool + memory_pool_used;
    memory_pool_used += size;
    pthread_mutex_unlock(&memory_pool_lock);
    return ptr;
}

void enqueue_event(LOG_EVENT_RECORD event) {
    pthread_mutex_lock(&event_queue.lock);
    if (event_queue.count >= MAX_EVENTS) {
        printf("Event queue overflow\n");
        pthread_mutex_unlock(&event_queue.lock);
        return;
    }
    event_queue.events[event_queue.count++] = event;
    pthread_mutex_unlock(&event_queue.lock);
}

void* logging_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&event_queue.lock);
        if (event_queue.count == 0) {
            pthread_mutex_unlock(&event_queue.lock);
            continue;
        }
        LOG_EVENT_RECORD event = event_queue.events[--event_queue.count];
        pthread_mutex_unlock(&event_queue.lock);

        // Simulate external logging service call
        printf("Logging event: ID=%d, Message=%s\n", event.event_id, event.message);
    }
    return NULL;
}

int main() {
    memory_pool = (char*)malloc(MAX_MEMORY_POOL_SIZE);
    if (!memory_pool) {
        printf("Failed to allocate memory pool\n");
        return 1;
    }

    init_event_queue();

    pthread_t logging_tid;
    pthread_create(&logging_tid, NULL, logging_thread, NULL);

    // Simulate event generation
    for (int i = 0; i < MAX_CLIENTS * MAX_EVENTS; i++) {
        LOG_EVENT_RECORD event;
        event.timestamp = time(NULL);
        event.event_id = rand() % 1000;
        snprintf(event.message, MAX_EVENT_SIZE, "Event %d", i);
        enqueue_event(event);
    }

    pthread_join(logging_tid, NULL);

    free(memory_pool);
    return 0;
}
