using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class DataProcessingUtils
{
    private static readonly ConcurrentDictionary<string, byte[]> _md5Cache = new ConcurrentDictionary<string, byte[]>();

    public static string ComputeMD5Hash(string input)
    {
        if (string.IsNullOrEmpty(input))
            return string.Empty;

        var hashBytes = _md5Cache.GetOrAdd(input, key =>
        {
            using (var md5 = MD5.Create())
                return md5.ComputeHash(Encoding.UTF8.GetBytes(key));
        });

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    public static byte[] DecryptWithAES_CBC(byte[] ciphertext, byte[] key, byte[] iv, byte[] padding = null)
    {
        if (ciphertext == null || key == null || iv == null)
            throw new ArgumentNullException("Input parameters cannot be null.");

        if (key.Length != 32 && key.Length != 48 && key.Length != 64)
            throw new ArgumentException("Key size must be 256, 384, or 512 bits.");

        if (iv.Length != 16)
            throw new ArgumentException("IV length must be 128 bits.");

        using (var aes = Aes.Create())
        {
            aes.KeySize = key.Length * 8;
            aes.BlockSize = 128;
            aes.Mode = CipherMode.CBC;
            aes.Padding = padding == null ? PaddingMode.PKCS7 : PaddingMode.None;

            aes.Key = key;
            aes.IV = iv;

            using (var decryptor = aes.CreateDecryptor())
                return decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
        }
    }
}
```

