#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    unsigned short availableRNTIs[MAX_RNTI];
    int availableCount;
} RNTIManager;

int initializeRNTIManager(RNTIManager* manager) {
    for (int i = 0; i < MAX_RNTI; i++) {
        manager->availableRNTIs[i] = i;
    }
    manager->availableCount = MAX_RNTI;
    return 0;
}

unsigned short getAvailableRNTI(RNTIManager* manager) {
    if (manager->availableCount == 0) {
        fprintf(stderr, "No available RNTI values.\n");
        exit(1);
    }
    unsigned short rnti = manager->availableRNTIs[--manager->availableCount];
    return rnti;
}

void releaseRNTI(RNTIManager* manager, unsigned short rnti) {
    if (rnti >= MAX_RNTI || manager->availableCount == MAX_RNTI) {
        fprintf(stderr, "Invalid RNTI value.\n");
        exit(1);
    }
    manager->availableRNTIs[manager->availableCount++] = rnti;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(RNTIManager* manager, Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    if (*head == NULL) {
        *head = createNode(data);
        return;
    }
    Node* current = *head;
    while (current->next != NULL && current->data.RNTI == data.RNTI) {
        current = current->next;
    }
    current->next = createNode(data);
}

void freeList(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));
    RNTIManager manager;
    initializeRNTIManager(&manager);

    Node* head = NULL;

    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = getAvailableRNTI(&manager);
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu.CRCFLAG = rand() % 2;

        addNode(&manager, &head, pdu);

        if (i % 10 == 0) {
            releaseRNTI(&manager, head->data.RNTI);
            free(head);
            head = head->next;
        }
    }

    freeList(&head);

    return 0;
}
