    public static <T> T deserializeAndProcess(byte[] data, String newFileType, Level logLevel) throws CustomDeserializationException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            T obj = (T) ois.readObject();
            logger.log(logLevel, "Deserialized object: " + obj.getClass().getName());

            String originalFilename = extractFilename(obj);
            String newFilename = generateNewFilename(originalFilename, newFileType);

            // Process the new filename as needed
            logger.log(logLevel, "Processed filename: " + newFilename);

            return obj;
        } catch (IOException | ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Deserialization failed", e);
            throw new CustomDeserializationException("Failed to deserialize object", e);
        }
