        int suffix = originalFilename.length();
        return originalFilename.substring(0, originalFilename.lastIndexOf('.')) + "_" + suffix + "." + newFileType;
    }
}

class CustomDeserializationException extends Exception {
    public CustomDeserializationException(String message, Throwable cause) {
        super(message, cause);
    }
