    if (node == NULL) return;
    Value *value = node->value;
    Subnode *subnode = value->subnodes;
    while (subnode != NULL) {
        Subnode *temp = subnode;
        subnode = subnode->next;
        destroy_subnode(temp);
    }
    free(value);
