    value->subnodes = NULL;

    for (int i = 0; i < retries; i++) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            // Set up the request
            curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/data");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "key=");

            // Perform the request
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                continue;
            }

            // Parse response and populate value structure
            // ...

            curl_easy_cleanup(curl);
            curl_global_cleanup();
            break;
        }
    }

    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch data after %d retries\n", retries);
        free(value);
        return NULL;
    }

    return value;
}

Subnode* create_subnode(int key) {
    Subnode *subnode = (Subnode*)malloc(sizeof(Subnode));
    subnode->key = key;
    subnode->next = NULL;
    return subnode;
}

void destroy_subnode(Subnode *subnode) {
    free(subnode);
}

void add_subnode(Value *value, Subnode *subnode) {
    subnode->next = value->subnodes;
    value->subnodes = subnode;
}

void remove_subnode(Value *value, int subkey) {
    Subnode *current = value->subnodes;
    Subnode *previous = NULL;

    while (current != NULL && current->key != subkey) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Subnode not found

    if (previous == NULL) {
        value->subnodes = current->next;
    } else {
        previous->next = current->next;
    }

    destroy_subnode(current);
}

