#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_INFO 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_UE_INFO * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_UE_INFO;
    pthread_mutex_init(&list->lock, NULL);
}

void freeDynamicList(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void addEntry(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        fprintf(stderr, "Dynamic list is full\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T newEntry = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, rand() % 2};
    list->data[list->count++] = newEntry;
    pthread_mutex_unlock(&list->lock);
}

void updateCRCFlag(DynamicList *list, int RX_UE_INFORMATION_TAG, int newCRCFLAG) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            list->data[i].CRCFLAG = newCRCFLAG;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void processList(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        // Perform processing based on specific conditions
        if (list->data[i].CRCFLAG == 1) {
            updateCRCFlag(list, list->data[i].RX_UE_INFORMATION_TAG, 0);
        }
    }
