#define MAX_RNTI 65535

typedef struct {
    int tag;
    int rnti;
    int crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNFAPDU(int numTags, int numRNTIs) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numTags * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    srand(time(NULL));
    for (int i = 0; i < numTags; ++i) {
        pdus[i].tag = rand() % MAX_UE_TAGS;
        pdus[i].rnti = rand() % MAX_RNTI;
        pdus[i].crcFlag = rand() % 2;
    }

    return pdus;
}

void serializeNFAPDU(NFAPI_CRC_INDICATION_PDU_T* pdus, int numTags, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), numTags, file);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserializeNFAPDU(const char* filename, int* numTags) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fclose(file);

    *numTags = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*numTags * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    file = fopen(filename, "rb");
    fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), *numTags, file);
    fclose(file);

    return pdus;
}

void freeNFAPDU(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    free(pdus);
}
