#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int interface_id;
    double bytes_sent;
    double bytes_received;
    // Add other metrics as needed
} NetworkInterfaceStatistics;

typedef struct {
    NetworkInterfaceStatistics *stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NetworkStatsManager;

NetworkStatsManager* create_network_stats_manager(size_t initial_capacity) {
    NetworkStatsManager *manager = (NetworkStatsManager*)malloc(sizeof(NetworkStatsManager));
    manager->stats = (NetworkInterfaceStatistics*)calloc(initial_capacity, sizeof(NetworkInterfaceStatistics));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_network_stats_manager(NetworkStatsManager *manager) {
    free(manager->stats);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_statistics(NetworkStatsManager *manager, NetworkInterfaceStatistics new_stats) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].interface_id == new_stats.interface_id) {
            // Update existing statistics
            manager->stats[i] = new_stats;
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    if (manager->count >= manager->capacity) {
        // Resize the array if necessary
        NetworkInterfaceStatistics *new_stats = (NetworkInterfaceStatistics*)realloc(manager->stats, manager->capacity * 2 * sizeof(NetworkInterfaceStatistics));
        if (!new_stats) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->stats = new_stats;
        manager->capacity *= 2;
    }
    // Add new statistics
    manager->stats[manager->count++] = new_stats;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

double calculate_moving_average(NetworkStatsManager *manager, int interface_id, double (*metric_selector)(NetworkInterfaceStatistics)) {
    pthread_mutex_lock(&manager->lock);
    double sum = 0.0;
    size_t count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].interface_id == interface_id) {
            sum += metric_selector(manager->stats[i]);
            ++count;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return count > 0 ? sum / count : 0.0;
}

// Example usage
int main() {
    NetworkStatsManager *manager = create_network_stats_manager(100);
    NetworkInterfaceStatistics stats = {1, 1024.5, 512.3};
    add_or_update_statistics(manager, stats);
    double avg_bytes_sent = calculate_moving_average(manager, 1, [](NetworkInterfaceStatistics s) { return s.bytes_sent; });
    printf("Average bytes sent: %f\n", avg_bytes_sent);
    destroy_network_stats_manager(manager);
    return 0;
}
