    NRCellConfig_t* cell_configs = (NRCellConfig_t*)malloc(num_cells * sizeof(NRCellConfig_t));
    if (!cell_configs) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Load and parse configuration file
    FILE* config_file = fopen(config_file_path, "r");
    if (!config_file) {
        fprintf(stderr, "Failed to open configuration file\n");
        free(cell_configs);
        return NULL;
    }

    int line_number = 0;
    while (fscanf(config_file, "%d %d %d %d", &cell_configs[line_number].band_id,
                   &cell_configs[line_number].num_of_antenna_ports,
                   &cell_configs[line_number].max_mcs_uplink,
                   &cell_configs[line_number].max_mcs_downlink) != 4) {
        fprintf(stderr, "Error parsing configuration file at line %d\n", line_number + 1);
        fclose(config_file);
        free(cell_configs);
        return NULL;
    }

    fclose(config_file);

    // Initialize PCI values
    NRCellPci_t* pci_list = (NRCellPci_t*)malloc(num_cells * sizeof(NRCellPci_t));
    if (!pci_list) {
        fprintf(stderr, "Memory allocation failed\n");
        free(cell_configs);
        return NULL;
    }

    for (int i = 0; i < num_cells; ++i) {
        pci_list[i].pci_value = generate_unique_pci(pci_list, i);
        cell_configs[i].band_id = pci_list[i].pci_value % 100; // Example mapping
    }

    return cell_configs;
}

int generate_unique_pci(NRCellPci_t* pci_list, int index) {
    static int last_assigned_pci = -1;
    int new_pci;

    do {
        new_pci = rand() % 1024; // Assuming a range of 0-1023 for PCI values
    } while (is_pci_conflicting(pci_list, index, new_pci));

    return new_pci;
}

int is_pci_conflicting(NRCellPci_t* pci_list, int current_index, int new_pci) {
    for (int i = 0; i < current_index; ++i) {
        if (pci_list[i].pci_value == new_pci) {
            return 1;
        }
    }
    return 0;
}
