import json
from abc import ABC, abstractmethod
from threading import Lock

class ConfigBase(ABC):
    _factories = {}
    _lock = Lock()

    @abstractmethod
    def parse_json(self, data: str) -> None:
        pass

    @abstractmethod
    def serialize_json(self) -> str:
        pass

    @classmethod
    def register_factory(cls, config_type: str, factory_func):
        with cls._lock:
            if config_type in cls._factories:
                raise ValueError(f"Factory for {config_type} already registered")
            cls._factories[config_type] = factory_func

    @classmethod
    def get_factory(cls, config_type: str):
        with cls._lock:
            return cls._factories.get(config_type)

class DatabaseConfig(ConfigBase):
    def __init__(self, host: str, port: int, user: str, password: str):
        self.host = host
        self.port = port
        self.user = user
        self.password = password

    def parse_json(self, data: str) -> None:
        config_data = json.loads(data)
        self.host = config_data['host']
        self.port = config_data['port']
        self.user = config_data['user']
        self.password = config_data['password']

    def serialize_json(self) -> str:
        return json.dumps({
            'host': self.host,
            'port': self.port,
            'user': self.user,
            'password': self.password
        })

class ApiEndpointConfig(ConfigBase):
    def __init__(self, url: str, method: str):
        self.url = url
        self.method = method

    def parse_json(self, data: str) -> None:
        config_data = json.loads(data)
        self.url = config_data['url']
        self.method = config_data['method']

    def serialize_json(self) -> str:
        return json.dumps({
            'url': self.url,
            'method': self.method
        })

# Registering factories
ConfigBase.register_factory('database', lambda data: DatabaseConfig(**data))
ConfigBase.register_factory('api_endpoint', lambda data: ApiEndpointConfig(**data))

# Example usage
config_data = {
    'type': 'database',
    'data': {
        'host': 'localhost',
        'port': 5432,
        'user': 'admin',
        'password': 'secret'
    }
}

factory = ConfigBase.get_factory(config_data['type'])
if factory:
    config_instance = factory(config_data['data'])
    print(config_instance.serialize_json())
else:
    print("Factory not found")
