#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int userId;
    double latency;
    // Other metrics...
} UserSessionMetrics;

typedef struct {
    UserSessionMetrics *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

void initSessionManager(SessionManager *manager, size_t initialCapacity) {
    manager->sessions = (UserSessionMetrics *)malloc(initialCapacity * sizeof(UserSessionMetrics));
    manager->count = 0;
    manager->capacity = initialCapacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void addOrUpdateSession(SessionManager *manager, UserSessionMetrics session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].userId == session.userId) {
            manager->sessions[i] = session;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = (UserSessionMetrics *)realloc(manager->sessions, manager->capacity * sizeof(UserSessionMetrics));
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

double calculateLatencyPercentile(SessionManager *manager, double percentile) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No data available
    }
    qsort(manager->sessions, manager->count, sizeof(UserSessionMetrics), [](const void *a, const void *b) {
        return ((UserSessionMetrics *)a)->latency < ((UserSessionMetrics *)b)->latency ? -1 : 1;
    });
    size_t index = (size_t)(percentile * (manager->count - 1));
    double latency = manager->sessions[index].latency;
    pthread_mutex_unlock(&manager->lock);
    return latency;
}

void purgeInactiveSessions(SessionManager *manager, time_t idleTimeout) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count;) {
        if (time(NULL) - manager->sessions[i].latency > idleTimeout) {
            for (size_t j = i + 1; j < manager->count; ++j) {
                manager->sessions[j - 1] = manager->sessions[j];
            }
            --manager->count;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void *updateSessionData(void *arg) {
    SessionManager *manager = (SessionManager *)arg;
    // Simulate external data source updates
    for (;;) {
        // Fetch and update session data...
        sleep(60); // Update every minute
    }
    return NULL;
}

int main() {
    SessionManager manager;
    initSessionManager(&manager, 10);

    pthread_t updaterThread;
    pthread_create(&updaterThread, NULL, updateSessionData, &manager);

    // Simulate adding and updating sessions
    UserSessionMetrics session1 = {1, 250.0};
    addOrUpdateSession(&manager, session1);
    UserSessionMetrics session2 = {2, 300.0};
    addOrUpdateSession(&manager, session2);

    double percentile95 = calculateLatencyPercentile(&manager, 0.95);
    printf("95th Percentile Latency: %.2f\n", percentile95);

    purgeInactiveSessions(&manager, 60 * 60); // Purge sessions inactive for more than an hour

    pthread_join(updaterThread, NULL);
    free(manager.sessions);
    return 0;
}
