#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <numeric>
#include <cmath>
#include <algorithm>

class SensorData {
public:
    std::string sensorId;
    double value;
    std::string location;
    std::chrono::system_clock::time_point timestamp;

    // Constructor, getters, and setters
};

class SensorManager {
private:
    std::vector<SensorData> data;
    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    SensorManager() : running(true) {}

    void addSensorData(const SensorData& newData) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push_back(newData);
        cv.notify_one();
    }

    void updateSensorData(const std::string& sensorId, double newValue) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& d : data) {
            if (d.sensorId == sensorId) {
                d.value = newValue;
                break;
            }
        }
        cv.notify_one();
    }

    void computeStatistics(const std::string& location, const std::chrono::system_clock::time_point& startTime, const std::chrono::system_clock::time_point& endTime, const std::string& measurementType) {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<double> values;
        for (const auto& d : data) {
            if (d.location == location && d.timestamp >= startTime && d.timestamp <= endTime && d.sensorId.find(measurementType) != std::string::npos) {
                values.push_back(d.value);
            }
        }

        // Compute mean, median, and standard deviation
        double sum = std::accumulate(values.begin(), values.end(), 0.0);
        double mean = sum / values.size();
        std::sort(values.begin(), values.end());
        double median = (values.size() % 2 == 0) ? (values[values.size() / 2 - 1] + values[values.size() / 2]) / 2 : values[values.size() / 2];
        double variance = std::accumulate(values.begin(), values.end(), 0.0, [mean](double acc, double val){ return acc + std::pow(val - mean, 2); }) / values.size();
        double stddev = std::sqrt(variance);

        // Output results
        std::cout << "Mean: " << mean << ", Median: " << median << ", Standard Deviation: " << stddev << std::endl;
    }

    void startService() {
        std::thread([this]() {
            while (running) {
                cv.wait(mtx, [this]{ return !data.empty(); });
                // Process data
                data.clear();
            }
        }).detach();
    }

    void stopService() {
        running = false;
        cv.notify_all();
    }
};

int main() {
    SensorManager manager;
    manager.startService();

    // Simulate adding sensor data
    for (int i = 0; i < 1000; ++i) {
        SensorData sd;
        sd.sensorId = "sensor" + std::to_string(i);
        sd.value = static_cast<double>(rand()) / RAND_MAX * 100.0;
        sd.location = "location" + std::to_string(i % 10);
        sd.timestamp = std::chrono::system_clock::now();
        manager.addSensorData(sd);
    }

    // Simulate computing statistics
    manager.computeStatistics("location5", std::chrono::system_clock::now() - std::chrono::hours(24), std::chrono::system_clock::now(), "temperature");

    manager.stopService();

    return 0;
}
