#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000
#define CRC8_POLYNOMIAL 0x07

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list[MAX_STRUCTURES];
    int active_count;
    pthread_mutex_t mutex;
} ResourceManager;

void calculate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // CRC8 CCITT calculation
    pdu->crc_indication.crcflag = 0x00;
    for (int i = 0; i < sizeof(RX_UE_INFORMATION_TAG); ++i) {
        pdu->crc_indication.crcflag ^= ((RX_UE_INFORMATION_TAG)pdu->ue_tag >> (8 * i)) & 0xFF;
        for (int j = 0; j < 8; ++j) {
            if (pdu->crc_indication.crcflag & 0x01) {
                pdu->crc_indication.crcflag = (pdu->crc_indication.crcflag >> 1) ^ CRC8_POLYNOMIAL;
            } else {
                pdu->crc_indication.crcflag >>= 1;
            }
        }
    }
}

int resource_manager_add(ResourceManager *rm, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&rm->mutex);
    if (rm->active_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&rm->mutex);
        return -1; // Resource limit exceeded
    }
    rm->pdu_list[rm->active_count++] = pdu;
    calculate_crc(pdu);
    pthread_mutex_unlock(&rm->mutex);
    return 0;
}

void resource_manager_remove(ResourceManager *rm, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&rm->mutex);
    for (int i = 0; i < rm->active_count; ++i) {
        if (rm->pdu_list[i] == pdu) {
            rm->pdu_list[i] = rm->pdu_list[--rm->active_count];
            break;
        }
    }
    pthread_mutex_unlock(&rm->mutex);
}

int main() {
    ResourceManager rm;
    pthread_mutex_init(&rm.mutex, NULL);
    rm.active_count = 0;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { /* initialize fields */ };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { /* initialize fields */ };

    if (resource_manager_add(&rm, &pdu1) == 0) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU due to resource limit.\n");
    }

    if (resource_manager_add(&rm, &pdu2) == 0) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU due to resource limit.\n");
    }

    resource_manager_remove(&rm, &pdu1);
    pthread_mutex_destroy(&rm.mutex);

    return 0;
}
