NetworkConfig* create_network_config() {
    NetworkConfig *config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    config->cell_configs = NULL;
    config->num_cell_configs = 0;
    pthread_mutex_init(&config->cell_config_lock, NULL);
    return config;
}

void add_cell_config(NetworkConfig *config, NRCellConfig_t cell_config) {
    pthread_mutex_lock(&config->cell_config_lock);
    config->cell_configs = realloc(config->cell_configs, (config->num_cell_configs + 1) * sizeof(NRCellConfig_t));
    config->cell_configs[config->num_cell_configs++] = cell_config;
    pthread_mutex_unlock(&config->cell_config_lock);
}

void remove_cell_config(NetworkConfig *config, int index) {
    pthread_mutex_lock(&config->cell_config_lock);
    if (index >= 0 && index < config->num_cell_configs) {
        for (int i = index; i < config->num_cell_configs - 1; i++) {
            config->cell_configs[i] = config->cell_configs[i + 1];
        }
        config->num_cell_configs--;
    }
    pthread_mutex_unlock(&config->cell_config_lock);
}

