    if (index >= 0 && index < data->num_crc_indications) {
        for (int i = index; i < data->num_crc_indications - 1; i++) {
            data->crc_indications[i] = data->crc_indications[i + 1];
        }
        data->num_crc_indications--;
    }
    pthread_mutex_unlock(&data->crc_indication_lock);
