    if (!manager) return NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void record_manager_add_record(RecordManager *manager, NFAPI_CRC_INDICATION_PDU_T *record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_RECORDS) {
        manager->records[manager->count++] = record;
    }
    pthread_mutex_unlock(&manager->lock);
}

void record_manager_cleanup(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
}

void record_manager_destroy(RecordManager *manager) {
    record_manager_cleanup(manager);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
