#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PDU_COUNT 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
int current_count = 0;
int max_count = MAX_PDU_COUNT;

void initialize_pdu_array(int count) {
    if (count > MAX_PDU_COUNT) {
        fprintf(stderr, "Error: Requested count exceeds maximum capacity.\n");
        return;
    }
    pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        fprintf(stderr, "Error: Failed to allocate memory for PDU array.\n");
        return;
    }
    max_count = count;
    current_count = 0;

    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_array[i].RNTI = rand() % 1000;
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void serialize_pdu_array(const char* filename) {
    if (!filename || !pdu_array) {
        fprintf(stderr, "Error: Invalid file path or uninitialized PDU array.\n");
        return;
    }

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    size_t written = fwrite(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_count, file);
    if (written != current_count) {
        fprintf(stderr, "Error: Failed to write all PDU elements to file.\n");
    } else {
        printf("Successfully serialized %zu PDUs to %s\n", written, filename);
    }

    fclose(file);
}

void deserialize_pdu_array(const char* filename) {
    if (!filename || !pdu_array) {
        fprintf(stderr, "Error: Invalid file path or uninitialized PDU array.\n");
        return;
    }

    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return;
    }

    size_t read_count = fread(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), max_count, file);
    if (read_count > current_count) {
        fprintf(stderr, "Warning: More PDUs were read than allocated space.\n");
    } else {
        printf("Successfully deserialized %zu PDUs from %s\n", read_count, filename);
    }

    fclose(file);
}

void validate_crc_flags(int reference_value) {
    for (int i = 0; i < current_count; i++) {
        if (pdu_array[i].CRC_INDICATION_REL8_TAG != reference_value) {
            fprintf(stderr, "Warning: CRC flag mismatch at index %d. Expected %d, got %d\n", i, reference_value, pdu_array[i].CRC_INDICATION_REL8_TAG);
        }
    }
}

void test_suite() {
    initialize_pdu_array(512);
    serialize_pdu_array("pdu_data.bin");
    deserialize_pdu_array("pdu_data.bin");

    // Simulate CRC flag validation
    validate_crc_flags(0);

    free(pdu_array);
}
