void addEvent(EventList* list, time_t timestamp, EventType type, void* data, size_t dataSize) {
    Event* newEvent = (Event*)malloc(sizeof(Event));
    if (!newEvent) return; // Handle memory allocation failure

    newEvent->timestamp = timestamp;
    newEvent->type = type;
    newEvent->data = malloc(dataSize);
    if (!newEvent->data) {
        free(newEvent);
        return; // Handle memory allocation failure
    }
    memcpy(newEvent->data, data, dataSize);
    newEvent->dataSize = dataSize;
    newEvent->next = NULL;

    if (list->tail) {
        list->tail->next = newEvent;
    } else {
        list->head = newEvent;
    }
    list->tail = newEvent;
    list->count++;
}

void freeEvent(Event* event) {
    if (!event) return;
    free(event->data);
    free(event);
}

void cleanupInactiveEvents(EventList* list, time_t cutoffTime) {
    Event* current = list->head;
    Event* prev = NULL;

    while (current) {
        if (current->timestamp < cutoffTime) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            freeEvent(current);
            current = prev ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }

    if (list->tail && list->tail->timestamp < cutoffTime) {
        list->tail = prev;
    }
}

