#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <time.h>

#define MAX_IP_ADDRESSES 10
#define DEFAULT_TIMEOUT 5
#define MAX_CONCURRENT_QUERIES 100
#define CACHE_DURATION 3600

typedef struct {
    char hostname[256];
    u_char ip_addresses[MAX_IP_ADDRESSES][16];
    int num_ip_addresses;
    time_t cache_expiration;
} DNSResult;

typedef void (*DNSCallback)(const DNSResult *result, void *user_data);

void dns_query(const char *hostname, DNSCallback callback, void *user_data) {
    struct addrinfo hints, *res, *p;
    int status;
    DNSResult result = {0};
    time_t current_time = time(NULL);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        callback(&result, user_data);
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET || p->ai_family == AF_INET6) {
            memcpy(result.ip_addresses[result.num_ip_addresses], p->ai_addr, p->ai_addrlen);
            result.num_ip_addresses++;
            if (result.num_ip_addresses >= MAX_IP_ADDRESSES) break;
        }
    }

    freeaddrinfo(res);

    result.hostname[0] = '\0';
    strncpy(result.hostname, hostname, sizeof(result.hostname) - 1);
    result.cache_expiration = current_time + CACHE_DURATION;

    callback(&result, user_data);
}

void dns_query_async(const char *hostname, DNSCallback callback, void *user_data) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, (void *(*)(void *))dns_query, (void *)hostname) != 0) {
        fprintf(stderr, "Failed to create thread for DNS query\n");
    }
}

int main() {
    void dns_callback(const DNSResult *result, void *user_data) {
        printf("Hostname: %s\n", result->hostname);
        for (int i = 0; i < result->num_ip_addresses; i++) {
            char ip_str[INET6_ADDRSTRLEN];
            if (inet_ntop(result->ip_addresses[i][0] == AF_INET ? AF_INET : AF_INET6, &result->ip_addresses[i], ip_str, sizeof(ip_str)) != NULL) {
                printf("IP Address %d: %s\n", i + 1, ip_str);
            }
        }
    }

    dns_query_async("example.com", dns_callback, NULL);

    pthread_exit(NULL);
}
