#define MAX_ENTRIES 10000

typedef struct LTE_DL_FRAME_MSG_T {
    PHY_RX_UE_INFO tag;
    uint16_t RNTI;
    PHY_DL_FRAME_INDication indication;
} LTE_DL_FRAME_MSG_T;

typedef struct ListNode {
    LTE_DL_FRAME_MSG_T data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_init() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_insert(DynamicList* list, LTE_DL_FRAME_MSG_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        // Handle error or log
        pthread_mutex_unlock(&list->lock);
        return;
    }
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

LTE_DL_FRAME_MSG_T* dynamic_list_get(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count || list->count == 0) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    ListNode* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    LTE_DL_FRAME_MSG_T* data = &current->data;
    pthread_mutex_unlock(&list->lock);
    return data;
}

void dynamic_list_free(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
