#include <iostream>
#include <forward_list>
#include <string>
#include <algorithm>

void insertOrMerge(std::forward_list<std::pair<std::string, int>>& list, const std::string& target, const std::string& newString) {
    auto it = list.begin();
    bool found = false;

    while (it != list.end()) {
        if (it->first == target) {
            it->second++;
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        list.push_back({newString, 1});
    } else {
        std::sort(list.begin(), list.end());
    }
}

int main() {
    std::forward_list<std::pair<std::string, int>> myList = {{"apple", 2}, {"banana", 3}};

    insertOrMerge(myList, "banana", "orange");
    insertOrMerge(myList, "grape", "apple");

    for (const auto& item : myList) {
        std::cout << item.first << ": " << item.second << std::endl;
    }

    return 0;
}
