#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    PHY_RRC_CHANNEL_MAP channel_map;
    int CELL_ID;
    int FRAME_NUM;
} LTE_PHY_RX_FRAME_INFO;

typedef struct {
    LTE_PHY_RX_FRAME_INFO* frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->frames = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array->frames) free(array->frames);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_frame_to_array(DynamicArray* array, LTE_PHY_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        if (new_capacity > MAX_MEMORY_LIMIT / sizeof(LTE_PHY_RX_FRAME_INFO)) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory limit exceeded
        }

        LTE_PHY_RX_FRAME_INFO* new_frames = realloc(array->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
        if (!new_frames) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Realloc failed
        }

        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    if (array->size > 0 && array->frames[array->size - 1].CELL_ID == frame.CELL_ID) {
        pthread_mutex_unlock(&array->lock);
        return -3; // Consecutive frames with the same CELL_ID
    }

    array->frames[array->size++] = frame;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

// Example usage:
int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) return -1;

    LTE_PHY_RX_FRAME_INFO frame = { /* initialize with valid values */ };

    int result = add_frame_to_array(array, frame);
    if (result != 0) {
        // Handle error
    }

    destroy_dynamic_array(array);
    return 0;
}
```

