        if ((time(NULL) - transactions[i].timestamp <= 30) && (transactions[i].value <= threshold)) {
            double marketFactor = calculateMarketFactor();
            double weightedValue = transactions[i].value * marketFactor;
            if (totalWeightedSum + weightedValue <= limit) {
                selectedTransactions[*selectedCount] = &transactions[i];
                (*selectedCount)++;
                totalWeightedSum += weightedValue;
            }
        }
    }

    return (int)totalWeightedSum;
}

void manageMemory(Transaction* transactions, HistoricalEvent* events) {
    free(transactions);
    free(events);
}

