typedef struct {
    time_t timestamp;
    char event_type[50];
    int event_id;
} TickerEvent;

typedef struct {
    TickerEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} EventList;

void init_event_list(EventList* list, size_t initial_capacity) {
    list->events = (TickerEvent*)malloc(initial_capacity * sizeof(TickerEvent));
    if (!list->events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_event_list(EventList* list) {
    size_t new_capacity = list->capacity * 2;
    TickerEvent* new_events = (TickerEvent*)realloc(list->events, new_capacity * sizeof(TickerEvent));
    if (!new_events) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->events = new_events;
    list->capacity = new_capacity;
}

void add_event(EventList* list, TickerEvent event) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resize_event_list(list);
    }
    list->events[list->size++] = event;
    pthread_mutex_unlock(&list->mutex);
}

void free_event_list(EventList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->events);
}

// Serialization and deserialization functions
void serialize_event_list(const EventList* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fprintf(file, "timestamp,event_type,event_id\n");
    for (size_t i = 0; i < list->size; ++i) {
        TickerEvent event = list->events[i];
        fprintf(file, "%ld,%s,%d\n", event.timestamp, event.event_type, event.event_id);
    }
    fclose(file);
}

void deserialize_event_list(EventList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        TickerEvent event;
        if (sscanf(line, "%ld,%[^,],%d", &event.timestamp, event.event_type, &event.event_id) == 3) {
            add_event(list, event);
        }
    }
    fclose(file);
}

// Error handling and caching strategies
void handle_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    // Additional error handling logic can be added here
}

