#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <arpa/inet.h>

#define MAX_EVENT_SIZE 1024

typedef struct NetworkEvent {
    time_t timestamp;
    char type[32];
    u_char data[MAX_EVENT_SIZE];
    struct NetworkEvent *next;
} NetworkEvent;

NetworkEvent* event_list = NULL;
pthread_mutex_t event_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_event(time_t timestamp, const char* type, const u_char* data, size_t data_size) {
    pthread_mutex_lock(&event_mutex);
    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    new_event->timestamp = timestamp;
    strncpy(new_event->type, type, sizeof(new_event->type) - 1);
    memcpy(new_event->data, data, data_size > MAX_EVENT_SIZE ? MAX_EVENT_SIZE : data_size);
    new_event->next = event_list;
    event_list = new_event;
    pthread_mutex_unlock(&event_mutex);
}

NetworkEvent* get_events_by_time_range(time_t start, time_t end) {
    NetworkEvent* result = NULL;
    pthread_mutex_lock(&event_mutex);
    for (NetworkEvent* current = event_list; current != NULL; current = current->next) {
        if (current->timestamp >= start && current->timestamp <= end) {
            NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
            memcpy(new_event, current, sizeof(NetworkEvent));
            new_event->next = result;
            result = new_event;
        }
    }
    pthread_mutex_unlock(&event_mutex);
    return result;
}

void cleanup_inactive_events(time_t threshold) {
    pthread_mutex_lock(&event_mutex);
    NetworkEvent* current = event_list;
    NetworkEvent* prev = NULL;
    while (current != NULL) {
        if (time(NULL) - current->timestamp > threshold) {
            if (prev == NULL) {
                event_list = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&event_mutex);
}

int resolve_dns(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s\n", ipstr);

        // copy the IP address to the output buffer
        memcpy(ip_address, ipstr, strlen(ipstr));
    }

    freeaddrinfo(res); // free the linked list

    return 0;
}

void log_event(const char* message) {
    FILE* log_file = fopen("network_events.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
