#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Event {
    time_t timestamp;
    int type;
    void* data;
    size_t dataSize;
    struct Event* next;
} Event;

typedef struct EventList {
    Event* head;
    Event* tail;
    size_t count;
} EventList;

Event* createEvent(time_t timestamp, int type, const void* data, size_t dataSize) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (event == NULL) return NULL;
    event->timestamp = timestamp;
    event->type = type;
    event->dataSize = dataSize;
    event->data = malloc(dataSize);
    if (event->data == NULL) {
        free(event);
        return NULL;
    }
    memcpy(event->data, data, dataSize);
    event->next = NULL;
    return event;
}

void addEvent(EventList* list, Event* event) {
    if (list->tail != NULL) {
        list->tail->next = event;
    } else {
        list->head = event;
    }
    list->tail = event;
    list->count++;
}

Event* getEventsInRange(EventList* list, time_t start, time_t end) {
    Event* result = NULL;
    for (Event* current = list->head; current != NULL; current = current->next) {
        if (current->timestamp >= start && current->timestamp <= end) {
            Event* newEvent = createEvent(current->timestamp, current->type, current->data, current->dataSize);
            if (newEvent == NULL) continue;
            addEvent(&result, newEvent);
        }
    }
    return result;
}

void freeEvents(EventList* list) {
    while (list->head != NULL) {
        Event* temp = list->head;
        list->head = list->head->next;
        free(temp->data);
        free(temp);
    }
    list->tail = NULL;
    list->count = 0;
}

int main() {
    EventList eventList = {NULL, NULL, 0};
    time_t now = time(NULL);

    // Add events
    addEvent(&eventList, createEvent(now - 3600, 1, "Data1", 5));
    addEvent(&eventList, createEvent(now - 1800, 2, "Data2", 5));
    addEvent(&eventList, createEvent(now, 3, "Data3", 5));

    // Retrieve events in the last hour
    Event* events = getEventsInRange(&eventList, now - 3600, now);
    for (Event* current = events; current != NULL; current = current->next) {
        printf("Timestamp: %ld, Type: %d, Data: %s\n", current->timestamp, current->type, (char*)current->data);
    }

    // Free events
    freeEvents(&eventList);

    return 0;
}
