import json
import subprocess
import os

def generate_config_file(json_config_path, template_path, output_path):
    with open(json_config_path, 'r') as file:
        config_data = json.load(file)

    with open(template_path, 'r') as file:
        template_content = file.read()

    for key, value in config_data.items():
        template_content = template_content.replace(f'${{{key}}}', str(value))

    encrypted_password = subprocess.check_output(['openssl', 'rand', '-base64', '12']).decode().strip()
    template_content += f'\npassword={encrypted_password}'

    with open(output_path, 'w') as file:
        file.write(template_content)

def main():
    json_config_path = 'config.json'
    template_path = 'template.conf'
    output_path = 'output.conf'

    try:
        generate_config_file(json_config_path, template_path, output_path)
        print(f'Configuration file generated successfully at {output_path}')
    except subprocess.CalledProcessError as e:
        print(f'Sed command failed: {e}')

if __name__ == '__main__':
    main()
