using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly IResourceService _resourceService;

    public ResourceController(IResourceService resourceService)
    {
        _resourceService = resourceService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, [FromBody] ResourceUpdateModel updateModel, [FromQuery] int? version)
    {
        var result = await _resourceService.UpdateResourceAsync(id, updateModel, version);
        if (result == null)
            return NotFound();
        if (!result.IsSuccess)
            return Conflict(result.ErrorMessage);

        return Ok(result.Resource);
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        var result = await _resourceService.DeleteResourceAsync(id, User.Identity.Name);
        if (result == null)
            return NotFound();
        if (!result.IsSuccess)
            return Forbid();

        return Ok(result.NewResource);
    }
}

public class ResourceUpdateModel
{
    public string Name { get; set; }
    public int Quantity { get; set; }
}

public class ResourceService : IResourceService
{
    private readonly IResourceRepository _resourceRepository;

    public ResourceService(IResourceRepository resourceRepository)
    {
        _resourceRepository = resourceRepository;
    }

    public async Task<ResourceUpdateResult> UpdateResourceAsync(int id, ResourceUpdateModel updateModel, int? version)
    {
        var resource = await _resourceRepository.GetByIdAsync(id);
        if (resource == null)
            return new ResourceUpdateResult { IsSuccess = false, ErrorMessage = "Resource not found" };

        if (version.HasValue && resource.Version != version.Value)
            return new ResourceUpdateResult { IsSuccess = false, ErrorMessage = "Version mismatch" };

        resource.Name = updateModel.Name;
        resource.Quantity = updateModel.Quantity;
        resource.Version++;

        await _resourceRepository.UpdateAsync(resource);
        return new ResourceUpdateResult { IsSuccess = true, Resource = resource };
    }

    public async Task<ResourceDeleteResult> DeleteResourceAsync(int id, string ownerId)
    {
        var resource = await _resourceRepository.GetByIdAsync(id);
        if (resource == null)
            return new ResourceDeleteResult { IsSuccess = false };

        if (resource.OwnerId != ownerId)
            return new ResourceDeleteResult { IsSuccess = false, ErrorMessage = "Unauthorized" };

        var newResource = new Resource
        {
            Id = id,
            Name = "Deleted",
            Quantity = 0,
            Version = resource.Version + 1,
            OwnerId = ownerId
        };

        await _resourceRepository.DeleteAsync(resource);
        await _resourceRepository.AddAsync(newResource);

        return new ResourceDeleteResult { IsSuccess = true, NewResource = newResource };
    }
}

public interface IResourceService
{
    Task<ResourceUpdateResult> UpdateResourceAsync(int id, ResourceUpdateModel updateModel, int? version);
    Task<ResourceDeleteResult> DeleteResourceAsync(int id, string ownerId);
}

public class ResourceUpdateResult
{
    public bool IsSuccess { get; set; }
    public string ErrorMessage { get; set; }
    public Resource Resource { get; set; }
}

public class ResourceDeleteResult
{
    public bool IsSuccess { get; set; }
    public string ErrorMessage { get; set; }
    public Resource NewResource { get; set; }
}

public interface IResourceRepository
{
    Task<Resource> GetByIdAsync(int id);
    Task UpdateAsync(Resource resource);
    Task DeleteAsync(Resource resource);
    Task AddAsync(Resource resource);
}

public class Resource
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Quantity { get; set; }
    public int Version { get; set; }
    public string OwnerId { get; set; }
}
