#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define IV_SIZE 16
#define SALT_SIZE 16

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} EncryptionContext;

int derive_key(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 10000, EVP_sha256(), KEY_SIZE, key);
}

int encrypt_data(const EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) return -1;

    if (1 != EVP_EncryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx_evp, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx_evp, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
    return ciphertext_len;
}

int decrypt_data(const EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) return -1;

    if (1 != EVP_DecryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx_evp, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx_evp, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
    return plaintext_len;
}

int generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, IV_SIZE)) return -1;
    return 0;
}

EncryptionContext* create_encryption_context(const char *password) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, SALT_SIZE)) {
        free(ctx);
        return NULL;
    }

    if (derive_key(password, salt, sizeof(salt), ctx->key) != 0) {
        free(ctx);
        return NULL;
    }

    if (generate_iv(ctx->iv) != 0) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    free(ctx);
}
