bool validate_crc_flag(bool crc_flag, const bool* expected_values, size_t expected_count) {
    for (size_t i = 0; i < expected_count; ++i) {
        if (crc_flag == expected_values[i]) {
            return true;
        }
    }
    return false;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_crc_indications(size_t N, const bool* expected_crc_values, size_t expected_count, int max_retries) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        int retries = 0;
        bool valid_crc_flag = false;

        while (!valid_crc_flag && retries < max_retries) {
            crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
            crc_indications[i].RNTI = rand() % 256; // Example range
            crc_indications[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0;

            valid_crc_flag = validate_crc_flag(crc_indications[i].CRC_INDICATION_REL8_TAG, expected_crc_values, expected_count);
            retries++;
        }

        if (!valid_crc_flag) {
            // Handle error: Could not find a valid CRC flag after max retries
            free(crc_indications);
            return NULL;
        }
    }

    return crc_indications;
}
