void log_memory_usage(size_t allocated, size_t freed) {
    printf("Memory Usage: Allocated = %zu bytes, Freed = %zu bytes\n", allocated, freed);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indication_pdu(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be greater than 0\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed for %d structures\n", N);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    size_t total_allocated = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 65536;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu_list[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
    }

    log_memory_usage(total_allocated, 0);

    return pdu_list;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int N) {
    if (pdu_list) {
        size_t total_freed = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        free(pdu_list);
        log_memory_usage(0, total_freed);
