typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t max_size;
} CRC_Indication_Array;

void initialize_crc_array(CRC_Indication_Array *crc_array, size_t max_size) {
    crc_array->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    crc_array->array = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    crc_array->size = 0;
    crc_array->max_size = max_size;
}

void destroy_crc_array(CRC_Indication_Array *crc_array) {
    pthread_mutex_lock(&crc_array->mutex);
    free(crc_array->array);
    pthread_mutex_unlock(&crc_array->mutex);
    pthread_mutex_destroy(&crc_array->mutex);
}

int add_to_crc_array(CRC_Indication_Array *crc_array, NFAPI_CRC_INDICATION_PDU_T *new_data) {
    pthread_mutex_lock(&crc_array->mutex);
    if (crc_array->size >= crc_array->max_size) {
        pthread_mutex_unlock(&crc_array->mutex);
        return -1; // Array is full
    }
    crc_array->array[crc_array->size++] = *new_data;
    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}

int read_from_binary_files(CRC_Indication_Array *crc_array, const char *file_paths[], size_t num_files) {
    for (size_t i = 0; i < num_files; ++i) {
        FILE *file = fopen(file_paths[i], "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T data;
        while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            if (add_to_crc_array(crc_array, &data) != 0) {
                break; // Array is full
            }
        }

        fclose(file);
    }
    return 0;
}

// Example usage:
int main() {
    CRC_Indication_Array crc_array;
    initialize_crc_array(&crc_array, MAX_ARRAY_SIZE);

    const char *file_paths[] = {"file1.bin", "file2.bin"};
    read_from_binary_files(&crc_array, file_paths, sizeof(file_paths) / sizeof(file_paths[0]));

    // Perform operations on the array...

    destroy_crc_array(&crc_array);
    return 0;
}
