#define MAX_ENB_CONTEXTS 1024

typedef struct {
    LTE_ENB_CONTEXT_T enbContexts[MAX_ENB_CONTEXTS];
    int count;
} ENB_CONTEXT_MANAGER;

ENB_CONTEXT_MANAGER* enbManager = NULL;

LTE_ENB_CONTEXT_T* createEnbContext(int cellId, int frequencyBand) {
    LTE_ENB_CONTEXT_T* newContext = (LTE_ENB_CONTEXT_T*)malloc(sizeof(LTE_ENB_CONTEXT_T));
    if (newContext == NULL) {
        logError("Memory allocation failed for eNB context");
        return NULL;
    }
    newContext->cellId = cellId;
    newContext->frequencyBand = frequencyBand;
    memset(&newContext->neighboringCells, 0, sizeof(newContext->neighboringCells));
    return newContext;
}

void freeEnbContext(LTE_ENB_CONTEXT_T* context) {
    if (context != NULL) {
        free(context);
    }
}

int addEnbContext(int cellId, int frequencyBand) {
    if (enbManager == NULL) {
        enbManager = (ENB_CONTEXT_MANAGER*)malloc(sizeof(ENB_CONTEXT_MANAGER));
        if (enbManager == NULL) {
            logError("Memory allocation failed for eNB context manager");
            return -1;
        }
        memset(enbManager, 0, sizeof(ENB_CONTEXT_MANAGER));
    }

    if (enbManager->count >= MAX_ENB_CONTEXTS) {
        logWarning("Maximum number of eNB contexts reached");
        return -2;
    }

    LTE_ENB_CONTEXT_T* newContext = createEnbContext(cellId, frequencyBand);
    if (newContext == NULL) {
        return -3;
    }

    enbManager->enbContexts[enbManager->count++] = *newContext;
    logInfo("eNB context added with cell ID %d", cellId);

    return 0;
}

int removeEnbContext(int cellId) {
    if (enbManager == NULL || enbManager->count == 0) {
        return -1;
    }

    for (int i = 0; i < enbManager->count; i++) {
        if (enbManager->enbContexts[i].cellId == cellId) {
            freeEnbContext(&enbManager->enbContexts[i]);
            memmove(&enbManager->enbContexts[i], &enbManager->enbContexts[i + 1], sizeof(LTE_ENB_CONTEXT_T) * (enbManager->count - i - 1));
            enbManager->count--;
            logInfo("eNB context removed with cell ID %d", cellId);
            return 0;
        }
    }

    logWarning("eNB context with cell ID %d not found", cellId);
    return -2;
}

void freeEnbContextManager() {
    if (enbManager != NULL) {
        for (int i = 0; i < enbManager->count; i++) {
            freeEnbContext(&enbManager->enbContexts[i]);
        }
        free(enbManager);
        enbManager = NULL;
    }
}
