#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    time_t timestamp;
    char network_id[10];
    unsigned long uplink_bytes;
    unsigned long downlink_bytes;
} NetworkReport;

typedef struct Node {
    NetworkReport data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} ReportList;

void init_report_list(ReportList* list) {
    list->head = NULL;
}

Node* create_node(NetworkReport report) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = report;
    new_node->next = NULL;
    return new_node;
}

void add_report(ReportList* list, NetworkReport report) {
    Node* new_node = create_node(report);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

unsigned long get_total_traffic(ReportList* list, const char* network_id, time_t start_time, time_t end_time) {
    unsigned long total_traffic = 0;
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.network_id, network_id) == 0 && current->data.timestamp >= start_time && current->data.timestamp <= end_time) {
            total_traffic += current->data.uplink_bytes + current->data.downlink_bytes;
        }
        current = current->next;
    }
    return total_traffic;
}

void free_report_list(ReportList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
}
