#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define BUFFER_SIZE 512

typedef struct {
    int RX_POWER;
    int RX_QUALITY;
    int RX_TIME_STAMP;
} NFAPI_L2_STATS_PDU_T;

typedef struct {
    NFAPI_L2_STATS_PDU_T buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_buffer() {
    CircularBuffer* cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
    return cb;
}

void destroy_buffer(CircularBuffer* cb) {
    pthread_mutex_destroy(&cb->mutex);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int insert_data(CircularBuffer* cb, NFAPI_L2_STATS_PDU_T data) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == BUFFER_SIZE) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }
    cb->buffer[cb->tail] = data;
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    cb->count++;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int retrieve_data(CircularBuffer* cb, NFAPI_L2_STATS_PDU_T* data) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->mutex);
    }
    *data = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count--;
    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

void reset_buffer(CircularBuffer* cb) {
    pthread_mutex_lock(&cb->mutex);
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_cond_signal(&cb->not_full);
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
}

double calculate_moving_average(CircularBuffer* cb, int window_size) {
    double sum = 0;
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (cb->buffer[i].RX_QUALITY != 0) {
            sum += cb->buffer[i].RX_QUALITY;
            count++;
        }
        if (count >= window_size) break;
    }
    return count > 0 ? sum / count : 0;
}
