#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void* generate_records(void* arg) {
    long* offsets = (long*)arg;
    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        pthread_exit(NULL);
    }

    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        free(keys);
        perror("Failed to allocate memory for records");
        pthread_exit(NULL);
    }

    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; ++i) {
        keys[i] = rand() % 1000;
        records[i].value = rand() % 1000;
        offsets[keys[i]] = i * sizeof(record);
    }

    free(keys);
    pthread_exit((void*)records);
}

int main() {
    long* offsets = (long*)calloc(1000, sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_records, offsets)) {
        perror("Failed to create thread");
        free(offsets);
        return EXIT_FAILURE;
    }

    record* records = (record*)pthread_join(thread, NULL);
    if (!records) {
        perror("Thread failed");
        free(offsets);
        return EXIT_FAILURE;
    }

    // Calculate and validate checksum
    int expected_checksum = 0;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        expected_checksum += records[i].value;
    }

    int actual_checksum = 0;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        actual_checksum += records[i].value;
    }

    if (expected_checksum != actual_checksum) {
        fprintf(stderr, "Checksum mismatch: expected %d, got %d\n", expected_checksum, actual_checksum);
        free(offsets);
        free(records);
        return EXIT_FAILURE;
    }

    // Log performance metrics and integrity check
    printf("Integrity check passed. Performance metrics logged.\n");

    free(offsets);
    free(records);

    return EXIT_SUCCESS;
}
