#include <time.h>

#define MAX_TRAFFIC_METRICS 10

typedef struct {
    time_t timestamp;
    char network_id[50];
    unsigned long uplink_bytes[MAX_TRAFFIC_METRICS];
    unsigned long downlink_bytes[MAX_TRAFFIC_METRICS];
} NetworkReport;

typedef struct Node {
    NetworkReport data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    time_t last_prune_time;
} ReportList;

void init_report_list(ReportList* list) {
    list->head = NULL;
    list->last_prune_time = 0;
}

Node* create_node(NetworkReport data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_report(ReportList* list, NetworkReport report) {
    Node* new_node = create_node(report);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void prune_reports(ReportList* list, time_t threshold) {
    if (list->head == NULL || difftime(threshold, list->last_prune_time) < 3600) {
        return;
    }
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > threshold) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    list->last_prune_time = time(NULL);
}

void print_reports(ReportList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Network ID: %s\n", current->data.timestamp, current->data.network_id);
        for (int i = 0; i < MAX_TRAFFIC_METRICS; i++) {
            printf("Uplink Bytes %d: %lu, Downlink Bytes %d: %lu\n", i, current->data.uplink_bytes[i], i, current->data.downlink_bytes[i]);
        }
        current = current->next;
    }
}

void free_report_list(ReportList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
}
