#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define COOLDOWN_SECONDS 9

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t lock;
} CustomMemoryPool;

void initializeMemoryPool(CustomMemoryPool *pool) {
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(CustomMemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element != NULL) {
        pthread_mutex_lock(&pool->lock);
        pool->elements[pool->count++] = element;
        pthread_mutex_unlock(&pool->lock);
    }
    return element;
}

void populateNFACRCList() {
    CustomMemoryPool pool;
    initializeMemoryPool(&pool);

    srand(time(NULL));
    int initialElements, stopProbability;
    // Assume these are set from configuration or command-line arguments
    initialElements = 500;
    stopProbability = 30; // 30% chance to stop

    for (int i = 0; i < initialElements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = allocateFromPool(&pool);
        if (element != NULL) {
            element->RX_UE_INFORMATION_TAG = rand() % 100;
            element->RNTI = rand() % 256;
            element->CRC_INDICATION_REL8_TAG = rand() % 2;
        }
    }

    pthread_t cooldownThread;
    if (pthread_create(&cooldownThread, NULL, cooldownProcess, &pool) != 0) {
        perror("Failed to create cooldown thread");
        return;
    }

    pthread_join(cooldownThread, NULL);
}

void* cooldownProcess(void *arg) {
    CustomMemoryPool *pool = (CustomMemoryPool*)arg;
    int stop = 0;

    for (int i = 0; i < COOLDOWN_SECONDS && !stop; ++i) {
        sleep(1);

        if (rand() % 100 < stopProbability) {
            NFAPI_CRC_INDICATION_PDU_T *element = allocateFromPool(pool);
            if (element != NULL) {
                element->RX_UE_INFORMATION_TAG = rand() % 100;
                element->RNTI = rand() % 256;
                element->CRC_INDICATION_REL8_TAG = rand() % 2;
            }
        } else {
            stop = 1;
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    populateNFACRCList();
    return 0;
}
