function copyBytesFromChunks(chunks, offset, length) {
  let totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);

  if (offset < 0 || length < 0 || offset + length > totalLength) {
    throw new Error('Invalid offset or length');
  }

  let newBuffer = Buffer.allocUnsafe(length);

  let bytesCopied = 0;
  for (let i = 0; i < chunks.length && bytesCopied < length; i++) {
    if (offset >= chunks[i].length) {
      offset -= chunks[i].length;
      continue;
    }

    let chunkOffset = Math.max(0, offset);
    let chunkLength = Math.min(chunks[i].length - chunkOffset, length - bytesCopied);

    newBuffer.write(chunks[i], chunkOffset, chunkLength, 'binary');
    bytesCopied += chunkLength;
    offset = 0; // Reset offset after copying from the first chunk
  }

  return { buffer: newBuffer, remainingChunks: chunks.slice(i) };
}
