unsigned long calculate_total_traffic(const char *network_id, time_t start_time, time_t end_time) {
    unsigned long total_traffic = 0;
    for (int i = 0; i < MAX_NETWORKS; i++) {
        if (network_stats[i] && strcmp(network_stats[i]->network_id, network_id) == 0 &&
            network_stats[i]->timestamp >= start_time && network_stats[i]->timestamp <= end_time) {
            total_traffic += network_stats[i]->uplink_bytes + network_stats[i]->downlink_bytes;
        }
    }
