["```javascript
// contentLoader.js

const CDN_URL = 'https://cdn.example.com/';

function loadScript(url, callback) {
  const script = document.createElement('script');
  script.src = url;
  script.onload = () => callback(null, script);
  script.onerror = (error) => callback(error, null);
  document.head.appendChild(script);
}

function loadCSS(url, callback) {
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = url;
  link.onload = () => callback(null, link);
  link.onerror = (error) => callback(error, null);
  document.head.appendChild(link);
}

function loadResource(type, url, fallbackUrl, callback) {
  const attemptLoad = (urlToTry) => {
    const resourceLoader = type === 'script' ? loadScript : loadCSS;
    resourceLoader(urlToTry, (error, resource) => {
      if (error) {
        console.warn(`Failed to load ${type} from ${urlToTry}. Trying fallback...`);
        attemptLoad(fallbackUrl);
      } else {
        callback(null, resource);
      }
    });
  };

  attemptLoad(url);
}

function loadDependencies(dependencies, callback) {
  const loadNext = (index) => {
    if (index >= dependencies.length) {
      return callback(null, 'All resources loaded successfully');
    }

    const { type, url, fallbackUrl } = dependencies[index];
    loadResource(type, url, fallbackUrl, (error, resource) => {
      if (error) {
        console.error(`Failed to load ${type} from any source`);
        return callback(error);
      }
      loadNext(index + 1);
    });
  };

  loadNext(0);
}

export default {
  loadDependencies,
};
```

This JavaScript module provides a `loadDependencies` function that takes an array of resource dependencies and loads them in the correct order. Each dependency is specified with its type (`script` or `css`), primary URL, and fallback URL. The module attempts to load each resource from the primary URL; if it fails, it falls back to the secondary URL. If both URLs fail, it logs an error.

The `loadScript` and `loadCSS` functions handle the actual loading of scripts and stylesheets, respectively, ensuring that they are added to the document's head and triggering callbacks on load or error.

This module is designed to be flexible and maintainable, allowing for easy addition of new dependencies and fallback strategies. It also handles network conditions by attempting to load resources from multiple sources if the primary fails."]

