#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_REALLOCATIONS 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_random_rnti(int previous_rnti) {
    static int last_rnti = 0;
    if (previous_rnti == -1) {
        srand(time(NULL));
        last_rnti = rand() % 1000; // Example range
    } else {
        do {
            last_rnti = (last_rnti + 1) % 1000; // Ensure no two consecutive RNTIs are the same
        } while (last_rnti == previous_rnti);
    }
    return last_rnti;
}

int generate_random_crcflag() {
    return rand() % 2; // Example range
}

NFAPI_CRC_INDICATION_PDU_T* manage_array(int N, int *reallocation_count) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int current_size = 0;

    for (int i = 0; i < N; ) {
        if (current_size == 0 || array[current_size - 1].RNTI != generate_random_rnti(current_size > 0 ? array[current_size - 1].RNTI : -1)) {
            if (array == NULL) {
                array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                current_size = N;
            } else if (current_size < N) {
                NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (new_array == NULL) {
                    if (*reallocation_count < MAX_REALLOCATIONS) {
                        *reallocation_count += 1;
                        new_array = array; // Retry with the same memory
                    } else {
                        free(array);
                        return NULL; // Maximum reallocations reached
                    }
                }
                array = new_array;
                current_size = N;
            }

            if (array != NULL) {
                array[i].RX_UE_INFORMATION_TAG = i + 1;
                array[i].RNTI = generate_random_rnti(i > 0 ? array[i - 1].RNTI : -1);
                array[i].CRC_INDICATION_REL8_TAG = i + 1;
                array[i].CRCFLAG = generate_random_crcflag();
                i++;
            }
        } else {
            // Skip this iteration if the RNTI is the same as the previous one
        }
    }

    return array;
}

int main() {
    int N = 1000; // Example size
    int reallocation_count = 0;

    NFAPI_CRC_INDICATION_PDU_T *array = manage_array(N, &reallocation_count);

    if (array != NULL) {
        printf("Array managed successfully with %d reallocations.\n", reallocation_count);
        free(array);
    } else {
        printf("Failed to manage array due to resource constraints.\n");
    }

    return 0;
}
