int initialize_aes_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    // Derive key using SHA-256
    unsigned char derived_key[32];
    if (EVP_Digest(password, strlen(password), derived_key, NULL, EVP_sha256()) != 32) {
        fprintf(stderr, "Failed to derive key\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Set key and IV length dynamically based on network conditions
    int key_length = 32; // AES-256 key length
    int iv_length = 16;  // AES block size

    // Allocate memory for key and IV
    *key = (unsigned char *)malloc(key_length);
    if (!*key) {
        fprintf(stderr, "Failed to allocate memory for key\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *iv = (unsigned char *)malloc(iv_length);
    if (!*iv) {
        fprintf(stderr, "Failed to allocate memory for IV\n");
        free(*key);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Copy derived key and generate random IV
    memcpy(*key, derived_key, key_length);
    if (RAND_bytes(*iv, iv_length) != 1) {
        fprintf(stderr, "Failed to generate random IV\n");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Initialize cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Log initialization success
    printf("AES-256-CBC cipher initialized successfully\n");

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int main() {
    const char *password = "secure_password";
    unsigned char *key, *iv;

    if (initialize_aes_cipher(password, &key, &iv) == 0) {
        // Use key and IV for encryption/decryption
        free(key);
        free(iv);
    }

    return 0;
}
