#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdio.h>

#define SALT_LEN 16
#define IV_LEN 12
#define KEY_LEN 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_LEN];
    unsigned char iv[IV_LEN];
} AES_GCM_CTX;

int aes_gcm_init(AES_GCM_CTX **ctx, const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int iteration_count) {
    *ctx = (AES_GCM_CTX *)malloc(sizeof(AES_GCM_CTX));
    if (!*ctx) return -1;

    (*ctx)->ctx = EVP_CIPHER_CTX_new();
    if (!(*ctx)->ctx) {
        free(*ctx);
        return -1;
    }

    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iteration_count, EVP_sha256(), KEY_LEN, (*ctx)->key) != 1) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1;
    }

    if (EVP_EncryptInit_ex((*ctx)->ctx, EVP_aes_256_gcm(), NULL, (*ctx)->key, NULL) != 1) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1;
    }

    if (RAND_bytes((*ctx)->iv, IV_LEN) != 1) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1;
    }

    if (EVP_EncryptUpdate((*ctx)->ctx, NULL, &(*ctx)->iv[IV_LEN], (*ctx)->iv, IV_LEN) != 1) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1;
    }

    return 0;
}

int aes_gcm_encrypt(AES_GCM_CTX *ctx, unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, size_t *ciphertext_len) {
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len) != 1) return -1;
    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + *ciphertext_len, ciphertext_len) != 1) return -1;

    unsigned char tag[16];
    size_t tag_len = 16;
    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, tag_len, tag) != 1) return -1;

    memcpy(ciphertext + *ciphertext_len, tag, tag_len);
    *ciphertext_len += tag_len;

    return 0;
}

void aes_gcm_cleanup(AES_GCM_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
