#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *struct_list[MAX_STRUCTS];
int current_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random_rnti(int *rnti) {
    // Simulate RNTI generation within network configuration limits
    *rnti = rand() % 16384 + 1; // Example range for RNTI
}

int is_valid_rnti(int rnti) {
    // Validate RNTI against network configuration limits
    return (rnti >= 1 && rnti <= 16384);
}

void populate_struct_list() {
    pthread_mutex_lock(&mutex);
    if (current_index < MAX_STRUCTS) {
        NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_struct->RX_UE_INFORMATION_TAG = rand();
        generate_random_rnti(&new_struct->RNTI);
        while (!is_valid_rnti(new_struct->RNTI)) {
            generate_random_rnti(&new_struct->RNTI);
        }
        new_struct->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        struct_list[current_index++] = new_struct;
    }
    pthread_mutex_unlock(&mutex);
}

void *thread_function(void *arg) {
    int num_iterations = *(int *)arg;
    for (int i = 0; i < num_iterations; i++) {
        populate_struct_list();
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    int iterations_per_thread = MAX_STRUCTS / 10;

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, &iterations_per_thread);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    for (int i = 0; i < current_index; i++) {
        free(struct_list[i]);
    }

    return 0;
}
