    *rnti = (rand() % (max_rnti - min_rnti + 1)) + min_rnti;
}

int is_rnti_available(uint16_t rnti, time_t timestamp, int window_size) {
    for (int i = 0; i < current_index; i++) {
        if (pdu_list[i].RNTI == rnti && 
            abs(difftime(timestamp, pdu_list[i].timestamp)) <= window_size) {
            return 0;
        }
    }
    return 1;
}

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint16_t min_rnti, uint16_t max_rnti, int window_size) {
    time_t current_time = time(NULL);
    uint16_t rnti;

    do {
        generate_random_rnti(&rnti, min_rnti, max_rnti);
    } while (!is_rnti_available(rnti, current_time, window_size));

    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    pdu->timestamp = current_time;
    pdu->sequence_number = current_index++;
}

void *generate_pdus_thread(void *arg) {
    int num_structs = *(int *)arg;
    for (int i = 0; i < num_structs; i++) {
        pthread_mutex_lock(&mutex);
        generate_pdu(&pdu_list[i], 1, 65535, 60); // Example RNTI range and window size
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    int num_threads = 4;
    int structs_per_thread = MAX_STRUCTS / num_threads;

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, generate_pdus_thread, &structs_per_thread);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Unit tests and further processing can be added here

    return 0;
}
