Logger logger = { .verbosity = 1, .lock = PTHREAD_MUTEX_INITIALIZER };

void log_message(int level, const char *format, ...) {
    if (level > logger.verbosity) return;

    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock(&logger.lock);

    char log_entry[MAX_LOG_SIZE];
    snprintf(log_entry, MAX_LOG_SIZE, "[%s] ", timestamp);
    vsnprintf(log_entry + strlen(log_entry), MAX_LOG_SIZE - strlen(log_entry), format, args);

    // Simulate external system integration
    printf("%s\n", log_entry);

    pthread_mutex_unlock(&logger.lock);

    va_end(args);
}

void set_verbosity(int level) {
    logger.verbosity = level;
}
