typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RNTI;
    // Other fields
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other fields
} CRC_INDICATION_REL8_TAG;

#define MAX_RNTI 1024

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int N, size_t max_memory_kb) {
    static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    static int current_size = 0;
    static size_t total_memory_used = 0;

    if (array == NULL) {
        srand(time(NULL));
    }

    while (current_size < N) {
        size_t new_memory_needed = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (total_memory_used + new_memory_needed > max_memory_kb * 1024) {
            // Perform garbage collection
            for (int i = current_size - 1; i >= 0; --i) {
                free(array[i].RX_UE_INFORMATION_TAG.RNTI);
                array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
            }
            total_memory_used -= new_memory_needed;
        } else {
            // Allocate memory for the new structure
            NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_memory_needed);
            if (new_struct == NULL) {
                return NULL; // Handle allocation failure
            }
            array[current_size] = *new_struct;
            current_size++;
            total_memory_used += new_memory_needed;

            // Initialize the structure fields
            RX_UE_INFORMATION_TAG* rx_tag = (RX_UE_INFORMATION_TAG*)malloc(sizeof(RX_UE_INFORMATION_TAG));
            if (rx_tag == NULL) {
                return NULL; // Handle allocation failure
            }
            rx_tag->RNTI = rand() % MAX_RNTI;
            array[current_size - 1].RX_UE_INFORMATION_TAG = *rx_tag;

            CRC_INDICATION_REL8_TAG* crc_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
            if (crc_tag == NULL) {
                return NULL; // Handle allocation failure
            }
            crc_tag->CRCFLAG = rand() % 2;
            array[current_size - 1].CRC_INDICATION_REL8_TAG = *crc_tag;
        }
    }

    return array;
}
