#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

typedef struct {
    double temperature;
    double humidity;
    double pressure;
    time_t timestamp;
} WeatherData;

WeatherData* read_sensor_data(int socket_fd, int *data_count) {
    WeatherData *weather_data = NULL;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    size_t total_bytes = 0;
    int count = 0;

    while ((bytes_read = recv(socket_fd, buffer + total_bytes, BUFFER_SIZE - total_bytes, 0)) > 0) {
        total_bytes += bytes_read;
        if (total_bytes >= sizeof(double) * 3) { // Assuming each data set is 3 doubles
            weather_data = realloc(weather_data, (count + 1) * sizeof(WeatherData));
            memcpy(&weather_data[count].temperature, buffer, sizeof(double));
            memcpy(&weather_data[count].humidity, buffer + sizeof(double), sizeof(double));
            memcpy(&weather_data[count].pressure, buffer + sizeof(double) * 2, sizeof(double));
            weather_data[count].timestamp = time(NULL);
            count++;
            total_bytes -= sizeof(double) * 3;
            memmove(buffer, buffer + sizeof(double) * 3, total_bytes);
        }
    }

    if (bytes_read == -1) {
        perror("recv");
        free(weather_data);
        return NULL;
    }

    *data_count = count;
    return weather_data;
}

void process_weather_data(WeatherData *weather_data, int data_count) {
    double max_temperature = -273.15; // Absolute zero
    time_t max_timestamp = 0;

    for (int i = 0; i < data_count; i++) {
        if (weather_data[i].temperature > max_temperature) {
            max_temperature = weather_data[i].temperature;
            max_timestamp = weather_data[i].timestamp;
        }
    }

    printf("Max Temperature: %.2f°C at %s\n", max_temperature, ctime(&max_timestamp));

    free(weather_data);
}

int main() {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("socket");
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("connect");
        close(socket_fd);
        return EXIT_FAILURE;
    }

    int data_count;
    WeatherData *weather_data = read_sensor_data(socket_fd, &data_count);
    if (weather_data != NULL) {
        process_weather_data(weather_data, data_count);
    }

    close(socket_fd);
    return EXIT_SUCCESS;
}
