#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

void* allocate_memory(void* arg) {
    long n = *(long*)arg;
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    record* records = (record*)malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (long i = 0; i < n; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    srand(time(NULL));
    int min = 10, max = 100;
    for (long i = 0; i < n; i++) {
        records[i].value = rand() % (max - min + 1) + min;
        if (i > 0 && records[i].value == records[i - 1].value) {
            i--;
        }
    }

    // Verification function
    int* unique_values = (int*)calloc(n, sizeof(int));
    for (long i = 0; i < n; i++) {
        if (unique_values[records[i].value]) {
            fprintf(stderr, "Duplicate value found\n");
            free(unique_values);
            return NULL;
        }
        unique_values[records[i].value] = 1;
    }
    free(unique_values);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    long n = 1000000; // Example size
    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_memory, &n) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }
    pthread_join(thread, NULL);
    return 0;
}
