#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef enum {
    WIFI,
    ETHERNET,
    CELLULAR
} InterfaceType;

typedef struct {
    InterfaceType type;
    int bandwidth; // in Mbps
    int frequency; // in MHz
} NetworkInterfaceConfig;

typedef struct {
    NetworkInterfaceConfig *interfaces;
    size_t count;
    pthread_mutex_t lock;
} NetworkManager;

NetworkManager* init_network_manager(size_t initial_count) {
    if (initial_count == 0) {
        fprintf(stderr, "Error: Initial count must be greater than zero.\n");
        return NULL;
    }

    NetworkManager *manager = malloc(sizeof(NetworkManager));
    if (!manager) {
        perror("Failed to allocate memory for network manager.");
        return NULL;
    }

    manager->interfaces = calloc(initial_count, sizeof(NetworkInterfaceConfig));
    if (!manager->interfaces) {
        perror("Failed to allocate memory for network interfaces.");
        free(manager);
        return NULL;
    }

    manager->count = initial_count;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int configure_interface(NetworkManager *manager, size_t index, InterfaceType type, int bandwidth, int frequency) {
    if (!manager || index >= manager->count) {
        fprintf(stderr, "Error: Invalid network manager or interface index.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    NetworkInterfaceConfig *config = &manager->interfaces[index];
    config->type = type;
    config->bandwidth = bandwidth;
    config->frequency = frequency;

    // Perform validation and error handling here
    if (/* invalid parameters */) {
        fprintf(stderr, "Error: Invalid interface configuration.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    pthread_mutex_unlock(&manager->lock);

    printf("Interface %zu configured successfully.\n", index);
    return 0;
}

void free_network_manager(NetworkManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->interfaces);
        free(manager);
    }
}
