NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(time(NULL));

    int last_RX_UE_INFORMATION_TAG = -1;
    int last_RNTI = -1;
    int CRCFLAG = 0;

    for (int i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = last_RX_UE_INFORMATION_TAG + 1;
        while (list[i].RX_UE_INFORMATION_TAG == last_RX_UE_INFORMATION_TAG) {
            list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Adjust range as needed
        }
        last_RX_UE_INFORMATION_TAG = list[i].RX_UE_INFORMATION_TAG;

        list[i].RNTI = (last_RNTI + 2) % 1000; // Ensure no two consecutive RNTIs are the same
        last_RNTI = list[i].RNTI;

        list[i].CRCFLAG = CRCFLAG;
    }

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    if (list) {
        free(list);
    }
}
