import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TaskManager {
    private ExecutorService executorService;
    private int maxInstances;
    private double loadThreshold;
    private int retryAttempts;
    private long initialBackoffTime;

    public TaskManager(int maxInstances, double loadThreshold, int retryAttempts, long initialBackoffTime) {
        this.maxInstances = maxInstances;
        this.loadThreshold = loadThreshold;
        this.retryAttempts = retryAttempts;
        this.initialBackoffTime = initialBackoffTime;
        this.executorService = Executors.newFixedThreadPool(maxInstances);
    }

    public void submitTask(Runnable task) {
        executorService.submit(() -> {
            int attempt = 0;
            while (attempt < retryAttempts) {
                try {
                    task.run();
                    break;
                } catch (Exception e) {
                    attempt++;
                    long backoffTime = initialBackoffTime * Math.pow(2, attempt);
                    try {
                        TimeUnit.MILLISECONDS.sleep(backoffTime);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        });
    }

    public void adjustInstances(double currentLoad) {
        int currentInstances = executorService.getPoolSize();
        if (currentLoad > loadThreshold && currentInstances < maxInstances) {
            executorService.submit(() -> {});
        } else if (currentLoad <= loadThreshold && currentInstances > maxInstances / 2) {
            // Logic to terminate instances
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
