        return NULL;
    }

    srand(time(NULL)); // Seed for random port generation

    int *usedIds = (int *)calloc(numFlows, sizeof(int));
    if (!usedIds) {
        free(flows);
        *error = -3; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < numFlows; ++i) {
        do {
            flows[i].flowId = rand() % numFlows + 1; // Generate unique flowId
        } while (usedIds[flows[i].flowId - 1]);

        usedIds[flows[i].flowId - 1] = 1;

        strcpy(flows[i].sourceIp, "192.168.0."); // Example source IP range
        flows[i].sourceIp[7] += i % 256; // Ensure uniqueness

        strcpy(flows[i].destinationIp, "10.0.0."); // Example destination IP range
        flows[i].destinationIp[4] += i % 256; // Ensure uniqueness

        flows[i].portRange = rand() % 65535 + 1; // Random port range
    }

    free(usedIds);
    *error = 0; // Success
    return flows;
}

void freeTrafficFlows(TrafficFlowConfig *flows, int numFlows) {
    if (flows) {
        free(flows);
    }
}
