import java.util.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DisjointPairProcessor {
    private static final Logger logger = LoggerFactory.getLogger(DisjointPairProcessor.class);
    private UnionFind unionFind;
    private long totalProcessingTime;
    private long unionOperationsTime;
    private long findOperationsTime;

    public List<int[]> processPairs(int[] array1, int[] array2) {
        long startTime = System.currentTimeMillis();
        unionFind = new UnionFind(array1.length + array2.length);

        // Perform union operations
        for (int num : array1) {
            unionFind.union(num, -num); // Using negative numbers to distinguish between arrays
        }
        for (int num : array2) {
            if (!unionFind.find(-num)) { // Check if the corresponding number from array1 is already paired
                unionFind.union(num, -num);
            }
        }

        List<int[]> disjointPairs = new ArrayList<>();
        for (int i = 0; i < array1.length; i++) {
            int[] pair = {array1[i], -array1[i]};
            if (!disjointPairs.contains(pair)) {
                disjointPairs.add(pair);
            }
        }

        long endTime = System.currentTimeMillis();
        totalProcessingTime = endTime - startTime;
        unionOperationsTime = unionFind.getTotalUnionTime();
        findOperationsTime = unionFind.getTotalFindTime();

        logger.info("Total processing time: {} ms", totalProcessingTime);
        logger.info("Time spent on union operations: {} ms", unionOperationsTime);
        logger.info("Time spent on find operations: {} ms", findOperationsTime);

        return disjointPairs;
    }

    private static class UnionFind {
        private int[] parent;
        private int[] rank;
        private long totalUnionTime;
        private long totalFindTime;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public void union(int x, int y) {
            long startTime = System.currentTimeMillis();
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
            totalUnionTime += System.currentTimeMillis() - startTime;
        }

        public int find(int x) {
            long startTime = System.currentTimeMillis();
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            totalFindTime += System.currentTimeMillis() - startTime;
            return parent[x];
        }

        public boolean find(int x, int y) {
            return find(x) == find(y);
        }

        public long getTotalUnionTime() {
            return totalUnionTime;
        }

        public long getTotalFindTime() {
            return totalFindTime;
        }
    }
}
