#define MAX_CONNECTIONS 10000

typedef struct {
    char ip[16];
    int port;
    int status; // 0 for closed, 1 for open
} TCPConnection;

TCPConnection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_connection(const char *ip, int port) {
    pthread_mutex_lock(&mutex);
    if (connection_count < MAX_CONNECTIONS) {
        strcpy(connections[connection_count].ip, ip);
        connections[connection_count].port = port;
        connections[connection_count].status = 1;
        connection_count++;
    }
    pthread_mutex_unlock(&mutex);
}

void update_connection(const char *ip, int new_port, int status) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < connection_count; i++) {
        if (strcmp(connections[i].ip, ip) == 0 && connections[i].port == port) {
            strcpy(connections[i].ip, ip);
            connections[i].port = new_port;
            connections[i].status = status;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int find_connection_by_ip(const char *ip) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < connection_count; i++) {
        if (strcmp(connections[i].ip, ip) == 0) {
            pthread_mutex_unlock(&mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1;
}

int find_connection_by_port(int port) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].port == port) {
            pthread_mutex_unlock(&mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1;
}

void print_all_connections() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < connection_count; i++) {
        printf("IP: %s, Port: %d, Status: %d\n", connections[i].ip, connections[i].port, connections[i].status);
    }
    pthread_mutex_unlock(&mutex);
}
