# Naive Implementation

class TCPConnection:
    def __init__(self, client_ip, port, status):
        self.client_ip = client_ip
        self.port = port
        self.status = status

class ConnectionManagerNaive:
    def __init__(self):
        self.connections = {}

    def add_connection(self, client_ip, port, status):
        if (client_ip, port) not in self.connections:
            self.connections[(client_ip, port)] = TCPConnection(client_ip, port, status)
            return True
        return False

    def modify_connection(self, client_ip, port, new_status):
        if (client_ip, port) in self.connections:
            self.connections[(client_ip, port)].status = new_status
            return True
        return False

    def lookup_connection(self, client_ip, port):
        return self.connections.get((client_ip, port), None)

# Optimized Implementation

from concurrent.futures import ThreadPoolExecutor
import redis

class TCPConnectionOptimized:
    def __init__(self, client_ip, port, status):
        self.client_ip = client_ip
        self.port = port
        self.status = status

class ConnectionManagerOptimized:
    def __init__(self, num_nodes=3):
        self.redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)
        self.executor = ThreadPoolExecutor(max_workers=num_nodes)

    def add_connection(self, client_ip, port, status):
        key = f"{client_ip}:{port}"
        return self.redis_client.set(key, status)

    def modify_connection(self, client_ip, port, new_status):
        key = f"{client_ip}:{port}"
        return self.redis_client.set(key, new_status)

    def lookup_connection(self, client_ip, port):
        key = f"{client_ip}:{port}"
        return self.redis_client.get(key)
