#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10000

typedef struct {
    char ip[16];
    int port;
    int status;
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
} ConnectionManager;

void init_connection_manager(ConnectionManager *manager) {
    memset(manager, 0, sizeof(ConnectionManager));
    pthread_mutex_init(&manager->lock, NULL);
}

int add_connection(ConnectionManager *manager, const char *ip, int port, int status) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].status == 0) {
            strcpy(manager->connections[i].ip, ip);
            manager->connections[i].port = port;
            manager->connections[i].status = status;
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // No available slot
}

int update_connection(ConnectionManager *manager, int index, const char *ip, int port, int status) {
    pthread_mutex_lock(&manager->lock);
    if (index >= 0 && index < MAX_CONNECTIONS) {
        strcpy(manager->connections[index].ip, ip);
        manager->connections[index].port = port;
        manager->connections[index].status = status;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Invalid index
}

int find_connection_by_ip(ConnectionManager *manager, const char *ip) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (strcmp(manager->connections[i].ip, ip) == 0 && manager->connections[i].status != 0) {
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Connection not found
}

int find_connection_by_port(ConnectionManager *manager, int port) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i].port == port && manager->connections[i].status != 0) {
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Connection not found
}

void destroy_connection_manager(ConnectionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
