#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SEM_NAME_PREFIX "/my_semaphore_"
#define LOG_FILE "semaphore_log.txt"

typedef struct {
    sem_t *sem;
    char name[256];
} Semaphore;

Semaphore* create_semaphore(const char *name, unsigned int initial_value) {
    Semaphore *sem = (Semaphore *)malloc(sizeof(Semaphore));
    if (!sem) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    snprintf(sem->name, sizeof(sem->name), "%s%s", SEM_NAME_PREFIX, name);
    sem->sem = sem_open(sem->name, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(sem);
        return NULL;
    }

    return sem;
}

int delete_semaphore(Semaphore *sem) {
    int ret = sem_close(sem->sem);
    if (ret != 0) {
        perror("Failed to close semaphore");
        return -1;
    }

    ret = sem_unlink(sem->name);
    if (ret != 0) {
        perror("Failed to unlink semaphore");
        return -1;
    }

    free(sem);
    return 0;
}

int wait_semaphore(Semaphore *sem, struct timespec *timeout) {
    int ret = sem_timedwait(sem->sem, timeout);
    if (ret == -1 && errno != ETIMEDOUT) {
        perror("Failed to wait on semaphore");
        return -1;
    }

    return ret;
}

int post_semaphore(Semaphore *sem) {
    int ret = sem_post(sem->sem);
    if (ret != 0) {
        perror("Failed to post semaphore");
        return -1;
    }

    return 0;
}

int get_semaphore_value(Semaphore *sem) {
    int value;
    int ret = sem_getvalue(sem->sem, &value);
    if (ret != 0) {
        perror("Failed to get semaphore value");
        return -1;
    }

    return value;
}

void log_semaphore_operation(const char *operation, const char *name) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s %s\n", operation, name);
    fclose(log_file);
}
