using System;
using System.Data;
using System.Data.SqlClient;
using log4net;

public class DataIngestionPipeline
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(DataIngestionPipeline));
    private const string ConnectionString = "your_sql_connection_string_here";

    public void IngestData(DataTable dataTable)
    {
        using (var sqlBulkCopy = new SqlBulkCopy(ConnectionString))
        {
            ConfigureSqlBulkCopy(sqlBulkCopy);
            ValidateAndTransformData(dataTable);
            InsertData(sqlBulkCopy, dataTable);
        }
    }

    private void ConfigureSqlBulkCopy(SqlBulkCopy bulkCopy)
    {
        bulkCopy.DestinationTableName = "YourDestinationTable";
        bulkCopy.BulkCopyTimeout = 0; // Set to zero for infinite timeout
        bulkCopy.EnableStreaming = true;
        bulkCopy.BatchSize = 10000; // Adjust based on your requirements
    }

    private void ValidateAndTransformData(DataTable dataTable)
    {
        // Implement data validation and transformation logic here
        // Example: Remove null values, convert data types, etc.
    }

    private void InsertData(SqlBulkCopy bulkCopy, DataTable dataTable)
    {
        try
        {
            Log.Info("Starting data ingestion...");
            bulkCopy.WriteToServer(dataTable);
            Log.Info("Data ingestion completed successfully.");
        }
        catch (SqlException ex)
        {
            HandleSqlException(ex);
        }
        catch (Exception ex)
        {
            Log.Error("An unexpected error occurred during data ingestion.", ex);
        }
    }

    private void HandleSqlException(SqlException ex)
    {
        if (ex.Number == -2) // Connection timeout
        {
            Log.Warn("Connection to the database timed out. Retrying...");
            RetryInsertion();
        }
        else
        {
            Log.Error("SQL error occurred during data ingestion.", ex);
            throw;
        }
    }

    private void RetryInsertion()
    {
        int retryCount = 3;
        for (int i = 0; i < retryCount; i++)
        {
            try
            {
                Log.Info($"Retrying data insertion attempt {i + 1}...");
                using (var sqlBulkCopy = new SqlBulkCopy(ConnectionString))
                {
                    ConfigureSqlBulkCopy(sqlBulkCopy);
                    InsertData(sqlBulkCopy, dataTable);
                    break;
                }
            }
            catch (Exception ex)
            {
                if (i == retryCount - 1)
                {
                    Log.Error("Failed to insert data after multiple retries.", ex);
                    throw;
                }
                else
                {
                    Log.Warn($"Attempt {i + 1} failed. Retrying...");
                }
            }
        }
    }

    // Additional methods for handling incremental loads, resource management, and logging can be added here.
}
```

This code snippet provides a basic structure for a data ingestion pipeline in C#. It includes the necessary components to handle bulk inserts using `SqlBulkCopy`, validate and transform data, manage connectivity issues, and log activities. The solution is designed to be extended with additional features as needed.']

