using System;
using System.IO;
using Newtonsoft.Json;

public class GameEngineConfig
{
    public RenderingParameters Rendering { get; set; }
    public PhysicsSettings Physics { get; set; }
    public NetworkCommunication Protocols { get; set; }
}

public class RenderingParameters
{
    public int ResolutionWidth { get; set; }
    public int ResolutionHeight { get; set; }
    public bool VSyncEnabled { get; set; }
}

public class PhysicsSettings
{
    public float Gravity { get; set; }
    public float TimeScale { get; set; }
}

public class NetworkCommunication
{
    public string Protocol { get; set; }
    public int Port { get; set; }
}

public class ConfigManager
{
    private GameEngineConfig _config;
    private readonly string _configFilePath;

    public ConfigManager(string environment)
    {
        _configFilePath = $"config_{environment}.json";
        LoadConfig();
    }

    private void LoadConfig()
    {
        if (File.Exists(_configFilePath))
        {
            var json = File.ReadAllText(_configFilePath);
            _config = JsonConvert.DeserializeObject<GameEngineConfig>(json);
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }
    }

    public GameEngineConfig GetConfig()
    {
        return _config;
    }

    public void UpdateConfig(GameEngineConfig newConfig)
    {
        _config = newConfig;
        SaveConfig();
    }

    private void SaveConfig()
    {
        var json = JsonConvert.SerializeObject(_config, Formatting.Indented);
        File.WriteAllText(_configFilePath, json);
    }
}

public class GameEngine
{
    private ConfigManager _configManager;

    public GameEngine(string environment)
    {
        _configManager = new ConfigManager(environment);
        InitializeGameEngine();
    }

    private void InitializeGameEngine()
    {
        var config = _configManager.GetConfig();
        // Initialize game engine with the loaded configuration
        Console.WriteLine($"Initializing game engine with resolution: {config.Rendering.ResolutionWidth}x{config.Rendering.ResolutionHeight}");
    }

    public void UpdateSettings(GameEngineConfig newConfig)
    {
        _configManager.UpdateConfig(newConfig);
        ReinitializeGameEngine();
    }

    private void ReinitializeGameEngine()
    {
        // Reinitialize game engine with updated configuration
        Console.WriteLine("Reinitializing game engine with updated settings.");
    }
}

public class Program
{
