using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.XPath;
using log4net;

public class XmlParser
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(XmlParser));
    private const int ChunkSize = 1024 * 1024; // 1MB chunk size for processing large files

    public string GetFirstElementText(string xmlContent, List<string> elementNames, bool returnTagName = false, int maxElements = int.MaxValue)
    {
        using (var reader = XmlReader.Create(new System.IO.StringReader(xmlContent)))
        {
            var navigator = reader.ReadSubtree();
            var context = new XPathEvaluationContext(navigator);
            var namespaceManager = new XmlNamespaceManager(context.NameTable);

            for (int i = 0; i < elementNames.Count && maxElements > 0; i++)
            {
                string xpathQuery = $"//*[local-name()='{elementNames[i]}']";
                var nodeIterator = navigator.Select(xpathQuery, namespaceManager);
                if (nodeIterator.MoveNext())
                {
                    var node = nodeIterator.Current;
                    if (!returnTagName)
                    {
                        return node.Value.Trim();
                    }
                    else
                    {
                        return node.Name;
                    }
                }
            }

            return string.Empty;
        }
    }

    public void ProcessLargeXml(string filePath, List<string> elementNames, bool returnTagName = false, int maxElements = int.MaxValue)
    {
        using (var reader = XmlReader.Create(filePath))
        {
            while (reader.Read())
            {
                if (reader.NodeType == System.Xml.XmlNodeType.Element && !string.IsNullOrEmpty(reader.Name))
                {
                    string xpathQuery = $"//*[local-name()='{reader.Name}']";
                    var nodeIterator = reader.Select(xpathQuery);
                    if (nodeIterator.MoveNext())
                    {
                        var node = nodeIterator.Current;
                        if (!returnTagName)
                        {
                            Log.Info(node.Value.Trim());
                        }
                        else
                        {
                            Log.Info(node.Name);
                        }

                        maxElements--;
                        if (maxElements <= 0)
                        {
                            break;
                        }
                    }
                }
            }
        }
    }
}
