<?php

function manageUserAccount($request) {
    $response = ['message' => '', 'data' => []];
    $dbHost = 'localhost';
    $dbName = 'user_db';
    $dbUser = 'root';
    $dbPass = '';

    try {
        $pdo = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPass);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        switch ($request['sub_action']) {
            case 'create':
                $name = $request['name'];
                $email = $request['email'];
                $password = password_hash($request['password'], PASSWORD_DEFAULT);

                $stmt = $pdo->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
                $stmt->bindParam(':name', $name);
                $stmt->bindParam(':email', $email);
                $stmt->bindParam(':password', $password);

                if ($stmt->execute()) {
                    $response['message'] = 'success';
                    $response['data'] = ['id' => $pdo->lastInsertId(), 'name' => $name, 'email' => $email];
                } else {
                    $response['message'] = 'error';
                    $response['data'] = ['error' => 'Failed to create user'];
                }
                break;

            case 'update':
                $id = $request['id'];
                $name = $request['name'];
                $email = $request['email'];

                $stmt = $pdo->prepare("UPDATE users SET name = :name, email = :email WHERE id = :id");
                $stmt->bindParam(':id', $id);
                $stmt->bindParam(':name', $name);
                $stmt->bindParam(':email', $email);

                if ($stmt->execute()) {
                    $response['message'] = 'success';
                    $response['data'] = ['id' => $id, 'name' => $name, 'email' => $email];
                } else {
                    $response['message'] = 'error';
                    $response['data'] = ['error' => 'Failed to update user'];
                }
                break;

            case 'delete':
                $id = $request['id'];

                $stmt = $pdo->prepare("DELETE FROM users WHERE id = :id");
                $stmt->bindParam(':id', $id);

                if ($stmt->execute()) {
                    $response['message'] = 'success';
                    $response['data'] = ['id' => $id];
                } else {
                    $response['message'] = 'error';
                    $response['data'] = ['error' => 'Failed to delete user'];
                }
                break;

            case 'retrieve':
                $id = $request['id'];

                $stmt = $pdo->prepare("SELECT * FROM users WHERE id = :id");
                $stmt->bindParam(':id', $id);
                $stmt->execute();

                $user = $stmt->fetch(PDO::FETCH_ASSOC);

                if ($user) {
                    $response['message'] = 'success';
                    $response['data'] = $user;
                } else {
                    $response['message'] = 'error';
                    $response['data'] = ['error' => 'User not found'];
                }
                break;

            default:
                $response['message'] = 'error';
                $response['data'] = ['error' => 'Invalid sub_action'];
        }

    } catch (PDOException $e) {
        $response['message'] = 'error';
        $response['data'] = ['error' => $e->getMessage()];
    }

    return json_encode($response);
}

// Example usage:
$request = [
    'sub_action' => 'create',
    'name' => 'John Doe',
    'email' => 'john.doe@example.com',
    'password' => 'securepassword123'
];

echo manageUserAccount($request);
?>
