const fetchUserData = async (userId, cache = new Map()) => {
  const operationLabel = 'Fetch User Data';
  console.log(`${operationLabel} - Requesting data for user ID: ${userId}`);

  if (cache.has(userId)) {
    console.log(`${operationLabel} - Using cached data for user ID: ${userId}`);
    return cache.get(userId);
  }

  try {
    const response = await fetch(`https://api.example.com/users/${userId}`);
    if (!response.ok) {
      throw new Error(`API request failed with status ${response.status}`);
    }
    const userData = await response.json();
    console.log(`${operationLabel} - Data fetched successfully for user ID: ${userId}`);
    cache.set(userId, userData);
    return userData;
  } catch (error) {
    console.error(`${operationLabel} - Error fetching data for user ID: ${userId}`, error);
    throw error;
  }
};

// Example usage:
fetchUserData(123)
  .then(userData => console.log('Fetched User Data:', userData))
  .catch(error => console.error('Failed to fetch user data:', error));

// Dynamic parameter update example
const userId = 456;
fetchUserData(userId)
  .then(userData => {
    console.log('Fetched User Data for updated ID:', userData);
    // Update the cache with new data if needed
    cache.set(userId, { ...userData, name: 'Updated Name' });
  })
  .catch(error => console.error('Failed to fetch user data after update:', error));
```

This code snippet demonstrates a JavaScript function `fetchUserData` that integrates with a third-party API to fetch user data asynchronously. It includes caching mechanism using a `Map` object for efficient repeated requests, handles potential errors gracefully, and logs relevant information to the console. The function is designed to be flexible and can accommodate future integrations with additional third-party APIs."]

