use hyper::{Client, Request, Uri};
use hyper_tls::HttpsConnector;
use std::time::Duration;

pub struct HttpClient {
    client: Client<HttpsConnector>,
}

impl HttpClient {
    pub fn new() -> Self {
        let https = HttpsConnector::new();
        HttpClient { client: Client::builder().build(https) }
    }

    pub async fn request(
        &self,
        method: hyper::Method,
        uri: Uri,
        headers: hyper::header::HeaderMap,
        body: Option<hyper::Body>,
        timeout: Duration,
        max_retries: u32,
        retry_interval: Duration,
    ) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let mut retries = 0;
        loop {
            if let Ok(response) = self.send_request(method, uri.clone(), headers.clone(), body.clone()).await {
                return Ok(response);
            }
            retries += 1;
            if retries >= max_retries {
                break;
            }
            tokio::time::sleep(retry_interval).await;
        }
        Err("Max retries reached".into())
    }

    async fn send_request(
        &self,
        method: hyper::Method,
        uri: Uri,
        headers: hyper::header::HeaderMap,
        body: Option<hyper::Body>,
    ) -> Result<hyper::Response<hyper::Body>, Box<dyn std::error::Error>> {
        let mut request = Request::builder()
            .method(method)
            .uri(uri)
            .headers(headers);

        if let Some(body) = body {
            request = request.body(body)?;
        }

        self.client.request(request).await
    }
}
