#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        fprintf(stderr, "Memory allocation failed for DynamicArray\n");
        return NULL;
    }
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da->array) {
        free(da->array);
    }
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed for resizing DynamicArray\n");
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int check_crc(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == RNTI) {
            // Simulate CRC check
            da->array[i].CRCFLAG = rand() % 2;
            pthread_mutex_unlock(&da->mutex);
            return da->array[i].CRCFLAG;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    fprintf(stderr, "RNTI not found in DynamicArray\n");
    return -1;
}

int main() {
    DynamicArray *da = create_dynamic_array();
    if (!da) {
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T element = {0};
    element.RX_UE_INFORMATION_TAG = 12345;
    element.RNTI = rand() % MAX_RNTI;
    element.CRC_INDICATION_REL8_TAG = 67890;

    if (add_element(da, element) != 0) {
        destroy_dynamic_array(da);
        return 1;
    }

    int crc_result = check_crc(da, element.RNTI);
    if (crc_result == -1) {
        destroy_dynamic_array(da);
        return 1;
    }

    printf("CRC Result: %d\n", crc_result);

    destroy_dynamic_array(da);
    return 0;
}
