<?php

class UserDataFetcher {
    private $apiUrl = 'https://third-party-api.com/user';
    private $cacheDir = '/path/to/cache/directory';
    private $accessToken;
    private $refreshToken;

    public function __construct($clientId, $clientSecret) {
        // Initialize OAuth 2.0 tokens
        $this->accessToken = $this->getAccessToken($clientId, $clientSecret);
        $this->refreshToken = $this->getRefreshToken();
    }

    public function getUserData($userId) {
        $cacheFile = $this->cacheDir . '/' . md5($userId) . '.json';

        if (file_exists($cacheFile)) {
            $cachedTime = filemtime($cacheFile);
            if ((time() - $cachedTime) < 86400) { // Cache valid for 24 hours
                return json_decode(file_get_contents($cacheFile), true);
            }
        }

        try {
            $userData = $this->fetchUserDataFromApi($userId);
            file_put_contents($cacheFile, json_encode($userData));
            return $userData;
        } catch (Exception $e) {
            // Fallback to local database
            return $this->getUserDataFromDatabase($userId);
        }
    }

    private function fetchUserDataFromApi($userId) {
        $headers = [
            'Authorization: Bearer ' . $this->accessToken,
            'Content-Type: application/json'
        ];

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $this->apiUrl . '/' . $userId);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);

        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('API request failed: ' . curl_error($ch));
        }

        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($httpCode == 200) {
            return json_decode($response, true);
        } elseif ($httpCode == 401) {
            // Access token expired or revoked
            $this->accessToken = $this->refreshAccessToken();
            return $this->fetchUserDataFromApi($userId); // Retry with new access token
        } else {
            throw new Exception('API request failed with HTTP code: ' . $httpCode);
        }
    }

    private function getUserDataFromDatabase($userId) {
        // Implement logic to fetch user data from local database
        return [
            'id' => $userId,
            'name' => 'John Doe',
            'email' => 'john.doe@example.com'
        ];
    }

    private function getAccessToken($clientId, $clientSecret) {
        // Implement logic to retrieve access token using OAuth 2.0
        return 'access_token_here';
    }

    private function getRefreshToken() {
        // Implement logic to retrieve refresh token
        return 'refresh_token_here';
    }

    private function refreshAccessToken() {
        // Implement logic to refresh access token using refresh token
        return $this->getAccessToken('client_id', 'client_secret');
    }
}

// Usage example:
$fetcher = new UserDataFetcher('client_id', 'client_secret');
