typedef struct {
    char *name;
    int version;
    void *metadata;
} ResourceItem;

typedef struct {
    ResourceItem **items;
    size_t count;
    size_t capacity;
} ResourceBundle;

size_t load_resource_bundle(const char *directory, ResourceBundle *bundle) {
    DIR *dir = opendir(directory);
    if (!dir) return 0;

    bundle->count = 0;
    bundle->capacity = 16;
    bundle->items = malloc(bundle->capacity * sizeof(ResourceItem *));
    if (!bundle->items) {
        closedir(dir);
        return 0;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".res")) {
            ResourceItem *item = malloc(sizeof(ResourceItem));
            item->name = strdup(entry->d_name);
            item->version = atoi(strrchr(item->name, '.') + 1);
            item->metadata = NULL; // Placeholder for metadata

            if (bundle->count >= bundle->capacity) {
                bundle->capacity *= 2;
                bundle->items = realloc(bundle->items, bundle->capacity * sizeof(ResourceItem *));
                if (!bundle->items) {
                    free(item->name);
                    free(item);
                    break;
                }
            }

            bundle->items[bundle->count++] = item;
        }
    }

    closedir(dir);
    return bundle->count;
}

void free_resource_bundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; i++) {
        free(bundle->items[i]->name);
        free(bundle->items[i]);
    }
    free(bundle->items);
}

int main() {
    ResourceBundle bundle;
    size_t count = load_resource_bundle("resources", &bundle);
    printf("Loaded %zu resource items.\n", count);

    // Additional processing...

    free_resource_bundle(&bundle);
    return 0;
}
