#include <string.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256

static int version_counter = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* generate_modified_filename(const char* input_filename) {
    if (strlen(input_filename) >= MAX_FILENAME_LENGTH) {
        return NULL; // Exceeds maximum filename length
    }

    char base_name[MAX_FILENAME_LENGTH];
    char extension[MAX_FILENAME_LENGTH];
    int digits_count = 0;
    int i, j;

    // Extract base name and extension
    for (i = 0; input_filename[i] != '\0'; ++i) {
        if (input_filename[i] == '.') {
            strncpy(base_name, input_filename, i);
            base_name[i] = '\0';
            strcpy(extension, &input_filename[i]);
            break;
        }
    }

    // Count uppercase letters in the base name
    for (j = 0; j < strlen(base_name); ++j) {
        if (isupper(base_name[j])) {
            digits_count++;
        }
    }

    // Generate unique version number
    pthread_mutex_lock(&mutex);
    int version_number = version_counter++;
    pthread_mutex_unlock(&mutex);

    // Create new filename
    char* new_filename = malloc(MAX_FILENAME_LENGTH * sizeof(char));
    if (new_filename == NULL) {
        return NULL; // Memory allocation failed
    }

    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s_.v%0*d%s", base_name, digits_count, version_number, extension);

    return new_filename;
}
