void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Generate random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Assuming valid range is 0 or 1
