    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory");
        return NULL;
    }

    generate_crc_indication_pdu(pdu);

    pthread_mutex_lock(&instances_lock);
    instances[instance_id] = pdu;
    pthread_mutex_unlock(&instances_lock);

    // Simulate processing
    sleep(1);

    pthread_mutex_lock(&instances_lock);
    free(instances[instance_id]);
    instances[instance_id] = NULL;
    pthread_mutex_unlock(&instances_lock);

    return NULL;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    pthread_t threads[MAX_INSTANCES];
    int thread_ids[MAX_INSTANCES];

    for (int i = 0; i < MAX_INSTANCES; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, manage_instances, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
