#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>

int execute_command_async(const char *command, const char *output_file) {
    pid_t pid;
    int fd;

    // Fork a new process
    if ((pid = fork()) == -1) {
        perror("fork");
        return 0; // Error launching the command
    } else if (pid == 0) {
        // Child process

        // Redirect stdout to the specified file
        if ((fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) == -1) {
            perror("open");
            return 2; // Output redirection fails due to insufficient disk space
        }
        dup2(fd, STDOUT_FILENO);
        close(fd);

        // Execute the command
        if (execlp(command, command, NULL) == -1) {
            perror("execlp");
            return 0; // Error launching the command
        }

        exit(EXIT_FAILURE); // Should never reach here
    } else {
        // Parent process

        // Set resource limits (example: limit CPU usage)
        struct rlimit cpu_limit;
        cpu_limit.rlim_cur = 1; // 1 second CPU time
        cpu_limit.rlim_max = 2; // 2 seconds CPU time
        if (setrlimit(RLIMIT_CPU, &cpu_limit) == -1) {
            perror("setrlimit");
        }

        return 1; // Command successfully launched in the background
    }
}
