using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

public class DeployWebApplication
{
    public static async Task<IHost> ExecuteAsync(string directoryPath, string siteName, int? port = null, string hostingEnvironment = "Development")
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(directoryPath) || string.IsNullOrEmpty(siteName))
        {
            Log.Error("Directory path and site name are required.");
            return null;
        }

        // Check for web.config file
        string configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            Log.Warning("No web.config file found. Using default configuration settings.");
        }

        // Validate port number
        int effectivePort = port ?? 5000; // Default port if not specified
        if (effectivePort < 0 || effectivePort > 65535)
        {
            Log.Error("Invalid port number. Port must be between 0 and 65535.");
            return null;
        }

        // Check for port availability with retry mechanism
        int maxRetries = 10;
        int delay = 100; // Initial delay in milliseconds
        while (maxRetries > 0)
        {
            if (!IsPortAvailable(effectivePort))
            {
                Log.Warning($"Port {effectivePort} is already in use. Retrying...");
                await Task.Delay(delay);
                maxRetries--;
                delay *= 2; // Exponential backoff
            }
            else
            {
                break;
            }
        }

        if (maxRetries == 0)
        {
            Log.Error($"Failed to acquire port {effectivePort} after multiple retries.");
            return null;
        }

        // Create and configure web host
        var builder = WebHost.CreateDefaultBuilder(new string[] { })
            .UseContentRoot(directoryPath)
            .ConfigureAppConfiguration((context, config) =>
            {
                config.AddJsonFile("appsettings.json", optional: true, reloadOnChange: true);
                config.AddEnvironmentVariables();
            })
            .ConfigureServices((context, services) =>
            {
                // Add your service configurations here
            })
            .UseUrls($"http://*:{effectivePort}")
            .UseStartup<Startup>();

        var host = builder.Build();

        try
        {
            // Start web host with timeout mechanism
            await Task.WhenAny(host.RunAsync(), Task.Delay(TimeSpan.FromSeconds(30)));
            Log.Info("Web application started successfully.");
            return host;
        }
        catch (Exception ex)
        {
            Log.Error($"Failed to start web application: {ex.Message}");
            return null;
        }
    }

    private static bool IsPortAvailable(int port)
    {
        using (TcpListener listener = new TcpListener(System.Net.IPAddress.Any, port))
        {
            try
            {
                listener.Start();
                listener.Stop();
                return true;
            }
            catch (Exception)
            {
                return false;
            }
        }
    }

    private static class Log
    {
        public static void Error(string message) { Console.WriteLine($"ERROR: {message}"); }
        public static void Warning(string message) { Console.WriteLine($"WARNING: {message}"); }
        public static void Info(string message) { Console.WriteLine($"INFO: {message}"); }
    }
}
