#define MAX_BUFFER_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    char* session_id;
    CONNECTION_CONFIG_T* config;
    void (*callback)(void*);
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    size_t max_size;
} RollingBuffer;

int init_rolling_buffer(RollingBuffer* buffer) {
    srand(time(NULL));
    buffer->head = NULL;
    buffer->tail = NULL;
    buffer->count = 0;
    buffer->max_size = MAX_BUFFER_SIZE;
    return 0;
}

int add_to_buffer(RollingBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T data) {
    if (data.session_id == NULL || strlen(data.session_id) == 0) {
        return -1; // Invalid session ID
    }
    if (data.config == NULL) {
        return -2; // Invalid connection config
    }
    if (data.callback == NULL) {
        return -3; // Invalid callback function
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return -4; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    if (buffer->count < buffer->max_size) {
        if (buffer->head == NULL) {
            buffer->head = new_node;
        } else {
            buffer->tail->next = new_node;
        }
        buffer->tail = new_node;
        buffer->count++;
    } else {
        Node* old_head = buffer->head;
        buffer->head = buffer->head->next;
        free(old_head);
        buffer->tail->next = new_node;
        buffer->tail = new_node;
    }

    return 0; // Success
}

// Example usage:
int main() {
    RollingBuffer buffer;
    init_rolling_buffer(&buffer);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Populate pdu with valid data

    int result = add_to_buffer(&buffer, pdu);
    if (result != 0) {
        // Handle error
    }

    return 0;
}
