// Helper function to find the largest integer in an array
int find_largest(int *arr, int size) {
    if (size <= 0) return -1; // Return -1 for invalid input
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function to read integers and validate JSON
bool process_input() {
    // Read integers from standard input
    int *numbers = NULL;
    int count = 0, capacity = 10; // Initial capacity for the array
    numbers = (int *)malloc(capacity * sizeof(int));
    if (!numbers) return false; // Handle memory allocation failure

    while (scanf("%d", &numbers[count]) == 1) {
        count++;
        if (count >= capacity) {
            capacity *= 2;
            int *new_numbers = (int *)realloc(numbers, capacity * sizeof(int));
            if (!new_numbers) {
                free(numbers);
                return false; // Handle memory reallocation failure
            }
            numbers = new_numbers;
        }
    }

    // Read JSON string from standard input
    char json_str[1024];
    fgets(json_str, sizeof(json_str), stdin);
    struct json_object *parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        free(numbers);
        return false; // Handle parsing error
    }

    // Validate JSON fields
    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) &&
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) &&
        json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        if (!strcmp(json_object_get_string(token_type), "Bearer") &&
            json_object_is_type(expires_in, json_type_int) &&
            json_object_get_int(expires_in) > 0) {
            if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token)) {
                if (!json_object_is_type(refresh_token, json_type_string) ||
                    json_object_get_string_len(refresh_token) == 0) {
                    free(numbers);
                    json_object_put(parsed_json);
                    return false; // Invalid refresh token
                }
            }
        } else {
            free(numbers);
            json_object_put(parsed_json);
            return false; // Invalid token_type or expires_in
        }
    } else {
        free(numbers);
        json_object_put(parsed_json);
        return false; // Missing required fields
    }

    // Print the largest integer in the array
    int largest = find_largest(numbers, count);
    printf("Largest number: %d\n", largest);

    // Clean up
    free(numbers);
    json_object_put(parsed_json);
    return true;
}

int main() {
    if (process_input()) {
        printf("Input processed successfully.\n");
    } else {
        printf("Error processing input.\n");
    }
    return 0;
}
