const axios = require('axios');
const FormData = require('form-data');

async function uploadFile(url, fileUrl, options = {}) {
  const { chunkSize = 1024 * 1024, parallelUploads = 5 } = options;
  const form = new FormData();
  form.append('file', await downloadFile(fileUrl));

  try {
    const response = await axios.post(url, form, {
      headers: form.getHeaders(),
      onUploadProgress: (progressEvent) => {
        console.log(`Upload progress: ${((progressEvent.loaded / progressEvent.total) * 100).toFixed(2)}%`);
      },
    });
    return response.data.url;
  } catch (error) {
    if (error.response && error.response.status === 429) {
      await new Promise(resolve => setTimeout(resolve, 5000)); // Retry after 5 seconds
      return uploadFile(url, fileUrl, options);
    }
    throw new Error(`Upload failed: ${error.message}`);
  }
}

async function downloadFile(fileUrl) {
  const response = await axios.get(fileUrl, { responseType: 'stream' });
  const chunks = [];
  for await (const chunk of response.data) {
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}
