const { exec } = require('child_process');
const ffi = require('ffi-napi');

// Define the C function signature
const cFunction = ffi.Library('./c_function.so', {
  'process_output': ['string', ['string', 'int']]
});

function executeShellCommand(command, sizeLimit) {
  return new Promise((resolve, reject) => {
    exec(command, { maxBuffer: Infinity }, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing command: ${command}`);
        reject(error);
        return;
      }
      if (stderr) {
        console.error(`Stderr output: ${stderr}`);
        reject(new Error('Command produced stderr output'));
        return;
      }

      try {
        const result = cFunction.process_output(stdout, sizeLimit);
        resolve(result);
      } catch (cError) {
        console.error(`Error processing output with C function: ${cError.message}`);
        reject(cError);
      }
    });
  });
}

// Example usage
executeShellCommand('ls -la', 100)
  .then(output => {
    console.log('Processed Output:', output);
  })
  .catch(error => {
    console.error('Failed to process command:', error);
  });
