#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char* payload;
} DataPacket;

DataPacket** initializeDynamicArray(int initialSize, int maxPayloadSize, size_t memoryLimit) {
    DataPacket** array = (DataPacket**)malloc(initialSize * sizeof(DataPacket*));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < initialSize; i++) {
        size_t payloadSize = rand() % maxPayloadSize + 1;
        if ((payloadSize * sizeof(char)) > memoryLimit) {
            fprintf(stderr, "Memory limit exceeded\n");
            free(array);
            return NULL;
        }

        array[i] = (DataPacket*)malloc(sizeof(DataPacket));
        if (!array[i]) {
            fprintf(stderr, "Memory allocation failed for packet %d\n", i);
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        array[i]->id = i + 1;
        array[i]->timestamp = time(NULL);
        array[i]->payload = (char*)malloc(payloadSize * sizeof(char));
        if (!array[i]->payload) {
            fprintf(stderr, "Memory allocation failed for payload of packet %d\n", i);
            for (int j = 0; j <= i; j++) {
                free(array[j]->payload);
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        // Populate payload with random data
        for (size_t j = 0; j < payloadSize; j++) {
            array[i]->payload[j] = rand() % 256;
        }
    }

    return array;
}

void freeDynamicArray(DataPacket** array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i]->payload);
        free(array[i]);
    }
    free(array);
}
