typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t mutex;
} NFAPDUList;

NFAPDUList* generateNfadpList(size_t N, const char *input_string) {
    NFAPDUList *list = (NFAPDUList*)malloc(sizeof(NFAPDUList));
    list->count = N;
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&list->mutex);
        // Simulate fetching RNTI from an external data source
        list->list[i].rnti = fetchRNTIFromExternalSource();
        pthread_mutex_unlock(&list->mutex);

        list->list[i].ue_info_tag = generateUEInformationTag();
        list->list[i].crc_indication.CRCFLAG = (rand() % 2) ? 1 : 0;

        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, input_string, strlen(input_string));
        MD5_Final(list->list[i].md5_hash, &md5);
    }

    return list;
}

void freeNfadpList(NFAPDUList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->list);
