DataPacket* initDynamicArray(int numPackets, size_t maxMemory) {
    if (numPackets > MAX_PACKETS || numPackets * sizeof(DataPacket) > maxMemory) {
        return NULL; // Error handling for invalid input
    }

    DataPacket* packets = (DataPacket*)malloc(numPackets * sizeof(DataPacket));
    if (packets == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < numPackets; i++) {
        packets[i].id = i + 1;
        packets[i].timestamp = time(NULL);
        size_t payloadSize = rand() % MAX_PAYLOAD_SIZE;
        for (size_t j = 0; j < payloadSize; j++) {
            packets[i].payload[j] = 'A' + rand() % 26; // Random character payload
        }
    }

    return packets;
}

// Function to dynamically resize the array and handle packet loss gracefully
void resizeDynamicArray(DataPacket** packets, int* numPackets, size_t maxMemory) {
    if (*numPackets >= MAX_PACKETS || *numPackets * sizeof(DataPacket) > maxMemory) {
        // Handle error or log warning
        return;
    }

    DataPacket* newPackets = (DataPacket*)realloc(*packets, (*numPackets + 1) * sizeof(DataPacket));
    if (newPackets == NULL) {
        // Handle memory allocation failure
        return;
    }

    (*packets) = newPackets;
    (*numPackets)++;
    // Initialize the new packet with random data
}

// Function to add a packet to the dynamic array
void addPacket(DataPacket** packets, int* numPackets, size_t maxMemory) {
    resizeDynamicArray(packets, numPackets, maxMemory);
    if (*packets != NULL && *numPackets > 0) {
        // Add new packet with random data
    }
}

// Function to retrieve a packet from the dynamic array
DataPacket* getPacket(DataPacket* packets, int id) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packets[i].id == id) {
            return &packets[i];
        }
    }
    return NULL; // Packet not found
}

// Function to update a packet in the dynamic array
void updatePacket(DataPacket* packets, int id, char* newPayload) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packets[i].id == id) {
            strcpy(packets[i].payload, newPayload);
            break;
        }
    }
}

// Function to free the memory allocated for the dynamic array
void freeDynamicArray(DataPacket* packets) {
    free(packets);
