    pthread_mutex_lock(&stats_list.lock);
    if (stats_list.count < MAX_STRUCTURES) {
        stats_list.data[stats_list.count++] = stats;
    }
    pthread_mutex_unlock(&stats_list.lock);
}

void* report_stats_thread(void* arg) {
