        pthread_mutex_lock(&stats_list.lock);
        size_t count_to_send = stats_list.count;
        LTE_PHY_STATS_PDU_T *batch[MAX_STRUCTURES];
        memcpy(batch, stats_list.data, count_to_send * sizeof(LTE_PHY_STATS_PDU_T*));
        stats_list.count = 0;
        pthread_mutex_unlock(&stats_list.lock);

