#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 10000

typedef struct {
    int ue_id;
    char mac_address[18];
    // Add other RRC states here
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts[MAX_UE_CONTEXTS];
    int count;
    pthread_mutex_t lock;
} UE_Context_Manager;

void init_ue_context_manager(UE_Context_Manager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_or_update_ue_context(UE_Context_Manager *manager, LTE_UE_Context *new_context) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->contexts[i]->ue_id == new_context->ue_id) {
            // Update existing context
            free(manager->contexts[i]);
            manager->contexts[i] = new_context;
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    if (manager->count < MAX_UE_CONTEXTS) {
        manager->contexts[manager->count++] = new_context;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Manager is full
    }
}

LTE_UE_Context* get_ue_context_by_id(UE_Context_Manager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->contexts[i]->ue_id == ue_id) {
            LTE_UE_Context* context = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Context not found
}

void free_ue_context_manager(UE_Context_Manager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->contexts[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}
```

