<?php

class ClinicUpdater {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function updateClinics(array $clinicIds, string $newStatus, string $lastModifiedIp): array {
        $results = [];

        foreach ($clinicIds as $clinicId) {
            $result = [
                'clinic_id' => $clinicId,
                'success' => false,
                'message' => ''
            ];

            if (!$this->isClinicLocked($clinicId)) {
                $lockKey = "clinic_lock:$clinicId";
                $this->cache->set($lockKey, true, 10); // Lock for 10 seconds

                try {
                    $this->updateDatabase($clinicId, $newStatus, $lastModifiedIp);
                    $result['success'] = true;
                } catch (Exception $e) {
                    $result['message'] = $e->getMessage();
                } finally {
                    $this->cache->delete($lockKey); // Release lock
                }
            } else {
                $result['message'] = 'Clinic is currently being updated.';
            }

            $results[] = $result;
        }

        return $results;
    }

    private function updateDatabase(int $clinicId, string $newStatus, string $lastModifiedIp): void {
        // Fetch clinic data from cache or database
        $clinicData = $this->getClinicData($clinicId);

        if ($clinicData) {
            $sql = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?";
            $stmt = $this->db->prepare($sql);
            $stmt->execute([$newStatus, $lastModifiedIp, $clinicId]);
        } else {
            throw new Exception('Clinic not found.');
        }
    }

    private function getClinicData(int $clinicId): ?array {
        $cacheKey = "clinic:$clinicId";
        $clinicData = $this->cache->get($cacheKey);

        if ($clinicData === false) {
            // Fetch clinic data from database
            $sql = "SELECT * FROM clinics WHERE id = ?";
            $stmt = $this->db->prepare($sql);
            $stmt->execute([$clinicId]);
            $clinicData = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($clinicData) {
                $this->cache->set($cacheKey, $clinicData, 3600); // Cache for 1 hour
            }
        }

        return $clinicData;
    }

    private function isClinicLocked(int $clinicId): bool {
        $lockKey = "clinic_lock:$clinicId";
        return $this->cache->get($lockKey) !== false;
    }
}

// Usage example:
$db = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
$cache = new Memcached();
$cache->addServer('localhost', 11211);

$updater = new ClinicUpdater($db, $cache);
$results = $updater->updateClinics([1, 2, 3], 'Active', $_SERVER['REMOTE_ADDR']);

print_r($results);
?>
