        return NULL;
    }
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        perror("Failed to allocate memory for NFAPI CRC Indication PDU elements");
        return NULL;
    }
    array->count = n;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

