    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        array->array[i].RX_UE_INFORMATION_TAG = base_seed + i;
        if (array->array[i].RX_UE_INFORMATION_TAG > UINT32_MAX) {
            array->array[i].RX_UE_INFORMATION_TAG %= UINT32_MAX;
        }

        static uint16_t last_rnti = 0;
        do {
            array->array[i].RNTI = rand() % UINT16_MAX;
        } while (array->array[i].RNTI == last_rnti);
        last_rnti = array->array[i].RNTI;

        static uint8_t last_crcflag = 0;
        do {
            array->array[i].CRC_INDICATION_REL8_TAG = rand() % UINT8_MAX;
        } while (array->array[i].CRC_INDICATION_REL8_TAG == last_crcflag);
        last_crcflag = array->array[i].CRC_INDICATION_REL8_TAG;
    }

    pthread_mutex_unlock(&array->mutex);

    return 0;
}
