    if (N > MAX_NFAPIS) {
        fprintf(stderr, "Error: Exceeds maximum supported NFAPIS\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfapis = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapis) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    uint16_t rnti_set[MAX_NFAPIS] = {0};
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while (rnti_set[i]) {
            i++;
            if (i >= N) {
                i = 0;
            }
        }
        rnti_set[i] = 1;
        nfapis[i].RNTI = i + 1; // Assign unique RNTI
        pthread_mutex_unlock(&mutex);

        nfapis[i].RX_UE_INFORMATION_TAG = base_seed + i * 1000 + (uint32_t)time(NULL);
        if (nfapis[i].RX_UE_INFORMATION_TAG > UINT32_MAX - 1000) {
            nfapis[i].RX_UE_INFORMATION_TAG -= UINT32_MAX;
        }

        static uint8_t last_crcflag = 0;
