            nfapis[i].CRC_INDICATION_REL8_TAG = (rand() % 256);
        } while (nfapis[i].CRC_INDICATION_REL8_TAG == last_crcflag);
        last_crcflag = nfapis[i].CRC_INDICATION_REL8_TAG;
    }

    pthread_mutex_destroy(&mutex);
    return nfapis;
}

