    LTE_UE_Context *contexts[MAX_UE_CONTEXTS];
    pthread_mutex_t lock;
} UE_Context_Manager;

int add_or_update_context(UE_Context_Manager *manager, int ue_id, const char *mac_address) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] == NULL || manager->contexts[i]->ue_id == ue_id) {
            if (manager->contexts[i] == NULL) {
                manager->contexts[i] = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
                if (manager->contexts[i] == NULL) {
                    pthread_mutex_unlock(&manager->lock);
                    return -1; // Memory allocation failed
                }
