            manager->contexts[i]->ue_id = ue_id;
            strncpy(manager->contexts[i]->mac_address, mac_address, 18);
            // Initialize other fields as needed
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -2; // Context limit reached
}

LTE_UE_Context *get_context_by_id(UE_Context_Manager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->contexts[i] != NULL && manager->contexts[i]->ue_id == ue_id) {
            LTE_UE_Context *context = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Context not found
}

int resolve_hostname(const char *hostname, u_char ip_address[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // Free the linked list
        return 0; // Success
    }

    freeaddrinfo(res); // Free the linked list if no valid address found
    return -2; // No valid IP address found
}

int main() {
    UE_Context_Manager manager;
    pthread_mutex_init(&manager.lock, NULL);

    // Example usage
    add_or_update_context(&manager, 1, "00:1A:2B:3C:4D:5E");
    LTE_UE_Context *context = get_context_by_id(&manager, 1);
    if (context != NULL) {
        printf("MAC Address: %s\n", context->mac_address);
    }

    u_char ip_address[4];
    if (resolve_hostname("example.com", ip_address) == 0) {
        printf("IP Address: %d.%d.%d.%d\n", ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    pthread_mutex_destroy(&manager.lock);
    return 0;
}
```

