} LTE_UPLINK_NAS_TRANSPORT;

typedef struct HashNode {
    IMSI key;
    LTE_UPLINK_NAS_TRANSPORT value;
    struct HashNode* next;
} HashNode;

typedef struct HashMap {
    HashNode** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashMap;

HashMap* create_hash_map(size_t initial_size) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    if (!map) {
        fprintf(stderr, "Memory allocation failed for hash map\n");
        return NULL;
    }
    map->buckets = (HashNode**)calloc(initial_size, sizeof(HashNode*));
    if (!map->buckets) {
        free(map);
        fprintf(stderr, "Memory allocation failed for hash map buckets\n");
        return NULL;
    }
    map->size = initial_size;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void destroy_hash_map(HashMap* map) {
    if (!map) return;

    for (size_t i = 0; i < map->size; ++i) {
        HashNode* node = map->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&map->lock);
    free(map->buckets);
    free(map);
}

int add_to_hash_map(HashMap* map, IMSI imsi, LTE_UPLINK_NAS_TRANSPORT value) {
    if (!map || !imsi || !value.nas_pdu || !value.imsi || !value.transport_format_ind) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    pthread_mutex_lock(&map->lock);
    size_t index = hash_function(imsi, map->size); // Implement your own hash function
    HashNode* node = map->buckets[index];

    while (node) {
        if (node->key == imsi) {
            fprintf(stderr, "Duplicate IMSI found\n");
            pthread_mutex_unlock(&map->lock);
            return -1;
        }
        node = node->next;
    }

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&map->lock);
        fprintf(stderr, "Memory allocation failed for hash node\n");
        return -1;
    }

    new_node->key = imsi;
    new_node->value = value;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;

    pthread_mutex_unlock(&map->lock);
    return 0;
}

LTE_UPLINK_NAS_TRANSPORT* get_from_hash_map(HashMap* map, IMSI imsi) {
    if (!map || !imsi) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    pthread_mutex_lock(&map->lock);
    size_t index = hash_function(imsi, map->size); // Implement your own hash function
    HashNode* node = map->buckets[index];

    while (node) {
        if (node->key == imsi) {
            pthread_mutex_unlock(&map->lock);
            return &node->value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL;
}

// Implement your own hash function here
size_t hash_function(IMSI imsi, size_t size) {
    // Example hash function using IMSI as a simple integer
    return (imsi % size);
}
