#define MAX_EVENT_SIZE 1024

typedef struct {
    time_t timestamp;
    char type[50];
    int source_id;
    int destination_id;
    size_t payload_size;
    char payload[MAX_EVENT_SIZE];
} CommunicationEvent;

typedef struct EventNode {
    CommunicationEvent event;
    struct EventNode* next;
} EventNode;

typedef struct {
    EventNode* head;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    EventNode* current = manager->head;
    while (current) {
        EventNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_event(EventManager* manager, CommunicationEvent event) {
    pthread_mutex_lock(&manager->lock);
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    memcpy(&new_node->event, &event, sizeof(CommunicationEvent));
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_event(EventManager* manager, int source_id, CommunicationEvent new_event) {
    pthread_mutex_lock(&manager->lock);
    EventNode* current = manager->head;
    while (current) {
        if (current->event.source_id == source_id) {
            memcpy(&current->event, &new_event, sizeof(CommunicationEvent));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int get_events_by_type(EventManager* manager, char type[], CommunicationEvent** events, int* count) {
    pthread_mutex_lock(&manager->lock);
    *count = 0;
    EventNode* current = manager->head;
    while (current) {
        if (strcmp(current->event.type, type) == 0) {
            (*events)[(*count)] = current->event;
            (*count)++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int archive_events(EventManager* manager) {
    // Placeholder for logging and archiving logic
    printf("Archiving events...\n");
    return 0;
}
