NetworkInterface *network_interfaces[MAX_INTERFACES] = {NULL};
int interface_count = 0;

void initialize_network_interfaces(const char *config_file) {
    // Load initial metrics from config_file
    FILE *file = fopen(config_file, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        return;
    }

    while (interface_count < MAX_INTERFACES && fscanf(file, "%s %d %lf %lf", network_interfaces[interface_count]->interface_name,
                                                       &network_interfaces[interface_count]->packet_loss,
                                                       &network_interfaces[interface_count]->latency,
                                                       &network_interfaces[interface_count]->throughput) == 4) {
        time(&network_interfaces[interface_count]->last_update);
        interface_count++;
    }

    fclose(file);
}

void add_network_interface(const char *interface_name, int packet_loss, double latency, double throughput) {
    if (interface_count >= MAX_INTERFACES) {
        printf("Maximum number of interfaces reached\n");
        return;
    }

    network_interfaces[interface_count] = (NetworkInterface *)malloc(sizeof(NetworkInterface));
    strcpy(network_interfaces[interface_count]->interface_name, interface_name);
    network_interfaces[interface_count]->packet_loss = packet_loss;
    network_interfaces[interface_count]->latency = latency;
    network_interfaces[interface_count]->throughput = throughput;
    time(&network_interfaces[interface_count]->last_update);
    interface_count++;
}

void update_last_update(int index) {
    if (index >= 0 && index < interface_count) {
        time(&network_interfaces[index]->last_update);
    }
}

void cleanup_network_interfaces() {
    for (int i = 0; i < interface_count; i++) {
        free(network_interfaces[i]);
    }
    interface_count = 0;
}

// Example usage
