} BufferElement;

typedef struct {
    BufferElement* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->elements = (BufferElement*)calloc(initial_capacity, sizeof(BufferElement));
    if (!pool->elements) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->elements);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_to_buffer(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        BufferElement* new_elements = (BufferElement*)realloc(pool->elements, new_capacity * sizeof(BufferElement));
        if (!new_elements) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->elements = new_elements;
        pool->capacity = new_capacity;
    }

    pool->elements[pool->size].data = data;
    pool->size++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void clear_buffer(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        // Clear each element if necessary
        memset(&pool->elements[i], 0, sizeof(BufferElement));
    }
    pool->size = 0;

    pthread_mutex_unlock(&pool->lock);
}

size_t get_buffer_size(MemoryPool* pool) {
    return pool->size;
}
