<?php

class UserAuthentication {
    private $db;
    private $config;

    public function __construct($db, $config) {
        $this->db = $db;
        $this->config = $config;
    }

    public function generateToken() {
        do {
            $token = bin2hex(random_bytes(32));
        } while ($this->isTokenUsed($token));

        return $token;
    }

    private function isTokenUsed($token) {
        // Check if the token already exists in the database
        $stmt = $this->db->prepare("SELECT * FROM sessions WHERE token = ?");
        $stmt->execute([$token]);
        return $stmt->rowCount() > 0;
    }

    public function hashPassword($password) {
        $algorithm = $this->config['hash_algorithm'];
        $cost = $this->config['hash_cost'];

        return password_hash($password, constant("PASSWORD_$algorithm"), ['cost' => $cost]);
    }

    public function verifyToken($token) {
        // Check if the token is valid and not expired
        $stmt = $this->db->prepare("SELECT * FROM sessions WHERE token = ?");
        $stmt->execute([$token]);
        $session = $stmt->fetch();

        if ($session && time() - strtotime($session['created_at']) < $this->config['token_expiration']) {
            return true;
        }

        return false;
    }

    public function createSession($userId, $token) {
        // Create a new session in the database
        $stmt = $this->db->prepare("INSERT INTO sessions (user_id, token, created_at) VALUES (?, ?, NOW())");
        $stmt->execute([$userId, $token]);
    }

    public function destroySession($token) {
        // Destroy an existing session by token
        $stmt = $this->db->prepare("DELETE FROM sessions WHERE token = ?");
        $stmt->execute([$token]);
    }
}
?>
