#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packet_loss;
    double latency;
    double throughput;
    time_t last_updated;
} NetworkStats;

typedef struct Node {
    NetworkStats data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NetworkList;

void initNetworkList(NetworkList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NetworkStats stats) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = stats;
    newNode->next = NULL;
    return newNode;
}

void addNetworkStats(NetworkList* list, NetworkStats stats) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(stats);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void updateTimestamp(NetworkList* list, time_t threshold) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (difftime(time(NULL), current->data.last_updated) > threshold) {
            current->data.last_updated = time(NULL);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanupNetworkList(NetworkList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    NetworkList networkList;
    initNetworkList(&networkList);

    NetworkStats stats1 = {0, 5.2, 1000.0, time(NULL)};
    NetworkStats stats2 = {1, 3.8, 950.0, time(NULL)};

    addNetworkStats(&networkList, stats1);
    addNetworkStats(&networkList, stats2);

    updateTimestamp(&networkList, 60);

    cleanupNetworkList(&networkList);

    return 0;
}
