typedef struct {
    long *offsets;
    int *keys;
    record **records;
} RecordManager;

RecordManager* create_record_manager(int num_records, int key_range, int max_offset_size) {
    if (num_records <= 0 || key_range <= 0 || max_offset_size <= 0) {
        return NULL; // Invalid input
    }

    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }

    manager->offsets = (long*)calloc(max_offset_size, sizeof(long));
    if (!manager->offsets) {
        free(manager);
        return NULL;
    }

    manager->keys = (int*)malloc(num_records * sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->records = (record**)malloc(num_records * sizeof(record*));
    if (!manager->records) {
        free(manager->keys);
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        manager->keys[i] = rand() % key_range + 1;

        // Custom hash function to map keys to indices
        int index = manager->keys[i] % max_offset_size;
        while (manager->offsets[index] != 0) {
            index = (index + 1) % max_offset_size; // Linear probing for collision resolution
        }
        manager->offsets[index] = i;

        record *rec = (record*)malloc(sizeof(record));
        if (!rec) {
            free_records(manager);
            return NULL;
        }

        rec->offset = &manager->offsets[index];
        rec->index = i;
        rec->value = rand() % key_range + 1; // Random value within the specified range

        manager->records[i] = rec;
    }

    return manager;
}

void free_records(RecordManager *manager) {
    if (manager) {
        for (int i = 0; i < num_records; ++i) {
            free(manager->records[i]);
        }
        free(manager->keys);
        free(manager->offsets);
        free(manager->records);
        free(manager);
    }
}

// Example usage
int main() {
    int num_records = 100;
    int key_range = 1000;
    int max_offset_size = 200;

    RecordManager *manager = create_record_manager(num_records, key_range, max_offset_size);
    if (manager) {
        // Use the record manager
        free_records(manager);
    } else {
        printf("Failed to create record manager\n");
    }

    return 0;
}
