#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SETTINGS 1024

typedef struct {
    char id[64];
    void* default_value;
    void* current_value;
    time_t last_updated;
    char metadata[256];
} ConfigSetting;

typedef struct {
    ConfigSetting settings[MAX_SETTINGS];
    int count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager config_manager = {0};

void init_config_manager() {
    pthread_mutex_init(&config_manager.lock, NULL);
}

int add_setting(const char* id, void* default_value, void* current_value, const char* metadata) {
    pthread_mutex_lock(&config_manager.lock);
    if (config_manager.count >= MAX_SETTINGS) {
        pthread_mutex_unlock(&config_manager.lock);
        return -1; // Error: Max settings reached
    }
    ConfigSetting* setting = &config_manager.settings[config_manager.count++];
    strncpy(setting->id, id, sizeof(setting->id));
    setting->default_value = default_value;
    setting->current_value = current_value;
    time(&setting->last_updated);
    strncpy(setting->metadata, metadata, sizeof(setting->metadata));
    pthread_mutex_unlock(&config_manager.lock);
    return 0; // Success
}

void* get_setting(const char* id) {
    pthread_mutex_lock(&config_manager.lock);
    for (int i = 0; i < config_manager.count; i++) {
        if (strcmp(config_manager.settings[i].id, id) == 0) {
            pthread_mutex_unlock(&config_manager.lock);
            return config_manager.settings[i].current_value;
        }
    }
    pthread_mutex_unlock(&config_manager.lock);
    return NULL; // Setting not found
}

int update_setting(const char* id, void* new_value) {
    pthread_mutex_lock(&config_manager.lock);
    for (int i = 0; i < config_manager.count; i++) {
        if (strcmp(config_manager.settings[i].id, id) == 0) {
            free(config_manager.settings[i].current_value); // Free old value
            config_manager.settings[i].current_value = new_value;
            time(&config_manager.settings[i].last_updated);
            pthread_mutex_unlock(&config_manager.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&config_manager.lock);
    return -1; // Setting not found
}

void cleanup_config_manager() {
    for (int i = 0; i < config_manager.count; i++) {
        free(config_manager.settings[i].current_value); // Free all values
    }
    pthread_mutex_destroy(&config_manager.lock);
}
