#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_INTERFACES 100
#define BANDWIDTH_LIMIT 1000

typedef enum {
    ETHERNET,
    WIFI,
    UNKNOWN
} InterfaceType;

typedef struct {
    InterfaceType type;
    int bandwidth;
    int frequency;
} NetworkInterfaceConfig;

typedef struct {
    NetworkInterfaceConfig *interfaces;
    int count;
    int total_bandwidth;
} TopologyConfig;

int validate_interface(NetworkInterfaceConfig *config) {
    if (config->bandwidth < 0 || config->bandwidth > BANDWIDTH_LIMIT) {
        return -1; // Bandwidth out of range
    }
    switch (config->type) {
        case ETHERNET:
            if (config->frequency != 0) {
                return -2; // Ethernet should not have a frequency
            }
            break;
        case WIFI:
            if (config->frequency < 2400 || config->frequency > 5900) {
                return -3; // WiFi frequency out of range
            }
            break;
        default:
            return -4; // Unknown interface type
    }
    return 0; // Valid configuration
}

int initialize_topology(TopologyConfig *topology, NetworkInterfaceConfig *configs, int count) {
    if (count > MAX_INTERFACES) {
        return -1; // Too many interfaces
    }

    topology->interfaces = malloc(count * sizeof(NetworkInterfaceConfig));
    if (!topology->interfaces) {
        return -2; // Memory allocation failed
    }

    topology->count = count;
    topology->total_bandwidth = 0;

    for (int i = 0; i < count; i++) {
        int result = validate_interface(&configs[i]);
        if (result != 0) {
            free(topology->interfaces);
            return result; // Invalid interface configuration
        }
        topology->interfaces[i] = configs[i];
        topology->total_bandwidth += configs[i].bandwidth;
    }

    if (topology->total_bandwidth > BANDWIDTH_LIMIT) {
        free(topology->interfaces);
        return -3; // Total bandwidth exceeds limit
    }

    return 0; // Success
}

// Example usage with pthreads for concurrent initialization
void *initialize_topology_thread(void *arg) {
    TopologyConfig *topology = (TopologyConfig *)arg;
    NetworkInterfaceConfig configs[MAX_INTERFACES];
    int count = ...; // Populate configs and count

    int result = initialize_topology(topology, configs, count);
    if (result != 0) {
        printf("Initialization failed with error code: %d\n", result);
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    TopologyConfig topologies[10];

    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, initialize_topology_thread, &topologies[i]) != 0) {
            printf("Failed to create thread %d\n", i);
            return -1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
