typedef struct {
    Record records[MAX_RECORDS];
    int count;
    char** cache;
    int cache_size;
} DataStructureManager;

int validate_identifier(const char* identifier) {
    // Simulate API call with random latency
    int latency = rand() % 1000 + 500; // between 500ms and 1500ms
    usleep(latency * 1000);
    return rand() % 2 == 0; // simulate success or failure
}

void add_to_cache(DataStructureManager* manager, const char* identifier) {
    if (manager->cache_size < MAX_RECORDS) {
        manager->cache[manager->cache_size++] = strdup(identifier);
    }
}

int is_cached(DataStructureManager* manager, const char* identifier) {
    for (int i = 0; i < manager->cache_size; i++) {
        if (strcmp(manager->cache[i], identifier) == 0) {
            return 1;
        }
    }
    return 0;
}

DataStructureManager* create_data_structure_manager() {
    DataStructureManager* manager = malloc(sizeof(DataStructureManager));
    manager->count = 0;
    manager->cache_size = 0;
    manager->cache = malloc(MAX_RECORDS * sizeof(char*));
    for (int i = 0; i < MAX_RECORDS; i++) {
        manager->records[i].identifier = NULL;
    }
    return manager;
}

void destroy_data_structure_manager(DataStructureManager* manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->records[i].identifier);
    }
    free(manager->cache);
    free(manager);
}

int add_record(DataStructureManager* manager, int timestamp, const char* identifier) {
    if (manager->count >= MAX_RECORDS) {
        return -1; // out of space
    }

    if (is_cached(manager, identifier)) {
        return 0; // already added
    }

    for (int i = 0; i < RETRY_LIMIT; i++) {
        if (validate_identifier(identifier)) {
            manager->records[manager->count].timestamp = timestamp;
            manager->records[manager->count].identifier = strdup(identifier);
            add_to_cache(manager, identifier);
            manager->count++;
            return 1;
        }
    }

    return -2; // failed to validate
}

int main() {
    srand(time(NULL));
    DataStructureManager* manager = create_data_structure_manager();

    for (int i = 0; i < 500; i++) {
        int timestamp = rand();
        const char* identifier = "id" + i;
        add_record(manager, timestamp, identifier);
    }

    destroy_data_structure_manager(manager);

    return 0;
}
