NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // Handle allocation failure
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        array[i].RNTI = rand() % 500; // Example range
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Check for duplicates and reallocate if necessary
        for (int j = 0; j < i; ++j) {
            if (array[j].RX_UE_INFORMATION_TAG == array[i].RX_UE_INFORMATION_TAG ||
                array[j].RNTI == array[i].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_array) {
                    free(array); // Free old memory on failure
                    return NULL;
                }
                array = new_array;
                array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Retry with new values
                array[i].RNTI = rand() % 500; // Retry with new values
                --i; // Decrement to reprocess the current index
                break;
            }
        }
    }

    return array;
}

// Function to serialize the array into a binary format
void serialize_array(NFAPI_CRC_INDICATION_PDU_T* array, int N, FILE* file) {
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
}

// Function to deserialize the array from a binary format
NFAPI_CRC_INDICATION_PDU_T* deserialize_array(FILE* file, int* N) {
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *N = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // Handle allocation failure
    }

    fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *N, file);
    return array;
}
