['```cpp
#include <iostream>
#include <vector>
#include <list>

class HashTable {
private:
    std::vector<std::list<int>> buckets;
    float loadFactor;
    int maxSize;
    int currentSize;

public:
    HashTable(int initialSize, float loadFactor, int maxSize) 
        : buckets(initialSize), loadFactor(loadFactor), maxSize(maxSize), currentSize(0) {}

    void insert(int key) {
        if (currentSize >= maxSize) {
            resize();
        }
        int index = hashFunction(key);
        buckets[index].push_back(key);
        currentSize++;
    }

    bool search(int key) {
        int index = hashFunction(key);
        for (int item : buckets[index]) {
            if (item == key) return true;
        }
        return false;
    }

    void remove(int key) {
        int index = hashFunction(key);
        buckets[index].remove(key);
        currentSize--;
    }

private:
    int hashFunction(int key) {
        return key % buckets.size();
    }

    void resize() {
        if (currentSize / buckets.size() >= loadFactor) {
            std::vector<std::list<int>> newBuckets(buckets.size() * 2);
            for (auto& bucket : buckets) {
                for (int item : bucket) {
                    int newIndex = hashFunction(item, newBuckets.size());
                    newBuckets[newIndex].push_back(item);
                }
            }
            buckets = std::move(newBuckets);
        }
    }
};

int main() {
    HashTable ht(10, 0.75f, 100);
    ht.insert(10);
    ht.insert(20);
    std::cout << "Search 10: " << (ht.search(10) ? "Found" : "Not Found") << std::endl;
    std::cout << "Search 30: " << (ht.search(30) ? "Found" : "Not Found") << std::endl;
    ht.remove(10);
    std::cout << "Search 10 after removal: " << (ht.search(10) ? "Found" : "Not Found") << std::endl;
    return 0;
}
