    LTE_Uu_UE_NAS_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (LTE_Uu_UE_NAS_T*)calloc(initial_capacity, sizeof(LTE_Uu_UE_NAS_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->data);
        free(array);
    }
}

int add_entry(DynamicArray* array, LTE_Uu_UE_NAS_T entry) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uu_UE_NAS_T* new_data = (LTE_Uu_UE_NAS_T*)realloc(array->data, new_capacity * sizeof(LTE_Uu_UE_NAS_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = entry;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_entry(DynamicArray* array, size_t index, LTE_Uu_UE_NAS_T entry) {
    if (index >= array->size) return -1; // Index out of bounds

    pthread_mutex_lock(&array->mutex);

    array->data[index] = entry;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

LTE_Uu_UE_NAS_T* get_entry(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL; // Index out of bounds

    pthread_mutex_lock(&array->mutex);

    LTE_Uu_UE_NAS_T* entry = &array->data[index];

    pthread_mutex_unlock(&array->mutex);
    return entry;
}
