#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CELL_ID 1000
#define MIN_MEASUREMENT_VALUE 0
#define MAX_MEASUREMENT_VALUE 100

typedef struct {
    int cell_id;
    int pci;
    int band_id;
} CELL_CONFIG_T;

typedef struct {
    int measurement_value;
} MEASUREMENT_RESULT_T;

typedef struct {
    CELL_CONFIG_T config;
    MEASUREMENT_RESULT_T result;
} MEASUREMENT_CONFIG_T;

typedef struct {
    MEASUREMENT_CONFIG_T *configs;
    size_t count;
    pthread_mutex_t lock;
} NETWORK_INTERFACE_T;

void initialize_network_interface(NETWORK_INTERFACE_T *interface, size_t initial_size) {
    interface->configs = (MEASUREMENT_CONFIG_T *)malloc(initial_size * sizeof(MEASUREMENT_CONFIG_T));
    if (!interface->configs) {
        perror("Failed to allocate memory for network interface");
        exit(EXIT_FAILURE);
    }
    interface->count = 0;
    pthread_mutex_init(&interface->lock, NULL);
}

void configure_network_interface(NETWORK_INTERFACE_T *interface, CELL_CONFIG_T config) {
    pthread_mutex_lock(&interface->lock);
    if (interface->count >= MAX_CELL_ID) {
        fprintf(stderr, "Network interface is full\n");
        pthread_mutex_unlock(&interface->lock);
        return;
    }
    interface->configs[interface->count++] = (MEASUREMENT_CONFIG_T){config, {rand() % (MAX_MEASUREMENT_VALUE - MIN_MEASUREMENT_VALUE + 1) + MIN_MEASUREMENT_VALUE}};
    pthread_mutex_unlock(&interface->lock);
}

void update_network_interface(NETWORK_INTERFACE_T *interface, CELL_CONFIG_T config) {
    pthread_mutex_lock(&interface->lock);
    for (size_t i = 0; i < interface->count; ++i) {
        if (interface->configs[i].config.cell_id == config.cell_id) {
            interface->configs[i] = (MEASUREMENT_CONFIG_T){config, {rand() % (MAX_MEASUREMENT_VALUE - MIN_MEASUREMENT_VALUE + 1) + MIN_MEASUREMENT_VALUE}};
            pthread_mutex_unlock(&interface->lock);
            return;
        }
    }
    fprintf(stderr, "Cell ID not found for update\n");
    pthread_mutex_unlock(&interface->lock);
}

void destroy_network_interface(NETWORK_INTERFACE_T *interface) {
    free(interface->configs);
    pthread_mutex_destroy(&interface->lock);
}
