#define MAX_POOL_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_POOL_SIZE];
    int size;
    pthread_mutex_t mutex;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T *create_pool() {
    NFAPI_CRC_POOL_T *pool = (NFAPI_CRC_POOL_T *)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) {
        perror("Failed to allocate memory for pool");
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    pool->size = 0;
    return pool;
}

void destroy_pool(NFAPI_CRC_POOL_T *pool) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->size; i++) {
        free(pool->pool[i]);
    }
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T *get_pdu(NFAPI_CRC_POOL_T *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (pool->size > 0) {
        pdu = pool->pool[--pool->size];
    }
    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void release_pdu(NFAPI_CRC_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size < MAX_POOL_SIZE) {
        pool->pool[pool->size++] = pdu;
    }
    pthread_mutex_unlock(&pool->mutex);
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Initialize the PDU with random values
    pdu->ue_info = generate_random_ue_info();
    pdu->rnti = generate_random_rnti();
    pdu->crc_indication.crcflag = rand() % 2;
}

void *pool_manager_thread(void *arg) {
    NFAPI_CRC_POOL_T *pool = (NFAPI_CRC_POOL_T *)arg;
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_pdu(pool);
        if (!pdu) {
            break; // No more PDUs available
        }
        initialize_pdu(pdu);
        release_pdu(pool, pdu);
    }
    return NULL;
}

int main() {
    NFAPI_CRC_POOL_T *pool = create_pool();
    if (!pool) {
        return 1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, pool_manager_thread, pool);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_pool(pool);
    return 0;
}
