#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 10000
#define MAX_EVENTS 500

typedef struct {
    long timestamp;
    int id;
    double value;
} Transaction;

typedef struct {
    long timestamp;
    char description[256];
} HistoricalEvent;

Transaction transactions[MAX_TRANSACTIONS];
HistoricalEvent events[MAX_EVENTS];

int transaction_count = 0;
int event_count = 0;
double market_factor = 1.0;
double total_weighted_sum = 0.0;
long last_processed_timestamp = 0;
double threshold = 1000.0;
double limit = 500000.0;

pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t event_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t process_transactions_cv = PTHREAD_COND_INITIALIZER;

void* process_transactions(void* arg) {
    while (1) {
        pthread_mutex_lock(&transaction_lock);
        while (transaction_count == 0 && last_processed_timestamp != 0) {
            pthread_cond_wait(&process_transactions_cv, &transaction_lock);
        }
        if (last_processed_timestamp == 0) {
            pthread_mutex_unlock(&transaction_lock);
            break;
        }

        for (int i = 0; i < transaction_count; i++) {
            if (transactions[i].timestamp > last_processed_timestamp + 30 ||
                transactions[i].value > threshold) {
                continue;
            }
            double weighted_value = transactions[i].value * market_factor;
            if (total_weighted_sum + weighted_value <= limit) {
                total_weighted_sum += weighted_value;
                // Process transaction
            } else {
                break;
            }
        }

        last_processed_timestamp = time(NULL);
        pthread_mutex_unlock(&transaction_lock);

        // Update performance metrics
    }
    return NULL;
}

void add_transaction(Transaction* new_transaction) {
    pthread_mutex_lock(&transaction_lock);
    if (transaction_count < MAX_TRANSACTIONS) {
        transactions[transaction_count++] = *new_transaction;
        pthread_cond_signal(&process_transactions_cv);
    }
    pthread_mutex_unlock(&transaction_lock);
}

void add_event(HistoricalEvent* new_event) {
    pthread_mutex_lock(&event_lock);
    if (event_count < MAX_EVENTS) {
        events[event_count++] = *new_event;
        // Update market_factor based on event
    }
    pthread_mutex_unlock(&event_lock);
}

int main() {
    pthread_t transaction_thread;
    pthread_create(&transaction_thread, NULL, process_transactions, NULL);

    // Simulate adding transactions and events
    for (int i = 0; i < 1000; i++) {
        Transaction new_transaction = {time(NULL), i, rand() % 1000};
        add_transaction(&new_transaction);
    }

    for (int i = 0; i < 50; i++) {
        HistoricalEvent new_event = {time(NULL), "Market Change"};
        add_event(&new_event);
    }

    pthread_join(transaction_thread, NULL);

    return 0;
}
