#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    ListNode* tail;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int push_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) return -1; // Overflow check
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) return -2; // Memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int pop_from_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->size == 0) return -1; // Underflow check

    pthread_mutex_lock(&list->mutex);
    ListNode* old_head = list->head;
    *data = old_head->data;

    list->head = old_head->next;
    if (!list->head) {
        list->tail = NULL;
    }
    list->size--;
    free(old_head);
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}
