#include <pthread.h>

#define MAX_TRANSACTIONS 1000
#define TRANSACTION_AGE 5
#define RECENT_WINDOW 3

typedef struct {
    int id;
    double amount;
    time_t timestamp;
    int frequency;
    int priority;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    pthread_mutex_t lock;
} TransactionQueue;

TransactionQueue transaction_queue;

void init_transaction_queue() {
    pthread_mutex_init(&transaction_queue.lock, NULL);
}

void enqueue_transaction(Transaction transaction) {
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.count < MAX_TRANSACTIONS) {
        transaction_queue.transactions[transaction_queue.count++] = transaction;
    }
    pthread_mutex_unlock(&transaction_queue.lock);
}

Transaction dequeue_transaction() {
    pthread_mutex_lock(&transaction_queue.lock);
    Transaction transaction = {0};
    if (transaction_queue.count > 0) {
        transaction = transaction_queue.transactions[--transaction_queue.count];
    }
    pthread_mutex_unlock(&transaction_queue.lock);
    return transaction;
}

double calculate_weighted_sum() {
    double sum = 0.0;
    time_t now = time(NULL);
    for (int i = 0; i < transaction_queue.count; i++) {
        if (now - transaction_queue.transactions[i].timestamp <= TRANSACTION_AGE) {
            sum += transaction_queue.transactions[i].amount * transaction_queue.transactions[i].frequency * transaction_queue.transactions[i].priority;
        }
    }
    return sum;
}

int count_transactions_per_second() {
    int count = 0;
    time_t now = time(NULL);
    for (int i = 0; i < transaction_queue.count; i++) {
        if (now - transaction_queue.transactions[i].timestamp <= RECENT_WINDOW) {
            count++;
        }
    }
    return count;
}

void log_transaction(Transaction transaction) {
    // Implement logging to external service
    printf("Logging transaction: ID=%d, Amount=%.2f\n", transaction.id, transaction.amount);
}

int main() {
    init_transaction_queue();

    // Simulate transactions
    for (int i = 0; i < 10; i++) {
        Transaction transaction = {i, (double)i * 10.0, time(NULL), rand() % 10 + 1, rand() % 5 + 1};
        enqueue_transaction(transaction);
        log_transaction(transaction);
    }

    double max_weighted_sum = calculate_weighted_sum();
    int transactions_per_second = count_transactions_per_second();

    printf("Max Weighted Sum: %.2f\n", max_weighted_sum);
    printf("Transactions per Second: %d\n", transactions_per_second);

    return 0;
}
