#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 200
#define SLIDING_WINDOW_SIZE 10
#define LOG_INTERVAL_SECONDS 60

typedef struct {
    int id;
    time_t timestamp;
    double value;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int front, rear;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TransactionQueue;

TransactionQueue transaction_queue;
double weighted_sum = 0.0;
time_t last_log_time = 0;

void init_transaction_queue() {
    pthread_mutex_init(&transaction_queue.lock, NULL);
    pthread_cond_init(&transaction_queue.cond, NULL);
    transaction_queue.front = transaction_queue.rear = -1;
    transaction_queue.count = 0;
}

int is_full(TransactionQueue *queue) {
    return queue->count == MAX_TRANSACTIONS;
}

int is_empty(TransactionQueue *queue) {
    return queue->count == 0;
}

void enqueue(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    while (is_full(queue)) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    if (is_empty(queue)) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % MAX_TRANSACTIONS;
    }
    queue->transactions[queue->rear] = transaction;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

Transaction dequeue(TransactionQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (is_empty(queue)) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    Transaction transaction = queue->transactions[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % MAX_TRANSACTIONS;
    }
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return transaction;
}

int process_transaction(Transaction transaction) {
    time_t current_time = time(NULL);
    if (difftime(current_time, transaction.timestamp) > 2) {
        return -1; // Transaction too old
    }

    for (size_t i = 0; i < transaction_queue.count; i++) {
        size_t index = (transaction_queue.front + i) % MAX_TRANSACTIONS;
        if (difftime(current_time, transaction_queue.transactions[index].timestamp) <= 2 &&
            transaction_queue.transactions[index].timestamp == transaction.timestamp) {
            return -1; // Duplicate transaction
        }
    }

    double new_weighted_sum = weighted_sum * (SLIDING_WINDOW_SIZE - 1) / SLIDING_WINDOW_SIZE + transaction.value;
    if (new_weighted_sum <= weighted_sum) {
        return -1; // Negative contribution to weighted sum
    }

    enqueue(&transaction_queue, transaction);
    weighted_sum = new_weighted_sum;

    return 0;
}

void *log_thread(void *arg) {
    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= LOG_INTERVAL_SECONDS) {
            printf("Max Weighted Sum: %.2f\n", weighted_sum);
            last_log_time = current_time;
        }
        sleep(1);
    }
}

int main() {
    init_transaction_queue();
    pthread_t log_tid;
    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Simulate transaction processing
    while (1) {
        Transaction transaction = {rand(), time(NULL), (double)rand() / RAND_MAX * 100};
        if (process_transaction(transaction) == 0) {
            printf("Transaction processed: ID=%d, Value=%.2f\n", transaction.id, transaction.value);
        }
    }

    pthread_join(log_tid, NULL);
    return 0;
}
