using UnityEngine;

public class DynamicValueGenerator
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;

    public DynamicValueGenerator(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        ValidateRange(minFloat, maxFloat);
        ValidateRange(minInt, maxInt);

        this.minFloat = minFloat;
        this.maxFloat = maxFloat;
        this.minInt = minInt;
        this.maxInt = maxInt;
    }

    private void ValidateRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
    }

    private void ValidateRange(int min, int max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
    }

    public float GenerateRandomFloat(bool inclusive = true)
    {
        return inclusive ? UnityEngine.Random.Range(minFloat, maxFloat + 1) : UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int GenerateRandomInt(bool inclusive = true)
    {
        return inclusive ? UnityEngine.Random.Range(minInt, maxInt + 1) : UnityEngine.Random.Range(minInt, maxInt);
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Float Range [{minFloat}, {maxFloat}], Int Range [{minInt}, {maxInt}]";
    }
}

