    {
        if (pduList == null || pduList.Length == 0)
            return -1; // Invalid input

        try
        {
            IPAddress ipAddress = Dns.GetHostEntry(hostname).AddressList[0];
            byte[] ipBytes = ipAddress.GetAddressBytes();

            for (int i = 0; i < pduList.Length; i++)
            {
                if (i >= PredefinedTags.Length)
                    return -2; // Not enough unique tags

                pduList[i].RX_UE_INFORMATION_TAG = PredefinedTags[i];
                pduList[i].RNTI = GenerateRandomUInt();
                pduList[i].CRC_INDICATION_REL8_TAG.CRCFLAG = GenerateRandomBool();
            }

            return 0; // Success
        }
        catch (SocketException)
        {
            return -3; // DNS resolution failed
        }
    }

    private static uint GenerateRandomUInt()
    {
        byte[] bytes = new byte[4];
        UnityEngine.Random.Fill(bytes);
        return BitConverter.ToUInt32(bytes, 0);
    }

    private static bool GenerateRandomBool()
    {
        return UnityEngine.Random.value > 0.5f;
    }
