#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define TIME_WINDOW_5S 5
#define TIME_WINDOW_3S 3
#define TIME_WINDOW_10S 10

typedef struct {
    time_t timestamp;
    int id;
    double amount;
    char tags[256];
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    time_t last_processed_time;
    double total_amount;
    int valid_transaction_count;
    double max_weighted_sum;
    int max_id;
} TransactionProcessor;

void init_processor(TransactionProcessor *processor) {
    processor->count = 0;
    processor->last_processed_time = time(NULL);
    processor->total_amount = 0.0;
    processor->valid_transaction_count = 0;
    processor->max_weighted_sum = 0.0;
    processor->max_id = -1;
}

int is_valid_transaction(Transaction *transaction, TransactionProcessor *processor) {
    if (transaction->amount <= 0 || transaction->timestamp < 0) return 0;
    time_t current_time = time(NULL);
    if (current_time - transaction->timestamp > TIME_WINDOW_5S) return 0;
    for (int i = 0; i < processor->count; i++) {
        if (processor->transactions[i].id == transaction->id && current_time - processor->transactions[i].timestamp < TIME_WINDOW_3S) return 0;
    }
    return 1;
}

void process_transaction(Transaction *transaction, TransactionProcessor *processor) {
    time_t current_time = time(NULL);
    if (!is_valid_transaction(transaction, processor)) return;

    processor->total_amount += transaction->amount;
    processor->valid_transaction_count++;
    double weighted_sum = transaction->amount / (processor->total_amount / processor->valid_transaction_count);

    if (weighted_sum > processor->max_weighted_sum) {
        processor->max_weighted_sum = weighted_sum;
        processor->max_id = transaction->id;
    }

    if (current_time - processor->last_processed_time >= TIME_WINDOW_10S) {
        processor->count = 0;
        processor->total_amount = 0.0;
        processor->valid_transaction_count = 0;
        processor->last_processed_time = current_time;
    }

    processor->transactions[processor->count++] = *transaction;
}

int main() {
    TransactionProcessor processor;
    init_processor(&processor);

    // Simulate processing transactions
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        Transaction transaction = {time(NULL), i, rand() % 100 + 1, "tag"};
        process_transaction(&transaction, &processor);
    }

    printf("Max Weighted Sum: %.2f\n", processor.max_weighted_sum);
    printf("Max ID: %d\n", processor.max_id);

    return 0;
}
