#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000000
#define ROLLING_WINDOW_SECONDS 60
#define MAX_ROLLING_COUNT 1000

typedef struct {
    int transaction_id;
    time_t timestamp;
    double amount;
    double weight;
} Transaction;

typedef struct {
    int id;
    double total_amount;
    double total_weight;
} AggregatedTransaction;

int compare_transactions(const void *a, const void *b) {
    return ((Transaction *)a)->transaction_id - ((Transaction *)b)->transaction_id;
}

void process_transactions(Transaction transactions[], int num_transactions, AggregatedTransaction **result) {
    qsort(transactions, num_transactions, sizeof(Transaction), compare_transactions);

    AggregatedTransaction aggregated[MAX_TRANSACTIONS] = {0};
    int result_count = 0;

    for (int i = 0; i < num_transactions; i++) {
        if (time(NULL) - transactions[i].timestamp > 5) continue;

        int j;
        for (j = 0; j < result_count; j++) {
            if (aggregated[j].id == transactions[i].transaction_id) {
                aggregated[j].total_amount += transactions[i].amount;
                aggregated[j].total_weight += transactions[i].weight;
                break;
            }
        }

        if (j == result_count) {
            aggregated[result_count].id = transactions[i].transaction_id;
            aggregated[result_count].total_amount = transactions[i].amount;
            aggregated[result_count].total_weight = transactions[i].weight;
            result_count++;
        }
    }

    *result = malloc(result_count * sizeof(AggregatedTransaction));
    memcpy(*result, aggregated, result_count * sizeof(AggregatedTransaction));

    int max_index = 0;
    for (int i = 1; i < result_count; i++) {
        if ((*result)[i].total_amount > (*result)[max_index].total_amount ||
            ((*result)[i].total_amount == (*result)[max_index].total_amount && (*result)[i].id > (*result)[max_index].id)) {
            max_index = i;
        }
    }

    (*result)[max_index].total_weight *= 10; // Assuming weight is in seconds
}

int main() {
    Transaction transactions[MAX_TRANSACTIONS];
    int num_transactions = 500000; // Example number of transactions

    // Populate transactions array with sample data
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].transaction_id = rand() % 100;
        transactions[i].timestamp = time(NULL) - rand() % 10;
        transactions[i].amount = rand() % 1000;
        transactions[i].weight = rand() % 5 + 1;
    }

    AggregatedTransaction *result;
    process_transactions(transactions, num_transactions, &result);

    printf("Max Weighted Sum: %.2f\n", result->total_weight);
    printf("Corresponding Transaction ID: %d\n", result->id);

    free(result);

    return 0;
}
