void log_message(int level, const char *message) {
    if (level == LOG_DEBUG) {
        printf("DEBUG: %s\n", message);
    } else if (level == LOG_INFO) {
        printf("INFO: %s\n", message);
    }
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message(LOG_ERROR, gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(u_char) * 4);

    freeaddrinfo(res);
    return 0;
}

int initialize_entry(int RX_UE_INFORMATION_TAG, uint16_t RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&mutex);
    if (entry_count >= MAX_ENTRIES) {
        log_message(LOG_WARNING, "Entry limit reached");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    entries[entry_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entries[entry_count].RNTI = RNTI;
    entries[entry_count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    entries[entry_count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    entry_count++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int validate_entries() {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].RX_UE_INFORMATION_TAG == -1 || entries[i].RNTI == 0) {
            log_message(LOG_ERROR, "Corrupted data at index %d", i);
            // Handle corrupted data
        }
    }
    return 0;
}

int main() {
    u_char ip_address[4];
    if (resolve_dns("example.com", ip_address) != 0) {
        return -1;
    }

    for (int i = 0; i < 5; i++) {
        initialize_entry(i, rand() % 65536, i);
    }

    validate_entries();

    return 0;
}
