#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int TransactionID;
    time_t Timestamp;
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
    size_t TotalBytes;
} NetworkTransaction;

typedef struct {
    NetworkTransaction *transactions;
    size_t count;
    size_t capacity;
} TransactionCollection;

void initTransactionCollection(TransactionCollection *collection) {
    collection->transactions = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

void addTransaction(TransactionCollection *collection, NetworkTransaction transaction) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = (collection->capacity == 0) ? 1 : collection->capacity * 2;
        NetworkTransaction *new_transactions = realloc(collection->transactions, new_capacity * sizeof(NetworkTransaction));
        if (!new_transactions) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->transactions = new_transactions;
        collection->capacity = new_capacity;
    }
    collection->transactions[collection->count++] = transaction;
}

void filterTransactionsByAge(TransactionCollection *collection, time_t max_age) {
    for (size_t i = 0; i < collection->count; ) {
        if (time(NULL) - collection->transactions[i].Timestamp > max_age) {
            memmove(&collection->transactions[i], &collection->transactions[i + 1], (collection->count - i - 1) * sizeof(NetworkTransaction));
            collection->count--;
        } else {
            i++;
        }
    }
}

void serializeTransactions(TransactionCollection *collection, FILE *file) {
    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; i++) {
        fwrite(&collection->transactions[i], sizeof(NetworkTransaction), 1, file);
    }
}

void deserializeTransactions(TransactionCollection *collection, FILE *file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > collection->capacity) {
        NetworkTransaction *new_transactions = realloc(collection->transactions, count * sizeof(NetworkTransaction));
        if (!new_transactions) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->transactions = new_transactions;
        collection->capacity = count;
    }
    collection->count = count;
    for (size_t i = 0; i < count; i++) {
        fread(&collection->transactions[i], sizeof(NetworkTransaction), 1, file);
    }
}

void freeTransactionCollection(TransactionCollection *collection) {
    free(collection->transactions);
    collection->transactions = NULL;
    collection->count = 0;
    collection->capacity = 0;
}
