        return -2; // Memory allocation failed
    }

    int *rnti_used = (int *)calloc(65536, sizeof(int)); // Assuming RNTI is 16 bits
    if (rnti_used == NULL) {
        free(*pdus);
        return -3; // Memory allocation failed for RNTI tracking
    }

    srand(time(NULL));
    int unique_rntis = 0;

    while (unique_rntis < N) {
        int rnti = rand() % 65536;
        if (!rnti_used[rnti]) {
            (*pdus)[unique_rntis].RNTI = rnti;
            rnti_used[rnti] = 1;
            unique_rntis++;
        }
    }

    for (int i = 0; i < N; i++) {
