typedef struct {
    int FlowID;
    int PacketCount;
    int ByteCount;
} TrafficFlow;

TrafficFlow* initializeFlows(int patternType) {
    TrafficFlow* flows = (TrafficFlow*)malloc(MAX_FLOWS * sizeof(TrafficFlow));
    if (!flows) return NULL;

    srand(time(NULL));

    for (int i = 0; i < MAX_FLOWS; i++) {
        flows[i].FlowID = i + 1;
        switch (patternType) {
            case 0: // Bursty
                flows[i].PacketCount = rand() % 100 + 1;
                break;
            case 1: // Steady
                flows[i].PacketCount = rand() % 50 + 1;
                break;
            case 2: // Random
                flows[i].PacketCount = rand() % 200 + 1;
                break;
        }
        flows[i].ByteCount = flows[i].PacketCount * (rand() % 1000 + 1);
    }

    return flows;
}

void updateFlows(TrafficFlow* flows, int packetSize, float arrivalRate) {
