TrafficData* init_traffic_data(size_t initial_capacity) {
    TrafficData* data = (TrafficData*)malloc(sizeof(TrafficData));
    if (!data) return NULL;

    data->events = (TrafficEvent*)calloc(initial_capacity, sizeof(TrafficEvent));
    if (!data->events) {
        free(data);
        return NULL;
    }

    data->capacity = initial_capacity;
    data->count = 0;
    pthread_mutex_init(&data->mutex, NULL);

    return data;
}

void destroy_traffic_data(TrafficData* data) {
    if (data) {
        free(data->events);
        pthread_mutex_destroy(&data->mutex);
        free(data);
    }
}

int add_traffic_event(TrafficData* data, TrafficEvent event) {
    pthread_mutex_lock(&data->mutex);

    if (data->count >= data->capacity) {
        size_t new_capacity = data->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(data->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) {
            pthread_mutex_unlock(&data->mutex);
            return -1; // Memory allocation failed
        }
        data->events = new_events;
        data->capacity = new_capacity;
    }

    data->events[data->count++] = event;

    pthread_mutex_unlock(&data->mutex);
    return 0;
}

int query_traffic_data(TrafficData* data, TrafficEvent** events, size_t* count, const char* source_mac, const char* destination_mac, uint64_t start_timestamp, uint64_t end_timestamp) {
    pthread_mutex_lock(&data->mutex);

    *count = 0;
    for (size_t i = 0; i < data->count; ++i) {
        if ((source_mac == NULL || strcmp(data->events[i].SourceMAC, source_mac) == 0) &&
            (destination_mac == NULL || strcmp(data->events[i].DestinationMAC, destination_mac) == 0) &&
            data->events[i].Timestamp >= start_timestamp && data->events[i].Timestamp <= end_timestamp) {
            if (*count >= *events_size) {
                // Resize events array if necessary
                *events = (TrafficEvent*)realloc(*events, (*count + 1) * sizeof(TrafficEvent));
                if (!*events) {
                    pthread_mutex_unlock(&data->mutex);
                    return -1; // Memory allocation failed
                }
            }
            (*events)[(*count)++] = data->events[i];
        }
    }

    pthread_mutex_unlock(&data->mutex);
    return 0;
}
