int allocate_mac_pdu_array(int size, MAC_PDU **array, FILE **log_files, int num_log_files) {
    *array = (MAC_PDU *)malloc(size * sizeof(MAC_PDU));
    if (*array == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        if (generate_random_mac_address(&(*array)[i].header.mac_address) != 0) {
            free(*array);
            return -2; // Failed to generate MAC address
        }
        (*array)[i].command.command = i % 256; // Ensure unique command ID
        (*array)[i].payload.length = rand() % 100 + 1; // Random payload length
        (*array)[i].payload.data = (uint8_t *)malloc((*array)[i].payload.length);
        if ((*array)[i].payload.data == NULL) {
            free(*array);
            return -3; // Failed to allocate payload memory
        }

        for (int j = 0; j < num_log_files; j++) {
            fprintf(log_files[j], "MAC_PDU %d: Command=%d, MAC Address=", i, (*array)[i].command.command);
            for (int k = 0; k < 6; k++) {
                fprintf(log_files[j], "%02X", (*array)[i].header.mac_address.address[k]);
                if (k < 5) fprintf(log_files[j], ":");
            }
            fprintf(log_files[j], ", Payload Length=%d\n", (*array)[i].payload.length);
        }
    }

    return 0; // Success
}

void free_mac_pdu_array(MAC_PDU *array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i].payload.data);
    }
    free(array);
}
