#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_STRUCTURES];
    int head;
    int tail;
    pthread_mutex_t mutex;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T* create_crc_pool() {
    NFAPI_CRC_POOL_T* pool = (NFAPI_CRC_POOL_T*)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;

    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_crc_pool(NFAPI_CRC_POOL_T* pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_struct(NFAPI_CRC_POOL_T* pool) {
    pthread_mutex_lock(&pool->mutex);

    if ((pool->tail + 1) % MAX_STRUCTURES == pool->head) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL; // Pool is full
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pool[pool->tail];
    pool->tail = (pool->tail + 1) % MAX_STRUCTURES;

    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void release_crc_struct(NFAPI_CRC_POOL_T* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->mutex);

    if ((pool->head + 1) % MAX_STRUCTURES == pool->tail) {
        pthread_mutex_unlock(&pool->mutex);
        return; // Pool is empty
    }

    int index = (pdu - &pool->pool[0]) % MAX_STRUCTURES;
    pool->pool[index].rx_ue_info = pdu->rx_ue_info;
    pool->pool[index].rnti = pdu->rnti;
    pool->pool[index].crc_ind_rel8.crcflag = pdu->crc_ind_rel8.crcflag;

    pool->head = (pool->head + 1) % MAX_STRUCTURES;

    pthread_mutex_unlock(&pool->mutex);
}
