extern void utf8lib_strcat(char *dest, const char *src);

typedef struct {
    pthread_mutex_t lock;
} StringHandler;

StringHandler handler = { PTHREAD_MUTEX_INITIALIZER };

char* appendSlashIfWithinLimit(const char *input, size_t limit) {
    if (input == NULL || limit == 0) {
        return NULL;
    }

    // Lock the handler to ensure thread safety
    pthread_mutex_lock(&handler.lock);

    // Calculate the length of the input string
    size_t inputLen = utf8lib_strlen(input);
    if (inputLen >= limit - 1) {
        // If the input exceeds the limit, return NULL
        pthread_mutex_unlock(&handler.lock);
        return NULL;
    }

    // Allocate memory for the new string with space for the slash and null terminator
    char *newString = malloc(limit + 1);
    if (newString == NULL) {
        pthread_mutex_unlock(&handler.lock);
        return NULL;
    }

    // Copy the input string to the new buffer
    utf8lib_strcat(newString, input);

    // Append a forward slash
    newString[inputLen] = '/';
    newString[inputLen + 1] = '\0';

    // Unlock the handler
    pthread_mutex_unlock(&handler.lock);

    return newString;
}

// Example usage and testing function
void testAppendSlashIfWithinLimit() {
    const char *testInput = "Hello, World!";
    size_t limit = 20;

    char *result = appendSlashIfWithinLimit(testInput, limit);
    if (result != NULL) {
        printf("Result: %s\n", result);
        free(result);
    } else {
        printf("Failed to append slash.\n");
    }
}

int main() {
    testAppendSlashIfWithinLimit();
    return 0;
}
