#define MAX_LIST_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t mutex;
} ThreadSafeList;

void initializeThreadSafeList(ThreadSafeList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int pushToThreadSafeList(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failure
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int popFromThreadSafeList(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is empty
    }
    ListNode* temp = list->head;
    *data = temp->data;
    list->head = temp->next;
    free(temp);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroyThreadSafeList(ThreadSafeList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
