    if (config_manager.count >= MAX_CONFIGS) {
        pthread_mutex_unlock(&config_manager.lock);
        return NULL; // Error: Max configurations reached
    }
    LTE_PHY_Config *new_config = malloc(sizeof(LTE_PHY_Config));
    if (!new_config) {
        pthread_mutex_unlock(&config_manager.lock);
        return NULL; // Memory allocation failed
    }
    new_config->id = id;
    new_config->phich_config = phich_config;
    new_config->dl_srs_config = dl_srs_config;
    config_manager.configs[config_manager.count++] = new_config;
    pthread_mutex_unlock(&config_manager.lock);
