    pthread_mutex_lock(&config_manager.lock);
    for (int i = 0; i < config_manager.count; i++) {
        if (config_manager.configs[i]->id == id) {
            pthread_mutex_unlock(&config_manager.lock);
            return config_manager.configs[i];
        }
    }
    pthread_mutex_unlock(&config_manager.lock);
    return NULL; // Config not found
}

int remove_config(int id) {
    pthread_mutex_lock(&config_manager.lock);
    for (int i = 0; i < config_manager.count; i++) {
        if (config_manager.configs[i]->id == id) {
            free(config_manager.configs[i]);
            for (; i < config_manager.count - 1; i++) {
                config_manager.configs[i] = config_manager.configs[i + 1];
            }
            config_manager.count--;
            pthread_mutex_unlock(&config_manager.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&config_manager.lock);
    return -1; // Config not found
}

void destroy_config_manager() {
