#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_STREAMS 100

typedef struct {
    int id;
    int bitrate;
    char resolution[20];
} VIDEO_STREAM;

typedef struct {
    VIDEO_STREAM stream;
    sem_t available;
} StreamQueueNode;

StreamQueueNode stream_queue[MAX_STREAMS];
int queue_head = 0, queue_tail = 0, queue_size = 0;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t queue_not_full, queue_not_empty;

void* process_video_stream(void* arg) {
    int index = *(int*)arg;
    while (1) {
        sem_wait(&queue_not_empty);
        pthread_mutex_lock(&queue_lock);
        if (queue_size == 0) {
            pthread_mutex_unlock(&queue_lock);
            continue;
        }
        StreamQueueNode node = stream_queue[queue_head];
        queue_head = (queue_head + 1) % MAX_STREAMS;
        queue_size--;
        pthread_mutex_unlock(&queue_lock);

        // Simulate processing
        printf("Processing stream ID: %d\n", node.stream.id);
        sem_post(&node.available);
    }
    return NULL;
}

void initialize_pipeline(int num_threads) {
    for (int i = 0; i < MAX_STREAMS; i++) {
        sem_init(&stream_queue[i].available, 0, 0);
    }
    sem_init(&queue_not_full, 0, MAX_STREAMS);
    sem_init(&queue_not_empty, 0, 0);

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        int* index = malloc(sizeof(int));
        *index = i;
        pthread_create(&threads[i], NULL, process_video_stream, index);
    }

    // Simulate adding streams to the queue
    for (int i = 1; i <= 50; i++) {
        sem_wait(&queue_not_full);
        pthread_mutex_lock(&queue_lock);
        stream_queue[queue_tail].stream.id = i;
        snprintf(stream_queue[queue_tail].stream.resolution, sizeof(stream_queue[queue_tail].stream.resolution), "%dx%d", i * 160, i * 90);
        sem_post(&stream_queue[queue_tail].available);
        queue_tail = (queue_tail + 1) % MAX_STREAMS;
        queue_size++;
        pthread_mutex_unlock(&queue_lock);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initialize_pipeline(5);
    return 0;
}
```

