#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRCFLAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

Node* create_linked_list(int N, int max_size) {
    if (N > max_size) {
        return NULL; // Handle exceeding maximum size
    }
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        Node* new_node = create_node(rand() % 100, rand() % 1000, rand() % 2); // Random values within valid range
        if (new_node == NULL) {
            free_linked_list(head);
            return NULL; // Handle memory allocation failure
        }
        new_node->next = head;
        head = new_node;
    }
    return head;
}

void free_linked_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int validate_crc_indication(Node* head, int valid_crc_flag) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.CRCFLAG != valid_crc_flag) {
            return 0; // CRC indication is invalid
        }
        current = current->next;
    }
    return 1; // All CRC indications are valid
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    int N = 100; // Number of elements in the list
    int max_size = 200; // Maximum size allowed
    Node* head = create_linked_list(N, max_size);
    if (head == NULL) {
        return -1; // Handle memory allocation failure or exceeding maximum size
    }
    if (!validate_crc_indication(head, 1)) { // Assuming valid CRC flag is 1
        free_linked_list(head);
        return -2; // Handle invalid CRC indication
    }
    // Use the linked list for further processing
    free_linked_list(head);
    return 0;
}
