#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

void resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < da->size; i++) {
        new_array[i] = da->array[i];
    }
    free(da->array);
    da->array = new_array;
    da->capacity = new_capacity;
}

void add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
}

void serialize_dynamic_array(DynamicArray *da, FILE *file) {
    fwrite(&da->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < da->size; i++) {
        fwrite(&da->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

void deserialize_dynamic_array(DynamicArray *da, FILE *file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    if (size > da->capacity) {
        resize_dynamic_array(da, size);
    }
    for (size_t i = 0; i < size; i++) {
        fread(&da->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    da->size = size;
}

void generate_random_data(DynamicArray *da) {
    srand(time(NULL));
    for (size_t i = 0; i < da->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T item;
        item.RX_UE_INFORMATION_TAG = rand() % 1000;
        item.RNTI = rand() % 1000;
        item.CRC_INDICATION_REL8_TAG = rand() % 1000;
        item.CRCFLAG = rand() % 2;
        add_to_dynamic_array(da, item);
    }
}
