#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    char* compressionMethod;
    int extraSamples;
} TIFFInfo;

int parseTIFF(const char* filename, TIFFInfo* info) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return -1;
    }

    uint32_t bitsPerSample, samplesPerPixel, compressionMethod, extraSamples;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) &&
        TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionMethod) &&
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {

        info->bitsPerSample = bitsPerSample;
        info->samplesPerPixel = samplesPerPixel;

        switch (compressionMethod) {
            case COMPRESSION_NONE:
                info->compressionMethod = "None";
                break;
            case COMPRESSION_LZW:
                info->compressionMethod = "LZW";
                break;
            case COMPRESSION_PACKBITS:
                info->compressionMethod = "Packbits";
                break;
            default:
                fprintf(stderr, "Unsupported compression method: %d\n", compressionMethod);
                TIFFClose(tif);
                return -1;
        }

        info->extraSamples = extraSamples;

        TIFFClose(tif);
        return 0;
    } else {
        fprintf(stderr, "Failed to read TIFF tags\n");
        TIFFClose(tif);
        return -1;
    }
}

int main() {
    TIFFInfo info;
    if (parseTIFF("example.tif", &info) == 0) {
        printf("Bits per sample: %d\n", info.bitsPerSample);
        printf("Samples per pixel: %d\n", info.samplesPerPixel);
        printf("Compression method: %s\n", info.compressionMethod);
        printf("Extra samples: %d\n", info.extraSamples);
    }
    return 0;
}
