#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_node(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Node not found
}

void iterate_forward(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI, 
               current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_backward(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->tail;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI, 
               current->data.CRCFLAG);
        current = current->prev;
    }
    pthread_mutex_unlock(&list->lock);
}
