} LTE_Transport_Array;

LTE_Transport_Array* create_transport_array(size_t initial_capacity) {
    LTE_Transport_Array* array = (LTE_Transport_Array*)malloc(sizeof(LTE_Transport_Array));
    if (!array) return NULL;

    array->blocks = (LTE_Uplink_Transport_Block*)calloc(initial_capacity, sizeof(LTE_Uplink_Transport_Block));
    if (!array->blocks) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_transport_array(LTE_Transport_Array* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->blocks);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_block(LTE_Transport_Array* array, LTE_Uplink_Transport_Block block) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uplink_Transport_Block* new_blocks = (LTE_Uplink_Transport_Block*)realloc(array->blocks, new_capacity * sizeof(LTE_Uplink_Transport_Block));
        if (!new_blocks) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->blocks = new_blocks;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (array->blocks[i].Transport_Block_ID == block.Transport_Block_ID) {
            pthread_mutex_unlock(&array->mutex);
            return -2; // Duplicate ID
        }
    }

    array->blocks[array->size++] = block;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

LTE_Uplink_Transport_Block* get_block(LTE_Transport_Array* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);
    LTE_Uplink_Transport_Block* block = &array->blocks[index];
    pthread_mutex_unlock(&array->mutex);

    return block;
}
