#include <string.h>
#include <time.h>

#define MAX_PATH_LENGTH 256

char* generate_modified_filename(const char* filename, const char* directory_path) {
    if (filename == NULL || directory_path == NULL) {
        return NULL;
    }

    size_t dir_len = strlen(directory_path);
    size_t file_len = strlen(filename);
    size_t ext_len = 0;

    // Find the extension length
    for (size_t i = file_len; i > 0; --i) {
        if (filename[i - 1] == '.') {
            ext_len = file_len - i + 1;
            break;
        }
    }

    if (ext_len == 0 || dir_len + file_len >= MAX_PATH_LENGTH) {
        return strdup(filename); // Preserve original filename
    }

    char* new_filename = malloc(MAX_PATH_LENGTH);
    if (new_filename == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy directory path and filename to the new buffer
    strncpy(new_filename, directory_path, dir_len);
    new_filename[dir_len] = '\0';
    strcat(new_filename, filename);

    // Generate a unique sequence of digits for the extension
    srand(time(NULL));
    int digit_sequence = rand() % 1000; // Example: 3-digit sequence

    // Construct the new filename with the modified extension
    char* new_ext = malloc(ext_len + 6); // Extra space for digits and null terminator
    if (new_ext == NULL) {
        free(new_filename);
        return NULL; // Memory allocation failed
    }

    strncpy(new_ext, filename + file_len - ext_len, ext_len);
    sprintf(new_ext + ext_len, "_%03d", digit_sequence); // Append 3-digit sequence

    // Replace the original extension with the new one
    size_t pos = dir_len + file_len - ext_len;
    strncpy(new_filename + pos, new_ext, ext_len + 6);
    new_filename[pos + ext_len + 6] = '\0';

    free(new_ext); // Clean up temporary buffer

    return new_filename;
}
