#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_N 1000
#define MIN_N 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->pool_size = initial_size;
    mp->used_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_count >= mp->pool_size) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(mp->pool, mp->pool_size * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->pool_size *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T *result = &mp->pool[mp->used_count++];
    pthread_mutex_unlock(&mp->lock);
    return result;
}

void populate_array(MemoryPool *mp, int N, int use_specific_crcflag) {
    if (N < MIN_N || N > MAX_N) {
        fprintf(stderr, "Error: N is out of range. Must be between %d and %d.\n", MIN_N, MAX_N);
        return;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(mp);
        if (!pdu) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Unique value generation logic
        pdu->RNTI = rand() % 1000; // Unique value generation logic
        if (use_specific_crcflag) {
            pdu->CRCFLAG = i % 2; // Specific pattern for CRCFLAG
        } else {
            pdu->CRCFLAG = rand() % 2; // Random value for CRCFLAG
        }
    }
}

int main() {
    srand(time(NULL));
    MemoryPool *mp = create_memory_pool(10);
    populate_array(mp, 50, 0); // Populate with random CRCFLAG values
    destroy_memory_pool(mp);
    return 0;
}
