        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (!list->head) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void delete_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);
    if (node == list->head) {
        list->head = node->next;
        if (list->head) list->head->prev = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        if (list->tail) list->tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    free(node);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

