void* manage_array(void* arg) {
    pthread_mutex_lock(&mutex);
    if (count < MAX_STRUCTURES) {
        array[count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array[count]) {
            // Initialize structure with random values
            array[count]->RX_UE_INFORMATION_TAG = rand() % 100;
            array[count]->RNTI = rand() % 1000;
            array[count]->CRC_INDICATION_REL8_TAG = rand() % 100;
            array[count]->CRCFLAG = rand() % 2;

            count++;
        } else {
            fprintf(stderr, "Memory allocation failed\n");
        }
    } else {
        fprintf(stderr, "Array is full\n");
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void print_array(int fd) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        if (array[i]) {
            dprintf(fd, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                    array[i]->RX_UE_INFORMATION_TAG,
                    array[i]->RNTI,
                    array[i]->CRC_INDICATION_REL8_TAG,
                    array[i]->CRCFLAG);
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, manage_array, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    int fd = open("output.txt", O_WRONLY | O_CREAT, 0644);
    if (fd != -1) {
        print_array(fd);
        close(fd);
    } else {
        perror("Failed to open file");
    }

    for (int i = 0; i < count; i++) {
        free(array[i]);
    }
    return 0;
}
