typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->mutex);
        free(list->list);
        free(list);
    }
}

int add_crc_indication(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->list[list->size].RNTI = RNTI;
    list->list[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int generate_random_crc_indication(NFAPI_CRC_LIST_T *list, int min_n, int max_n) {
    if (min_n < 1 || max_n < min_n) return -1;

    size_t N = rand() % (max_n - min_n + 1) + min_n;
    for (size_t i = 0; i < N; i++) {
        add_crc_indication(list, rand(), rand(), rand());
    }

    return 0;
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_LIST_T *list = create_crc_list(10);
    if (!list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return -1;
    }

    if (generate_random_crc_indication(list, 5, 20) != 0) {
        fprintf(stderr, "Failed to generate random CRC indications\n");
        destroy_crc_list(list);
        return -1;
    }

    // Use the list...

    destroy_crc_list(list);
    return 0;
}
