        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

// Function to generate CRC indications
std::vector<NFAPI_CRC_INDICATION_PDU_T> generateMD5AndCRCIndications(const std::string& input, SystemHealthMonitor* monitor, int maxBatchSize) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
    UnionFind uf(100); // Example size
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    for (int i = 0; i < maxBatchSize; ++i) {
        NFAPI_CRC_INDICATION_PDU_T indication;
        indication.rx_ue_info_tag = i % 50; // Example tag
        indication.rnti = i % 20; // Example RNTI
        indication.crcflag = dis(gen); // Random CRC flag

        crcIndications.push_back(indication);

        // Simulate disjointness check
        int x = i % 10;
        int y = (i + 1) % 10;
        auto start = std::chrono::high_resolution_clock::now();
        uf.unionSets(x, y);
        auto end = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> duration = end - start;
        std::cout << "Disjointness check time: " << duration.count() << " ms" << std::endl;

        // Cooldown mechanism
        if (monitor->getCpuUsage() > 80.0 || monitor->getMemoryConsumption() > 90.0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            std::cout << "Cooldown period" << std::endl;
        }
    }

    return crcIndications;
}

int main() {
    SystemHealthMonitor monitor;
    std::string input = "example_input";
    int maxBatchSize = 50;

    auto crcIndications = generateMD5AndCRCIndications(input, &monitor, maxBatchSize);

    for (const auto& indication : crcIndications) {
        std::cout << "RX UE Info Tag: " << indication.rx_ue_info_tag
                  << ", RNTI: " << indication.rnti
                  << ", CRC Flag: " << (indication.crcflag ? "True" : "False") << std::endl;
    }

    return 0;
}
