    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly ILogger _logger;

    public AesCbcDecryptor(byte[] key, byte[] iv, ILogger logger)
    {
        _key = key;
        _iv = iv;
        _logger = logger;
    }

    public async Task<byte[]> DecryptAsync(Stream ciphertextStream)
    {
        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _key;
                aes.IV = _iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                using (var memoryStream = new MemoryStream())
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                {
                    await ciphertextStream.CopyToAsync(cryptoStream);
                    return memoryStream.ToArray();
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed");
            throw;
        }
    }

    public bool VerifyIntegrity(byte[] decryptedData, byte[] checksum)
    {
        // Implement integrity verification logic here
