    {
        if (!File.Exists("appsettings.json"))
        {
            // Initialize with default settings
        }

        while (_list.Count < _maxSize)
        {
            try
            {
                var response = await _httpClient.GetAsync(_apiEndpoint);
                if (response.IsSuccessStatusCode)
                {
                    var pdu = new NFAPI_CRC_INDICATION_PDU_T
                    {
                        UEInfo = new RX_UE_INFORMATION_TAG(),
                        RNTI = GenerateRandomRNTI(),
                        CRCFlag = new CRC_INDICATION_REL8_TAG()
                    };
                    _list.Add(pdu);
                }
            }
            catch (Exception)
            {
                // Handle transient failures
            }

            await Task.Delay(100); // Adjust delay as needed
        }
    }

