#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ssb_index;
    int cgi;
    int cqi;
} LTE_PHY_Sync;

typedef struct {
    LTE_PHY_Sync *sync_list;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LTE_PHY_Sync_List;

LTE_PHY_Sync_List* create_sync_list(size_t initial_capacity) {
    LTE_PHY_Sync_List *list = (LTE_PHY_Sync_List*)malloc(sizeof(LTE_PHY_Sync_List));
    list->sync_list = (LTE_PHY_Sync*)calloc(initial_capacity, sizeof(LTE_PHY_Sync));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_sync_list(LTE_PHY_Sync_List *list) {
    free(list->sync_list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_sync_entry(LTE_PHY_Sync_List *list, int ssb_index, int cgi, int cqi) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_Sync *new_sync_list = (LTE_PHY_Sync*)realloc(list->sync_list, new_capacity * sizeof(LTE_PHY_Sync));
        if (!new_sync_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->sync_list = new_sync_list;
        list->capacity = new_capacity;
    }
    list->sync_list[list->size].ssb_index = ssb_index;
    list->sync_list[list->size].cgi = cgi;
    list->sync_list[list->size].cqi = cqi;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_sync_entry(LTE_PHY_Sync_List *list, size_t index, int ssb_index, int cgi, int cqi) {
    if (index >= list->size) return; // Index out of bounds
    pthread_mutex_lock(&list->lock);
    list->sync_list[index].ssb_index = ssb_index;
    list->sync_list[index].cgi = cgi;
    list->sync_list[index].cqi = cqi;
    pthread_mutex_unlock(&list->lock);
}

void* sync_update_thread(void *arg) {
    LTE_PHY_Sync_List *list = (LTE_PHY_Sync_List*)arg;
    // Simulate periodic updates from an external data source
    for (;;) {
        // Fetch new SSB indices, CGIs, and CQIs from the external data source
        int ssb_index = fetch_ssb_index();
        int cgi = fetch_cgi();
        int cqi = fetch_cqi();

        // Update the sync list with new values
        update_sync_entry(list, 0, ssb_index, cgi, cqi); // Assuming we always update the first entry for simplicity

        // Sleep for a while before fetching the next set of data
        sleep(1);
    }
    return NULL;
}

int main() {
    LTE_PHY_Sync_List *sync_list = create_sync_list(10);

    // Start a thread to handle periodic updates
    pthread_t update_thread;
    pthread_create(&update_thread, NULL, sync_update_thread, sync_list);

    // Main program logic here

    // Clean up resources
    pthread_join(update_thread, NULL);
    destroy_sync_list(sync_list);

    return 0;
}
```

This code provides a basic implementation of an LTE PHY synchronization list with dynamic memory management and thread safety. It includes functions to create, destroy, add, update, and handle periodic updates from an external data source. The `sync_update_thread` function simulates fetching new SSB indices, CGIs, and CQIs and updating the sync list accordingly. The main program starts this thread and then proceeds with its logic. Finally, it cleans up resources by joining the update thread and destroying the sync list.']

