#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MAX_MEMORY_PER_ELEMENT 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t total_memory_usage;
    pthread_mutex_t mutex;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->total_memory_usage = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_element(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->total_memory_usage + MAX_MEMORY_PER_ELEMENT > 1024 * 1024 * MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory limit exceeded
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->total_memory_usage += MAX_MEMORY_PER_ELEMENT;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void log_list_status(DoublyLinkedList* list) {
    time_t now = time(NULL);
    printf("Time: %s", ctime(&now));
    printf("Number of elements: %ld\n", (long)(list->tail - list->head + 1));
    printf("Total memory usage: %zu bytes\n", list->total_memory_usage);
}

int main() {
    DoublyLinkedList* list = create_list();
    if (!list) return 1;

    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data = {rand(), rand(), rand()};
        add_element(list, data);
    }

    log_list_status(list);

    destroy_list(list);
    return 0;
}
