#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 5000
#define MAX_MEMORY_FOOTPRINT (2 * 1024 * 1024) // 2 MB

typedef struct TCP_CONNECTION_INFO {
    char remote_ip[16];
    char local_ip[16];
    int remote_port;
    int local_port;
    int state;
    struct TCP_CONNECTION_INFO* next;
} TCP_CONNECTION_INFO;

TCP_CONNECTION_INFO* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int add_connection(const char* remote_ip, const char* local_ip, int remote_port, int local_port, int state) {
    pthread_mutex_lock(&lock);
    if (head == NULL || (head != NULL && (TCP_CONNECTION_INFO*)malloc(sizeof(TCP_CONNECTION_INFO)) != NULL)) {
        TCP_CONNECTION_INFO* new_connection = (TCP_CONNECTION_INFO*)malloc(sizeof(TCP_CONNECTION_INFO));
        strcpy(new_connection->remote_ip, remote_ip);
        strcpy(new_connection->local_ip, local_ip);
        new_connection->remote_port = remote_port;
        new_connection->local_port = local_port;
        new_connection->state = state;
        new_connection->next = head;
        head = new_connection;
        pthread_mutex_unlock(&lock);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&lock);
        return -1; // Memory allocation failed
    }
}

void remove_connection(const char* remote_ip, const char* local_ip) {
    pthread_mutex_lock(&lock);
    TCP_CONNECTION_INFO* current = head;
    TCP_CONNECTION_INFO* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->remote_ip, remote_ip) == 0 && strcmp(current->local_ip, local_ip) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void print_connections() {
    pthread_mutex_lock(&lock);
    TCP_CONNECTION_INFO* current = head;
    while (current != NULL) {
        printf("Remote IP: %s, Local IP: %s, Remote Port: %d, Local Port: %d, State: %d\n",
               current->remote_ip, current->local_ip, current->remote_port, current->local_port, current->state);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    // Example usage
    add_connection("192.168.1.1", "10.0.0.1", 8080, 80, 1);
    print_connections();
    remove_connection("192.168.1.1", "10.0.0.1");
    return 0;
}
```

