#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T crc_array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_crc_array() {
    crc_array.capacity = MAX_STRUCTURES;
    crc_array.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(crc_array.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array.array) {
        fprintf(stderr, "Failed to allocate memory for CRC array\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_crc_array() {
    pthread_mutex_lock(&crc_array.lock);
    free(crc_array.array);
    crc_array.array = NULL;
    crc_array.count = 0;
    crc_array.capacity = 0;
    pthread_mutex_unlock(&crc_array.lock);
}

int add_crc_structure(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&crc_array.lock);
    if (crc_array.count >= crc_array.capacity) {
        fprintf(stderr, "CRC array limit exceeded\n");
        pthread_mutex_unlock(&crc_array.lock);
        return -1;
    }
    for (size_t i = 0; i < crc_array.count; ++i) {
        if (crc_array.array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&crc_array.lock);
            return -2; // Duplicate entry
        }
    }
    NFAPI_CRC_INDICATION_PDU_T new_struct = {RX_UE_INFORMATION_TAG, RNTI, rand() % 100, rand() % 2};
    crc_array.array[crc_array.count++] = new_struct;
    pthread_mutex_unlock(&crc_array.lock);
    return 0;
}

void cleanup_unused_structures() {
    pthread_mutex_lock(&crc_array.lock);
    for (size_t i = 0; i < crc_array.count; ++i) {
        // Simulate checking for temporary unavailability
        if (rand() % 2 == 0) {
            memmove(&crc_array.array[i], &crc_array.array[i + 1], (crc_array.count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --crc_array.count;
            --i; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&crc_array.lock);
}

void* cleanup_thread(void* arg) {
    while (1) {
        sleep(60); // Cleanup every minute
        cleanup_unused_structures();
    }
    return NULL;
}

int main() {
    initialize_crc_array();

    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, NULL);

    srand(time(NULL));
    for (int i = 0; i < 15000; ++i) {
        add_crc_structure(rand() % 1000, rand() % 100);
    }

    pthread_join(cleanup_tid, NULL);
    cleanup_crc_array();

    return 0;
}
