    if (N > 10000 || min_rnti < 0 || max_rnti > 65535 || min_rnti > max_rnti) {
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int rnti_count[65536] = {0}; // Track RNTI usage
    int current_index = 0;

    while (current_index < N) {
        unsigned short rnti = (unsigned short)(rand() % (max_rnti - min_rnti + 1)) + min_rnti;
        if (rnti_count[rnti] == 0) {
            list[current_index].RX_UE_INFORMATION_TAG = current_index + 1;
            list[current_index].RNTI = rnti;
            list[current_index].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
            rnti_count[rnti] = 1;
            current_index++;
        }
    }

    return list;
}
