#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef enum {
    LTE_PHY_RX_STATUS_OK,
    LTE_PHY_RX_STATUS_ERROR
} LTE_PHY_RX_STATUS;

typedef struct LTE_PHY_RX_TTI_PDU {
    int TTI_INDEX;
    int TX_POWER;
    LTE_PHY_RX_STATUS PHY_RX_STATUS;
    int FRAME_TYPE;
} LTE_PHY_RX_TTI_PDU;

typedef struct HashNode {
    LTE_PHY_RX_TTI_PDU data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(TABLE_SIZE, sizeof(HashNode*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

int insert_entry(HashTable* table, LTE_PHY_RX_TTI_PDU entry) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(entry.TTI_INDEX);
    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->data = entry;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
    return 0; // Assuming success
}

LTE_PHY_RX_TTI_PDU* retrieve_entry(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash_function(key);
    HashNode* current = table->buckets[index];
    while (current != NULL) {
        if (current->data.TTI_INDEX == key) {
            pthread_mutex_unlock(&table->lock);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL; // Entry not found
}

void cleanup_hash_table(HashTable* table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        HashNode* current = table->buckets[i];
        while (current != NULL) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

int main() {
    HashTable* table = create_hash_table();
    LTE_PHY_RX_TTI_PDU entry = {1, 20, LTE_PHY_RX_STATUS_OK, 3};
    insert_entry(table, entry);

    LTE_PHY_RX_TTI_PDU* retrieved_entry = retrieve_entry(table, 1);
    if (retrieved_entry != NULL) {
        printf("Retrieved Entry: TTI_INDEX=%d, TX_POWER=%d, PHY_RX_STATUS=%d, FRAME_TYPE=%d\n",
               retrieved_entry->TTI_INDEX, retrieved_entry->TX_POWER,
               retrieved_entry->PHY_RX_STATUS, retrieved_entry->FRAME_TYPE);
    }

    cleanup_hash_table(table);
    return 0;
}
