#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_UE_ID 1024
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 65535

typedef struct {
    int UE_ID;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} SharedResourcePool;

void initialize_pool(SharedResourcePool *pool, size_t size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_pool(SharedResourcePool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T *get_from_pool(SharedResourcePool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count < pool->pool_size) {
        pdu = &pool->pool[pool->used_count++];
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void put_back_to_pool(SharedResourcePool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count > 0 && &pool->pool[pool->used_count - 1] == pdu) {
        pool->used_count--;
    }
    pthread_mutex_unlock(&pool->lock);
}

int compute_crcflag(int seed, int ue_id, int frame_number) {
    // Non-trivial CRCFLAG computation
    return (seed * ue_id + frame_number) % 0xFFFFFFFF;
}

void populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int ue_id, int rnti, int frame_number, int seed) {
    if (rnti < RNTI_RANGE_MIN || rnti > RNTI_RANGE_MAX) {
        fprintf(stderr, "Invalid RNTI value: %d\n", rnti);
        return;
    }
    pdu->UE_ID = ue_id;
    pdu->RNTI = rnti;
    pdu->CRCFLAG = compute_crcflag(seed, ue_id, frame_number);
}

void *generate_pdus(void *arg) {
    SharedResourcePool *pool = (SharedResourcePool *)arg;
    int seed = 12345; // Example seed value
    for (int i = 0; i < MAX_UE_ID; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_from_pool(pool);
        if (pdu) {
            populate_pdu(pdu, i, rand() % RNTI_RANGE_MAX + RNTI_RANGE_MIN, i, seed);
            put_back_to_pool(pool, pdu);
        }
    }
    return NULL;
}

int main() {
    SharedResourcePool pool;
    initialize_pool(&pool, MAX_UE_ID);

    pthread_t threads[MAX_UE_ID];
    for (int i = 0; i < MAX_UE_ID; i++) {
        if (pthread_create(&threads[i], NULL, generate_pdus, &pool) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_UE_ID; i++) {
        pthread_join(threads[i], NULL);
    }

