#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeDynamicList(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
    }
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
}

void resizeDynamicList(DynamicList *list, size_t newCapacity) {
    pthread_mutex_lock(&list->lock);
    if (newCapacity > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newData == NULL) {
            // Handle memory allocation failure
            perror("Failed to resize dynamic list");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->data = newData;
        list->capacity = newCapacity;
    }
    pthread_mutex_unlock(&list->lock);
}

void addElementToDynamicList(DynamicList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        resizeDynamicList(list, list->capacity == 0 ? 1 : list->capacity * 2);
    }
    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->data[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void exportDynamicListToBinaryFile(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    fclose(file);
}

int main() {
    DynamicList myList;
    initDynamicList(&myList);

    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        addElementToDynamicList(&myList, rand(), rand(), rand());
    }

    exportDynamicListToBinaryFile(&myList, "napi_crc_indication_pdu.bin");

    freeDynamicList(&myList);

    return 0;
}
