NICB* initialize_nicb_array(int max_interfaces, size_t total_memory_limit) {
    NICB *nicb_array = (NICB *)malloc(max_interfaces * sizeof(NICB));
    if (!nicb_array) return NULL;

    size_t buffer_size = 0;
    for (int i = 0; i < max_interfaces; ++i) {
        nicb_array[i].interface_id = i + 1;
        nicb_array[i].reference_count = 0;
        nicb_array[i].packet_buffer = (char *)malloc(MAX_PACKET_SIZE);
        if (!nicb_array[i].packet_buffer) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(nicb_array[j].packet_buffer);
            free(nicb_array);
            return NULL;
        }
        buffer_size += MAX_PACKET_SIZE;
        if (buffer_size > total_memory_limit) {
            // Handle memory limit exceeded
            for (int j = 0; j <= i; ++j) free(nicb_array[j].packet_buffer);
            free(nicb_array);
            return NULL;
        }
    }

    return nicb_array;
}

void cleanup_nicb_array(NICB *nicb_array, int max_interfaces) {
    for (int i = 0; i < max_interfaces; ++i) {
        free(nicb_array[i].packet_buffer);
    }
    free(nicb_array);
}
