#define MAX_TAG_LENGTH 1024
#define MAX_LIST_SIZE 1000

typedef struct {
    int TAG_ID;
    int TAG_LENGTH;
    char TAG_CONTENT[MAX_TAG_LENGTH];
} NFIT_TAG_T;

typedef struct {
    NFIT_TAG_T *tags;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} TagList;

void initTagList(TagList *list) {
    list->tags = (NFIT_TAG_T *)malloc(MAX_LIST_SIZE * sizeof(NFIT_TAG_T));
    if (!list->tags) {
        perror("Failed to allocate memory for tag list");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&list->mutex, NULL);
}

void addTag(TagList *list, NFIT_TAG_T tag) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        // Handle capacity exceeded
        printf("Tag list is full. Cannot add more tags.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->tags[list->size++] = tag;
    pthread_mutex_unlock(&list->mutex);
}

NFIT_TAG_T getTag(TagList *list, int index) {
    NFIT_TAG_T tag;
    pthread_mutex_lock(&list->mutex);
    if (index < 0 || index >= list->size) {
        // Handle invalid index
        printf("Invalid tag index.\n");
        memset(&tag, 0, sizeof(NFIT_TAG_T));
    } else {
        tag = list->tags[index];
    }
    pthread_mutex_unlock(&list->mutex);
    return tag;
}

void freeTagList(TagList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->tags);
    pthread_mutex_destroy(&list->mutex);
    pthread_mutex_unlock(&list->mutex);
}
