#define MAX_PAYLOAD_LENGTH 1024

typedef struct {
    int sender_id;
    time_t timestamp;
    char payload[MAX_PAYLOAD_LENGTH];
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
} MessageArray;

void init_message_array(MessageArray* array) {
    array->messages = NULL;
    array->count = 0;
    array->capacity = 0;
}

void add_message(MessageArray* array, int sender_id, time_t timestamp, const char* payload) {
    if (array->count >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        Message* new_messages = realloc(array->messages, new_capacity * sizeof(Message));
        if (new_messages == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->count].sender_id = sender_id;
    array->messages[array->count].timestamp = timestamp;
    strncpy(array->messages[array->count].payload, payload, MAX_PAYLOAD_LENGTH - 1);
    array->messages[array->count].payload[MAX_PAYLOAD_LENGTH - 1] = '\0';
    array->count++;
}

Message* get_messages_by_sender(MessageArray* array, int sender_id) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->messages[i].sender_id == sender_id) {
            return &array->messages[i];
        }
    }
    return NULL;
}

void clear_message_array(MessageArray* array) {
    free(array->messages);
    array->messages = NULL;
    array->count = 0;
    array->capacity = 0;
}
