    sensor_crc_data* data = (sensor_crc_data*)malloc(num_sensors * sizeof(sensor_crc_data));
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_sensors; i++) {
        data[i].num_crc_data = 0;
    }
    return data;
}

void free_sensor_crc_data(sensor_crc_data* data, int num_sensors) {
    free(data);
}

void initialize_sensor_crc_data(sensor_crc_data* data, int sensor_id, UE_Info ue_info, CRC_Data crc_data) {
    if (sensor_id < 0 || sensor_id >= MAX_Sensors) {
        fprintf(stderr, "Invalid sensor ID\n");
        return;
    }
    if (data[sensor_id].num_crc_data >= MAX_CRC_DATA) {
        fprintf(stderr, "Too many CRC data points for this sensor\n");
        return;
    }
    data[sensor_id].ue_info = ue_info;
    data[sensor_id].crc_data[data[sensor_id].num_crc_data++] = crc_data;
}

void process_sensor_crc_data(sensor_crc_data* data, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        if (data[i].num_crc_data == 0) {
            continue;
        }
        // Process CRC data here
        printf("Sensor %d: UE Info - RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", i, data[i].ue_info.RX_UE_INFORMATION_TAG, data[i].ue_info.RNTI);
        for (int j = 0; j < data[i].num_crc_data; j++) {
            printf("CRC Data - CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n", data[i].crc_data[j].CRC_INDICATION_REL8_TAG, data[i].crc_data[j].CRCFLAG);
        }
    }
}

int main() {
    srand(time(NULL));
    int num_sensors = 5;
    sensor_crc_data* data = allocate_sensor_crc_data(num_sensors);

    for (int i = 0; i < num_sensors; i++) {
        UE_Info ue_info = {i, rand() % 100};
        CRC_Data crc_data = {rand() % 100, rand() % 2};
        initialize_sensor_crc_data(data, i, ue_info, crc_data);
    }

    process_sensor_crc_data(data, num_sensors);

    free_sensor_crc_data(data, num_sensors);
    return 0;
}
