#define MAX_ELEMENTS 10000
#define HASH_TABLE_SIZE 4096

typedef struct {
    uint16_t RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buckets[HASH_TABLE_SIZE];
} HashTable;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_elements(uint16_t N) {
    if (N > MAX_ELEMENTS) {
        return NULL; // Error: Exceeds maximum allowed elements
    }

    NFAPI_CRC_INDICATION_PDU_T *elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) {
        return NULL; // Memory allocation failed
    }

    HashTable hash_table;
    memset(&hash_table, 0, sizeof(HashTable));

    for (uint16_t i = 0; i < N; ++i) {
        elements[i].RNTI = rand() % 4096; // Random RNTI value
        elements[i].rx_ue_info_tag.RNTI = elements[i].RNTI;
        elements[i].crc_ind_rel8_tag.CRCFLAG = (rand() % 2); // Random CRCFLAG

        uint32_t hash_index = elements[i].RNTI % HASH_TABLE_SIZE;
        elements[i].next = hash_table.buckets[hash_index];
        hash_table.buckets[hash_index] = &elements[i];
    }

    return elements;
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *elements = allocate_and_initialize_elements(5000);
    if (elements) {
        // Use the allocated and initialized elements
        free(elements); // Don't forget to free the allocated memory when done
    }
    return 0;
}
