typedef struct LTE_UE_CONTEXT {
    uint64_t RRC_UE_ID;
    int NAS_MM_STATE;
    char* LTE_UL_SRB1_BUFFER;
} LTE_UE_CONTEXT;

typedef struct DynamicArray {
    LTE_UE_CONTEXT** elements;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->elements = (LTE_UE_CONTEXT**)malloc(initial_capacity * sizeof(LTE_UE_CONTEXT*));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->elements[i]->LTE_UL_SRB1_BUFFER) {
            free(array->elements[i]->LTE_UL_SRB1_BUFFER);
        }
        free(array->elements[i]);
    }
    free(array->elements);
    free(array);
}

int add_UE_context(DynamicArray* array, LTE_UE_CONTEXT* context) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_UE_CONTEXT** new_elements = (LTE_UE_CONTEXT**)realloc(array->elements, new_capacity * sizeof(LTE_UE_CONTEXT*));
        if (!new_elements) return -1;

        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    array->elements[array->size++] = context;
    return 0;
}

LTE_UE_CONTEXT* get_UE_context(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;
    return array->elements[index];
}

int remove_UE_context(DynamicArray* array, size_t index) {
    if (index >= array->size) return -1;

    if (array->elements[index]->LTE_UL_SRB1_BUFFER) {
        free(array->elements[index]->LTE_UL_SRB1_BUFFER);
    }
    free(array->elements[index]);

    for (size_t i = index; i < array->size - 1; ++i) {
        array->elements[i] = array->elements[i + 1];
    }

    --array->size;
    return 0;
}
