#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int interface_id;
    char ip_address[16];
    char subnet_mask[16];
} NetworkInterface;

typedef struct {
    NetworkInterface **interfaces;
    size_t count;
    pthread_mutex_t mutex;
} NetworkConfig;

NetworkConfig* init_network_config() {
    NetworkConfig *config = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    if (!config) return NULL;

    config->interfaces = NULL;
    config->count = 0;
    if (pthread_mutex_init(&config->mutex, NULL) != 0) {
        free(config);
        return NULL;
    }

    return config;
}

int add_interface(NetworkConfig *config, int interface_id, const char *ip_address, const char *subnet_mask) {
    pthread_mutex_lock(&config->mutex);

    NetworkInterface *new_interface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    if (!new_interface) {
        pthread_mutex_unlock(&config->mutex);
        return -1;
    }

    new_interface->interface_id = interface_id;
    strncpy(new_interface->ip_address, ip_address, sizeof(new_interface->ip_address) - 1);
    strncpy(new_interface->subnet_mask, subnet_mask, sizeof(new_interface->subnet_mask) - 1);

    NetworkInterface **new_interfaces = (NetworkInterface**)realloc(config->interfaces, (config->count + 1) * sizeof(NetworkInterface*));
    if (!new_interfaces) {
        free(new_interface);
        pthread_mutex_unlock(&config->mutex);
        return -1;
    }

    new_interfaces[config->count] = new_interface;
    config->interfaces = new_interfaces;
    config->count++;

    pthread_mutex_unlock(&config->mutex);
    return 0;
}

void destroy_network_config(NetworkConfig *config) {
    if (!config) return;

    pthread_mutex_lock(&config->mutex);

    for (size_t i = 0; i < config->count; i++) {
        free(config->interfaces[i]);
    }

    free(config->interfaces);
    pthread_mutex_destroy(&config->mutex);
    free(config);
}
