#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ACCOUNTS 1000

typedef struct {
    int id;
    char username[50];
    char email[100];
    long storage_quota;
} Account;

Account* account_list[MAX_ACCOUNTS];
int account_count = 0;
pthread_mutex_t account_lock;

void initialize_accounts() {
    pthread_mutex_init(&account_lock, NULL);
}

int add_account(int id, const char* username, const char* email, long storage_quota) {
    if (id < 1 || strlen(username) > 50 || strlen(email) > 100 || storage_quota <= 0) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&account_lock);
    if (account_count >= MAX_ACCOUNTS) {
        pthread_mutex_unlock(&account_lock);
        return -2; // Account list full
    }

    account_list[account_count] = (Account*)malloc(sizeof(Account));
    if (!account_list[account_count]) {
        pthread_mutex_unlock(&account_lock);
        return -3; // Memory allocation failed
    }

    account_list[account_count]->id = id;
    strcpy(account_list[account_count]->username, username);
    strcpy(account_list[account_count]->email, email);
    account_list[account_count]->storage_quota = storage_quota;

    account_count++;
    pthread_mutex_unlock(&account_lock);

    return 0; // Success
}

int remove_account(int id) {
    pthread_mutex_lock(&account_lock);
    for (int i = 0; i < account_count; i++) {
        if (account_list[i]->id == id) {
            free(account_list[i]);
            for (int j = i; j < account_count - 1; j++) {
                account_list[j] = account_list[j + 1];
            }
            account_count--;
            pthread_mutex_unlock(&account_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&account_lock);
    return -1; // Account not found
}

Account* get_account(int id) {
    pthread_mutex_lock(&account_lock);
    for (int i = 0; i < account_count; i++) {
        if (account_list[i]->id == id) {
            pthread_mutex_unlock(&account_lock);
            return account_list[i];
        }
    }
    pthread_mutex_unlock(&account_lock);
    return NULL; // Account not found
}

void cleanup_accounts() {
    for (int i = 0; i < account_count; i++) {
        free(account_list[i]);
    }
    pthread_mutex_destroy(&account_lock);
}
