#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int validateRNTI(LinkedList* list, int RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return -1; // Duplicate RNTI found
        }
        current = current->next;
    }
    return 0;
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
