    fprintf(log_file, "[%s] RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", ctime(&now), element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRCFLAG);
}

void log_list(NFAPI_CRC_LIST_T *list, FILE *log_file) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        log_element(list->elements[i], log_file);
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
