#define MAX_ELEMENTS 20000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    time_t expiration_policy;
} NFAPI_LIST_T;

NFAPI_LIST_T* create_nfa_list() {
    NFAPI_LIST_T *list = (NFAPI_LIST_T*)malloc(sizeof(NFAPI_LIST_T));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&list->lock, NULL);
    list->expiration_policy = time(NULL) + 3600; // Example expiration policy

    return list;
}

void destroy_nfa_list(NFAPI_LIST_T *list) {
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_to_nfa_list(NFAPI_LIST_T *list, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, list->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->elements = new_elements;
        list->capacity *= 2;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_element = &list->elements[list->count++];
    new_element->ue_info = ue_info;
    new_element->rnti = rnti;
    new_element->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void purge_nfa_list(NFAPI_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < list->count; ) {
        if (current_time > list->elements[i].expiration_policy) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
