uint8_t* decryptCiphertext(uint8_t* ciphertext, int ciphertext_len, uint8_t* encryption_key, uint8_t* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error
        return NULL;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, encryption_key, iv)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    uint8_t* decrypted_data = (uint8_t*)malloc(ciphertext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    if (!decrypted_data) {
        // Handle memory allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int len, total_len = 0;
    if (1 != EVP_DecryptUpdate(ctx, decrypted_data, &len, ciphertext, ciphertext_len)) {
        // Handle error
        free(decrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    total_len += len;

    if (1 != EVP_DecryptFinal_ex(ctx, decrypted_data + total_len, &len)) {
        // Handle error
        free(decrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    total_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return decrypted_data;
}
