#include <pthread.h>

#define MAX_NFAPI_CRC_INDICATION_PDU_T 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(uint32_t base_seed, size_t count) {
    if (count > MAX_NFAPI_CRC_INDICATION_PDU_T) {
        fprintf(stderr, "Error: Count exceeds maximum supported.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
    uint16_t rnti_values[MAX_NFAPI_CRC_INDICATION_PDU_T];
    for (size_t i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = base_seed + i;
        pthread_mutex_lock(&rnti_mutex);
        while (1) {
            uint16_t rnti = rand() % UINT16_MAX;
            int found = 0;
            for (size_t j = 0; j < i; ++j) {
                if (rnti_values[j] == rnti) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                array[i].RNTI = rnti;
                rnti_values[i] = rnti;
                break;
            }
        }
        pthread_mutex_unlock(&rnti_mutex);
    }

    uint8_t last_crcflag = 0xFF; // Initialize with an invalid value
    for (size_t i = 0; i < count; ++i) {
        do {
            array[i].CRCFLAG = rand() % 256;
        } while (array[i].CRCFLAG == last_crcflag);
        last_crcflag = array[i].CRCFLAG;
    }

    return array;
}

void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
