NetworkInterfaceStats* init_network_stats(size_t num_interfaces, size_t max_packets) {
    NetworkInterfaceStats *stats = (NetworkInterfaceStats*)malloc(num_interfaces * sizeof(NetworkInterfaceStats));
    if (!stats) return NULL;

    for (size_t i = 0; i < num_interfaces; ++i) {
        stats[i].packet_sizes = (size_t*)calloc(max_packets, sizeof(size_t));
        if (!stats[i].packet_sizes) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) free(stats[j].packet_sizes);
            free(stats);
            return NULL;
        }
    }

    return stats;
}

void populate_network_stats(NetworkInterfaceStats *stats, size_t num_interfaces, size_t interface_id,
                            uint64_t throughput, double error, double latency, size_t packet_count, const size_t *packet_sizes) {
    if (interface_id >= num_interfaces || !stats[interface_id].packet_sizes) return;

    stats[interface_id].receive_throughput = throughput;
    stats[interface_id].error_rate = error;
    stats[interface_id].latency = latency;
    stats[interface_id].packet_count = packet_count;
    memcpy(stats[interface_id].packet_sizes, packet_sizes, packet_count * sizeof(size_t));
}

void free_network_stats(NetworkInterfaceStats *stats, size_t num_interfaces) {
    if (!stats) return;

    for (size_t i = 0; i < num_interfaces; ++i) {
        free(stats[i].packet_sizes);
    }
    free(stats);
}

