// Define a custom data structure for network interface statistics
typedef struct {
    char interface_name[50];
    double receive_throughput;
    double error_rate;
    int latency;
    int *packet_sizes;
    time_t *timestamps;
    size_t packet_count;
} NetworkInterfaceStats;

// Function to initialize and populate the list of network interface statistics
void initialize_network_stats(NetworkInterfaceStats **stats, size_t num_interfaces) {
    *stats = (NetworkInterfaceStats *)malloc(num_interfaces * sizeof(NetworkInterfaceStats));
    if (*stats == NULL) {
        fprintf(stderr, "Memory allocation failed for network stats\n");
        exit(EXIT_FAILURE);
    }

    // Populate the statistics with dummy data
    for (size_t i = 0; i < num_interfaces; ++i) {
        snprintf((*stats)[i].interface_name, sizeof((*stats)[i].interface_name), "Interface%d", i + 1);
        (*stats)[i].receive_throughput = 100.0 * rand() / RAND_MAX;
        (*stats)[i].error_rate = 0.1 * rand() / RAND_MAX;
        (*stats)[i].latency = 50 + rand() % 200;

        // Dynamically allocate memory for packet sizes and timestamps
        (*stats)[i].packet_sizes = (int *)malloc(100 * sizeof(int));
        (*stats)[i].timestamps = (time_t *)malloc(100 * sizeof(time_t));
        if ((*stats)[i].packet_sizes == NULL || (*stats)[i].timestamps == NULL) {
            fprintf(stderr, "Memory allocation failed for packet data\n");
            exit(EXIT_FAILURE);
        }

        // Initialize packet sizes and timestamps
        for (size_t j = 0; j < 100; ++j) {
            (*stats)[i].packet_sizes[j] = 1500 + rand() % 2048;
            (*stats)[i].timestamps[j] = time(NULL);
        }
    }
}

// Function to serialize the statistics into a binary format
void serialize_stats_to_binary(NetworkInterfaceStats *stats, size_t num_interfaces, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&num_interfaces, sizeof(size_t), 1, file);
    for (size_t i = 0; i < num_interfaces; ++i) {
        fwrite((*stats)[i].interface_name, sizeof(char), sizeof((*stats)[i].interface_name), file);
        fwrite(&(*stats)[i].receive_throughput, sizeof(double), 1, file);
        fwrite(&(*stats)[i].error_rate, sizeof(double), 1, file);
        fwrite(&(*stats)[i].latency, sizeof(int), 1, file);
        fwrite((*stats)[i].packet_sizes, sizeof(int), (*stats)[i].packet_count, file);
        fwrite((*stats)[i].timestamps, sizeof(time_t), (*stats)[i].packet_count, file);
    }

    fclose(file);
}

// Function to free the allocated memory for network interface statistics
void free_network_stats(NetworkInterfaceStats *stats, size_t num_interfaces) {
    for (size_t i = 0; i < num_interfaces; ++i) {
        free(stats[i].packet_sizes);
        free(stats[i].timestamps);
    }
    free(stats);
}

int main() {
    NetworkInterfaceStats *network_stats;
    size_t num_interfaces = 5;

    initialize_network_stats(&network_stats, num_interfaces);

    // Serialize the statistics to a binary file
    serialize_stats_to_binary(network_stats, num_interfaces, "network_stats.bin");

    // Free the allocated memory
    free_network_stats(network_stats, num_interfaces);

    return 0;
}
