typedef struct {
    NetworkInterfaceStats **stats_array;
    size_t array_size;
    pthread_mutex_t lock;
} NetworkStatsCollection;

NetworkStatsCollection* initializeNetworkStats(size_t initial_capacity) {
    NetworkStatsCollection *collection = (NetworkStatsCollection*)malloc(sizeof(NetworkStatsCollection));
    if (!collection) return NULL;

    collection->array_size = initial_capacity;
    collection->stats_array = (NetworkInterfaceStats**)calloc(initial_capacity, sizeof(NetworkInterfaceStats*));
    if (!collection->stats_array) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroyNetworkStatsCollection(NetworkStatsCollection *collection) {
    for (size_t i = 0; i < collection->array_size; ++i) {
        if (collection->stats_array[i]) {
            free(collection->stats_array[i]->packet_sizes);
            free(collection->stats_array[i]);
        }
    }
    free(collection->stats_array);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void addNetworkInterfaceStats(NetworkStatsCollection *collection, NetworkInterfaceStats *new_stats) {
    pthread_mutex_lock(&collection->lock);
    if (collection->array_size <= collection->current_count) {
        // Resize array
        size_t new_capacity = collection->array_size * 2;
        NetworkInterfaceStats **new_array = (NetworkInterfaceStats**)realloc(collection->stats_array, new_capacity * sizeof(NetworkInterfaceStats*));
        if (!new_array) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->stats_array = new_array;
        collection->array_size = new_capacity;
    }
    collection->stats_array[collection->current_count++] = new_stats;
    pthread_mutex_unlock(&collection->lock);
}

