#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_from_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI &&
            current->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int main() {
    List* list = create_list();
    if (!list) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = {1, 2, 3, rand() % 2};
    add_to_list(list, data);

    destroy_list(list);
    return 0;
}
