typedef struct {
    NFAPI_RRC_PDU_T *pool;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t lock;
} DynamicPool;

DynamicPool* create_pool(size_t initial_size) {
    DynamicPool *pool = (DynamicPool*)malloc(sizeof(DynamicPool));
    pool->pool = (NFAPI_RRC_PDU_T*)calloc(initial_size, sizeof(NFAPI_RRC_PDU_T));
    pool->allocated_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_pool(DynamicPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_RRC_PDU_T* allocate_struct(DynamicPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count >= pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        NFAPI_RRC_PDU_T *new_pool = (NFAPI_RRC_PDU_T*)realloc(pool->pool, new_size * sizeof(NFAPI_RRC_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle memory allocation failure
        }
        pool->pool = new_pool;
        pool->allocated_size = new_size;
    }
    NFAPI_RRC_PDU_T *result = &pool->pool[pool->used_count++];
    pthread_mutex_unlock(&pool->lock);
    return result;
}

void serialize_pool(DynamicPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        // Handle file opening failure
        return;
    }

    size_t total_size = pool->used_count * sizeof(NFAPI_RRC_PDU_T);
    uLongf compressed_size = compressBound(total_size);

    Bytef *compressed_data = (Bytef*)malloc(compressed_size);
    if (!compressed_data) {
        fclose(file);
        // Handle memory allocation failure
        return;
    }

    size_t result = compress2(compressed_data, &compressed_size, (const Bytef*)pool->pool, total_size, Z_DEFAULT_COMPRESSION);
    if (result != Z_OK) {
        free(compressed_data);
        fclose(file);
        // Handle compression failure
        return;
    }

    fwrite(&compressed_size, sizeof(uLongf), 1, file);
    fwrite(compressed_data, compressed_size, 1, file);

    free(compressed_data);
    fclose(file);
}

void deserialize_pool(DynamicPool *pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        // Handle file opening failure
        return;
    }

    uLongf compressed_size;
    fread(&compressed_size, sizeof(uLongf), 1, file);

    Bytef *compressed_data = (Bytef*)malloc(compressed_size);
    if (!compressed_data) {
        fclose(file);
        // Handle memory allocation failure
        return;
    }

    size_t result = fread(compressed_data, compressed_size, 1, file);
    if (result != 1) {
        free(compressed_data);
        fclose(file);
        // Handle read failure
        return;
    }

    uLongf original_size = pool->allocated_size * sizeof(NFAPI_RRC_PDU_T);
    Bytef *original_data = (Bytef*)malloc(original_size);
    if (!original_data) {
        free(compressed_data);
        fclose(file);
        // Handle memory allocation failure
        return;
    }

    result = uncompress(original_data, &original_size, compressed_data, compressed_size);
    if (result != Z_OK) {
        free(compressed_data);
        free(original_data);
        fclose(file);
        // Handle decompression failure
        return;
    }

    memcpy(pool->pool, original_data, original_size);

    free(compressed_data);
    free(original_data);
    fclose(file);
}

void* update_pool(void *arg) {
