#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void dynamic_list_remove(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index < list->size) {
        for (size_t i = index; i < list->size - 1; ++i) {
            list->data[i] = list->data[i + 1];
        }
        --list->size;
    }
    pthread_mutex_unlock(&list->mutex);
}

