} DataPacket;

typedef struct {
    DataPacket *data;
    int timestamp;
    int frameNumber;
} FrameMetadata;

FrameMetadata* initializeFrames(int numFrames, int maxPayload) {
    if (numFrames <= 0 || maxPayload <= 0) {
        fprintf(stderr, "Error: Invalid input sizes. Number of frames and maximum payload must be positive.\n");
        return NULL;
    }

    FrameMetadata *frames = (FrameMetadata *)malloc(numFrames * sizeof(FrameMetadata));
    if (frames == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numFrames; i++) {
        frames[i].data = (DataPacket *)malloc(maxPayload);
        if (frames[i].data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for frame %d.\n", i);
            // Free previously allocated memory before returning
            for (int j = 0; j < i; j++) {
                free(frames[j].data);
            }
            free(frames);
            return NULL;
        }
    }

    // Initialize other members of FrameMetadata if necessary

    return frames;
}

// Function to verify the integrity of the data structure
void checkFrames(FrameMetadata *frames, int numFrames) {
    for (int i = 0; i < numFrames - 1; i++) {
        if (frames[i].frameNumber >= frames[i + 1].frameNumber || frames[i].timestamp >= frames[i + 1].timestamp) {
            fprintf(stderr, "Error: Frame %d is out of order or has an invalid timestamp.\n", i);
        }
    }
}

// Example usage
int main() {
    int numFrames = 10;
    int maxPayload = 256;
    FrameMetadata *frames = initializeFrames(numFrames, maxPayload);

    if (frames != NULL) {
        // Use the frames array for processing
        checkFrames(frames, numFrames);
        // Free allocated memory when done
        for (int i = 0; i < numFrames; i++) {
            free(frames[i].data);
        }
        free(frames);
    }

    return 0;
}
