#include <time.h>

#define MAX_STRUCTURES 10000
#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define BATCH_SIZE 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T structures[MAX_STRUCTURES];
int structure_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void initialize_log() {
    log_file = fopen("nfaapi_crc_indication.log", "w");
}

void log_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (log_file == NULL) return;
    fprintf(log_file, "{\"RX_UE_INFORMATION_TAG\": %d, \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %d, \"CRCFLAG\": %d}\n",
            structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRC_INDICATION_REL8_TAG, structure->CRCFLAG);
    fflush(log_file);
}

void* generate_structures(void *arg) {
    srand(time(NULL));
    while (1) {
        pthread_mutex_lock(&mutex);
        if (structure_count >= MAX_STRUCTURES) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T new_structure = {
            .RX_UE_INFORMATION_TAG = rand() % 1000,
            .RNTI = rand() % 100 + 1, // Ensure RNTI is between 1 and 100
            .CRC_INDICATION_REL8_TAG = rand() % 256,
            .CRCFLAG = rand() % 2
        };
        if (structure_count > 0 && structures[structure_count - 1].RNTI == new_structure.RNTI) {
            pthread_mutex_unlock(&mutex);
            continue;
        }
        structures[structure_count++] = new_structure;
        log_structure(&new_structure);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* process_events(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (structure_count == 0) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        for (int i = 0; i < BATCH_SIZE && structure_count > 0; i++) {
            // Process the event
            printf("Processing event: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
                   structures[structure_count - 1].RX_UE_INFORMATION_TAG,
                   structures[structure_count - 1].RNTI,
                   structures[structure_count - 1].CRC_INDICATION_REL8_TAG,
                   structures[structure_count - 1].CRCFLAG);
            structure_count--;
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    initialize_log();
    pthread_t generator_thread, processor_thread;

    if (pthread_create(&generator_thread, NULL, generate_structures, NULL) != 0) {
        perror("Failed to create generator thread");
        return 1;
    }

    if (pthread_create(&processor_thread, NULL, process_events, NULL) != 0) {
        perror("Failed to create processor thread");
        return 1;
    }

    pthread_join(generator_thread, NULL);
    pthread_join(processor_thread, NULL);

    fclose(log_file);
    return 0;
}
