#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define LOG_QUEUE_SIZE 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int priority;
} LogEntry;

typedef struct {
    LogEntry queue[LOG_QUEUE_SIZE];
    int front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} LogQueue_T;

NFAPI_LIST_T *create_list() {
    NFAPI_LIST_T *list = (NFAPI_LIST_T *)malloc(sizeof(NFAPI_LIST_T));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(NFAPI_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    free(list);
}

LogQueue_T *create_log_queue() {
    LogQueue_T *queue = (LogQueue_T *)malloc(sizeof(LogQueue_T));
    queue->front = queue->rear = -1;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    return queue;
}

void destroy_log_queue(LogQueue_T *queue) {
    while (queue->front != -1) {
        LogEntry entry = queue->queue[queue->front];
        free(entry.pdu.RX_UE_INFORMATION_TAG);
        free(entry.pdu.RNTI);
        free(entry.pdu.CRC_INDICATION_REL8_TAG);
        if (++queue->front == LOG_QUEUE_SIZE)
            queue->front = 0;
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

void add_to_list(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    while (list->count == MAX_STRUCTURES)
        pthread_cond_wait(&list->not_full, &list->lock);
    list->data[list->count++] = pdu;
    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T *remove_from_list(NFAPI_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    while (list->count == 0)
        pthread_cond_wait(&list->not_empty, &list->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->data[--list->count];
    pthread_cond_signal(&list->not_full);
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

void add_to_log_queue(LogQueue_T *queue, LogEntry entry) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->rear + 1) % LOG_QUEUE_SIZE == queue->front)
        pthread_cond_wait(&queue->not_full, &queue->lock);
    if (queue->front == -1)
        queue->front = queue->rear = 0;
    else
        queue->rear = (queue->rear + 1) % LOG_QUEUE_SIZE;
    queue->queue[queue->rear] = entry;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

LogEntry remove_from_log_queue(LogQueue_T *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->front == -1)
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    LogEntry entry = queue->queue[queue->front];
    if (queue->front == queue->rear)
        queue->front = queue->rear = -1;
    else
        queue->front = (queue->front + 1) % LOG_QUEUE_SIZE;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return entry;
}

void *log_thread(void *arg) {
    LogQueue_T *queue = (LogQueue_T *)arg;
    while (1) {
        LogEntry entry = remove_from_log_queue(queue);
        // Log the entry to the external system
    }
}
