use std::sync::{Arc, Mutex};
use std::collections::HashSet;
use rand::{Rng, SeedableRng};
use rand_chacha::ChaCha8Rng;

const MAX_DIR_NAME_LEN: usize = 256;
const BASE_SEED: u64 = 1234567890;
const MAX_RNTI: u16 = 65535;
const CRC_FLAGS: &[u8] = &[0x01, 0x02, 0x04, 0x08, 0x10];

struct DirectoryManager {
    directories: Arc<Mutex<Vec<String>>>,
    rnti_set: Arc<Mutex<HashSet<u16>>>,
    crc_flag_index: usize,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager {
            directories: Arc::new(Mutex::new(Vec::new())),
            rnti_set: Arc::new(Mutex::new(HashSet::new())),
            crc_flag_index: 0,
        }
    }

    fn create_directory(&self, index: usize) -> Option<String> {
        let mut rng = ChaCha8Rng::seed_from_u64(BASE_SEED + index as u64);
        let mut directories = self.directories.lock().unwrap();
        let mut rnti_set = self.rnti_set.lock().unwrap();

        if directories.len() >= MAX_DIR_NAME_LEN {
            eprintln!("Maximum directory count reached");
            return None;
        }

        loop {
            let rnti: u16 = rng.gen_range(0..MAX_RNTI);
            if !rnti_set.contains(&rnti) {
                rnti_set.insert(rnti);
                break;
            }
        }

        let crc_flag = CRC_FLAGS[self.crc_flag_index % CRC_FLAGS.len()];
        self.crc_flag_index += 1;

        let dir_name = format!("RX_UE_INFORMATION_TAG_{:04X}_{:02X}", rnti, crc_flag);
        directories.push(dir_name.clone());

        Some(dir_name)
    }

    fn free_memory(&self) {
        *self.directories.lock().unwrap() = Vec::new();
        *self.rnti_set.lock().unwrap() = HashSet::new();
    }
}

fn main() {
    let manager = DirectoryManager::new();

    for i in 0..1000 {
        if let Some(dir) = manager.create_directory(i) {
            println!("Created directory: {}", dir);
        } else {
            break;
        }
    }

    manager.free_memory();
}
