#include <pthread.h>

typedef struct {
    time_t timestamp;
    char* event_type;
    char* details;
} TrafficEvent;

typedef struct {
    TrafficEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TrafficEventArray;

TrafficEvent* initialize_traffic_event(time_t timestamp, const char* event_type, const char* details) {
    TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    if (event == NULL) return NULL;

    event->timestamp = timestamp;
    event->event_type = strdup(event_type);
    event->details = strdup(details);

    if (event->event_type == NULL || event->details == NULL) {
        free(event);
        return NULL;
    }

    return event;
}

TrafficEventArray* initialize_traffic_events(int initial_capacity) {
    TrafficEventArray* array = (TrafficEventArray*)malloc(sizeof(TrafficEventArray));
    if (array == NULL) return NULL;

    array->events = (TrafficEvent*)calloc(initial_capacity, sizeof(TrafficEvent));
    if (array->events == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_traffic_event(TrafficEvent* event) {
    if (event != NULL) {
        free(event->event_type);
        free(event->details);
        free(event);
    }
}

void destroy_traffic_events(TrafficEventArray* array) {
    if (array != NULL) {
        for (size_t i = 0; i < array->size; ++i) {
            destroy_traffic_event(&array->events[i]);
        }
        free(array->events);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_traffic_event(TrafficEventArray* array, TrafficEvent* event) {
    if (array == NULL || event == NULL) return -1;

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(array->events, new_capacity * sizeof(TrafficEvent));
        if (new_events == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }

    memcpy(&array->events[array->size], event, sizeof(TrafficEvent));
    ++array->size;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int remove_traffic_event(TrafficEventArray* array, size_t index) {
    if (array == NULL || index >= array->size) return -1;

    pthread_mutex_lock(&array->mutex);

    destroy_traffic_event(&array->events[index]);

    for (size_t i = index; i < array->size - 1; ++i) {
        memcpy(&array->events[i], &array->events[i + 1], sizeof(TrafficEvent));
    }

    --array->size;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}
