#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10000

typedef struct {
    int fd;
    int state;
    time_t timeout;
} Connection;

Connection connection_pool[MAX_CONNECTIONS];
int current_connections = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_condition = PTHREAD_COND_INITIALIZER;

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i].fd = -1;
        connection_pool[i].state = 0;
        connection_pool[i].timeout = 0;
    }
}

int acquire_connection() {
    pthread_mutex_lock(&pool_lock);
    while (current_connections >= MAX_CONNECTIONS) {
        pthread_cond_wait(&pool_condition, &pool_lock);
    }
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd != -1) {
        connection_pool[current_connections].fd = fd;
        connection_pool[current_connections].state = 1;
        connection_pool[current_connections].timeout = time(NULL) + 60; // Set timeout to 60 seconds
        current_connections++;
    }
    pthread_mutex_unlock(&pool_lock);
    return fd;
}

void release_connection(int fd) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < current_connections; i++) {
        if (connection_pool[i].fd == fd) {
            close(fd);
            connection_pool[i] = connection_pool[current_connections - 1];
            current_connections--;
            break;
        }
    }
    pthread_cond_signal(&pool_condition);
    pthread_mutex_unlock(&pool_lock);
}

void* monitor_connections(void* arg) {
    while (1) {
        sleep(60); // Check every minute
        for (int i = 0; i < current_connections; i++) {
            if (time(NULL) > connection_pool[i].timeout) {
                release_connection(connection_pool[i].fd);
            }
        }
    }
    return NULL;
}

void log_connection_status(int fd, int state, time_t timeout) {
    printf("Connection %d: State=%d, Timeout=%ld\n", fd, state, timeout);
}

int main() {
    initialize_connection_pool();
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_connections, NULL);

    // Example usage
    int conn1 = acquire_connection();
    log_connection_status(conn1, 1, connection_pool[0].timeout);

    release_connection(conn1);
    log_connection_status(conn1, 0, 0);

    pthread_join(monitor_thread, NULL);
    return 0;
}
```

