    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long checksum;
} CRC_LIST_T;

CRC_LIST_T* crc_list_create(size_t initial_capacity) {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->checksum = 0;

    return list;
}

void crc_list_destroy(CRC_LIST_T *list) {
    if (list) {
        free(list->entries);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int crc_list_add(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T entry, int is_active) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    if (is_active && entry.CRCFLAG == 0) {
        entry.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else if (!is_active) {
        entry.CRCFLAG = 0;
    }

    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int crc_list_update(CRC_LIST_T *list, size_t index, NFAPI_CRC_INDICATION_PDU_T new_entry, int is_active) {
    if (index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);

    if (is_active && new_entry.CRCFLAG == 0) {
        new_entry.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else if (!is_active) {
        new_entry.CRCFLAG = 0;
    }

    list->entries[index] = new_entry;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* crc_list_get(CRC_LIST_T *list, size_t *count) {
    if (count) *count = list->count;
    return list->entries;
}
