    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

void populate_struct(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti, int crcflag) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crcflag;
}

void serialize_data(NFAPI_CRC_INDICATION_PDU_T* data, int count, const char* filepath) {
    FILE* file = fopen(filepath, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }
    size_t written = fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    if (written != (size_t)count) {
        fprintf(stderr, "Error writing data to file\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }
    fclose(file);
}

void* thread_function(void* arg) {
    int* params = (int*)arg;
    int count = params[0];
    int seed = params[1];
    const char* filepath = (const char*)params[2];

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T* data = allocate_memory(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < count; i++) {
        populate_struct(&data[i], rand() % 100, rand() % 2);
    }

    serialize_data(data, count, filepath);

    free_memory(data);
    pthread_exit(NULL);
}

void create_and_serialize(int num_threads, int structs_per_thread, int seed, const char* filepath) {
    pthread_t threads[num_threads];
    int params[num_threads][3];

    for (int i = 0; i < num_threads; i++) {
        params[i][0] = structs_per_thread;
        params[i][1] = seed + i;
        params[i][2] = filepath;

        if (pthread_create(&threads[i], NULL, thread_function, &params[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    int num_threads = 4;
    int structs_per_thread = MAX_STRUCTS / num_threads;
    int seed = time(NULL);
    const char* filepath = "output.bin";

    create_and_serialize(num_threads, structs_per_thread, seed, filepath);

    return 0;
}
