#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 4096
#define TIMEOUT 5

typedef struct {
    unsigned char header[6];
    unsigned char payload[BUFFER_SIZE];
} MAC_PACKET;

typedef struct {
    int fd;
    pthread_t thread_id;
    MAC_PACKET packet;
} TCP_CONNECTION;

TCP_CONNECTION connections[MAX_CONNECTIONS];

void* handle_connection(void* arg) {
    int conn_fd = *(int*)arg;
    free(arg);

    while (1) {
        // Receive data from the connection
        ssize_t bytes_received = recv(conn_fd, &connections[conn_fd].packet, sizeof(MAC_PACKET), 0);
        if (bytes_received <= 0) {
            break; // Connection closed or error occurred
        }

        // Process the received packet
        // ...

        // Send a response back to the client
        send(conn_fd, &connections[conn_fd].packet, bytes_received, 0);
    }

    close(conn_fd);
    return NULL;
}

void initialize_connections(int max_connections) {
    for (int i = 0; i < max_connections; i++) {
        connections[i].fd = -1;
        pthread_create(&connections[i].thread_id, NULL, handle_connection, NULL);
    }
}

void add_connection(int fd) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].fd == -1) {
            connections[i].fd = fd;
            break;
        }
    }
}

void remove_connection(int fd) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].fd == fd) {
            close(fd);
            connections[i].fd = -1;
            pthread_join(connections[i].thread_id, NULL);
            break;
        }
    }
}

void start_server(int port) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Setting up the address struct
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Binding the socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    initialize_connections(MAX_CONNECTIONS);

    while (1) {
        // Accepting a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        add_connection(new_socket);
    }
}

int main() {
    int port = 8080; // Example port number
    start_server(port);
    return 0;
}
