#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->size = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used >= mp->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(mp->pool, 2 * mp->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->size *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = &mp->pool[mp->used++];
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void populate_structure(NFAPI_CRC_INDICATION_PDU_T *struct_ptr, int rnti, int crcflag) {
    struct_ptr->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    struct_ptr->RNTI = rnti;
    struct_ptr->CRC_INDICATION_REL8_TAG = crcflag;
}

void write_to_file(const char *file_path, NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    FILE *file = fopen(file_path, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    if (fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file) != count) {
        perror("Error writing to file");
    }
    fclose(file);
}

void* producer_thread(void *arg) {
    MemoryPool *mp = (MemoryPool*)arg;
    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *struct_ptr = allocate_from_pool(mp);
        if (!struct_ptr) {
            fprintf(stderr, "Failed to allocate memory\n");
            break;
        }
        populate_structure(struct_ptr, rand() % 1000, rand() % 2); // Example values
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_structures> <seed> <output_file>\n", argv[0]);
        return 1;
    }

    int num_structures = atoi(argv[1]);
    int seed = atoi(argv[2]);
    const char *file_path = argv[3];

    srand(seed);

    MemoryPool *mp = create_memory_pool(num_structures);
    if (!mp) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    pthread_t producer;
    if (pthread_create(&producer, NULL, producer_thread, mp)) {
        fprintf(stderr, "Failed to create thread\n");
        destroy_memory_pool(mp);
        return 1;
    }

    pthread_join(producer, NULL);

    write_to_file(file_path, mp->pool, num_structures);

    destroy_memory_pool(mp);
    return 0;
}
