    ue_contexts[num_ue_contexts]->c_rnti = c_rnti;
    ue_contexts[num_ue_contexts]->mobility_indicators = mobility_indicators;
    num_ue_contexts++;
    pthread_mutex_unlock(&mutex);
}

void free_ue_contexts() {
