int resolve_hostname(const char *hostname, struct in_addr *ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip->s_addr = ipv4->sin_addr.s_addr;
        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);
    return -1;
}

int populate_structures(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        array[i].RNTI = rand() % 65535 + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;
        array[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int resolve_dns(const char *hostname, struct in_addr *ip) {
    int retries = MAX_RETRIES;
    while (retries--) {
        if (resolve_hostname(hostname, ip) == 0) {
            return 0;
        }
        sleep(RETRY_INTERVAL);
    }
    return -1;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    if (populate_structures(array, MAX_STRUCTS) != 0) {
        fprintf(stderr, "Failed to populate structures\n");
        free(array);
        return 1;
    }

    struct in_addr ip;
    if (resolve_dns("example.com", &ip) != 0) {
        fprintf(stderr, "DNS resolution failed\n");
        free(array);
        return 1;
    }

    printf("IP address: %s\n", inet_ntoa(ip));

    free(array);
    return 0;
}
