    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_pdu_list(PDU_List *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    list->pdus = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void add_pdu(PDU_List *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->mutex);
            exit(EXIT_FAILURE);
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
    list->pdus[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->pdus[list->size].RNTI = RNTI;
    list->pdus[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

