    init_pdu_list(&list, 10);

    pthread_t threads[100];
    for (int i = 0; i < 100; i++) {
        if (pthread_create(&threads[i], NULL, create_pdu_thread, &list) != 0) {
            // Handle thread creation failure
            free_pdu_list(&list);
            exit(EXIT_FAILURE);
        }
    }

