    if (list->count < list->capacity) {
        list->data[list->count++] = element;
    } else {
        // Handle threshold notification
        printf("Threshold reached!\n");
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_element(DynamicList *list, size_t index) {
