    uint8_t PDCP_PDU_TYPE;
    uint16_t MAC_SEQ_NUMBER;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MAC_PDU_POOL_T;

MAC_PDU_POOL_T* create_mac_pdu_pool(size_t initial_capacity) {
    MAC_PDU_POOL_T *pool = (MAC_PDU_POOL_T*)malloc(sizeof(MAC_PDU_POOL_T));
    pool->pool = (MAC_PDU_T*)calloc(initial_capacity, sizeof(MAC_PDU_T));
    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_mac_pdu_pool(MAC_PDU_POOL_T *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int allocate_mac_pdu(MAC_PDU_POOL_T *pool, MAC_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool overflow
    }
    memcpy(&pool->pool[pool->used], pdu, sizeof(MAC_PDU_T));
    pool->used++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int deallocate_mac_pdu(MAC_PDU_POOL_T *pool, size_t index) {
    pthread_mutex_lock(&pool->lock);
    if (index >= pool->used) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Invalid index
    }
    pool->used--;
    memcpy(&pool->pool[index], &pool->pool[pool->used], sizeof(MAC_PDU_T));
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

size_t get_available_slots(MAC_PDU_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    size_t available = pool->capacity - pool->used;
    pthread_mutex_unlock(&pool->lock);
    return available;
}
