    ConfigNode* current = list->head;
    while (current != NULL) {
        if (current->config.cellIdentity == config.cellIdentity && 
            current->config.operatingFrequency == config.operatingFrequency) {
            current->config = config;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
    ConfigNode* newNode = (ConfigNode*)malloc(sizeof(ConfigNode));
    newNode->config = config;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

