            current->config.operatingFrequency == frequency) {
            LTE_ENB_MODEM_CONFIG* result = (LTE_ENB_MODEM_CONFIG*)malloc(sizeof(LTE_ENB_MODEM_CONFIG));
            *result = current->config;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

