            memcpy(config, &current->config, sizeof(LTE_ENB_MODEM_CONFIG));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

