typedef struct {
    FrameHeader header;
    size_t payloadLength;
    unsigned char* payload;
} DataPacket;

DataPacket* initializeDynamicArray(size_t numPackets, size_t maxPayloadSize, size_t memoryLimit) {
    if (numPackets * sizeof(DataPacket) + numPackets * maxPayloadSize > memoryLimit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return NULL;
    }

    DataPacket* packetArray = (DataPacket*)malloc(numPackets * sizeof(DataPacket));
    if (!packetArray) {
        fprintf(stderr, "Failed to allocate memory for packet array.\n");
        return NULL;
    }

    for (size_t i = 0; i < numPackets; ++i) {
        packetArray[i].payloadLength = maxPayloadSize;
        packetArray[i].payload = (unsigned char*)malloc(maxPayloadSize);
        if (!packetArray[i].payload) {
            fprintf(stderr, "Failed to allocate memory for payload of packet %zu.\n", i);
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(packetArray[j].payload);
            }
            free(packetArray);
            return NULL;
        }
    }

    printf("Dynamic array initialized successfully with %zu packets.\n", numPackets);
    return packetArray;
}

void cleanupDynamicArray(DataPacket* packetArray, size_t numPackets) {
    for (size_t i = 0; i < numPackets; ++i) {
        free(packetArray[i].payload);
    }
    free(packetArray);
    printf("Dynamic array cleaned up.\n");
}
