#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_crc_array(size_t initial_size) {
    NFAPI_CRC_ARRAY* array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->allocated_size = initial_size;
    array->used_count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY* array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_crc_entry(NFAPI_CRC_ARRAY* array, int RX_UE_INFORMATION_TAG, int RNTI, int seed) {
    pthread_mutex_lock(&array->mutex);

    if (array->used_count >= array->allocated_size) {
        size_t new_size = array->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }

        array->array = new_array;
        array->allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &array->array[array->used_count++];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = 0; // Assuming this is a constant for simplicity
    srand(seed);
    entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&array->mutex);

    return array->used_count - 1;
}

int update_crc_flag(NFAPI_CRC_ARRAY* array, int RNTI, int new_value) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->used_count; ++i) {
        if (array->array[i].RNTI == RNTI) {
            array->array[i].CRCFLAG = new_value;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // Invalid RNTI
}

void reset_crc_flags(NFAPI_CRC_ARRAY* array) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->used_count; ++i) {
        array->array[i].CRCFLAG = 0;
    }

    pthread_mutex_unlock(&array->mutex);
}
