#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define N 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* populate_structures(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    for (int i = 0; i < N; i++) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rand() % 65536;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        structures[i].CRCFLAG = rand() % 2;
    }
    return NULL;
}

int resolve_hostname(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy((char*)ip_address, ipstr);
    }

    freeaddrinfo(res); // all done with this structure
    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T structures[N];
    u_char ip_address[INET6_ADDRSTRLEN];

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, populate_structures, structures) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        return -1;
    }

    if (resolve_hostname("example.com", ip_address) == 0) {
        printf("Resolved IP: %s\n", ip_address);
    } else {
        printf("Failed to resolve hostname\n");
    }

    return 0;
}
