#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_nfaapi_crc_array(size_t initial_count, uint32_t seed) {
    NFAPI_CRC_ARRAY *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);

    for (size_t i = 0; i < initial_count; ++i) {
        array->array[i].RX_UE_INFORMATION_TAG = rand_r(&seed);
        array->array[i].RNTI = rand_r(&seed) % 65536;
        array->array[i].CRCFLAG = (rand_r(&seed) & 1) ? 0 : 1;
    }

    array->count = initial_count;

    return array;
}

void destroy_nfaapi_crc_array(NFAPI_CRC_ARRAY *array) {
    if (!array) return;

    pthread_mutex_destroy(&array->mutex);
    free(array->array);
    free(array);
}

int update_crc_flag(NFAPI_CRC_ARRAY *array, uint16_t rnti, uint8_t new_crcflag) {
    if (!array || rnti >= MAX_ELEMENTS) return -1;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].RNTI == rnti) {
            array->array[i].CRCFLAG = new_crcflag;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1;
}

void reset_all_crc_flags(NFAPI_CRC_ARRAY *array) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        array->array[i].CRCFLAG = (rand_r((unsigned int*)&array->array[i]) & 1) ? 0 : 1;
    }

    pthread_mutex_unlock(&array->mutex);
}

int update_rx_ue_information_tag(NFAPI_CRC_ARRAY *array, uint32_t new_tag) {
    if (!array) return -1;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        array->array[i].RX_UE_INFORMATION_TAG = new_tag;
    }

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_crc_indication_rel8_tag(NFAPI_CRC_ARRAY *array, uint16_t rnti, uint8_t new_tag) {
