    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    int total_crc_indications;
} CRC_Indication_Manager;

void init_crc_manager(CRC_Indication_Manager *manager) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_STRUCTURES;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->total_crc_indications = 0;
}

void destroy_crc_manager(CRC_Indication_Manager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
}

int insert_crc_indication(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->array[manager->count++] = pdu;
    manager->total_crc_indications++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_crc_indication(CRC_Indication_Manager *manager, int index) {
    pthread_mutex_lock(&manager->mutex);
    if (index < 0 || index >= manager->count) {
        // Handle invalid index
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->count--;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void reset_total_crc_indications(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    manager->total_crc_indications = 0;
    pthread_mutex_unlock(&manager->mutex);
}

int get_total_crc_indications(const CRC_Indication_Manager *manager) {
    int total;
    pthread_mutex_lock(&manager->mutex);
    total = manager->total_crc_indications;
    pthread_mutex_unlock(&manager->mutex);
    return total;
