#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList *list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i - 1));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

int get_count(DynamicList *list) {
    int count;
    pthread_mutex_lock(&list->lock);
    count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

void serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    fclose(file);
}

void deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    int count = fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    list->count = count < MAX_ENTRIES ? count : MAX_ENTRIES;
    fclose(file);
}

void destroy_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
}
