int resolve_hostname(const char *hostname, struct in_addr *ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip->s_addr = ipv4->sin_addr.s_addr;
        break;
    }

    freeaddrinfo(res);
    return 0;
}

void initialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indicators, int N) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < N; i++) {
        indicators[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        indicators[i].RNTI = rand() % 65536;
        indicators[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        indicators[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *indicators = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indicators) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    initialize_crc_indications(indicators, N);

    struct in_addr ip;
    if (resolve_hostname("example.com", &ip)) {
        fprintf(stderr, "DNS resolution failed\n");
        free(indicators);
        return -1;
    }

    printf("IP address: %s\n", inet_ntoa(ip));

    free(indicators);
    return 0;
}
