void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}

void add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for dynamic array");
            pthread_mutex_unlock(&da->mutex);
            return;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
}

void garbage_collect(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    // Implement a strategy for garbage collection, e.g., time-based expiration or reference counting
    // For simplicity, let's assume we're using a time-based expiration
    time_t current_time = time(NULL);
    for (size_t i = 0; i < da->size; ) {
        if (da->array[i].crcflag == 0 && difftime(current_time, da->array[i].ue_info_tag.timestamp) > 60) { // Example: expire after 1 minute
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            da->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&da->mutex);
}

void* update_thread(void *arg) {
    DynamicArray *da = (DynamicArray *)arg;
    NFAPI_CRC_INDICATION_PDU_T item;
    // Populate item with valid data
    add_to_dynamic_array(da, item);
    return NULL;
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da, MAX_CONCURRENT_UPDATES);

    pthread_t threads[MAX_CONCURRENT_UPDATES];
    for (size_t i = 0; i < MAX_CONCURRENT_UPDATES; i++) {
        if (pthread_create(&threads[i], NULL, update_thread, &da) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < MAX_CONCURRENT_UPDATES; i++) {
        pthread_join(threads[i], NULL);
    }

    garbage_collect(&da);

    destroy_dynamic_array(&da);
    return 0;
}
