#include <pthread.h>
#include <stdlib.h>

typedef struct LTEPHYCONTEXT {
    int cellID;
    int slotOffset;
    // Other configuration parameters...
} LTEPHYCONTEXT;

typedef struct ListNode {
    LTEPHYCONTEXT data;
    struct ListNode* next;
} ListNode;

typedef struct {
    pthread_mutex_t lock;
    ListNode* head;
} LTEPHYCONFIG;

LTEPHYCONFIG* initLTEPHYCONFIG() {
    LTEPHYCONFIG* config = (LTEPHYCONFIG*)malloc(sizeof(LTEPHYCONFIG));
    if (config == NULL) return NULL;
    pthread_mutex_init(&config->lock, NULL);
    config->head = NULL;
    return config;
}

void addOrUpdateLTEPHYCONTEXT(LTEPHYCONFIG* config, int cellID, int slotOffset, LTEPHYCONTEXT newConfig) {
    pthread_mutex_lock(&config->lock);
    ListNode* current = config->head;
    while (current != NULL) {
        if (current->data.cellID == cellID && current->data.slotOffset == slotOffset) {
            // Update existing configuration
            current->data = newConfig;
            pthread_mutex_unlock(&config->lock);
            return;
        }
        current = current->next;
    }
    // Add new configuration
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&config->lock);
        return;
    }
    newNode->data = newConfig;
    newNode->next = config->head;
    config->head = newNode;
    pthread_mutex_unlock(&config->lock);
}

LTEPHYCONTEXT* getLTEPHYCONTEXT(LTEPHYCONFIG* config, int cellID, int slotOffset) {
    pthread_mutex_lock(&config->lock);
    ListNode* current = config->head;
    while (current != NULL) {
        if (current->data.cellID == cellID && current->data.slotOffset == slotOffset) {
            LTEPHYCONTEXT* result = (LTEPHYCONTEXT*)malloc(sizeof(LTEPHYCONTEXT));
            if (result != NULL) *result = current->data;
            pthread_mutex_unlock(&config->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&config->lock);
    return NULL;
}

void freeLTEPHYCONFIG(LTEPHYCONFIG* config) {
    pthread_mutex_lock(&config->lock);
    ListNode* current = config->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&config->lock);
    pthread_mutex_destroy(&config->lock);
    free(config);
}
