    int connection_count;
} DeviceProfile;

DeviceProfile profiles[MAX_PROFILES];
int profile_count = 0;

void init_profile(int device_id) {
    if (profile_count >= MAX_PROFILES) return;
    profiles[profile_count].device_id = device_id;
    profiles[profile_count].connection_count = 0;
    profile_count++;
}

void add_connection(int device_id, int connection_id, char *diagnostics) {
    for (int i = 0; i < profile_count; i++) {
        if (profiles[i].device_id == device_id) {
            if (profiles[i].connection_count >= MAX_CONNECTIONS) return;
            profiles[i].connections[profiles[i].connection_count].id = connection_id;
            profiles[i].connections[profiles[i].connection_count].diagnostics[0] = strdup(diagnostics);
            profiles[i].connection_count++;
            break;
        }
    }
}

void update_diagnostics(int device_id, int connection_id, char *new_diagnostics) {
    for (int i = 0; i < profile_count; i++) {
        if (profiles[i].device_id == device_id) {
            for (int j = 0; j < profiles[i].connection_count; j++) {
                if (profiles[i].connections[j].id == connection_id) {
                    free(profiles[i].connections[j].diagnostics[0]);
                    profiles[i].connections[j].diagnostics[0] = strdup(new_diagnostics);
                    break;
                }
            }
            break;
        }
    }
}

double average_latency() {
    int total_latency = 0;
    for (int i = 0; i < profile_count; i++) {
        for (int j = 0; j < profiles[i].connection_count; j++) {
            // Assuming latency is stored in diagnostics as a string and converted to integer
            total_latency += atoi(profiles[i].connections[j].diagnostics[0]);
        }
    }
    return profile_count > 0 ? (double)total_latency / (profile_count * profiles[i].connection_count) : 0;
}

int main() {
    init_profile(1);
    add_connection(1, 101, "Latency: 5ms");
    update_diagnostics(1, 101, "Latency: 7ms");

    printf("Average Latency: %.2f\n", average_latency());

    return 0;
}
