#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define MAX_OPS_PER_SEC 1000

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

int add_element(DynamicList *list, RX_UE_INFORMATION_TAG rx_ue_info, CRC_INDICATION_REL8_TAG crc_ind_rel8) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Resize the list
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity *= 2;
    }

    // Check for duplicate RNTI
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].rx_ue_info.RNTI == rx_ue_info.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI found
        }
    }

    // Add the new element
    list->elements[list->size++] = (NFAPI_CRC_INDICATION_PDU_T){rx_ue_info, crc_ind_rel8};
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return; // File opening failed
    }

    pthread_mutex_lock(&list->lock);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

int main() {
    DynamicList list;
    init_list(&list);

    // Example usage
    RX_UE_INFORMATION_TAG rx_ue_info = {12345};
    CRC_INDICATION_REL8_TAG crc_ind_rel8 = {rand() % 2}; // Randomly set CRCFLAG

    if (add_element(&list, rx_ue_info, crc_ind_rel8) == 0) {
        serialize_list(&list, "output.bin");
    }

    free_list(&list);
    return 0;
}
