#include <stdlib.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    size_t packet_size;
    uint32_t checksum;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    pm->count = 0;
    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->lock, NULL);
}

void destroy_packet_manager(PacketManager* pm) {
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
}

int add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count >= pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&pm->lock);
            return -1; // Memory allocation failed
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int update_packet(PacketManager* pm, time_t timestamp, DataPacket new_packet) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].timestamp == timestamp) {
            pm->packets[i] = new_packet;
            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // Packet not found
}

int get_packets_in_range(PacketManager* pm, time_t start_time, time_t end_time, DataPacket** packets, size_t* count) {
    pthread_mutex_lock(&pm->lock);
    *count = 0;
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].timestamp >= start_time && pm->packets[i].timestamp <= end_time) {
            (*count)++;
        }
    }
    *packets = realloc(*packets, *count * sizeof(DataPacket));
    for (size_t i = 0, j = 0; i < pm->count; ++i) {
        if (pm->packets[i].timestamp >= start_time && pm->packets[i].timestamp <= end_time) {
            (*packets)[j++] = pm->packets[i];
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return 0;
}
