        // Handle error
        return;
    }

    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
}

void deserialize_array(NFAPI_CRC_INDICATION_PDU_T **array, int *size, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fclose(file);

    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(file_size);
    if (*array == NULL) {
        // Handle error
        return;
    }

    FILE *file2 = fopen(filename, "rb");
    if (file2 == NULL) {
        // Handle error
        free(*array);
        return;
    }

    fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T), file2);
    fclose(file2);

    *size = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

