typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    time_t last_accessed;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY;

int init_crc_array(NFAPI_CRC_ARRAY *crc_array, size_t initial_capacity) {
    crc_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        perror("Failed to allocate memory for CRC array");
        return -1;
    }
    crc_array->size = 0;
    crc_array->capacity = initial_capacity;
    crc_array->last_accessed = time(NULL);
    pthread_mutex_init(&crc_array->lock, NULL);
    return 0;
}

void destroy_crc_array(NFAPI_CRC_ARRAY *crc_array) {
    free(crc_array->array);
    pthread_mutex_destroy(&crc_array->lock);
}

int add_to_crc_array(NFAPI_CRC_ARRAY *crc_array, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti) {
    pthread_mutex_lock(&crc_array->lock);
    if (crc_array->size >= crc_array->capacity) {
        // Implement LRU eviction policy here
        // For simplicity, we'll just free the array and allocate a new one
        destroy_crc_array(crc_array);
        int result = init_crc_array(crc_array, crc_array->capacity * 2);
        if (result != 0) {
            pthread_mutex_unlock(&crc_array->lock);
            return result;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T new_pdu = {ue_info, rnti};
    new_pdu.crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    crc_array->array[crc_array->size++] = new_pdu;
    crc_array->last_accessed = time(NULL);
    pthread_mutex_unlock(&crc_array->lock);
    return 0;
}

void purge_old_elements(NFAPI_CRC_ARRAY *crc_array, time_t max_age) {
    pthread_mutex_lock(&crc_array->lock);
    size_t i = 0;
    while (i < crc_array->size && difftime(time(NULL), crc_array->array[i].last_accessed) > max_age) {
        i++;
    }
    if (i > 0) {
        memmove(crc_array->array, crc_array->array + i, (crc_array->size - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crc_array->size -= i;
    }
    pthread_mutex_unlock(&crc_array->lock);
}
