#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int TransportChannelID;
    int TransmissionMode;
    int RACH_Config;
} LTE_PHY_TransportChannelInfo;

typedef struct {
    LTE_PHY_TransportChannelInfo *channels;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_PHY_TransportChannelManager;

LTE_PHY_TransportChannelManager* create_manager() {
    LTE_PHY_TransportChannelManager *manager = (LTE_PHY_TransportChannelManager*)malloc(sizeof(LTE_PHY_TransportChannelManager));
    manager->channels = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(LTE_PHY_TransportChannelManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->channels);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_channel(LTE_PHY_TransportChannelManager *manager, int id, int transmission_mode, int rach_config) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        LTE_PHY_TransportChannelInfo *new_channels = (LTE_PHY_TransportChannelInfo*)realloc(manager->channels, new_capacity * sizeof(LTE_PHY_TransportChannelInfo));
        if (!new_channels) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->channels = new_channels;
        manager->capacity = new_capacity;
    }
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->channels[i].TransportChannelID == id) {
            manager->channels[i].TransmissionMode = transmission_mode;
            manager->channels[i].RACH_Config = rach_config;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated existing entry
        }
    }
    manager->channels[manager->count].TransportChannelID = id;
    manager->channels[manager->count].TransmissionMode = transmission_mode;
    manager->channels[manager->count].RACH_Config = rach_config;
    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
    return 1; // Added new entry
}

void iterate_and_calculate(LTE_PHY_TransportChannelManager *manager, void (*callback)(int, int)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        callback(manager->channels[i].TransportChannelID, manager->channels[i].TransmissionMode);
    }
    pthread_mutex_unlock(&manager->lock);
}

void serialize_manager(LTE_PHY_TransportChannelManager *manager, FILE *file) {
    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(&manager->channels[i], sizeof(LTE_PHY_TransportChannelInfo), 1, file);
    }
    pthread_mutex_unlock(&manager->lock);
}

int deserialize_manager(LTE_PHY_TransportChannelManager *manager, FILE *file) {
    size_t count;
    if (fread(&count, sizeof(size_t), 1, file) != 1) {
        return -1; // Failed to read count
    }
    pthread_mutex_lock(&manager->lock);
    LTE_PHY_TransportChannelInfo *new_channels = (LTE_PHY_TransportChannelInfo*)realloc(manager->channels, count * sizeof(LTE_PHY_TransportChannelInfo));
    if (!new_channels) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    manager->channels = new_channels;
    manager->capacity = count;
    for (size_t i = 0; i < count; ++i) {
        if (fread(&manager->channels[i], sizeof(LTE_PHY_TransportChannelInfo), 1, file) != 1) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Failed to read channel data
        }
    }
    manager->count = count;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}
