NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t N, int log_errors) {
    if (N > MAX_STRUCTURES) {
        if (log_errors) {
            fprintf(stderr, "Error: Requested number of structures exceeds maximum limit.\n");
        }
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        if (log_errors) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
        }
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        array[i].RNTI = rand() % 4096; // Random RNTI within valid range
        array[i].CRC_INDICATION_REL8_TAG = (rand() & 1); // Random CRCFLAG
    }

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

// Example usage in a multi-threaded environment with synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* get_array(size_t N, int log_errors) {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(N, log_errors);
    pthread_mutex_unlock(&mutex);
    return array;
}

void release_array(NFAPI_CRC_INDICATION_PDU_T* array) {
