int load_profile(const char *profile_name, json_object **config) {
    // Load JSON configuration file
    FILE *file = fopen(profile_name, "r");
    if (!file) {
        perror("Failed to open profile file");
        return -1;
    }

    *config = json_tokener_parse_file(file);
    fclose(file);

    if (!*config || json_object_get_type(*config) != json_type_object) {
        fprintf(stderr, "Invalid JSON format in profile file\n");
        json_object_put(*config);
        return -1;
    }

    return 0;
}

int create_nfaapi_pdu_list(const char *profile_name, NFAPI_CRC_INDICATION_PDU_T **pdu_list, int *num_pdus) {
    json_object *config = NULL;
    if (load_profile(profile_name, &config) != 0) {
        fprintf(stderr, "Failed to load profile\n");
        return -1;
    }

    // Extract number of PDUs from configuration
    json_object *num_pdus_obj = json_object_object_get_ex(config, "num_pdus", num_pdus);
    if (!num_pdus_obj || json_object_get_type(num_pdus_obj) != json_type_int) {
        fprintf(stderr, "Invalid 'num_pdus' setting in profile\n");
        json_object_put(config);
        return -1;
    }
    *num_pdus = json_object_get_int(num_pdus_obj);

    // Allocate memory for PDU list
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(*num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_list) {
        perror("Failed to allocate memory for PDU list");
        json_object_put(config);
        return -1;
    }

    // Populate PDU list with random data
    srand(time(NULL));
    for (int i = 0; i < *num_pdus; i++) {
        (*pdu_list)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pdu_list)[i].RNTI = rand() % 1000;
        (*pdu_list)[i].CRCFLAG = rand() % 2;
    }

    json_object_put(config);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <profile_name>\n", argv[0]);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int num_pdus;

    if (create_nfaapi_pdu_list(argv[1], &pdu_list, &num_pdus) != 0) {
        fprintf(stderr, "Failed to create PDU list\n");
        return -1;
    }

    // Process PDU list...

    free(pdu_list);
    return 0;
}
