    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} DL_RB_Pool;

DL_RB_Pool* create_dl_rb_pool(size_t initial_size) {
    DL_RB_Pool *pool = (DL_RB_Pool*)malloc(sizeof(DL_RB_Pool));
    if (!pool) return NULL;

    pool->pool = (DL_RB_Info*)calloc(initial_size, sizeof(DL_RB_Info));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_dl_rb_pool(DL_RB_Pool *pool) {
    if (pool) {
        free(pool->pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_dl_rb_info(DL_RB_Pool *pool, int DL_RESOURCE_BLOCK_ASSIGNMENT, int indicator_flag) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_count >= pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        DL_RB_Info *new_pool = (DL_RB_Info*)realloc(pool->pool, new_size * sizeof(DL_RB_Info));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }

        pool->pool = new_pool;
        pool->pool_size = new_size;
    }

    pool->pool[pool->used_count].DL_RESOURCE_BLOCK_ASSIGNMENT = DL_RESOURCE_BLOCK_ASSIGNMENT;
    pool->pool[pool->used_count].indicator_flag = indicator_flag;
    pool->used_count++;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int update_dl_rb_info(DL_RB_Pool *pool, int index, int DL_RESOURCE_BLOCK_ASSIGNMENT, int indicator_flag) {
    if (index < 0 || index >= pool->used_count) return -1; // Invalid index

    pthread_mutex_lock(&pool->lock);

    pool->pool[index].DL_RESOURCE_BLOCK_ASSIGNMENT = DL_RESOURCE_BLOCK_ASSIGNMENT;
    pool->pool[index].indicator_flag = indicator_flag;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int get_dl_rb_info(DL_RB_Pool *pool, int index, int *DL_RESOURCE_BLOCK_ASSIGNMENT, int *indicator_flag) {
    if (index < 0 || index >= pool->used_count) return -1; // Invalid index

    pthread_mutex_lock(&pool->lock);

    *DL_RESOURCE_BLOCK_ASSIGNMENT = pool->pool[index].DL_RESOURCE_BLOCK_ASSIGNMENT;
    *indicator_flag = pool->pool[index].indicator_flag;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
