    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DL_RB_Info* new_array = (DL_RB_Info*)realloc(manager->rb_array, new_capacity * sizeof(DL_RB_Info));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        manager->rb_array = new_array;
        manager->capacity = new_capacity;
    }

    manager->rb_array[manager->size].DL_RESOURCE_BLOCK_ASSIGNMENT = DL_RESOURCE_BLOCK_ASSIGNMENT;
    manager->rb_array[manager->size].indicator_flag = indicator_flag;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool update_dl_rb_info(DL_RB_Manager* manager, size_t index, int DL_RESOURCE_BLOCK_ASSIGNMENT, bool indicator_flag) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    manager->rb_array[index].DL_RESOURCE_BLOCK_ASSIGNMENT = DL_RESOURCE_BLOCK_ASSIGNMENT;
    manager->rb_array[index].indicator_flag = indicator_flag;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool delete_dl_rb_info(DL_RB_Manager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    for (size_t i = index; i < manager->size - 1; i++) {
        manager->rb_array[i] = manager->rb_array[i + 1];
    }
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool exists_dl_rb_info(DL_RB_Manager* manager, int DL_RESOURCE_BLOCK_ASSIGNMENT) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; i++) {
        if (manager->rb_array[i].DL_RESOURCE_BLOCK_ASSIGNMENT == DL_RESOURCE_BLOCK_ASSIGNMENT) {
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return false;
}

void get_stats(DL_RB_Manager* manager, size_t* total_count, size_t* valid_count) {
    pthread_mutex_lock(&manager->lock);

    *total_count = manager->size;
    *valid_count = 0;
    for (size_t i = 0; i < manager->size; i++) {
        if (manager->rb_array[i].indicator_flag) (*valid_count)++;
    }

    pthread_mutex_unlock(&manager->lock);
}

