void init_dl_rb_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

DL_RB_Indicator* allocate_dl_rb_indicator(int dl_rb_allocation) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size < pool_capacity) {
        DL_RB_Indicator *indicator = malloc(sizeof(DL_RB_Indicator));
        if (indicator != NULL) {
            indicator->dl_rb_allocation = dl_rb_allocation;
            indicator->active_flag = 0;
            dl_rb_pool[pool_size++] = indicator;
        }
    } else {
        printf("Memory pool is full\n");
    }
    pthread_mutex_unlock(&pool_lock);
    return dl_rb_pool[pool_size - 1];
}

void update_dl_rb_indicator(int index, int dl_rb_allocation) {
    if (index >= 0 && index < pool_size) {
        pthread_mutex_lock(&pool_lock);
        dl_rb_pool[index]->dl_rb_allocation = dl_rb_allocation;
        pthread_mutex_unlock(&pool_lock);
    } else {
        printf("Invalid index\n");
    }
}

