NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* initialize_pdus(int N, int M, int L) {
    if (N * M > L) {
        return NULL; // Exceeds the specified limit
    }

    NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* pdus = (NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T*)malloc(N * sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T));
    if (!pdus) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        pdus[i].tag.value = rand() % 1000; // Random tag value
        pdus[i].num_uecfg_tags = 0;

        while (pdus[i].num_uecfg_tags < M) {
            int new_UE_ID = rand() % 1000;
            int is_duplicate = 0;

            for (int j = 0; j < pdus[i].num_uecfg_tags; ++j) {
                if (pdus[i].uecfg_tags[j].UE_ID == new_UE_ID) {
                    is_duplicate = 1;
                    break;
