#include <stdlib.h>
#include <pthread.h>

typedef struct {
    PHY_RX_FRAME_INFO_TAG frame_info;
    RX_POWER_LEVEL power_level;
} LTE_PHY_RX_BUFFER;

typedef struct {
    LTE_PHY_RX_BUFFER* buffer;
    size_t capacity;
    size_t used_slots;
    pthread_mutex_t lock;
} LTE_PHY_RX_QUEUE;

LTE_PHY_RX_QUEUE* create_queue(size_t initial_capacity, size_t max_overflows) {
    LTE_PHY_RX_QUEUE* queue = (LTE_PHY_RX_QUEUE*)malloc(sizeof(LTE_PHY_RX_QUEUE));
    queue->buffer = (LTE_PHY_RX_BUFFER*)calloc(initial_capacity, sizeof(LTE_PHY_RX_BUFFER));
    queue->capacity = initial_capacity;
    queue->used_slots = 0;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void destroy_queue(LTE_PHY_RX_QUEUE* queue) {
    free(queue->buffer);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int enqueue(LTE_PHY_RX_QUEUE* queue, LTE_PHY_RX_BUFFER item) {
    pthread_mutex_lock(&queue->lock);
    if (queue->used_slots >= queue->capacity) {
        // Handle overflow
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    queue->buffer[queue->used_slots++] = item;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(LTE_PHY_RX_QUEUE* queue, LTE_PHY_RX_BUFFER* item) {
    pthread_mutex_lock(&queue->lock);
    if (queue->used_slots == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    *item = queue->buffer[--queue->used_slots];
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

size_t get_used_slots(LTE_PHY_RX_QUEUE* queue) {
    pthread_mutex_lock(&queue->lock);
    size_t used = queue->used_slots;
    pthread_mutex_unlock(&queue->lock);
    return used;
}
