#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_PROFILES 100
#define MAX_THREADS 10

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} ProfileData;

typedef struct {
    json_object *config;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager config_manager[MAX_PROFILES];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

int load_profile(const char *profile_name, ProfileData *data) {
    // Load and parse JSON configuration
    json_object *profile_json = json_tokener_parse_file(profile_name);
    if (!profile_json) {
        fprintf(stderr, "Failed to parse JSON file: %s\n", profile_name);
        return -1;
    }

    // Validate JSON schema (not shown here)
    // ...

    // Extract data from JSON
    json_object *ue_info_tag_obj = NULL;
    json_object *rnti_obj = NULL;
    json_object *crcflag_obj = NULL;

    if (!json_object_object_get_ex(profile_json, "UE_INFO_TAG", &ue_info_tag_obj) ||
        !json_object_object_get_ex(profile_json, "RNTI", &rnti_obj) ||
        !json_object_object_get_ex(profile_json, "CRCFLAG", &crcflag_obj)) {
        fprintf(stderr, "Missing required fields in JSON file: %s\n", profile_name);
        json_object_put(profile_json);
        return -1;
    }

    // Convert JSON values to C data types
    data->ue_info_tag = (RX_UE_INFORMATION_TAG)json_object_get_int(ue_info_tag_obj);
    data->pdu.RNTI = json_object_get_int(rnti_obj);
    data->pdu.CRCFLAG = json_object_get_int(crcflag_obj);

    // Free JSON object
    json_object_put(profile_json);

    return 0;
}

void *process_profile(void *arg) {
    int profile_index = *(int *)arg;
    ProfileData data;

    pthread_mutex_lock(&global_lock);
    if (config_manager[profile_index].config == NULL) {
        pthread_mutex_unlock(&global_lock);
        fprintf(stderr, "Profile %d not loaded\n", profile_index);
        return NULL;
    }

    int result = load_profile("profile%d.json", &data);
    pthread_mutex_unlock(&global_lock);

    if (result != 0) {
        fprintf(stderr, "Failed to process profile %d\n", profile_index);
        return NULL;
    }

    // Process data
    // ...

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <profile1> [<profile2> ...]\n", argv[0]);
        return -1;
    }

    int num_profiles = argc - 1;

    // Initialize config manager
    for (int i = 0; i < MAX_PROFILES; i++) {
        pthread_mutex_init(&config_manager[i].lock, NULL);
        config_manager[i].config = NULL;
    }

    // Load profiles concurrently
    pthread_t threads[MAX_THREADS];
    int thread_args[MAX_THREADS];

    for (int i = 0; i < num_profiles; i++) {
        if (i >= MAX_THREADS) {
            fprintf(stderr, "Too many profiles for concurrent processing\n");
            return -1;
        }

        thread_args[i] = i;
        pthread_create(&threads[i], NULL, process_profile, &thread_args[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_profiles; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
