typedef struct {
    int cell_id;
    int frequency_band;
    int power_level;
} CellConfig;

typedef struct {
    CellConfig *configs[MAX_CELL_ID];
    pthread_mutex_t lock;
} ConfigManager;

void init_config_manager(ConfigManager *manager) {
    for (int i = 0; i < MAX_CELL_ID; i++) {
        manager->configs[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

int add_cell_config(ConfigManager *manager, int cell_id, int frequency_band, int power_level) {
    pthread_mutex_lock(&manager->lock);
    if (cell_id < 0 || cell_id >= MAX_CELL_ID) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid cell ID
    }
    if (frequency_band < MIN_FREQUENCY_BAND || frequency_band > MAX_FREQUENCY_BAND) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Invalid frequency band
    }
    if (power_level < MIN_POWER_LEVEL || power_level > MAX_POWER_LEVEL) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Invalid power level
    }
    if (manager->configs[cell_id] != NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -4; // Cell ID already in use
    }
    manager->configs[cell_id] = (CellConfig *)malloc(sizeof(CellConfig));
    if (manager->configs[cell_id] == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -5; // Memory allocation failed
    }
    manager->configs[cell_id]->cell_id = cell_id;
    manager->configs[cell_id]->frequency_band = frequency_band;
    manager->configs[cell_id]->power_level = power_level;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int update_cell_config(ConfigManager *manager, int cell_id, int frequency_band, int power_level) {
    pthread_mutex_lock(&manager->lock);
    if (cell_id < 0 || cell_id >= MAX_CELL_ID) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid cell ID
    }
    if (frequency_band < MIN_FREQUENCY_BAND || frequency_band > MAX_FREQUENCY_BAND) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Invalid frequency band
    }
    if (power_level < MIN_POWER_LEVEL || power_level > MAX_POWER_LEVEL) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Invalid power level
    }
    if (manager->configs[cell_id] == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -4; // Cell ID not found
    }
    manager->configs[cell_id]->frequency_band = frequency_band;
    manager->configs[cell_id]->power_level = power_level;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

CellConfig *get_cell_config(ConfigManager *manager, int cell_id) {
    pthread_mutex_lock(&manager->lock);
    if (cell_id < 0 || cell_id >= MAX_CELL_ID) {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // Invalid cell ID
    }
    CellConfig *config = manager->configs[cell_id];
    pthread_mutex_unlock(&manager->lock);
    return config;
}

void free_config_manager(ConfigManager *manager) {
    for (int i = 0; i < MAX_CELL_ID; i++) {
        if (manager->configs[i] != NULL) {
            free(manager->configs[i]);
        }
    }
    pthread_mutex_destroy(&manager->lock);
}
