#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crc_list[MAX_ELEMENTS];
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int stop_generation = 0;

void* generate_crc_elements(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (list_size >= MAX_ELEMENTS || stop_generation) {
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        new_element->RX_UE_INFORMATION_TAG = rand() % 100;
        new_element->RNTI = rand() % 1000;
        new_element->CRC_INDICATION_REL8_TAG = rand() % 2;
        crc_list[list_size++] = new_element;
        pthread_mutex_unlock(&mutex);
        if (rand() % 10 < 5) { // 50% chance to stop
            stop_generation = 1;
            break;
        }
    }
    return NULL;
}

void* cooldown_period(void* arg) {
    sleep(9);
    pthread_mutex_lock(&mutex);
    stop_generation = 1;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main(int argc, char *argv[]) {
    srand(time(NULL));
    pthread_t generate_thread, cooldown_thread;

    if (pthread_create(&generate_thread, NULL, generate_crc_elements, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(1);
    }

    if (pthread_create(&cooldown_thread, NULL, cooldown_period, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(1);
    }

    pthread_join(generate_thread, NULL);
    pthread_join(cooldown_thread, NULL);

    for (int i = 0; i < list_size; i++) {
        free(crc_list[i]);
    }

    return 0;
}
