#define NFAPI_UL_FRAME_T_SIZE 1024
#define MAX_UE_INFO 100

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication[MAX_UE_INFO];
} NFAPI_UL_FRAME_T;

typedef struct {
    NFAPI_UL_FRAME_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t pool_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = (NFAPI_UL_FRAME_T*)calloc(pool_size, sizeof(NFAPI_UL_FRAME_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->pool_size = pool_size;
    mp->used_count = 0;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        pthread_mutex_destroy(&mp->lock);
        free(mp->pool);
        free(mp);
    }
}

NFAPI_UL_FRAME_T* allocate_frame(MemoryPool *mp) {
    NFAPI_UL_FRAME_T *frame = NULL;

    pthread_mutex_lock(&mp->lock);
    if (mp->used_count < mp->pool_size) {
        frame = &mp->pool[mp->used_count++];
    }
    pthread_mutex_unlock(&mp->lock);

    return frame;
}

void deallocate_frame(MemoryPool *mp, NFAPI_UL_FRAME_T *frame) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->pool_size; ++i) {
        if (&mp->pool[i] == frame) {
            mp->used_count--;
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

void initialize_and_populate_frames(MemoryPool *mp, size_t num_frames) {
    for (size_t i = 0; i < num_frames; ++i) {
        NFAPI_UL_FRAME_T *frame = allocate_frame(mp);
        if (!frame) {
            // Handle allocation failure
            continue;
        }

        frame->RX_UE_INFORMATION_TAG = rand() % 1000;
        frame->RNTI = rand() % 65536;

