#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int network_id;
    int signal_strength;
    int *ue_ids;
    int ue_count;
} NetworkStats;

typedef struct Node {
    NetworkStats data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} NetworkList;

void initNetworkList(NetworkList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addOrUpdateRecord(NetworkList *list, NetworkStats new_record) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->data.network_id == new_record.network_id && current->data.timestamp == new_record.timestamp) {
            // Update existing record
            free(current->data.ue_ids);
            current->data = new_record;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
    // Add new record
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = new_record;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void cleanupOldRecords(NetworkList *list, time_t retention_period) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    Node *prev = NULL;
    while (current != NULL) {
        if (time(NULL) - current->data.timestamp > retention_period) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data.ue_ids);
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void *batchProcessingThread(void *arg) {
    NetworkList *list = (NetworkList *)arg;
    // Perform batch processing here
    return NULL;
}

int main() {
    NetworkList network_list;
    initNetworkList(&network_list);

    // Example usage
    NetworkStats new_record = {time(NULL), 123, -50, (int[]){1, 2, 3}, 3};
    addOrUpdateRecord(&network_list, new_record);
    cleanupOldRecords(&network_list, 86400); // Retention period of 1 day

    pthread_t batch_thread;
    pthread_create(&batch_thread, NULL, batchProcessingThread, &network_list);

    pthread_join(batch_thread, NULL);

    return 0;
}
