typedef struct LTE_DL_FRAMEINFO {
    // Define the structure fields as per requirements
} LTE_DL_FRAMEINFO;

typedef struct LTE_PHY_RX_FRAME_INFO {
    LTE_DL_FRAMEINFO dl_frameinfo;
    uint8_t* sync_buffer;
    size_t buffer_size;
} LTE_PHY_RX_FRAME_INFO;

typedef struct DynamicArray {
    LTE_PHY_RX_FRAME_INFO* frames;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->frames = (LTE_PHY_RX_FRAME_INFO*)calloc(initial_capacity, sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!array->frames) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->frames[i].sync_buffer);
    }
    free(array->frames);
    free(array);
}

int insert_frame(DynamicArray* array, LTE_PHY_RX_FRAME_INFO frame, size_t buffer_size) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_RX_FRAME_INFO* new_frames = (LTE_PHY_RX_FRAME_INFO*)realloc(array->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
        if (!new_frames) return -1;

        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    array->frames[array->size] = frame;
    array->frames[array->size].sync_buffer = (uint8_t*)malloc(buffer_size);
    if (!array->frames[array->size].sync_buffer) return -1;

    array->frames[array->size].buffer_size = buffer_size;
    ++array->size;

    return 0;
}

int remove_frame(DynamicArray* array, size_t index) {
    if (index >= array->size) return -1;

    free(array->frames[index].sync_buffer);

    for (size_t i = index; i < array->size - 1; ++i) {
        array->frames[i] = array->frames[i + 1];
    }

    --array->size;

    return 0;
}

LTE_PHY_RX_FRAME_INFO* get_frame(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;
    return &array->frames[index];
}
```

This code provides a basic implementation of a dynamic array to manage `LTE_PHY_RX_FRAME_INFO` structures. It includes functions for creating and destroying the dynamic array, inserting frames with associated synchronization buffers, removing frames, and retrieving frames by index. The implementation dynamically resizes the array when necessary and handles memory allocation and deallocation for each frame's synchronization buffer.

For a more advanced implementation, consider adding thread safety mechanisms if the array will be accessed from multiple threads simultaneously. Additionally, you may want to implement a mechanism for pre-allocating buffers of a fixed size to reduce the overhead of frequent allocations and deallocations during high-throughput scenarios."]

