void replace_placeholders(const char *kickstart_file, const char *new_line) {
    FILE *file = fopen(kickstart_file, "r+");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *content = (char*)malloc(file_size + 1);
    if (!content) {
        fclose(file);
        return;
    }

    fread(content, 1, file_size, file);
    content[file_size] = '\0';
    fclose(file);

    char *placeholder = strstr(content, "PLACEHOLDER");
    if (placeholder) {
        size_t new_line_len = strlen(new_line);
        memmove(placeholder + new_line_len, placeholder, strlen(placeholder));
        memcpy(placeholder, new_line, new_line_len);
    }

    file = fopen(kickstart_file, "w");
    if (file) {
        fwrite(content, 1, file_size, file);
        fclose(file);
    }
    free(content);
}

void append_encrypted_password(const char *kickstart_file, const char *password) {
    FILE *file = fopen(kickstart_file, "a");
    if (!file) return;
    fprintf(file, "%s\n", password);
    fclose(file);
}

int main() {
    DynamicArray *array = create_dynamic_array();
    if (!array) return -1;

    for (int i = 0; i < 5; i++) {
        add_ue_info(array, i, i * 2, i % 2);
    }

    update_measurements(array);

    replace_placeholders("kickstart.cfg", "new_line_content");
    append_encrypted_password("kickstart.cfg", "encrypted_password");

    destroy_dynamic_array(array);
    return 0;
}
