void init_rnti_hash_table() {
    for (int i = 0; i < MAX_RNTI; i++) {
        rnti_hash_table.data[i] = NULL;
    }
    pthread_mutex_init(&rnti_hash_table.lock, NULL);
}

int add_crc_indication_pdu(uint32_t RNTI, RX_UE_INFORMATION_TAG rx_ue_info_tag) {
