    SessionInfo **sessions;
    int count;
    pthread_mutex_t listLock;
} SessionList;

SessionList *createSessionList() {
    SessionList *list = (SessionList *)malloc(sizeof(SessionList));
    list->sessions = NULL;
    list->count = 0;
    pthread_mutex_init(&list->listLock, NULL);
    return list;
}

void destroySessionList(SessionList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->sessions[i]->userTags);
        free(list->sessions[i]);
    }
    free(list->sessions);
    pthread_mutex_destroy(&list->listLock);
    free(list);
}

SessionInfo *createSession(int sessionID, int connectionState) {
    SessionInfo *session = (SessionInfo *)malloc(sizeof(SessionInfo));
    session->sessionID = sessionID;
    session->connectionState = connectionState;
    session->userTags = NULL;
    session->tagCount = 0;
    pthread_mutex_init(&session->lock, NULL);
    return session;
}

void destroySession(SessionInfo *session) {
    free(session->userTags);
    pthread_mutex_destroy(&session->lock);
    free(session);
}

int addSessionTag(SessionInfo *session, int UID, int priority) {
    pthread_mutex_lock(&session->lock);
    for (int i = 0; i < session->tagCount; i++) {
        if (session->userTags[i].UID == UID) {
            pthread_mutex_unlock(&session->lock);
            return -1; // Duplicate UID
        }
    }
    UserTag *newTags = realloc(session->userTags, (session->tagCount + 1) * sizeof(UserTag));
    if (!newTags) {
        pthread_mutex_unlock(&session->lock);
        return -2; // Memory allocation failed
    }
    session->userTags = newTags;
    session->userTags[session->tagCount].UID = UID;
    session->userTags[session->tagCount].priority = priority;
    session->tagCount++;
    pthread_mutex_unlock(&session->lock);
    return 0; // Success
}

int addSessionToList(SessionList *list, SessionInfo *session) {
    pthread_mutex_lock(&list->listLock);
    for (int i = 0; i < list->count; i++) {
        if (list->sessions[i]->sessionID == session->sessionID) {
            pthread_mutex_unlock(&list->listLock);
            return -1; // Duplicate session ID
        }
    }
    SessionInfo **newSessions = realloc(list->sessions, (list->count + 1) * sizeof(SessionInfo *));
    if (!newSessions) {
        pthread_mutex_unlock(&list->listLock);
        return -2; // Memory allocation failed
    }
    list->sessions = newSessions;
    list->sessions[list->count] = session;
    list->count++;
    pthread_mutex_unlock(&list->listLock);
    return 0; // Success
}
