#define MAX_RNTI 10000

typedef struct {
    int RNTI;
    RX_UE_INFORMATION_TAG rx_tag;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_RNTI];
    int size;
} HashTable;

HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 0;
    for(int i = 0; i < MAX_RNTI; i++) {
        table->data[i] = NULL;
    }
    return table;
}

int hash_function(int RNTI) {
    return RNTI % MAX_RNTI;
}

int insert_hash_table(HashTable *table, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    int index = hash_function(pdu->RNTI);
    while(table->data[index] != NULL) {
        if(table->data[index]->RNTI == pdu->RNTI) {
            return -1; // Duplicate RNTI
        }
        index = (index + 1) % MAX_RNTI;
    }
    table->data[index] = pdu;
    table->size++;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* find_hash_table(HashTable *table, int RNTI) {
    int index = hash_function(RNTI);
    while(table->data[index] != NULL) {
        if(table->data[index]->RNTI == RNTI) {
            return table->data[index];
        }
        index = (index + 1) % MAX_RNTI;
    }
    return NULL;
}

void free_hash_table(HashTable *table) {
    for(int i = 0; i < MAX_RNTI; i++) {
        if(table->data[i] != NULL) {
            free(table->data[i]);
        }
    }
    free(table);
}
