NetworkEntityState* initializeNetworkEntities(Configuration config, int *numEntities) {
    if (config.maxEntities <= 0 || 
        config.minLatency < 0 || config.maxLatency < config.minLatency ||
        config.minThroughput < 0 || config.maxThroughput < config.minThroughput ||
        config.minPacketLossRate < 0 || config.maxPacketLossRate < config.minPacketLossRate) {
        *numEntities = 0;
        return NULL;
    }

    int maxAllowedEntities = config.maxEntities;
    NetworkEntityState* entities = (NetworkEntityState*)malloc(maxAllowedEntities * sizeof(NetworkEntityState));
    if (!entities) {
        *numEntities = 0;
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < maxAllowedEntities; ++i) {
        entities[i].entityId = i + 1;
        entities[i].status = (NetworkStatus)(rand() % 3);
        entities[i].connectionMetrics.latency = rand() % (config.maxLatency - config.minLatency + 1) + config.minLatency;
        entities[i].connectionMetrics.throughput = ((double)rand() / RAND_MAX) * (config.maxThroughput - config.minThroughput) + config.minThroughput;
        entities[i].connectionMetrics.packetLossRate = ((double)rand() / RAND_MAX) * (config.maxPacketLossRate - config.minPacketLossRate) + config.minPacketLossRate;
    }

    *numEntities = maxAllowedEntities;
    return entities;
