// Define TCP connection states
typedef enum {
    ESTABLISHED,
    CLOSE_WAIT,
    // Add other states as needed
} TcpState;

// Define packet metadata structure
typedef struct PacketMetadata {
    int segmentNumber;
    size_t dataSize;
    // Add other fields as needed
} PacketMetadata;

// Define custom data structure for TCP connection
typedef struct TcpConnection {
    int connectionID;
    char remoteIP[16];
    char localIP[16];
    int remotePort;
    int localPort;
    TcpState state;
    PacketMetadata *packetMetadata;
    size_t packetCount;
    // Add optional fields for advanced features as needed
} TcpConnection;

// Function to initialize a TCP connection
TcpConnection* initTcpConnection(int connectionID, const char *remoteIP, const char *localIP, int remotePort, int localPort) {
    if (connectionID < 0 || remoteIP == NULL || localIP == NULL || remotePort <= 0 || localPort <= 0) {
        return NULL; // Invalid input parameters
    }

    TcpConnection *conn = (TcpConnection *)malloc(sizeof(TcpConnection));
    if (conn == NULL) {
        return NULL; // Memory allocation failed
    }

    conn->connectionID = connectionID;
    strncpy(conn->remoteIP, remoteIP, sizeof(conn->remoteIP) - 1);
    strncpy(conn->localIP, localIP, sizeof(conn->localIP) - 1);
    conn->remotePort = remotePort;
    conn->localPort = localPort;
    conn->state = ESTABLISHED; // Default state
    conn->packetMetadata = NULL;
    conn->packetCount = 0;

    return conn;
}

// Function to add packet metadata to a TCP connection
int addPacketMetadata(TcpConnection *conn, int segmentNumber, size_t dataSize) {
    if (conn == NULL || segmentNumber < 0 || dataSize <= 0) {
        return -1; // Invalid input parameters
    }

    PacketMetadata *newMetadata = (PacketMetadata *)realloc(conn->packetMetadata, (conn->packetCount + 1) * sizeof(PacketMetadata));
    if (newMetadata == NULL) {
        return -1; // Memory allocation failed
    }

    conn->packetMetadata = newMetadata;
    conn->packetMetadata[conn->packetCount].segmentNumber = segmentNumber;
    conn->packetMetadata[conn->packetCount].dataSize = dataSize;
    conn->packetCount++;

    return 0; // Success
}

// Function to free a TCP connection and its resources
void freeTcpConnection(TcpConnection *conn) {
    if (conn == NULL) {
        return;
    }

    if (conn->packetMetadata != NULL) {
        free(conn->packetMetadata);
    }

    free(conn);
}
