#define MAX_ELEMENTS 10000

typedef struct {
    int RNTI;
    // Other fields of NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->count = 0;
    da->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    free(da);
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failure
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int update_element(DynamicArray *da, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].RNTI == RNTI) {
            da->array[i] = new_element;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // Element not found
}

int remove_element(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].RNTI == RNTI) {
            for (size_t j = i; j < da->count - 1; ++j) {
                da->array[j] = da->array[j + 1];
            }
            --da->count;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // Element not found
}

void clear_old_entries(DynamicArray *da, int max_age) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (/* condition to check if entry is old */) {
            for (size_t j = i; j < da->count - 1; ++j) {
                da->array[j] = da->array[j + 1];
            }
            --da->count;
            --i; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&da->lock);
}

int validate_RNTI(int RNTI, int min_RNTI, int max_RNTI) {
    return (RNTI >= min_RNTI && RNTI <= max_RNTI) ? 0 : -1;
}
