typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NL_DU_Entity {
    int MAC_Entity_ID;
    int sequence_number;
    int payload_length;
    unsigned char* payload;
    struct NL_DU_Entity* next;
} NL_DU_Entity;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** array;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

typedef struct {
    NL_DU_Entity* head;
    int count;
    pthread_mutex_t mutex;
} LinkedList;

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_NFAPI_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->size = 0;
    da->capacity = MAX_NFAPI_ELEMENTS;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    for (int i = 0; i < da->size; i++) {
        free(da->array[i]);
    }
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

LinkedList* create_linked_list() {
    LinkedList* ll = (LinkedList*)malloc(sizeof(LinkedList));
    if (!ll) return NULL;
    ll->head = NULL;
    ll->count = 0;
    pthread_mutex_init(&ll->mutex, NULL);
    return ll;
}

void destroy_linked_list(LinkedList* ll) {
    NL_DU_Entity* current = ll->head;
    while (current) {
        NL_DU_Entity* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&ll->mutex);
    free(ll);
}

void add_to_dynamic_array(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        // Resize array
        NFAPI_CRC_INDICATION_PDU_T** new_array = (NFAPI_CRC_INDICATION_PDU_T**)realloc(da->array, da->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return;
        }
        da->array = new_array;
        da->capacity *= 2;
    }
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->mutex);
}

void add_to_linked_list(LinkedList* ll, NL_DU_Entity* entity) {
    pthread_mutex_lock(&ll->mutex);
    if (ll->count >= MAX_NFAPI_ELEMENTS) {
        pthread_mutex_unlock(&ll->mutex);
        return; // Exceeds maximum size limit
    }
    entity->next = ll->head;
    ll->head = entity;
    ll->count++;
    pthread_mutex_unlock(&ll->mutex);
}

void remove_from_dynamic_array(DynamicArray* da, int index) {
    pthread_mutex_lock(&da->mutex);
    if (index < 0 || index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return;
    }
    free(da->array[index]);
    for (int i = index; i < da->size - 1; i++) {
        da->array[i] = da->array[i + 1];
    }
    da->size--;
    pthread_mutex_unlock(&da->mutex);
}

void remove_from_linked_list(LinkedList* ll, int mac_entity_id) {
    pthread_mutex_lock(&ll->mutex);
    NL_DU_Entity* current = ll->head;
    NL_DU_Entity* prev = NULL;
    while (current) {
        if (current->MAC_Entity_ID == mac_entity_id) {
            if (prev) {
                prev->next = current->next;
            } else {
                ll->head = current->next;
            }
            free(current->payload);
            free(current);
            ll->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&ll->mutex);
}

