#include <time.h>

#define MAX_ELEMENTS 10000
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 65535
#define TIMEOUT_SECONDS 600

typedef struct {
    int RNTI;
    // Other fields of NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
    time_t last_cleanup_time;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->last_cleanup_time = time(NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->elements[i]);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i]->RNTI == element->RNTI) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Duplicate RNTI
        }
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i]->RNTI == element->RNTI) {
            free(array->elements[i]);
            array->elements[i] = element;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Element not found
}

int remove_element(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i]->RNTI == RNTI) {
            free(array->elements[i]);
            for (size_t j = i; j < array->count - 1; ++j) {
                array->elements[j] = array->elements[j + 1];
            }
            --array->count;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Element not found
}

void cleanup_old_elements(DynamicArray *array) {
    time_t now = time(NULL);
    if (now - array->last_cleanup_time < TIMEOUT_SECONDS) return;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        // Check if element is older than 10 minutes
        if (time(NULL) - array->elements[i]->timestamp > TIMEOUT_SECONDS) {
            free(array->elements[i]);
            for (size_t j = i; j < array->count - 1; ++j) {
                array->elements[j] = array->elements[j + 1];
            }
            --array->count;
            --i; // Adjust index after removal
        }
    }
    array->last_cleanup_time = now;
    pthread_mutex_unlock(&array->lock);
}

void* update_thread(void *arg) {
    DynamicArray *array = (DynamicArray*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *new_element = read_from_external_source();
        if (!new_element) continue; // Handle unavailable data source
        cleanup_old_elements(array);
        add_element(array, new_element);
        sleep(1); // Simulate periodic updates
    }
    return NULL;
}

int main() {
    DynamicArray *array = create_dynamic_array();
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, update_thread, array);
    pthread_join(thread_id, NULL);
    destroy_dynamic_array(array);
    return 0;
}
