    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100000; // Example range
        (*array)[i].RNTI = generate_unique_rnti(existing_rntis, i);
        existing_rntis[i] = (*array)[i].RNTI;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Example range
