typedef struct {
    NFAPI_RX_FRAME_PDU_T frames[MAX_FRAMES];
    int frame_count;
    // Optional metadata
    unsigned long timestamp;
    int cell_identity;
} NFapiRxFrameSet;

NFapiRxFrameSet* initialize_and_populate_frames(int num_frames, int* ue_ids, void** rrc_requests, float (*srs_measurements)[10], unsigned long* timestamps, int* cell_identities) {
    if (num_frames > MAX_FRAMES) {
        return NULL; // Error: Exceeds maximum allowed frames
    }

    NFapiRxFrameSet* frame_set = (NFapiRxFrameSet*)malloc(sizeof(NFapiRxFrameSet));
    if (!frame_set) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_frames; ++i) {
        frame_set->frames[i].UE_ID = ue_ids[i];
        frame_set->frames[i].rrc_request = rrc_requests[i];

        if (srs_measurements) {
            memcpy(frame_set->frames[i].srs_measurements, srs_measurements[i], sizeof(float) * 10);
        } else {
            memset(frame_set->frames[i].srs_measurements, 0, sizeof(float) * 10); // Default to zero if not provided
        }

        if (timestamps && cell_identities) {
            frame_set->timestamp = timestamps[i];
            frame_set->cell_identity = cell_identities[i];
        } else {
            frame_set->timestamp = 0; // Default timestamp
            frame_set->cell_identity = -1; // Invalid cell identity
        }
    }

    frame_set->frame_count = num_frames;
    return frame_set;
}

// Example usage:
int main() {
    int ue_ids[] = {1, 2, 3};
    void* rrc_requests[3]; // Assume these are properly initialized RRC request pointers
    float srs_measurements[][10] = {{-5.6, -4.7, ...}, {-6.8, -5.9, ...}, {-7.0, -6.1, ...}};
    unsigned long timestamps[] = {1234567890, 1234567891, 1234567892};
    int cell_identities[] = {100, 101, 102};

    NFapiRxFrameSet* frame_set = initialize_and_populate_frames(3, ue_ids, rrc_requests, srs_measurements, timestamps, cell_identities);
    if (frame_set) {
        // Use the frame_set as needed
        free(frame_set); // Don't forget to free when done
    }

    return 0;
}
