#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CELLS 500

typedef struct LTE_ENB_STATEIE_T {
    int cellID;
    unsigned char *macBuffer;
    struct PUSCH_Symbol {
        int mcs;
        // Other PUSCH symbol fields
    } *puschSymbols;
    int numPuschSymbols;
} LTE_ENB_STATEIE_T;

typedef struct ListNode {
    LTE_ENB_STATEIE_T data;
    struct ListNode *next;
} ListNode;

typedef struct MemoryPool {
    void *pool;
    size_t blockSize;
    size_t poolSize;
    size_t freeCount;
} MemoryPool;

MemoryPool *createMemoryPool(size_t blockSize, size_t poolSize) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->blockSize = blockSize;
    pool->poolSize = poolSize;
    pool->freeCount = poolSize / blockSize;
    pool->pool = malloc(poolSize);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    return pool;
}

void *allocateFromPool(MemoryPool *pool) {
    if (pool->freeCount == 0) return NULL;
    void *block = ((char *)pool->pool) + (pool->poolSize - pool->freeCount * pool->blockSize);
    pool->freeCount--;
    return block;
}

void deallocateToPool(MemoryPool *pool, void *block) {
    size_t index = ((char *)block - (char *)pool->pool) / pool->blockSize;
    if (index >= pool->poolSize / pool->blockSize) return;
    pool->freeCount++;
}

ListNode *createNode(LTE_ENB_STATEIE_T data) {
    ListNode *node = (ListNode *)malloc(sizeof(ListNode));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void freeNode(ListNode *node) {
    free(node);
}

void initializeList(ListNode **head, MemoryPool *pool) {
    *head = NULL;
}

int addCellToList(ListNode **head, LTE_ENB_STATEIE_T data, MemoryPool *pool) {
    ListNode *newNode = createNode(data);
    if (!newNode) return -1;

    newNode->data.macBuffer = (unsigned char *)allocateFromPool(pool);
    if (!newNode->data.macBuffer) {
        freeNode(newNode);
        return -1;
    }

    newNode->data.puschSymbols = (struct PUSCH_Symbol *)allocateFromPool(pool);
    if (!newNode->data.puschSymbols) {
        free(newNode->data.macBuffer);
        freeNode(newNode);
        return -1;
    }

    newNode->next = *head;
    *head = newNode;

    return 0;
}

void removeCellFromList(ListNode **head, int cellID, MemoryPool *pool) {
    ListNode *current = *head;
    ListNode *previous = NULL;

    while (current != NULL && current->data.cellID != cellID) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->data.macBuffer);
    free(current->data.puschSymbols);
    deallocateToPool(pool, current->data.macBuffer);
    deallocateToPool(pool, current->data.puschSymbols);
    freeNode(current);
}

void destroyList(ListNode **head, MemoryPool *pool) {
    ListNode *current = *head;
    while (current != NULL) {
        removeCellFromList(head, current->data.cellID, pool);
        current = *head;
    }
}
