    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int n) {
    return (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 256;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void check_errors(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    int error_count = 0;
    for (int i = 0; i < n; i++) {
        if (list[i].CRC_INDICATION_REL8_TAG != 0 && list[i].CRC_INDICATION_REL8_TAG != 1) {
            printf("Error at index %d: Invalid CRC_INDICATION_REL8_TAG value\n", i);
            error_count++;
        }
    }
    if ((double)error_count / n > ERROR_THRESHOLD / 100.0) {
        printf("Too many errors detected (%d%%)\n", (int)((double)error_count / n * 100));
    }
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int n, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
    fclose(file);
}

int main() {
    int n = 1000; // Example size
    NFAPI_CRC_INDICATION_PDU_T* list = create_list(n);
    populate_list(list, n);
    check_errors(list, n);
    serialize_list(list, n, "crc_indication_pdu.bin");
    free(list);
    return 0;
}
