UeContextManager* createUeContextManager() {
    UeContextManager *manager = (UeContextManager*)malloc(sizeof(UeContextManager));
    manager->records = (UeContextInfo**)malloc(INITIAL_CAPACITY * sizeof(UeContextInfo*));
    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyUeContextManager(UeContextManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->rrcStateTransitions);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int insertUeContextInfo(UeContextManager *manager, int uei, int servingCellId, int rrcStateTransition) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->records = (UeContextInfo**)realloc(manager->records, manager->capacity * sizeof(UeContextInfo*));
    }
    UeContextInfo *newRecord = (UeContextInfo*)malloc(sizeof(UeContextInfo));
    newRecord->uei = uei;
    newRecord->servingCellId = servingCellId;
    newRecord->rrcStateTransitions = (int*)malloc(sizeof(int));
    newRecord->rrcStateTransitions[0] = rrcStateTransition;
    newRecord->rrcStateTransitionCount = 1;
    manager->records[manager->count++] = newRecord;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int deleteUeContextInfo(UeContextManager *manager, int uei) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]->uei == uei) {
            free(manager->records[i]->rrcStateTransitions);
            free(manager->records[i]);
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->records[j] = manager->records[j + 1];
            }
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

