#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct RRCMessage {
    int sequenceNumber;
    char *data;
    struct RRCMessage *next;
} RRCMessage;

typedef struct LTEUEContext {
    int UE_ID;
    RRCMessage *rrcMessages;
    pthread_mutex_t mutex;
} LTEUEContext;

LTEUEContext* createLTEUEContext(int UE_ID) {
    LTEUEContext *context = (LTEUEContext *)malloc(sizeof(LTEUEContext));
    context->UE_ID = UE_ID;
    context->rrcMessages = NULL;
    pthread_mutex_init(&context->mutex, NULL);
    return context;
}

void addRRCMessage(LTEUEContext *context, int sequenceNumber, char *data) {
    pthread_mutex_lock(&context->mutex);
    RRCMessage *newMessage = (RRCMessage *)malloc(sizeof(RRCMessage));
    newMessage->sequenceNumber = sequenceNumber;
    newMessage->data = data;
    newMessage->next = context->rrcMessages;
    context->rrcMessages = newMessage;
    pthread_mutex_unlock(&context->mutex);
}

void modifyRRCMessage(LTEUEContext *context, int sequenceNumber, char *newData) {
    pthread_mutex_lock(&context->mutex);
    RRCMessage *current = context->rrcMessages;
    while (current != NULL) {
        if (current->sequenceNumber == sequenceNumber) {
            current->data = newData;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&context->mutex);
}

void removeRRCMessage(LTEUEContext *context, int sequenceNumber) {
    pthread_mutex_lock(&context->mutex);
    RRCMessage *current = context->rrcMessages;
    RRCMessage *previous = NULL;
    while (current != NULL) {
        if (current->sequenceNumber == sequenceNumber) {
            if (previous == NULL) {
                context->rrcMessages = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&context->mutex);
}

void destroyLTEUEContext(LTEUEContext *context) {
    RRCMessage *current = context->rrcMessages;
    while (current != NULL) {
        RRCMessage *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&context->mutex);
    free(context);
}
