}

NetworkInterfaceConfig* initializeNetworkInterfaces(int numInterfaces, int *interfaceIds, TrafficFlowTemplate **templates, int *numTemplatesPerInterface, int defaultQosProfile) {
    NetworkInterfaceConfig *configs = (NetworkInterfaceConfig*)malloc(numInterfaces * sizeof(NetworkInterfaceConfig));
    if (!configs) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < numInterfaces; i++) {
        configs[i].interfaceId = interfaceIds[i];
        configs[i].numTemplates = numTemplatesPerInterface[i];
        configs[i].templates = (TrafficFlowTemplate*)malloc(configs[i].numTemplates * sizeof(TrafficFlowTemplate));
        if (!configs[i].templates) {
            fprintf(stderr, "Memory allocation failed for interface %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(configs[j].templates);
            }
            free(configs);
            return NULL;
        }

        memcpy(configs[i].templates, templates[i], configs[i].numTemplates * sizeof(TrafficFlowTemplate));

        if (!validateQoSProfile(defaultQosProfile)) {
            fprintf(stderr, "Invalid QoS profile %d\n", defaultQosProfile);
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) {
                free(configs[j].templates);
            }
            free(configs);
            return NULL;
        }

        configs[i].defaultQosProfile = defaultQosProfile;
    }

    return configs;
}

// Example usage
int main() {
    int interfaceIds[] = {1, 2, 3};
    TrafficFlowTemplate templates[][3] = {
        {{10}, {11}, {12}},
        {{20}, {21}},
        {{30}}
    };
    int numTemplatesPerInterface[] = {3, 2, 1};
    int defaultQosProfile = 1;

    NetworkInterfaceConfig *configs = initializeNetworkInterfaces(3, interfaceIds, templates, numTemplatesPerInterface, defaultQosProfile);
    if (configs) {
        // Use the configs array
        for (int i = 0; i < 3; i++) {
            free(configs[i].templates);
        }
        free(configs);
    }

    return 0;
}
