typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct hash_entry {
    int key; // RNTI
    NFAPI_CRC_INDICATION_PDU_T value;
    struct hash_entry *next;
} HashEntry;

typedef struct {
    HashEntry **buckets;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->buckets = (HashEntry**)calloc(size, sizeof(HashEntry*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void insert_into_hash_table(HashTable *ht, NFAPI_CRC_INDICATION_PDU_T pdu) {
    int key = pdu.RNTI % ht->size;
    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->key = key;
    entry->value = pdu;
    entry->next = ht->buckets[key];
    ht->buckets[key] = entry;
}

NFAPI_CRC_INDICATION_PDU_T* find_in_hash_table(HashTable *ht, int rnti) {
    int key = rnti % ht->size;
    HashEntry *entry = ht->buckets[key];
    while (entry != NULL) {
        if (entry->key == key && entry->value.RNTI == rnti) {
            return &entry->value;
        }
        entry = entry->next;
    }
    return NULL;
}

void free_hash_table(HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        HashEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            HashEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}

