#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_INTERFACES 100
#define IP_RANGE_START "192.168.1.1"
#define IP_RANGE_END "192.168.1.254"

typedef struct {
    char ip_address[INET_ADDRSTRLEN];
    char subnet_mask[INET_ADDRSTRLEN];
    char mac_address[18];
    uint32_t mtu;
} NFAPI_CONFIG_PDU_T;

NFAPI_CONFIG_PDU_T interfaces[MAX_INTERFACES];
int interface_count = 0;

void log_message(const char* message) {
    printf("%s\n", message);
}

int is_ip_in_range(const char* ip, const char* start, const char* end) {
    struct in_addr addr, start_addr, end_addr;
    inet_pton(AF_INET, ip, &addr);
    inet_pton(AF_INET, start, &start_addr);
    inet_pton(AF_INET, end, &end_addr);

    return (ntohl(addr.s_addr) >= ntohl(start_addr.s_addr) && ntohl(addr.s_addr) <= ntohl(end_addr.s_addr));
}

void calculate_default_gateway(char* ip_address, char* subnet_mask, char* gateway) {
    struct in_addr addr, mask, network;
    inet_pton(AF_INET, ip_address, &addr);
    inet_pton(AF_INET, subnet_mask, &mask);

    network.s_addr = addr.s_addr & mask.s_addr;

    inet_ntop(AF_INET, &network, gateway, INET_ADDRSTRLEN);
}

int validate_and_populate_config(const char* config_data) {
    NFAPI_CONFIG_PDU_T new_interface;
    if (sscanf(config_data, "%s %s %s %u", new_interface.ip_address, new_interface.subnet_mask, new_interface.mac_address, &new_interface.mtu) != 4) {
        log_message("Invalid configuration format");
        return -1;
    }

    if (!is_ip_in_range(new_interface.ip_address, IP_RANGE_START, IP_RANGE_END)) {
        log_message("IP address out of range");
        return -1;
    }

    for (int i = 0; i < interface_count; i++) {
        if (strcmp(interfaces[i].ip_address, new_interface.ip_address) == 0) {
            log_message("Duplicate IP address");
            return -1;
        }
    }

    calculate_default_gateway(new_interface.ip_address, new_interface.subnet_mask, interfaces[interface_count].gateway);
    memcpy(&interfaces[interface_count], &new_interface, sizeof(NFAPI_CONFIG_PDU_T));
    interface_count++;
    return 0;
}

void find_highest_mtu() {
    uint32_t max_mtu = 0;
    int index = -1;

    for (int i = 0; i < interface_count; i++) {
        if (interfaces[i].mtu > max_mtu) {
            max_mtu = interfaces[i].mtu;
            index = i;
        }
    }

    if (index != -1) {
        printf("Interface with highest MTU: %s\n", interfaces[index].ip_address);
    } else {
        log_message("No interfaces found");
    }
}

int main() {
    // Simulate reading and validating configurations
    const char* config_data[] = {
        "192.168.1.2 255.255.255.0 00:1A:2B:3C:4D:5E 1500",
        "192.168.1.3 255.255.255.0 00:1A:2B:3C:4D:5F 1400"
    };

    for (int i = 0; i < sizeof(config_data) / sizeof(config_data[0]); i++) {
        if (validate_and_populate_config(config_data[i]) != 0) {
            return -1;
        }
    }

    find_highest_mtu();
    return 0;
}
