    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item, int seed) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity * MEMORY_THRESHOLD) {
        list->capacity *= 2;
        list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    item.CRCFLAG = (seed + list->size) % 2; // Simple CRC flag based on seed and size
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

