int initialize_interfaces(int N, int max_size, char **error_message, Interface **interfaces) {
    srand(time(NULL));
    *interfaces = (Interface *)malloc(N * sizeof(Interface));
    if (*interfaces == NULL) {
        *error_message = "Memory allocation failed";
        return -1;
    }

    int total_buffer_size = 0;
    for (int i = 0; i < N; i++) {
        int buffer_size = rand() % max_size + 1; // Random buffer size within the limit
        (*interfaces)[i].buffer_size = buffer_size;
        (*interfaces)[i].packet_buffer = (char *)malloc(buffer_size);
        if ((*interfaces)[i].packet_buffer == NULL) {
            *error_message = "Memory allocation failed for packet buffer";
            free(*interfaces);
            return -1;
        }
        total_buffer_size += buffer_size;

        // Initialize other fields
        (*interfaces)[i].interface_id = i + 1;
        (*interfaces)[i].reference_count = 0;
        (*interfaces)[i].RX_UE_INFORMATION_TAG = rand() % 256; // Random tag value
        (*interfaces)[i].RNTI = rand() % 65536; // Random RNTI value
        (*interfaces)[i].CRC_INDICATION_REL8_TAG = rand() % 4; // Random CRC flag within valid range

        if (total_buffer_size > max_size) {
            *error_message = "Buffer overflow";
            for (int j = 0; j <= i; j++) {
                free((*interfaces)[j].packet_buffer);
            }
            free(*interfaces);
            return -1;
        }
    }

    *error_message = NULL;
    return N;
}
