#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data, int position) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;

    if (position == 0 || list->head == NULL) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        for (int i = 1; i < position && current->next != NULL; i++) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Element removed successfully
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

Node* find_element(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return current; // Element found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Element not found
}

void clean_up_unused_entries(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (/* condition to determine if the entry is unused */) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next; // Continue with the next node
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}
