#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_BUNDLE_T;

NFAPI_CRC_BUNDLE_T* create_crc_bundle(size_t initial_capacity) {
    NFAPI_CRC_BUNDLE_T *bundle = (NFAPI_CRC_BUNDLE_T*)malloc(sizeof(NFAPI_CRC_BUNDLE_T));
    if (!bundle) return NULL;

    bundle->items = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!bundle->items) {
        free(bundle);
        return NULL;
    }

    bundle->count = 0;
    bundle->capacity = initial_capacity;
    pthread_mutex_init(&bundle->mutex, NULL);

    return bundle;
}

void destroy_crc_bundle(NFAPI_CRC_BUNDLE_T *bundle) {
    if (bundle) {
        free(bundle->items);
        pthread_mutex_destroy(&bundle->mutex);
        free(bundle);
    }
}

int add_crc_indication(NFAPI_CRC_BUNDLE_T *bundle, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&bundle->mutex);

    if (bundle->count >= bundle->capacity) {
        size_t new_capacity = bundle->capacity ? bundle->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T*)realloc(bundle->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) {
            pthread_mutex_unlock(&bundle->mutex);
            return -1; // Memory allocation failed
        }
        bundle->items = new_items;
        bundle->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *item = &bundle->items[bundle->count++];
    item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    item->RNTI = RNTI;
    item->CRCFLAG = (RNTI % 5 == 0) ? true : (RNTI % 7 == 0) ? false : rand() % 2;

    pthread_mutex_unlock(&bundle->mutex);
    return 0; // Success
}

int get_crc_indication_by_rnti(NFAPI_CRC_BUNDLE_T *bundle, int RNTI, NFAPI_CRC_INDICATION_PDU_T **item) {
    pthread_mutex_lock(&bundle->mutex);

    for (size_t i = 0; i < bundle->count; ++i) {
        if (bundle->items[i].RNTI == RNTI) {
            *item = &bundle->items[i];
            pthread_mutex_unlock(&bundle->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&bundle->mutex);
    return -1; // Item not found
}

int load_crc_bundle_from_file(const char *filename, NFAPI_CRC_BUNDLE_T **bundle) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // File open failed

    size_t initial_capacity = 10;
    *bundle = create_crc_bundle(initial_capacity);
    if (!*bundle) {
        fclose(file);
        return -1; // Memory allocation failed
    }

    int RX_UE_INFORMATION_TAG, RNTI;
    while (fscanf(file, "%d %d", &RX_UE_INFORMATION_TAG, &RNTI) == 2) {
        if (add_crc_indication(*bundle, RX_UE_INFORMATION_TAG, RNTI) != 0) {
            destroy_crc_bundle(*bundle);
            *bundle = NULL;
            fclose(file);
            return -1; // Failed to add item
        }
    }

    fclose(file);
    return (*bundle)->count; // Number of items in the bundle
}
