#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void reverseList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* prev = NULL;
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    list->head = prev;
    pthread_mutex_unlock(&list->lock);
}

Node* removeNode(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Node not found
    }
    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void mergeLists(LinkedList* dest, LinkedList* src) {
    pthread_mutex_lock(&dest->lock);
    pthread_mutex_lock(&src->lock);
    Node* current = src->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T data = current->data;
        insertNode(dest, data);
        current = current->next;
    }
    destroyList(src); // Assuming ownership transfer
    pthread_mutex_unlock(&src->lock);
    pthread_mutex_unlock(&dest->lock);
}

void cleanupUnusedNodes(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (/* condition to determine if node is unused */) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

