#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    bool memory_allocation_failed;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->memory_allocation_failed = false;
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (data.RNTI < 0 || data.RNTI > 65535) {
        fprintf(stderr, "Invalid RNTI value: %d\n", data.RNTI);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    if (data.CRC_INDICATION_REL8_TAG != 0 && data.CRC_INDICATION_REL8_TAG != 1) {
        fprintf(stderr, "Invalid CRCFLAG value: %d\n", data.CRC_INDICATION_REL8_TAG);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        list->memory_allocation_failed = true;
        pthread_mutex_unlock(&list->mutex);
        return -2;
    }

    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
