NFAPI_CRC_INDICATION_PDU_T *cache[MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)];
size_t cache_size = 0;

uint32_t generate_tag(uint32_t seed, size_t index) {
    return (seed + index) * 17; // Simple hash function
}

uint16_t calculate_rnti(uint32_t tag) {
    return (tag >> 16) & 0xFFFF; // Extract upper 16 bits as RNTI
}

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t tag, size_t index) {
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = calculate_rnti(tag);
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
}

size_t allocate_structures(size_t N, uint32_t seed) {
    size_t allocated_count = 0;
    pthread_mutex_lock(&allocation_lock);

    for (size_t i = 0; i < N && cache_size * sizeof(NFAPI_CRC_INDICATION_PDU_T) <= MAX_MEMORY; ++i) {
        if (cache_size >= MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            continue; // Memory allocation failed
        }

        uint32_t tag = generate_tag(seed, i);
        initialize_structure(pdu, tag, i);

        cache[cache_size++] = pdu;
        ++allocated_count;
    }

    pthread_mutex_unlock(&allocation_lock);
    return allocated_count;
}

void free_structures() {
    pthread_mutex_lock(&allocation_lock);

    for (size_t i = 0; i < cache_size; ++i) {
        free(cache[i]);
    }

    cache_size = 0;

    pthread_mutex_unlock(&allocation_lock);
}
