        }
        classifyNetworkType((*configArray)[i].entityID, (*configArray)[i].networkType);
        (*configArray)[i].configVersion = count + 1;
        count++;
    }

    pthread_mutex_unlock(&mutex);
    return count; // Return the count of successfully allocated structures
}

