#include <pthread.h>

typedef struct {
    int id;
    time_t timestamp;
    char *payload;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->packets = (DataPacket **)malloc(initial_capacity * sizeof(DataPacket *));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void free_packet_array(PacketArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->payload);
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

int add_packet(PacketArray *array, DataPacket *packet) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        DataPacket **new_packets = (DataPacket **)realloc(array->packets, new_capacity * sizeof(DataPacket *));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->count++] = packet;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_packet(PacketArray *array, int id, DataPacket *new_packet) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->id == id) {
            free(array->packets[i]->payload);
            array->packets[i] = new_packet;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Packet not found
}

int get_packets_by_timestamp_range(PacketArray *array, time_t start_time, time_t end_time, DataPacket ***result) {
    pthread_mutex_lock(&array->lock);
    size_t result_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->timestamp >= start_time && array->packets[i]->timestamp <= end_time) {
            result_count++;
        }
    }
    *result = (DataPacket **)malloc(result_count * sizeof(DataPacket *));
    size_t j = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->timestamp >= start_time && array->packets[i]->timestamp <= end_time) {
            (*result)[j++] = array->packets[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return result_count;
}
