#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* allocated_memory = NULL;
size_t allocated_count = 0;

uint32_t generate_unique_tag(uint32_t seed, size_t index) {
    return (seed * 1103515245 + index) % UINT32_MAX;
}

uint16_t calculate_rnti(uint32_t tag) {
    uint8_t hash[4];
    memcpy(hash, &tag, sizeof(tag));
    return ((hash[0] << 8) | hash[1]) & 0xFFFF;
}

int allocate_structures(size_t N, uint32_t seed) {
    pthread_mutex_lock(&allocation_lock);
    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (allocated_count + N > MAX_MEMORY_USAGE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&allocation_lock);
        return -1; // Memory limit exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T* new_memory = realloc(allocated_memory, allocated_count + N);
    if (!new_memory) {
        pthread_mutex_unlock(&allocation_lock);
        return -2; // Memory allocation failed
    }
    allocated_memory = new_memory;

    for (size_t i = 0; i < N; ++i) {
        size_t index = allocated_count + i;
        uint32_t tag = generate_unique_tag(seed, index);
        allocated_memory[index].RX_UE_INFORMATION_TAG = tag;
        allocated_memory[index].RNTI = calculate_rnti(tag);
        allocated_memory[index].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    allocated_count += N;
    pthread_mutex_unlock(&allocation_lock);
    return (int)N;
}

void free_allocated_memory() {
    pthread_mutex_lock(&allocation_lock);
    free(allocated_memory);
    allocated_memory = NULL;
    allocated_count = 0;
    pthread_mutex_unlock(&allocation_lock);
}
