typedef struct {
    EVP_CIPHER *cipher;
    pthread_mutex_t lock;
} CipherContext;

CipherContext* create_cipher_context(const char* algorithm) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    pthread_mutex_init(&ctx->lock, NULL);

    if (strcmp(algorithm, "AES-GCM") == 0) {
        ctx->cipher = EVP_aes_256_gcm();
    } else if (strcmp(algorithm, "CCM") == 0) {
        ctx->cipher = EVP_aes_128_ccm();
    } else if (strcmp(algorithm, "CBC") == 0) {
        ctx->cipher = EVP_aes_256_cbc();
    } else if (strcmp(algorithm, "ChaCha20-Poly1305") == 0) {
        ctx->cipher = EVP_chacha20_poly1305();
    } else {
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_cipher_context(CipherContext* ctx) {
    if (ctx) {
        pthread_mutex_destroy(&ctx->lock);
        EVP_CIPHER_free(ctx->cipher);
        free(ctx);
    }
}

int encrypt_data(CipherContext* ctx, const unsigned char* key, size_t key_len,
                 const unsigned char* iv, size_t iv_len,
                 const unsigned char* plaintext, size_t plaintext_len,
                 unsigned char* ciphertext, size_t *ciphertext_len,
                 const unsigned char* ad, size_t ad_len) {
    pthread_mutex_lock(&ctx->lock);
    int ret = EVP_EncryptInit_ex(ctx->cipher, NULL, NULL, key, iv);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (ad_len > 0) {
        ret = EVP_EncryptUpdate(ctx->cipher, NULL, NULL, ad, ad_len);
        if (ret != 1) {
            pthread_mutex_unlock(&ctx->lock);
            return -1;
        }
    }

    ret = EVP_EncryptUpdate(ctx->cipher, ciphertext, ciphertext_len, plaintext, plaintext_len);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    ret = EVP_EncryptFinal_ex(ctx->cipher, ciphertext + *ciphertext_len, ciphertext_len);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

int decrypt_data(CipherContext* ctx, const unsigned char* key, size_t key_len,
                 const unsigned char* iv, size_t iv_len,
                 const unsigned char* ciphertext, size_t ciphertext_len,
                 unsigned char* plaintext, size_t *plaintext_len,
                 const unsigned char* ad, size_t ad_len) {
    pthread_mutex_lock(&ctx->lock);
    int ret = EVP_DecryptInit_ex(ctx->cipher, NULL, NULL, key, iv);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    if (ad_len > 0) {
        ret = EVP_DecryptUpdate(ctx->cipher, NULL, NULL, ad, ad_len);
        if (ret != 1) {
            pthread_mutex_unlock(&ctx->lock);
            return -1;
        }
    }

    ret = EVP_DecryptUpdate(ctx->cipher, plaintext, plaintext_len, ciphertext, ciphertext_len);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    ret = EVP_DecryptFinal_ex(ctx->cipher, plaintext + *plaintext_len, plaintext_len);
    if (ret != 1) {
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }

    pthread_mutex_unlock(&ctx->lock);
    return 0;
}
