#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <string.h>

// Function to derive a key from a password using PBKDF2
int derive_key(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key, size_t key_len) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 10000, EVP_sha256(), key_len, key);
}

// Function to generate a nonce
int generate_nonce(unsigned char *nonce, size_t len) {
    return RAND_bytes(nonce, len);
}

// Function to encrypt data using AES-GCM
int encrypt_data(const unsigned char *key, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, unsigned char *tag, unsigned char *nonce) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, nonce)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    size_t tag_len = 16; // AES-GCM tag length
    if (1 != EVP_EncryptFinal_ex(ctx, NULL, &tag_len) || tag_len != 16) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    memcpy(tag, EVP_CIPHER_CTX_buf_noconst(ctx), tag_len);

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len + tag_len;
}

// Function to decrypt data using AES-GCM
int decrypt_data(const unsigned char *key, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext, unsigned char *tag, unsigned char *nonce) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, nonce)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    size_t tag_len = 16; // AES-GCM tag length
    memcpy(EVP_CIPHER_CTX_buf_noconst(ctx), tag, tag_len);

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptFinal_ex(ctx, NULL, &tag_len) || tag_len != 16) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to rotate keys securely
void rotate_keys(unsigned char *old_key, unsigned char *new_key, const char *password, const unsigned char *salt, size_t salt_len) {
    derive_key(password, salt, salt_len, new_key, 32); // AES-256 key length
}

// Example usage
int main() {
    unsigned char key[32], new_key[32];
    unsigned char nonce[12]; // AES-GCM nonce length
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[100], tag[16];

    derive_key("password", NULL, 0, key, 32);
    generate_nonce(nonce, 12);

    int encrypted_len = encrypt_data(key, plaintext, strlen((char *)plaintext), ciphertext, tag, nonce);
    if (encrypted_len < 0) {
        // Handle error
    }

    unsigned char decrypted_text[100];
    int decrypted_len = decrypt_data(key, ciphertext, encrypted_len - 16, decrypted_text, tag, nonce); // Subtract tag length
    if (decrypted_len < 0) {
        // Handle error
    }

    rotate_keys(key, new_key, "new_password", NULL, 0);

    return 0;
}
