typedef struct {
    int timestamp;
    char event_type[50];
    int source_id;
    char payload[256];
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager *manager = (EventManager*)malloc(sizeof(EventManager));
    manager->events = (NetworkEvent*)calloc(initial_capacity, sizeof(NetworkEvent));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager *manager) {
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_event(EventManager *manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkEvent *new_events = (NetworkEvent*)realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }
    manager->events[manager->size++] = event;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NetworkEvent* get_event_by_source(EventManager *manager, int source_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].source_id == source_id) {
            NetworkEvent *event = &manager->events[i];
            pthread_mutex_unlock(&manager->lock);
            return event;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int update_event_timestamp(EventManager *manager, int source_id, int new_timestamp) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].source_id == source_id) {
            manager->events[i].timestamp = new_timestamp;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Event not found
}
