#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    int key_length;
} CipherContext;

CipherContext* create_cipher_context(const char *mode, int key_length) {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->key_length = key_length;

    if (strcmp(mode, "DES_ECB") == 0) {
        ctx->cipher = EVP_des_ecb();
    } else if (strcmp(mode, "DES_EDE") == 0) {
        ctx->cipher = EVP_des_ede();
    } else if (strcmp(mode, "DES_EDE3") == 0) {
        ctx->cipher = EVP_des_ede3();
    } else if (strcmp(mode, "AES") == 0) {
        ctx->cipher = EVP_aes_256_cbc(); // Example: AES-256-CBC
    } else if (strcmp(mode, "CFB") == 0) {
        ctx->cipher = EVP_cfb128();
    } else {
        fprintf(stderr, "Unsupported cipher mode\n");
        free(ctx);
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(ctx);
        return NULL;
    }

    return ctx;
}

void initialize_cipher(CipherContext *ctx, const unsigned char *key, const unsigned char *iv) {
    if (EVP_EncryptInit_ex(ctx->ctx, ctx->cipher, NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        exit(EXIT_FAILURE);
    }
}

void encrypt_data(CipherContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        fprintf(stderr, "Encryption failed\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        exit(EXIT_FAILURE);
    }
    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len) != 1) {
        fprintf(stderr, "Final encryption failed\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        exit(EXIT_FAILURE);
    }

    ciphertext_len += len;
}

void decrypt_data(CipherContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    if (EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        fprintf(stderr, "Decryption failed\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        exit(EXIT_FAILURE);
    }
    int plaintext_len = len;

    if (EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len) != 1) {
        fprintf(stderr, "Final decryption failed\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        exit(EXIT_FAILURE);
    }

    plaintext_len += len;
}

void destroy_cipher_context(CipherContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```

