void encrypt(const CipherContext *ctx, const unsigned char *plaintext, unsigned char *ciphertext, size_t plaintext_len);
void decrypt(const CipherContext *ctx, const unsigned char *ciphertext, unsigned char *plaintext, size_t ciphertext_len);

// Example usage
int main() {
    CipherContext ctx;
    unsigned char key[] = "0123456789abcdef";
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    init_cipher_context(&ctx, ECB, PKCS7, key, 16);
    encrypt(&ctx, plaintext, ciphertext, strlen((char *)plaintext));
    decrypt(&ctx, ciphertext, decryptedtext, sizeof(decryptedtext));

    printf("Decrypted: %s\n", decryptedtext);

    return 0;
}
