    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        array[i].RNTI = rand() % 256; // Example range
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Example range
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
        array[i].timestamp = time(NULL); // Current timestamp
    }

    // Sort the array based on timestamp using a simple bubble sort for demonstration
    for (int i = 0; i < N - 1; ++i) {
        for (int j = 0; j < N - i - 1; ++j) {
            if (array[j].timestamp > array[j + 1].timestamp) {
                NFAPI_CRC_INDICATION_PDU_T temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }

    return array;
}

