    for key, value in env_config.items():
        subprocess.run(['sed', '-i', f's/{key}/{value}/g', file_path])

def thread_safe_file_operation(file_path, operation, *args):
    lock = threading.Lock()
    with lock:
        if operation == 'write':
            with open(file_path, 'w') as file:
                file.write(*args)
        elif operation == 'read':
            with open(file_path, 'r') as file:
                return file.read()

def exponential_backoff(func, *args, **kwargs):
    delay = 1
    while True:
        try:
            return func(*args, **kwargs)
        except Exception as e:
            time.sleep(delay)
            delay *= 2

