#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int size;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* createNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    node->prev = node->next = NULL;
    return node;
}

int insertNode(DoublyLinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "List is full\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(RX_UE_INFORMATION_TAG, RNTI);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (list->size == 0) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* findNode(DoublyLinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void printList(DoublyLinkedList* list, FILE* logFile) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        fprintf(logFile, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
                current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
