#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Define cipher modes
typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB,
    NULL_ENCRYPTION
} CipherMode;

// Define cipher instance structure
typedef struct {
    EVP_CIPHER_CTX *ctx;
    CipherMode mode;
    int key_length;
} CipherInstance;

// Initialize a new cipher instance
CipherInstance* cipher_init(CipherMode mode, int key_length) {
    CipherInstance *cipher = (CipherInstance*)malloc(sizeof(CipherInstance));
    if (!cipher) return NULL;

    cipher->mode = mode;
    cipher->key_length = key_length;
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }

    switch (mode) {
        case ECB:
            EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_ecb(), NULL, NULL, NULL);
            break;
        case EDE:
            EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_cbc(), NULL, NULL, NULL);
            break;
        case EDE3:
            EVP_EncryptInit_ex(cipher->ctx, EVP_aes_192_ecb(), NULL, NULL, NULL);
            break;
        case CFB:
            EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cfb(), NULL, NULL, NULL);
            break;
        case NULL_ENCRYPTION:
            // No encryption
            break;
        default:
            EVP_CIPHER_CTX_free(cipher->ctx);
            free(cipher);
            return NULL;
    }

    return cipher;
}

// Encrypt data using the cipher instance
int cipher_encrypt(CipherInstance *cipher, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len, ciphertext_len;

    switch (cipher->mode) {
        case ECB:
        case EDE:
        case EDE3:
            EVP_EncryptUpdate(cipher->ctx, ciphertext, &len, plaintext, plaintext_len);
            ciphertext_len = len;
            break;
        case CFB:
            EVP_EncryptUpdate(cipher->ctx, ciphertext, &len, plaintext, plaintext_len);
            ciphertext_len = len;
            break;
        case NULL_ENCRYPTION:
            memcpy(ciphertext, plaintext, plaintext_len);
            ciphertext_len = plaintext_len;
            break;
        default:
            return -1; // Invalid mode
    }

    EVP_EncryptFinal_ex(cipher->ctx, ciphertext + len, &len);
    ciphertext_len += len;

    return ciphertext_len;
}

// Free a cipher instance
void cipher_free(CipherInstance *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}
