#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_INFO 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *ue_info[MAX_UE_INFO];
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} UE_Info_Manager;

void init_ue_info_manager(UE_Info_Manager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

int add_ue_info(UE_Info_Manager *manager, NFAPI_CRC_INDICATION_PDU_T *ue_info) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_UE_INFO) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Queue is full
    }
    manager->ue_info[manager->count++] = ue_info;
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_next_ue_info(UE_Info_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    while (manager->count == 0) {
        pthread_cond_wait(&manager->cond, &manager->lock);
    }
    NFAPI_CRC_INDICATION_PDU_T *ue_info = manager->ue_info[--manager->count];
    pthread_mutex_unlock(&manager->lock);
    return ue_info;
}

void destroy_ue_info_manager(UE_Info_Manager *manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}
