#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct ListNode *next;
} ListNode;

typedef struct DynamicList {
    ListNode *head;
    size_t count;
    size_t max_count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t max_count) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->max_count = max_count;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }

    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void dynamic_list_clear(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
}
