    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

void init_crc_array(NFAPI_CRC_ARRAY *arr, size_t initial_capacity) {
    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        perror("Failed to allocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void free_crc_array(NFAPI_CRC_ARRAY *arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

void expand_crc_array(NFAPI_CRC_ARRAY *arr) {
    size_t new_capacity = arr->capacity ? arr->capacity * 2 : 16;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory for CRC array");
        exit(EXIT_FAILURE);
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

void add_crc_to_array(NFAPI_CRC_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T crc) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        expand_crc_array(arr);
    }
    arr->array[arr->size++] = crc;
    pthread_mutex_unlock(&arr->mutex);
