typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SortedList;

void initSortedList(SortedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addElement(SortedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->data = data;
    newNode->next = NULL;

    Node** current = &list->head;
    while (*current && (*current)->data.RNTI < data.RNTI) {
        current = &(*current)->next;
    }

    newNode->next = *current;
    *current = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int removeElement(SortedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node** current = &list->head;
    while (*current && (*current)->data.RNTI != RNTI) {
        current = &(*current)->next;
    }

    if (!*current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Element not found
    }

    Node* temp = *current;
    *current = (*current)->next;
    free(temp);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int getCount(SortedList* list) {
    int count = 0;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void freeSortedList(SortedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
