#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packetId;
    time_t timestamp;
    size_t payloadSize;
    char status;
} DataPacket;

DataPacket* initializePackets(int numPackets, int* errorFlag) {
    if (numPackets <= 0) {
        *errorFlag = -1; // Invalid number of packets
        return NULL;
    }

    DataPacket* packetArray = (DataPacket*)malloc(numPackets * sizeof(DataPacket));
    if (!packetArray) {
        *errorFlag = -2; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < numPackets; ++i) {
        packetArray[i].packetId = i + 1;
        packetArray[i].timestamp = time(NULL);
        packetArray[i].payloadSize = rand() % 1024 + 1; // Random payload size between 1 and 1024
        packetArray[i].status = (i % 2 == 0) ? 'A' : 'B'; // Alternate status flags

        // Simulate potential memory corruption by intentionally corrupting the last byte of payloadSize
        if (i == numPackets - 1) {
            ((char*)&packetArray[i].payloadSize)[sizeof(size_t) - 1] = '\xFF';
        }
    }

    *errorFlag = 0; // No errors
    return packetArray;
}

void freePackets(DataPacket* packetArray, int numPackets) {
    if (packetArray) {
        free(packetArray);
    }
}

int main() {
    int errorFlag;
    DataPacket* packets = initializePackets(10, &errorFlag);

    if (errorFlag != 0) {
        printf("Error initializing packets: %d\n", errorFlag);
        return 1;
    }

    for (int i = 0; i < 10; ++i) {
        printf("Packet ID: %d, Timestamp: %ld, Payload Size: %zu, Status: %c\n",
               packets[i].packetId, packets[i].timestamp, packets[i].payloadSize, packets[i].status);
    }

    freePackets(packets, 10);

    return 0;
}
