#include <string.h>
#include <pthread.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    int userId;
    LogLevel level;
    char* message;
} LogEntry;

typedef struct LogStorage {
    LogEntry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogStorage;

LogStorage* log_storage_init(size_t initial_capacity) {
    LogStorage* storage = (LogStorage*)malloc(sizeof(LogStorage));
    if (!storage) return NULL;

    storage->entries = (LogEntry**)calloc(initial_capacity, sizeof(LogEntry*));
    if (!storage->entries) {
        free(storage);
        return NULL;
    }

    storage->capacity = initial_capacity;
    storage->count = 0;
    pthread_mutex_init(&storage->mutex, NULL);

    return storage;
}

void log_storage_add(LogStorage* storage, int userId, LogLevel level, const char* message) {
    pthread_mutex_lock(&storage->mutex);
    if (storage->count >= storage->capacity) {
        size_t new_capacity = storage->capacity * 2;
        LogEntry** new_entries = (LogEntry**)realloc(storage->entries, new_capacity * sizeof(LogEntry*));
        if (!new_entries) {
            pthread_mutex_unlock(&storage->mutex);
            return; // Handle error
        }
        storage->entries = new_entries;
        storage->capacity = new_capacity;
    }

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) {
        pthread_mutex_unlock(&storage->mutex);
        return; // Handle error
    }

    entry->userId = userId;
    entry->level = level;
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        pthread_mutex_unlock(&storage->mutex);
        return; // Handle error
    }

    storage->entries[storage->count++] = entry;
    pthread_mutex_unlock(&storage->mutex);
}

void log_storage_free(LogStorage* storage) {
    for (size_t i = 0; i < storage->count; ++i) {
        free(storage->entries[i]->message);
        free(storage->entries[i]);
    }
    free(storage->entries);
    pthread_mutex_destroy(&storage->mutex);
    free(storage);
}
