#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTEPHYCONTEXT {
    int cellID;
    int slotOffset;
    int frequencyBand;
} LTEPHYCONTEXT;

typedef struct ListNode {
    LTEPHYCONTEXT data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addOrUpdateConfig(DynamicList* list, LTEPHYCONTEXT newConfig) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.cellID == newConfig.cellID && current->data.slotOffset == newConfig.slotOffset) {
            current->data = newConfig;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    newNode->data = newConfig;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

LTEPHYCONTEXT getConfig(DynamicList* list, int cellID, int slotOffset) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.cellID == cellID && current->data.slotOffset == slotOffset) {
            LTEPHYCONTEXT config = current->data;
            pthread_mutex_unlock(&list->lock);
            return config;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    LTEPHYCONTEXT emptyConfig = {0, 0, 0};
    return emptyConfig;
}

void dumpConfigsToFile(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        fprintf(file, "%d %d %d\n", current->data.cellID, current->data.slotOffset, current->data.frequencyBand);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void validateConfigs(DynamicList* list, const char* referenceDB) {
    // Implement validation logic here
}

void freeDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
