    size_t size;
} Payload;

typedef struct PacketHeader {
    IPHeader ip_header;
    TransportHeader transport_header;
    Payload payload;
} PacketHeader;

typedef struct {
    PacketHeader* headers;
    size_t capacity;
    size_t count;
} PacketPool;

PacketPool* create_packet_pool(size_t max_packets) {
    PacketPool* pool = (PacketPool*)malloc(sizeof(PacketPool));
    if (!pool) return NULL;

    pool->headers = (PacketHeader*)calloc(max_packets, sizeof(PacketHeader));
    if (!pool->headers) {
        free(pool);
        return NULL;
    }

    pool->capacity = max_packets;
    pool->count = 0;

    return pool;
}

void destroy_packet_pool(PacketPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->headers[i].payload.data);
    }
    free(pool->headers);
    free(pool);
}

int add_packet_header(PacketPool* pool, size_t payload_size, int ip_flags, int src_port, int dst_port,
                      int min_payload_size, int max_payload_size) {
    if (pool->count >= pool->capacity) return -1; // Pool is full

    PacketHeader* header = &pool->headers[pool->count++];

    // Initialize IP Header with random flags
    header->ip_header.flags = ip_flags;

    // Initialize Transport Header with random source and destination ports
    header->transport_header.src_port = src_port;
    header->transport_header.dst_port = dst_port;

    // Allocate and initialize Payload with random size within specified limits
    if (payload_size == 0) {
        payload_size = rand() % (max_payload_size - min_payload_size + 1) + min_payload_size;
    }
    header->payload.data = (char*)malloc(payload_size);
    if (!header->payload.data) return -2; // Memory allocation failed

    header->payload.size = payload_size;

    return 0; // Success
}

// Additional functions for custom ranges, error handling, and performance optimization can be implemented here

int main() {
    srand(time(NULL)); // Seed random number generator

    PacketPool* pool = create_packet_pool(1000);
    if (!pool) {
        fprintf(stderr, "Failed to create packet pool\n");
        return 1;
    }

    for (size_t i = 0; i < 500; ++i) {
        int result = add_packet_header(pool, 0, rand() % 256, rand() % 65536, rand() % 65536, 100, 1000);
        if (result != 0) {
            fprintf(stderr, "Failed to add packet header: %d\n", result);
            break;
        }
    }

    destroy_packet_pool(pool);

    return 0;
}
