#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_INSTANCES 10000
#define MAX_MEM_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_INSTANCES];
    int next_index;
    size_t total_memory_used;
    pthread_mutex_t lock;
    time_t last_purge_time;
    int evictions;
    int purges;
} NFAPI_POOL_MANAGER_T;

NFAPI_POOL_MANAGER_T pool_manager = {
    .next_index = 0,
    .total_memory_used = 0,
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .last_purge_time = time(NULL),
    .evictions = 0,
    .purges = 0
};

int allocate_nfaip_pdu() {
    pthread_mutex_lock(&pool_manager.lock);

    if (pool_manager.total_memory_used >= MAX_MEM_LIMIT) {
        // Perform LRU eviction and purge old elements
        time_t current_time = time(NULL);
        if (current_time - pool_manager.last_purge_time > 60) { // Purge every minute
            for (int i = 0; i < MAX_INSTANCES; i++) {
                if (pool_manager.pool[i] != NULL && difftime(current_time, pool_manager.pool[i]->crc_indication.timestamp) > 300) { // Evict after 5 minutes
                    free(pool_manager.pool[i]);
                    pool_manager.pool[i] = NULL;
                    pool_manager.total_memory_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
                    pool_manager.evictions++;
                }
            }
            pool_manager.last_purge_time = current_time;
        }
    }

    if (pool_manager.next_index >= MAX_INSTANCES) {
        pthread_mutex_unlock(&pool_manager.lock);
        return -1; // Pool is full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        pthread_mutex_unlock(&pool_manager.lock);
        return -2; // Memory allocation failed
    }

    new_pdu->crc_indication.timestamp = time(NULL);
    new_pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    pool_manager.pool[pool_manager.next_index++] = new_pdu;
    pool_manager.total_memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&pool_manager.lock);
    return pool_manager.next_index - 1;
}

void free_nfaip_pdu(int index) {
    if (index < 0 || index >= MAX_INSTANCES) return;

    pthread_mutex_lock(&pool_manager.lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = pool_manager.pool[index];
    if (pdu != NULL) {
        free(pdu);
        pool_manager.pool[index] = NULL;
        pool_manager.total_memory_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pool_manager.purges++;
    }

    pthread_mutex_unlock(&pool_manager.lock);
}
