#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEM 1024 * 1024 // 1MB
#define INACTIVE_THRESHOLD 60 // seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    time_t last_accessed;
    int priority;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t count;
    size_t next_index;
    pthread_mutex_t lock;
} LRU_CACHE_T;

LRU_CACHE_T* create_cache(size_t capacity) {
    LRU_CACHE_T *cache = (LRU_CACHE_T*)malloc(sizeof(LRU_CACHE_T));
    cache->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->capacity = capacity;
    cache->count = 0;
    cache->next_index = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(LRU_CACHE_T *cache) {
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void insert_entry(LRU_CACHE_T *cache, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count >= cache->capacity) {
        // Evict the least recently used item
        size_t min_index = 0;
        time_t min_time = cache->entries[0].last_accessed;
        for (size_t i = 1; i < cache->capacity; ++i) {
            if (cache->entries[i].last_accessed < min_time) {
                min_index = i;
                min_time = cache->entries[i].last_accessed;
            }
        }
        // Evict the item
        cache->count--;
    }
    cache->entries[cache->next_index] = entry;
    cache->next_index = (cache->next_index + 1) % cache->capacity;
    cache->count++;
    pthread_mutex_unlock(&cache->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(LRU_CACHE_T *cache, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && cache->entries[i].RNTI == RNTI) {
            cache->entries[i].last_accessed = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return &cache->entries[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void periodic_purge(LRU_CACHE_T *cache, int inactive_threshold) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (time(NULL) - cache->entries[i].last_accessed > inactive_threshold) {
            // Evict the item
            cache->count--;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

int check_memory_usage(LRU_CACHE_T *cache, size_t max_mem) {
    pthread_mutex_lock(&cache->lock);
    if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache->capacity > 0.9 * max_mem) {
        pthread_mutex_unlock(&cache->lock);
        return -1; // Memory usage exceeds 90%
    }
    pthread_mutex_unlock(&cache->lock);
    return 0;
}

int main() {
    LRU_CACHE_T *cache = create_cache(100);
    NFAPI_CRC_INDICATION_PDU_T entry = {1, 2, rand() % 2, time(NULL), 5};
    insert_entry(cache, entry);
    NFAPI_CRC_INDICATION_PDU_T *result = get_entry(cache, 1, 2);
    if (result != NULL) {
        printf("CRCFLAG: %d\n", result->CRCFLAG);
    }
    periodic_purge(cache, INACTIVE_THRESHOLD);
    int memory_status = check_memory_usage(cache, MAX_MEM);
    if (memory_status == -1) {
        printf("Memory usage exceeds 90%\n");
    }
    destroy_cache(cache);
    return 0;
}
