#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONCURRENT_INSTANCES 50000
#define MIN_MEMORY_LIMIT 1024 * 1024 // 1MB
#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    TCP_NODE_DIAGNOSTICS_DATA_TAG tag;
    uint32_t sequence_number;
    uint32_t acknowledgment_number;
    uint32_t window_size;
    int congestion_window_flag;
} TCP_NODE_DIAGNOSTICS_DATA_T;

typedef struct {
    TCP_NODE_DIAGNOSTICS_DATA_T data;
    int frequency;
    time_t last_accessed;
} LFU_ENTRY_T;

typedef struct {
    LFU_ENTRY_T entries[MAX_CONCURRENT_INSTANCES];
    size_t count;
    size_t memory_usage;
    size_t max_memory;
    pthread_mutex_t lock;
} TCP_NODE_POOL_T;

TCP_NODE_POOL_T tcp_node_pool = {0};

void initialize_tcp_node_pool(size_t initial_memory_limit) {
    if (initial_memory_limit < MIN_MEMORY_LIMIT || initial_memory_limit > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Invalid memory limit. Must be between %zu and %zu bytes.\n", MIN_MEMORY_LIMIT, MAX_MEMORY_LIMIT);
        exit(EXIT_FAILURE);
    }
    tcp_node_pool.max_memory = initial_memory_limit;
    pthread_mutex_init(&tcp_node_pool.lock, NULL);
}

int allocate_tcp_node(TCP_NODE_DIAGNOSTICS_DATA_T *data) {
    pthread_mutex_lock(&tcp_node_pool.lock);
    if (tcp_node_pool.memory_usage + sizeof(LFU_ENTRY_T) > tcp_node_pool.max_memory) {
        pthread_mutex_unlock(&tcp_node_pool.lock);
        fprintf(stderr, "Memory limit exceeded. Cannot allocate new TCP node.\n");
        return -1;
    }
    LFU_ENTRY_T *entry = &tcp_node_pool.entries[tcp_node_pool.count++];
    entry->data = *data;
    entry->frequency = 0;
    entry->last_accessed = time(NULL);
    tcp_node_pool.memory_usage += sizeof(LFU_ENTRY_T);
    pthread_mutex_unlock(&tcp_node_pool.lock);
    return 0;
}

void evict_least_frequently_used() {
    pthread_mutex_lock(&tcp_node_pool.lock);
    if (tcp_node_pool.count == 0) {
        pthread_mutex_unlock(&tcp_node_pool.lock);
        return;
    }
    int min_frequency = INT_MAX;
    int index_to_evict = -1;
    for (size_t i = 0; i < tcp_node_pool.count; ++i) {
        if (tcp_node_pool.entries[i].frequency < min_frequency) {
            min_frequency = tcp_node_pool.entries[i].frequency;
            index_to_evict = i;
        }
    }
    tcp_node_pool.memory_usage -= sizeof(LFU_ENTRY_T);
    --tcp_node_pool.count;
    memmove(&tcp_node_pool.entries[index_to_evict], &tcp_node_pool.entries[index_to_evict + 1], (tcp_node_pool.count - index_to_evict) * sizeof(LFU_ENTRY_T));
    pthread_mutex_unlock(&tcp_node_pool.lock);
}

void update_tcp_node_frequency(int index) {
    pthread_mutex_lock(&tcp_node_pool.lock);
    if (index >= 0 && index < tcp_node_pool.count) {
        ++tcp_node_pool.entries[index].frequency;
        tcp_node_pool.entries[index].last_accessed = time(NULL);
    }
    pthread_mutex_unlock(&tcp_node_pool.lock);
}

void *monitor_and_purge(void *arg) {
    while (1) {
        sleep(60); // Purge every minute
        evict_least_frequently_used();
    }
    return NULL;
}

int main() {
    initialize_tcp_node_pool(512 * 1024 * 1024); // 512MB initial memory limit

    pthread_t purge_thread;
    pthread_create(&purge_thread, NULL, monitor_and_purge, NULL);

    // Example usage
    TCP_NODE_DIAGNOSTICS_DATA_T data = { /* initialize data */ };
    if (allocate_tcp_node(&data) == -1) {
        fprintf(stderr, "Failed to allocate TCP node.\n");
        return EXIT_FAILURE;
    }

    update_tcp_node_frequency(0); // Update frequency of the first entry

    pthread_join(purge_thread, NULL);
    pthread_mutex_destroy(&tcp_node_pool.lock);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a dynamic pool for managing TCP_NODE_DIAGNOSTICS_DATA_T structures using an LFU eviction policy. It includes functions for initializing the pool, allocating new nodes, updating node frequencies, and periodically purging least frequently used entries. The solution also demonstrates how to handle memory limits, concurrency, and periodic maintenance tasks.']

