#define MAX_PACKETS 1000
#define TIME_THRESHOLD 5 // in seconds

typedef struct {
    unsigned char mac_header[6];
    unsigned int pdu_session_id;
    unsigned char security_container[256];
} PacketInfo;

typedef struct {
    PacketInfo *packets;
    size_t count;
    size_t capacity;
} PacketArray;

void initialize_packet_array(PacketArray *array) {
    array->packets = (PacketInfo *)malloc(MAX_PACKETS * sizeof(PacketInfo));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = MAX_PACKETS;
}

void populate_packet_array(PacketArray *array) {
    clock_t start_time = clock();
    for (size_t i = 0; i < array->capacity; ++i) {
        // Simulate packet generation and validation
        if (clock() - start_time > TIME_THRESHOLD * CLOCKS_PER_SEC) {
            fprintf(stderr, "Initialization time exceeded threshold\n");
            break;
        }
        // Generate random MAC header
        for (int j = 0; j < 6; ++j) {
            array->packets[i].mac_header[j] = rand() % 256;
        }
        // Generate random PDU session ID
        array->packets[i].pdu_session_id = rand();
        // Simulate security container generation and integrity check
        for (int j = 0; j < 256; ++j) {
            array->packets[i].security_container[j] = rand() % 256;
        }
    }
}

void save_packet_array(const PacketArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(array->packets, sizeof(PacketInfo), array->count, file);
    fclose(file);
}

void load_packet_array(PacketArray *array, const char *filename) {
