#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    int size;
    int max_size;
} ThreadSafeList;

void init_list(ThreadSafeList* list, int max_size) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);
    list->size = 0;
    list->max_size = max_size;
}

void destroy_list(ThreadSafeList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_full);
    pthread_cond_destroy(&list->not_empty);
}

void enqueue(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    while (list->size == list->max_size) {
        pthread_cond_wait(&list->not_full, &list->lock);
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;
    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(ThreadSafeList* list) {
    pthread_mutex_lock(&list->lock);
    while (list->size == 0) {
        pthread_cond_wait(&list->not_empty, &list->lock);
    }
    Node* old_head = list->head;
    NFAPI_CRC_INDICATION_PDU_T data = old_head->data;
    list->head = old_head->next;
    if (list->head == NULL) {
        list->tail = NULL;
    }
    free(old_head);
    list->size--;
    pthread_cond_signal(&list->not_full);
    pthread_mutex_unlock(&list->lock);
    return data;
}

void* batch_processing(void* arg) {
    ThreadSafeList* list = (ThreadSafeList*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T data = dequeue(list);
        // Process the CRC indication
        printf("Processed CRC indication with RNTI: %d\n", data.RNTI);
    }
    return NULL;
}

int main() {
    ThreadSafeList list;
    init_list(&list, MAX_LIST_SIZE);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, batch_processing, &list);
    }

    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 100;
        data.RNTI = rand() % 1000;
        data.CRC_INDICATION_REL8_TAG = rand() % 2;
        enqueue(&list, data);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(&list);

    return 0;
}
