typedef struct {
    unsigned char mac_header[6];
    unsigned int pdu_session_id;
    unsigned char security_container[128];
    unsigned int integrity_check_value;
} PacketInfo;

typedef struct {
    PacketInfo *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->packets = (PacketInfo *)malloc(initial_capacity * sizeof(PacketInfo));
    pthread_mutex_init(&array->lock, NULL);
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    PacketInfo *new_packets = (PacketInfo *)realloc(array->packets, new_capacity * sizeof(PacketInfo));
    if (new_packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->capacity = new_capacity;
}

void add_packet(DynamicArray *array, PacketInfo packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}
