#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_N 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    NFAPI_CRC_INDICATION_REL8_TAG rel8;
} NFAPI_STRUCT;

typedef struct {
    int parent[MAX_N];
    int rank[MAX_N];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

NFAPI_STRUCT* createAndPopulateArray(int N) {
    NFAPI_STRUCT *array = (NFAPI_STRUCT*)malloc(N * sizeof(NFAPI_STRUCT));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        array[i].pdu.RX_UE_INFORMATION_TAG = rand() % MAX_N;
        array[i].pdu.RNTI = rand() % MAX_N;
        array[i].rel8.CRCFLAG = rand() % 2;
    }

    return array;
}

void checkDisjointness(NFAPI_STRUCT *array, int N) {
    UnionFind uf;
    initUnionFind(&uf, N);

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (array[i].pdu.RX_UE_INFORMATION_TAG != array[j].pdu.RX_UE_INFORMATION_TAG &&
                array[i].pdu.RNTI != array[j].pdu.RNTI) {
                start = clock();
                unionSets(&uf, i, j);
                end = clock();
                cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
                printf("Disjoint pair (%d, %d): Time taken = %.6f microseconds\n", i, j, cpu_time_used * 1e6);
            }
        }
    }
}

int main() {
    int N = MAX_N;
    NFAPI_STRUCT *array = createAndPopulateArray(N);
    checkDisjointness(array, N);
    free(array);
    return 0;
}
