        array[i].RNTI = rand() % N;
        array[i].CRC_INDICATION_REL8_TAG = rand() % N;
        array[i].CRCFLAG = rand() % 2;

        if (i > 0) {
            unionSets(&uf, i - 1, i);
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            clock_t start = clock();
            if (areDisjoint(&uf, i, j)) {
                printf("Pair (%d, %d) is disjoint\n", i, j);
            }
            clock_t end = clock();
            double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
            printf("Time taken: %f milliseconds\n", time_taken * 1000);
        }
    }

    free(array);
}

int main() {
    int N = 1000; // Example value for N
    populateAndCheckDisjointness(N);
    return 0;
