#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define N 10000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8;

typedef struct {
    RX_UE_INFORMATION rx_ue_info;
    CRC_INDICATION_REL8 crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} CustomMemoryPool;

CustomMemoryPool* create_memory_pool(size_t size) {
    CustomMemoryPool *pool = (CustomMemoryPool*)malloc(sizeof(CustomMemoryPool));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(CustomMemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(CustomMemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->size) {
        pdu = &pool->pool[pool->used++];
    } else {
        pdu = NULL; // Pool is full
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void deallocate_to_pool(CustomMemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used; ++i) {
        if (&pool->pool[i] == pdu) {
            pool->used--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int rx_ue_info_tag, int rnti, int crcflag) {
    pdu->rx_ue_info.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->rx_ue_info.RNTI = rnti;
    pdu->crc_ind_rel8.CRCFLAG = crcflag;
}

void* disjointness_check(void *arg) {
    CustomMemoryPool *pool = (CustomMemoryPool*)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu1, *pdu2;
    clock_t start, end;
    double cpu_time_used;

    for (size_t i = 0; i < pool->used - 1; ++i) {
        pdu1 = &pool->pool[i];
        for (size_t j = i + 1; j < pool->used; ++j) {
            pdu2 = &pool->pool[j];
            start = clock();
            // Perform disjointness check
            if (pdu1->rx_ue_info.RX_UE_INFORMATION_TAG != pdu2->rx_ue_info.RX_UE_INFORMATION_TAG ||
                pdu1->rx_ue_info.RNTI != pdu2->rx_ue_info.RNTI) {
                end = clock();
                cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
                printf("Disjoint pair found: %zu and %zu, Time taken: %.6f microseconds\n", i, j, cpu_time_used * 1e6);
            }
        }
    }

    return NULL;
}

int main() {
    CustomMemoryPool *pool = create_memory_pool(N);

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(pool);
        if (pdu != NULL) {
            populate_pdu(pdu, rand() % 1000, rand() % 1000, rand() % 2);
        }
    }

    pthread_t thread;
    pthread_create(&thread, NULL, disjointness_check, pool);

    pthread_join(thread, NULL);

    destroy_memory_pool(pool);

    return 0;
}
