int generate_unique_rnti(int *used_rntis, int used_count, int min_rnti, int max_rnti) {
    // Generate a unique RNTI within the specified range
    int rnti;
    do {
        rnti = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    } while (used_count > 0 && used_rntis[used_count - 1] == rnti);
    return rnti;
}

int populate_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T **list, int N, int min_rnti, int max_rnti) {
    if (N > MAX_LIST_SIZE) {
        printf("Error: List size exceeds maximum supported size.\n");
        return -1; // Return an error code
    }

    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        printf("Error: Memory allocation failed.\n");
        return -2; // Return another error code for memory failure
    }

    int used_rntis[N];
    int used_count = 0;

    for (int i = 0; i < N; i++) {
        int rnti = generate_unique_rnti(used_rntis, used_count, min_rnti, max_rnti);
        if (rnti == -1) {
            printf("Warning: Insufficient unique RNTI values available.\n");
            break;
        }
        (*list)[i].RX_UE_INFORMATION_TAG = i + 1; // Example initialization
        (*list)[i].RNTI = rnti;
        (*list)[i].CRC_INDICATION_REL8_TAG = i % 2; // Example CRCFLAG value
        (*list)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        used_rntis[used_count++] = rnti;
    }

    return N - used_count; // Return the number of elements that could not be populated
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list;
    int N = 500;
    int min_rnti = 100;
    int max_rnti = 999;

    int result = populate_nfaapi_list(&list, N, min_rnti, max_rnti);
    if (result < 0) {
        printf("Failed to populate list.\n");
    } else {
        printf("%d elements could not be populated due to insufficient unique RNTI values.\n", result);
    }

    free(list); // Free the allocated memory
    return 0;
}
