    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->list[i].rnti == rnti) {
            memmove(&list->list[i], &list->list[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list->size;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void filter_list(ThreadSafeList *list, RNTI exclude_rnti) {
