    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
}

int add_session_context(SessionManager *manager, int subscription_id, int qos_settings) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        SessionContext *new_contexts = (SessionContext *)realloc(manager->contexts, new_capacity * sizeof(SessionContext));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }
    manager->contexts[manager->count].subscription_id = subscription_id;
    manager->contexts[manager->count].qos_settings = qos_settings;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
