SessionManager* session_manager_init() {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->contexts = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void session_manager_add(SessionManager *manager, const char *subscription_id, int qos_settings, const char *account_id, const char *user_name, const char *email_address, size_t storage_quota) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        manager->capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        manager->contexts = realloc(manager->contexts, manager->capacity * sizeof(SessionContext));
    }
    strcpy(manager->contexts[manager->count].subscription_id, subscription_id);
    manager->contexts[manager->count].qos_settings = qos_settings;
    strcpy(manager->contexts[manager->count].account_id, account_id);
    strcpy(manager->contexts[manager->count].user_name, user_name);
    strcpy(manager->contexts[manager->count].email_address, email_address);
    manager->contexts[manager->count].storage_quota = storage_quota;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void session_manager_free(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
