#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_THREADS 100

typedef struct {
    int task_id;
    int priority;
} Task;

typedef struct {
    pthread_t threads[MAX_THREADS];
    Task tasks[MAX_THREADS];
    int thread_count;
    int next_task_index;
    int max_priority;
} ThreadPool;

void* worker_thread(void* arg) {
    ThreadPool* pool = (ThreadPool*)arg;
    while (1) {
        // Lock the pool to access shared data
        pthread_mutex_lock(&pool->mutex);

        // Check if there are tasks available
        if (pool->next_task_index >= pool->thread_count) {
            // No tasks, check for termination signal
            if (pool->terminate) {
                pthread_mutex_unlock(&pool->mutex);
                break;
            }
            // Wait for new tasks or termination signal
            pthread_cond_wait(&pool->cond, &pool->mutex);
        } else {
            // Get the next task
            Task task = pool->tasks[pool->next_task_index++];

            // Unlock the pool
            pthread_mutex_unlock(&pool->mutex);

            // Process the task
            printf("Processing task %d with priority %d\n", task.task_id, task.priority);
        }
    }
    return NULL;
}

void initialize_thread_pool(ThreadPool* pool, int max_priority) {
    pool->thread_count = 0;
    pool->next_task_index = 0;
    pool->max_priority = max_priority;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);

    // Create worker threads
    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&pool->threads[i], NULL, worker_thread, pool) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
        pool->thread_count++;
    }
}

void submit_task(ThreadPool* pool, Task task) {
    pthread_mutex_lock(&pool->mutex);

    // Check if the task priority is valid
    if (task.priority > pool->max_priority) {
        printf("Invalid task priority\n");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    // Add the task to the pool
    pool->tasks[pool->next_task_index++] = task;

    // Signal a worker thread to process the new task
    pthread_cond_signal(&pool->cond);

    pthread_mutex_unlock(&pool->mutex);
}

void terminate_thread_pool(ThreadPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    pool->terminate = 1;
    pthread_cond_broadcast(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);

    // Wait for all threads to finish
    for (int i = 0; i < pool->thread_count; i++) {
        pthread_join(pool->threads[i], NULL);
    }

    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
}

int main() {
    ThreadPool pool;
    initialize_thread_pool(&pool, 5);

    // Submit tasks
    submit_task(&pool, (Task){1, 3});
    submit_task(&pool, (Task){2, 4});
    submit_task(&pool, (Task){3, 2});

    // Terminate the thread pool
    terminate_thread_pool(&pool);

    return 0;
}
