#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    uint16_t max_rnti_range;
    int logging_level;
} CRC_LIST_MANAGER_T;

void init_crc_list_manager(CRC_LIST_MANAGER_T *manager, uint16_t max_rnti_range, int logging_level) {
    manager->head = NULL;
    manager->tail = NULL;
    manager->max_rnti_range = max_rnti_range;
    manager->logging_level = logging_level;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_pdu->ue_info_tag = ue_info_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_pdu->next = NULL;
    return new_pdu;
}

void add_crc_pdu(CRC_LIST_MANAGER_T *manager, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    if (rnti > manager->max_rnti_range) {
        printf("Invalid RNTI value\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = create_crc_pdu(ue_info_tag, rnti, crc_indication_rel8_tag);
    if (new_pdu == NULL) {
        return;
    }

    if (manager->head == NULL) {
        manager->head = new_pdu;
        manager->tail = new_pdu;
    } else {
        manager->tail->next = new_pdu;
        manager->tail = new_pdu;
    }
}

void free_crc_list(CRC_LIST_MANAGER_T *manager) {
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->tail = NULL;
}

int main() {
    CRC_LIST_MANAGER_T manager;
    init_crc_list_manager(&manager, 1023, 1);

    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        RX_UE_INFORMATION_TAG ue_info_tag = i % 100;
        uint16_t rnti = rand() % manager.max_rnti_range + 1;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag = (rand() % 2 == 0) ? 1 : 0;

        add_crc_pdu(&manager, ue_info_tag, rnti, crc_indication_rel8_tag);
    }

    free_crc_list(&manager);

    return 0;
}
