fn initializeDataProcessingEnvironment() -> Result<(), Box<dyn std::error::Error>> {
    let mut data_dir_path = env::var("DATA_DIR_PATH").ok();

    if data_dir_path.is_none() {
        let dir_name = format!("rlc_data_{}", thread_rng().gen::<u32>());
        let data_dir = Path::new(&dir_name);

        // Lock to handle race conditions
        let _lock = DATA_DIR_LOCK.lock().unwrap();

        if !data_dir.exists() {
            DirBuilder::new()
                .recursive(true)
                .create(data_dir)?;
        }

        data_dir_path = Some(dir_name);
    }

    if let Some(path) = &data_dir_path {
        env::set_var("DATA_DIR_PATH", path);
    }

    // Initialize necessary structures with random CRCFLAG
