#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_ID 1024
#define MAX_MAC_HEADERS 64

typedef struct {
    int ue_id;
    char tx_rx_config[32];
    struct MAC_PDU_HEADER *mac_headers[MAX_MAC_HEADERS];
} LTEPHYCONTEXT;

typedef struct {
    LTEPHYCONTEXT **array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (LTEPHYCONTEXT**)malloc(initial_capacity * sizeof(LTEPHYCONTEXT*));
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i]);
    }
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    if (new_capacity <= da->capacity) return -1;
    LTEPHYCONTEXT **new_array = (LTEPHYCONTEXT**)realloc(da->array, new_capacity * sizeof(LTEPHYCONTEXT*));
    if (!new_array) return -1;
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_to_dynamic_array(DynamicArray *da, LTEPHYCONTEXT *context) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity && resize_dynamic_array(da, da->capacity * 2) != 0) {
        pthread_mutex_unlock(&da->mutex);
        return -1;
    }
    da->array[da->size++] = context;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

LTEPHYCONTEXT* get_from_dynamic_array(DynamicArray *da, size_t index) {
    if (index >= da->size) return NULL;
    pthread_mutex_lock(&da->mutex);
    LTEPHYCONTEXT *context = da->array[index];
    pthread_mutex_unlock(&da->mutex);
    return context;
}
