#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamic_array[MAX_ELEMENTS];
int array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void fetch_rnti_values(int *rntis, int count) {
    // Simulate fetching RNTI values from an external data source
    for (int i = 0; i < count; i++) {
        rntis[i] = rand() % 1000;
    }
}

int is_unique_rnti(int *rntis, int count) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (rntis[i] == rntis[j]) {
                return 0;
            }
        }
    }
    return 1;
}

void* populate_array(void *arg) {
    int count = *(int*)arg;
    int rntis[count];

    fetch_rnti_values(rntis, count);

    while (!is_unique_rnti(rntis, count)) {
        fetch_rnti_values(rntis, count);
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        dynamic_array[array_size++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        dynamic_array[array_size - 1]->RX_UE_INFORMATION_TAG = rand() % 100;
        dynamic_array[array_size - 1]->RNTI = rntis[i];
        dynamic_array[array_size - 1]->CRC_INDICATION_REL8_TAG = rand() % 2;
        dynamic_array[array_size - 1]->CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void cleanup_array() {
    for (int i = 0; i < array_size; i++) {
        free(dynamic_array[i]);
    }
    array_size = 0;
}

int main() {
    int count = 100;
    pthread_t thread;

    srand(time(NULL));

    if (pthread_create(&thread, NULL, populate_array, &count) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    cleanup_array();

    return 0;
}
