use std::fs::{self, File};
use std::io::{self, Write};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};
use rand::Rng;

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[derive(Debug)]
struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

fn createAndManageDirectoryWithCRCIndications(directory_name: &str) -> io::Result<String> {
    let crc_dir_path = std::env::var("CRC_DIR_PATH").map_err(|_| io::Error::new(io::ErrorKind::Other, "CRC_DIR_PATH environment variable not set"))?;
    let directory_path = Path::new(&crc_dir_path).join(directory_name);

    if directory_path.exists() {
        Ok(crc_dir_path)
    } else {
        fs::create_dir_all(&directory_path)?;
        populate_directory_with_crc_indications(&directory_path, 1000)?; // Populate with 1000 CRC indications
        Ok(crc_dir_path)
    }
}

fn populate_directory_with_crc_indications(directory_path: &Path, num_entries: usize) -> io::Result<()> {
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos();
    let rng = rand::thread_rng();

    for i in 0..num_entries {
        let file_name = format!("crc_indication_{}.bin", i);
        let file_path = directory_path.join(&file_name);

        let mut file = File::create(&file_path)?;
        let crc_indication = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: rng.gen(),
            rnti: rng.gen(),
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag: rng.gen() },
        };

        file.write_all(&crc_indication.rx_ue_information_tag.to_le_bytes())?;
        file.write_all(&crc_indication.rnti.to_le_bytes())?;
        file.write_all(&crc_indication.crc_indication_rel8_tag.crcflag.to_le_bytes())?;
        file.write_all(&now.to_le_bytes())?;

        // Simulate cleanup mechanism
        if i % 100 == 0 {
            clean_old_files(directory_path)?;
        }
    }

    Ok(())
}

fn clean_old_files(directory_path: &Path) -> io::Result<()> {
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
    let two_days_ago = now - 24 * 60 * 60;

    for entry in fs::read_dir(directory_path)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() {
            if let Ok(metadata) = fs::metadata(&path) {
                if metadata.modified().map_or(false, |mtime| mtime.timestamp() < two_days_ago as i64) {
                    fs::remove_file(&path)?;
                }
            }
        }
    }

    Ok(())
}
