typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    int *RNTI_pool;
    int pool_size;
    int pool_index;
} RNTI_Manager;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPISDU(int N, RNTI_Manager *manager) {
    NFAPI_CRC_INDICATION_PDU_T *sdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!sdu_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < N; ++i) {
        if (manager->pool_index >= manager->pool_size) {
            fprintf(stderr, "RNTI pool exhausted\n");
            free(sdu_list);
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
        sdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example tag generation
