#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];
    int size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    for (int i = 0; i < da->size; i++) {
        free(da->array[i]);
    }
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Out of memory
    }
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int remove_element(DynamicArray *da, int index) {
    pthread_mutex_lock(&da->mutex);
    if (index < 0 || index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Invalid index
    }
    free(da->array[index]);
    for (int i = index; i < da->size - 1; i++) {
        da->array[i] = da->array[i + 1];
    }
    da->size--;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *da, int index) {
    pthread_mutex_lock(&da->mutex);
    if (index < 0 || index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return NULL; // Invalid index
    }
    NFAPI_CRC_INDICATION_PDU_T *element = da->array[index];
    pthread_mutex_unlock(&da->mutex);
    return element;
}

void validate_crc_indications(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    for (int i = 0; i < da->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = da->array[i];
        // Perform CRC validation logic here
        printf("Validating CRC indication for RNTI %d\n", element->RNTI);
    }
    pthread_mutex_unlock(&da->mutex);
}

int main() {
    DynamicArray *da = create_dynamic_array();
    if (!da) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        destroy_dynamic_array(da);
        fprintf(stderr, "Failed to allocate memory for element\n");
        return 1;
    }
    element->RX_UE_INFORMATION_TAG = 12345;
    element->RNTI = 67890;
    element->CRC_INDICATION_REL8_TAG = rand() % 2;

    if (add_element(da, element) != 0) {
        free(element);
        destroy_dynamic_array(da);
        fprintf(stderr, "Failed to add element\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *retrieved_element = get_element(da, 0);
    if (retrieved_element) {
        printf("Retrieved CRC indication for RNTI %d\n", retrieved_element->RNTI);
    } else {
        fprintf(stderr, "Failed to retrieve element\n");
    }

    remove_element(da, 0);

    destroy_dynamic_array(da);
    return 0;
}
