#include <string.h>

#define NR_CU_UP_CAPEX_PERF_DATA 100

typedef struct {
    int throughput;
    float latency;
    float error_rate;
} NR_CU_UP_CAPEX_PERF_DATA;

int read_csv_file(const char *filename, NR_CU_UP_CAPEX_PERF_DATA **data, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    *count = 0;
    while (*count < NR_CU_UP_CAPEX_PERF_DATA && fscanf(file, "%d,%f,%f", &(*data)[*count].throughput, &(*data)[*count].latency, &(*data)[*count].error_rate) == 3) {
        (*count)++;
    }

    fclose(file);
    return 0;
}

int validate_data(NR_CU_UP_CAPEX_PERF_DATA *data, int count) {
    for (int i = 0; i < count; i++) {
        if (data[i].throughput <= 0 || data[i].latency < 0.01 || data[i].error_rate < 0.001) {
            return -1;
        }
    }
    return 0;
}

int populate_performance_data(NR_CU_UP_CAPEX_PERF_DATA **data, int *count, const char **filenames, int num_files) {
    *data = (NR_CU_UP_CAPEX_PERF_DATA *)malloc(NR_CU_UP_CAPEX_PERF_DATA * sizeof(NR_CU_UP_CAPEX_PERF_DATA));
    if (!*data) return -1;

    for (int i = 0; i < num_files; i++) {
        int file_count;
        if (read_csv_file(filenames[i], data, &file_count) != 0) {
            free(*data);
            *data = NULL;
            return -1;
        }
        *count += file_count;
    }

    if (validate_data(*data, *count) != 0) {
        free(*data);
        *data = NULL;
        return -1;
    }

    return 0;
}

int main() {
    const char *filenames[] = {"file1.csv", "file2.csv"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);
    NR_CU_UP_CAPEX_PERF_DATA *data;
    int count;

    if (populate_performance_data(&data, &count, filenames, num_files) != 0) {
        printf("Failed to populate performance data.\n");
        return -1;
    }

    // Process the data as needed

    free(data);
    return 0;
}
