#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define MIN_CRCFLAG 0
#define MAX_CRCFLAG 255

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
    int *rnti_pool;
    int rnti_count;
} CRC_LIST_MANAGER_T;

CRC_LIST_MANAGER_T crc_list_manager;

void init_crc_list_manager() {
    pthread_mutex_init(&crc_list_manager.lock, NULL);
    crc_list_manager.count = 0;
    crc_list_manager.rnti_pool = (int *)malloc(MAX_STRUCTURES * sizeof(int));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        crc_list_manager.rnti_pool[i] = i + 1;
    }
    crc_list_manager.rnti_count = MAX_STRUCTURES;
}

void* populate_crc_list(void *arg) {
    pthread_mutex_lock(&crc_list_manager.lock);
    if (crc_list_manager.count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&crc_list_manager.lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        pthread_mutex_unlock(&crc_list_manager.lock);
        return NULL;
    }

    new_struct->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    int rnti;
    do {
        rnti = crc_list_manager.rnti_pool[rand() % crc_list_manager.rnti_count];
    } while (rnti == crc_list_manager.list[crc_list_manager.count - 1]->RNTI]);
    new_struct->RNTI = rnti;

    new_struct->CRC_INDICATION_REL8_TAG = rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1) + MIN_CRCFLAG;
    if (new_struct->CRC_INDICATION_REL8_TAG < MIN_CRCFLAG || new_struct->CRC_INDICATION_REL8_TAG > MAX_CRCFLAG) {
        printf("Out-of-range CRCFLAG value: %d\n", new_struct->CRC_INDICATION_REL8_TAG);
    }

    crc_list_manager.list[crc_list_manager.count++] = new_struct;
    pthread_mutex_unlock(&crc_list_manager.lock);
    return NULL;
}

void update_crc_list() {
    for (int i = 0; i < crc_list_manager.count; i++) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, populate_crc_list, NULL);
        pthread_join(thread_id, NULL);
    }
}

void free_crc_list() {
    for (int i = 0; i < crc_list_manager.count; i++) {
        free(crc_list_manager.list[i]);
    }
    free(crc_list_manager.rnti_pool);
    pthread_mutex_destroy(&crc_list_manager.lock);
}
