    return element;
}

void free_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    free(element);
}

void destroy_list(ThreadSafeList *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        free_element(list->elements[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

