typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_size) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = initial_size;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdus);
        free(list);
    }
}

int add_crc_pdu(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0) {
        list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->pdus) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->count = 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdus[list->count - 1];
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int generate_crc_indications(NFAPI_CRC_LIST_T *list, size_t N, int M) {
    for (size_t i = 0; i < N; ++i) {
        int RX_UE_INFORMATION_TAG = rand() % 1000; // Example generation
        int RNTI = rand() % 1000; // Example generation
        int CRC_INDICATION_REL8_TAG = rand() % 2; // Example generation

        if (add_crc_pdu(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG) != 0) {
            return -1;
        }
    }

    return 0;
}
