import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ResilientConnectionHandler {

    private AsynchronousServerSocketChannel serverChannel;
    private ExecutorService executorService;

    public void start(int port, int numberOfSessions) throws IOException {
        executorService = Executors.newFixedThreadPool(numberOfSessions);
        serverChannel = AsynchronousServerSocketChannel.open(AsynchronousChannelGroup.withFixedThreadPool(numberOfSessions));
        serverChannel.bind(new InetSocketAddress(port));

        for (int i = 0; i < numberOfSessions; i++) {
            serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Void>() {
                @Override
                public void completed(AsynchronousSocketChannel result, Void attachment) {
                    handleConnection(result);
                    serverChannel.accept(null, this); // Accept next connection
                }

                @Override
                public void failed(Throwable exc, Void attachment) {
                    exc.printStackTrace();
                }
            });
        }
    }

    private void handleConnection(AsynchronousSocketChannel channel) {
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
        channel.read(buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                if (result == -1) {
                    try {
                        channel.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                } else {
                    // Process data
                    buffer.flip();
                    byte[] data = new byte[buffer.remaining()];
                    buffer.get(data);
                    buffer.clear();

                    // Schedule next read operation
                    channel.read(buffer, buffer, this);
                }
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                exc.printStackTrace();
                try {
                    channel.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        });
    }

    public void stop() throws IOException {
        serverChannel.close();
        executorService.shutdown();
    }
}
