    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = head;
    head = new_node;
    size++;
}

void delete(int RX_UE_INFORMATION_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *current = head, *prev = NULL;
    while (current != NULL && current->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("Element not found\n");
        return;
    }
    if (prev == NULL)
        head = current->next;
    else
        prev->next = current->next;
    free(current);
    size--;
}

void traverse() {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRCFLAG);
        current = current->next;
    }
}

int validate() {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->CRCFLAG < 0 || current->CRCFLAG > 1) {
            printf("Invalid CRCFLAG value\n");
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int main() {
    srand(time(0));
    insert(1, 10);
    insert(2, 20);
    traverse();
    delete(1);
    traverse();
    if (validate())
        printf("Validation successful\n");
    else
        printf("Validation failed\n");
    return 0;
}
