#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

void init_crc_list(NFAPI_CRC_LIST_T *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].RNTI == entry.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI
        }
    }
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List full
    }
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_list(NFAPI_CRC_LIST_T *list, char **buffer, size_t *size) {
    pthread_mutex_lock(&list->lock);
    *size = sizeof(int) + (list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *buffer = malloc(*size);
    if (!*buffer) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    memcpy(*buffer, &list->count, sizeof(int));
    memcpy(*buffer + sizeof(int), list->entries, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_event(const char *message) {
    printf("%s\n", message);
}
