typedef struct {
    LTE_MME_UE_S1AP_ID_t id;
    RRC_Connexion_State state;
    int nas_message_count;
} UE_Status_Report_T;

typedef struct {
    UE_Status_Report_T* reports;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UE_Status_Array_T;

void init_UE_status_array(UE_Status_Array_T* array, size_t initial_capacity) {
    array->reports = (UE_Status_Report_T*)malloc(initial_capacity * sizeof(UE_Status_Report_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void destroy_UE_status_array(UE_Status_Array_T* array) {
    free(array->reports);
    pthread_mutex_destroy(&array->mutex);
}

int add_UE_status_report(UE_Status_Array_T* array, UE_Status_Report_T report) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->reports[i].id == report.id) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Duplicate ID
        }
    }
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UE_Status_Report_T* new_reports = (UE_Status_Report_T*)realloc(array->reports, new_capacity * sizeof(UE_Status_Report_T));
        if (!new_reports) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->reports = new_reports;
        array->capacity = new_capacity;
    }
    array->reports[array->size++] = report;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_UE_status_report(UE_Status_Array_T* array, LTE_MME_UE_S1AP_ID_t id) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->reports[i].id == id) {
            for (size_t j = i; j < array->size - 1; ++j) {
                array->reports[j] = array->reports[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // ID not found
}

UE_Status_Report_T* filter_UE_status_reports(UE_Status_Array_T* array, int threshold) {
    pthread_mutex_lock(&array->mutex);
    UE_Status_Report_T* filtered = (UE_Status_Report_T*)malloc(array->size * sizeof(UE_Status_Report_T));
    size_t filtered_size = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->reports[i].nas_message_count > threshold) {
            filtered[filtered_size++] = array->reports[i];
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return filtered;
}

int update_UE_status_report(UE_Status_Array_T* array, LTE_MME_UE_S1AP_ID_t id, RRC_Connexion_State new_state) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->reports[i].id == id) {
            array->reports[i].state = new_state;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // ID not found
}
