NFAPI_CRC_INDICATION_PDU_T* array = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int current_size = 0;

void initialize_array() {
    pthread_mutex_lock(&mutex);
    if (array == NULL) {
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);
}

void populate_array(int N) {
    if (N > MAX_STRUCTURES - current_size) {
        fprintf(stderr, "Cannot populate more than %d structures\n", MAX_STRUCTURES);
        return;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; i++) {
        array[current_size + i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[current_size + i].RNTI = rand() % 65536;
        array[current_size + i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[current_size + i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }
    current_size += N;
    pthread_mutex_unlock(&mutex);
}

void validate_array(int N) {
    if (N > current_size) {
        fprintf(stderr, "Cannot validate more structures than currently populated\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        if (array[i].RX_UE_INFORMATION_TAG < 0 || array[i].RNTI < 0 || array[i].CRC_INDICATION_REL8_TAG < 0 ||
            array[i].CRCFLAG != 0 && array[i].CRCFLAG != 1) {
            fprintf(stderr, "Validation failed for structure %d\n", i);
        }
    }
}

void* thread_function(void* arg) {
    int N = *(int*)arg;
    populate_array(N);
    validate_array(N);
    free(arg);
    return NULL;
}

int main() {
    srand(time(NULL));
    initialize_array();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* N = (int*)malloc(sizeof(int));
        *N = rand() % 5000 + 1;
        if (pthread_create(&threads[i], NULL, thread_function, N) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free(array);
    return 0;
}
