typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->mutex);
        free(list->array);
        free(list);
    }
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity + CHUNK_SIZE;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        list->array = new_array;
        list->capacity = new_capacity;
    }

    list->array[list->count++] = item;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int validate_crc_list(NFAPI_CRC_LIST_T *list) {
    for (size_t i = 1; i < list->count; ++i) {
        if (list->array[i].RX_UE_INFORMATION_TAG == list->array[i-1].RX_UE_INFORMATION_TAG) {
            return -1;
        }
    }

    return 0;
}

int export_crc_list(NFAPI_CRC_LIST_T *list, const char *path, const char *format) {
    pthread_mutex_lock(&list->mutex);

    FILE *file = fopen(path, format == "binary" ? "wb" : "w");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (format == "binary") {
            fwrite(&list->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        } else {
            fprintf(file, "%d %d %d %d\n", 
                    list->array[i].RX_UE_INFORMATION_TAG,
                    list->array[i].RNTI,
                    list->array[i].CRC_INDICATION_REL8_TAG,
                    list->array[i].CRCFLAG);
        }
    }

    fclose(file);

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void log_event(const char *message) {
    printf("%s\n", message);
}
