        perror("Error opening file for writing");
        return;
    }
    fwrite(graph, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);
}

void deserialize_graph(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file for reading");
