#define MAX_CONNECTIONS 1024

typedef struct {
    char client_ip[16];
    char server_ip[16];
    time_t timestamp;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_connection(const char* client_ip, const char* server_ip) {
    pthread_mutex_lock(&lock);
    if (connection_count < MAX_CONNECTIONS) {
        strcpy(connections[connection_count].client_ip, client_ip);
        strcpy(connections[connection_count].server_ip, server_ip);
        connections[connection_count].timestamp = time(NULL);
        connection_count++;
    }
    pthread_mutex_unlock(&lock);
}

void remove_connection(const char* client_ip, const char* server_ip) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < connection_count; i++) {
        if (strcmp(connections[i].client_ip, client_ip) == 0 && strcmp(connections[i].server_ip, server_ip) == 0) {
            for (int j = i; j < connection_count - 1; j++) {
                connections[j] = connections[j + 1];
            }
