typedef struct {
    UEContext *contexts[MAX_UE_CONTEXTS];
    int size;
    pthread_mutex_t lock;
} UEContextList;

void init_ue_context_list(UEContextList *list) {
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_ue_context(UEContextList *list, const char *imsi, NAS_MESSAGE nas_message) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    UEContext *new_context = malloc(sizeof(UEContext));
    if (!new_context) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    strncpy(new_context->imsi, imsi, sizeof(new_context->imsi) - 1);
    new_context->nas_message = nas_message;
    list->contexts[list->size++] = new_context;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

UEContext* find_ue_context_by_imsi(UEContextList *list, const char *imsi) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        if (strcmp(list->contexts[i]->imsi, imsi) == 0) {
            UEContext *result = list->contexts[i];
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void free_ue_context_list(UEContextList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        free(list->contexts[i]);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
