#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ALLOCATIONS 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t allocated_count;
    size_t max_allocations;
    pthread_mutex_t lock;
} AllocationPool;

AllocationPool* create_allocation_pool(size_t max_allocations, unsigned int seed) {
    AllocationPool *pool = (AllocationPool*)malloc(sizeof(AllocationPool));
    if (!pool) return NULL;

    pool->max_allocations = max_allocations;
    pool->allocated_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_allocations, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    srand(seed ? seed : time(NULL));

    for (size_t i = 0; i < max_allocations; ++i) {
        pool->pool[i].ue_info = generate_rx_ue_information_tag();
        pool->pool[i].rnti = generate_rnti();
        pool->pool[i].crc_indication.tag = CRC_INDICATION_REL8_TAG;
        pool->pool[i].crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    return pool;
}

void destroy_allocation_pool(AllocationPool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->pool);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(AllocationPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_count >= pool->max_allocations) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pool[pool->allocated_count++];
    pthread_mutex_unlock(&pool->lock);

    return pdu;
}

void deallocate_to_pool(AllocationPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->allocated_count; ++i) {
        if (&pool->pool[i] == pdu) {
            --pool->allocated_count;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Example usage
int main() {
    AllocationPool *pool = create_allocation_pool(MAX_ALLOCATIONS, 42);
    if (!pool) {
        fprintf(stderr, "Failed to create allocation pool\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(pool);
    if (pdu) {
        // Use the allocated PDU
        deallocate_to_pool(pool, pdu);
    } else {
        fprintf(stderr, "Failed to allocate from pool\n");
    }

    destroy_allocation_pool(pool);
    return EXIT_SUCCESS;
}
```

