void* retrieve_tags(void* arg) {
    // Simulate data retrieval from an external source
    sleep(1); // Delay to simulate network latency or processing time

    NFAPI_CRC_INDICATION_PDU_T new_struct;
    new_struct.RX_UE_INFORMATION_TAG = rand() % 100; // Example tag value
    new_struct.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_lock(&mutex);
    if (structure_count < MAX_STRUCTURES) {
        int rnti;
        do {
            rnti = rand() % 1000; // Example RNTI range
        } while (find_rnti(rnti)); // Function to check if RNTI is already used

        new_struct.RNTI = rnti;
        structures[structure_count++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *structures[structure_count - 1] = new_struct;
    } else {
        printf("Error: Maximum number of structures reached.\n");
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int find_rnti(int rnti) {
    for (int i = 0; i < structure_count; i++) {
        if (structures[i]->RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

void free_structures() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < structure_count; i++) {
        free(structures[i]);
    }
    structure_count = 0;
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_STRUCTURES];
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pthread_create(&threads[i], NULL, retrieve_tags, NULL) != 0) {
            printf("Error creating thread %d\n", i);
            break;
        }
    }

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_join(threads[i], NULL);
    }

    free_structures();

    return 0;
}
