```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPIS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_list[MAX_NFAPIS];
int nfapi_count = 0;
pthread_mutex_t nfapi_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % MAX_NFAPIS; // Ensure unique RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand();
    pdu->CRCFLAG = rand() % 2;
}

int add_crc_indication_to_list() {
    pthread_mutex_lock(&nfapi_mutex);
    if (nfapi_count >= MAX_NFAPIS) {
        pthread_mutex_unlock(&nfapi_mutex);
        return -1; // Error: List is full
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&nfapi_mutex);
        return -2; // Error: Memory allocation failed
    }
    generate_random_crc_indication(new_pdu);
    nfapi_list[nfapi_count++] = new_pdu;
    pthread_mutex_unlock(&nfapi_mutex);
    return 0; // Success
}

void free_crc_indication_list() {
    pthread_mutex_lock(&nfapi_mutex);
    for (int i = 0; i < nfapi_count; i++) {
        free(nfapi_list[i]);
    }
    nfapi_count = 0;
    pthread_mutex_unlock(&nfapi_mutex);
}
