### JavaScript Program Code

```javascript
const MAX_SCRIPTS = 100;

let scriptCache = {};
let scriptQueue = [];
let executingScripts = new Set();

function loadScript(url, callback) {
    if (scriptCache[url]) {
        callback(null, scriptCache[url]);
        return;
    }

    const script = document.createElement('script');
    script.src = url;
    script.onload = () => {
        scriptCache[url] = true;
        callback(null, script);
    };
    script.onerror = (error) => {
        callback(error, null);
    };

    document.head.appendChild(script);
}

function executeScripts() {
    while (scriptQueue.length > 0 && executingScripts.size < MAX_SCRIPTS) {
        const url = scriptQueue.shift();
        if (!executingScripts.has(url)) {
            executingScripts.add(url);
            loadScript(url, (error, script) => {
                if (error) {
                    console.error(`Failed to load script: ${url}`, error);
                } else {
                    console.log(`Executed script: ${url}`);
                }
                executingScripts.delete(url);
                executeScripts();
            });
        }
    }
}

function addScriptToQueue(url) {
    if (!scriptQueue.includes(url)) {
        scriptQueue.push(url);
        executeScripts();
    }
}

// Example usage
addScriptToQueue('https://example.com/script1.js');
addScriptToQueue('https://example.com/script2.js');
```

### Explanation

- **C Function**: This function manages a list of `NFAPI_CRC_INDICATION_PDU_T` structures. It ensures that each structure has unique RNTI values, uses mutexes for thread safety, and provides functions to add new structures and free the entire list.

- **JavaScript Program**: This program dynamically loads and executes JavaScript files from URLs. It uses a queue to manage script execution order, caches loaded scripts to avoid redundant requests, and handles errors gracefully. The `executeScripts` function ensures that no more than `MAX_SCRIPTS` are executing at once.

Both components work together to provide efficient data management in C and dynamic web interactions in JavaScript, with considerations for performance, scalability, and error handling."]

