#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    int error_flag;
} NFAPI_CRC_COLLECTION_T;

size_t custom_hash_function(uint16_t RNTI, size_t capacity) {
    return (RNTI * 31) % capacity;
}

NFAPI_CRC_COLLECTION_T* create_collection() {
    NFAPI_CRC_COLLECTION_T *collection = malloc(sizeof(NFAPI_CRC_COLLECTION_T));
    if (!collection) {
        return NULL; // Memory allocation failed
    }
    collection->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->data) {
        free(collection);
        return NULL; // Memory allocation failed
    }
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    collection->error_flag = 0;
    return collection;
}

void destroy_collection(NFAPI_CRC_COLLECTION_T *collection) {
    if (collection->data) {
        free(collection->data);
    }
    free(collection);
}

int add_entry(NFAPI_CRC_COLLECTION_T *collection, NFAPI_CRC_INDICATION_PDU_T entry) {
