#define MAX_NFAPI_PDUS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t blockSize;
    size_t poolSize;
    void* blocks;
    int freeIndices[MAX_NFAPI_PDUS];
    int freeCount;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t poolSize) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->poolSize = poolSize;
    pool->blocks = malloc(blockSize * poolSize);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    for (int i = 0; i < poolSize; i++) {
        pool->freeIndices[i] = i;
    }
    pool->freeCount = poolSize;

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocateBlock(MemoryPool* pool) {
    if (pthread_mutex_lock(&pool->lock) != 0) {
        fprintf(stderr, "Failed to lock memory pool\n");
        return NULL;
    }

    if (pool->freeCount == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    int index = pool->freeIndices[--pool->freeCount];
    void* block = (char*)pool->blocks + index * pool->blockSize;

    pthread_mutex_unlock(&pool->lock);

    return block;
}

void freeBlock(MemoryPool* pool, void* block) {
    if (!block) return;

    size_t index = ((char*)block - (char*)pool->blocks) / pool->blockSize;

    if (pthread_mutex_lock(&pool->lock) != 0) {
        fprintf(stderr, "Failed to lock memory pool\n");
        return;
    }

    if (index < 0 || index >= pool->poolSize) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Invalid block index\n");
        return;
    }

    pool->freeIndices[pool->freeCount++] = index;

    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* createPdu(MemoryPool* pool) {
    if (!pool) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocateBlock(pool);
    if (!pdu) {
        fprintf(stderr, "Failed to allocate PDU\n");
        return NULL;
    }

    // Initialize PDU fields
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    pdu->RNTI = rand() % 1000; // Example initialization
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    return pdu;
}

void destroyPdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    freeBlock(pool, pdu);
}
