#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfaapi_crc_indication_pdu(int N, int cache_line_size, int num_threads) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(cache_line_size, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_t* threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        perror("Thread allocation failed");
        free(pdu_list);
        aligned_free(pdu_list);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_threads; ++i) {
        int start = i * N / num_threads;
        int end = (i + 1) * N / num_threads;
        if (pthread_create(&threads[i], NULL, fill_pdu_list, (void*)(start, end, pdu_list, &mutex)) != 0) {
            perror("Thread creation failed");
            for (int j = 0; j < i; ++j) {
                pthread_join(threads[j], NULL);
            }
            free(threads);
            aligned_free(pdu_list);
            return NULL;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    return pdu_list;
}

void* fill_pdu_list(void* arg) {
    int start, end;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    pthread_mutex_t* mutex;

    if (sscanf(arg, "%d,%d,%p,%p", &start, &end, (void**)&pdu_list, (void**)&mutex) != 4) {
        fprintf(stderr, "Invalid argument format\n");
        return NULL;
    }

    for (int i = start; i < end; ++i) {
        pthread_mutex_lock(mutex);
        pdu_list[i].RX_UE_INFORMATION_TAG = i;
        pdu_list[i].RNTI = rand() % 1024;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        pthread_mutex_unlock(mutex);
    }

    return NULL;
}
