};

class NfadynValGen {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mutex mtx;
    std::random_device rd;
    std::mt19937 gen;
    int rangeMin, rangeMax;

public:
    NfadynValGen(int min, int max) : rangeMin(min), rangeMax(max), gen(rd()) {}

    void setRange(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);
        rangeMin = min;
        rangeMax = max;
    }

    NFAPI_CRC_INDICATION_PDU_T generatePdu() {
        std::lock_guard<std::mutex> lock(mtx);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = gen() % (rangeMax - rangeMin + 1) + rangeMin;
        pdu.RNTI = gen() % (rangeMax - rangeMin + 1) + rangeMin;
        pdu.CRC_INDICATION_REL8_TAG = static_cast<float>(gen()) / gen.max();
        return pdu;
    }

    void addPdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push_back(pdu);
    }

    template<typename Func>
    auto executeAsync(Func&& func) -> std::future<decltype(func())> {
        return std::async(std::launch::async, std::forward<Func>(func));
    }

    void logException(const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mtx);
        return "Range: [" + std::to_string(rangeMin) + ", " + std::to_string(rangeMax) + "]";
