#define TABLE_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    int size;
} HashTable;

HashTable* createHashTable() {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->table = (Node**)calloc(TABLE_SIZE, sizeof(Node*));
    ht->size = TABLE_SIZE;
    return ht;
}

unsigned int hashFunction(int RNTI) {
    return RNTI % TABLE_SIZE;
}

void insertElement(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hashFunction(data.RNTI);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = ht->table[index];
    ht->table[index] = newNode;
}

void removeElement(HashTable* ht, int RNTI) {
    unsigned int index = hashFunction(RNTI);
    Node* current = ht->table[index];
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                ht->table[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void clearHashTable(HashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* current = ht->table[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    memset(ht->table, 0, TABLE_SIZE * sizeof(Node*));
}

int main() {
    HashTable* ht = createHashTable();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 2, 3, rand()};
    insertElement(ht, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {4, 5, 6, rand()};
    insertElement(ht, pdu2);

    removeElement(ht, 2);

    clearHashTable(ht);

    free(ht->table);
    free(ht);

    return 0;
}
```

This code provides a basic implementation of a hash table for managing `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions for creating the hash table, inserting elements, removing elements by RNTI, and clearing the entire table. The hash function uses the modulo operation to distribute elements across the table, and collision resolution is handled through chaining.']

