typedef struct {
    NFAPI_CRC_INDICATION_PDU_T elements[MAX_ELEMENTS];
    int size;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

int addElement(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->elements[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int removeElement(DynamicArray *array, int index) {
    pthread_mutex_lock(&array->mutex);
    if (index < 0 || index >= array->size) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Invalid index
    }
    for (int i = index; i < array->size - 1; i++) {
        array->elements[i] = array->elements[i + 1];
    }
    array->size--;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void clearDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}

