    initDynamicArray(&array);

    NFAPI_CRC_INDICATION_PDU_T element1 = {1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T element2 = {4, 5, 6};

    addElement(&array, element1);
    addElement(&array, element2);

    removeElement(&array, 0);

