    int cache_index;
    pthread_mutex_t cache_lock;
} CacheManager;

CacheManager cache_manager = {0};

void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache_manager.cache[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!cache_manager.cache[i]) {
            // Handle memory allocation failure
        }
    }
    pthread_mutex_init(&cache_manager.cache_lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_cached_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&cache_manager.cache_lock);
    if (cache_manager.cache_index > 0) {
        pdu = cache_manager.cache[--cache_manager.cache_index];
    }
    pthread_mutex_unlock(&cache_manager.cache_lock);
    return pdu;
}

void release_cached_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cache_manager.cache_lock);
    if (cache_manager.cache_index < CACHE_SIZE) {
        cache_manager.cache[cache_manager.cache_index++] = pdu;
    }
    pthread_mutex_unlock(&cache_manager.cache_lock);
}

