        populate_pdu(batch[i], RX_UE_INFORMATION_TAG, RNTI);
        // Process the PDU
        destroy_pdu(batch[i]);
    }
}

void* batch_processor(void *arg) {
    int *batch_size_ptr = (int*)arg;
    int batch_size = *batch_size_ptr;
    NFAPI_CRC_INDICATION_PDU_T *batch[MAX_BATCH_SIZE];

    for (int i = 0; i < batch_size; i++) {
        batch[i] = create_pdu();
    }

    process_batch(batch, batch_size);

    free(batch_size_ptr);
    return NULL;
}

void submit_batch(int batch_size) {
    int *batch_size_ptr = malloc(sizeof(int));
    if (!batch_size_ptr) {
        // Handle memory allocation failure
    }
    *batch_size_ptr = batch_size;

    pthread_t thread;
    if (pthread_create(&thread, NULL, batch_processor, batch_size_ptr)) {
        // Handle thread creation failure
    }
}

void cleanup_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        free(cache_manager.cache[i]);
    }
