    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return array;
}

long* create_offsets_array(int num_offsets, long min_offset, long max_offset) {
    if (min_offset > max_offset) return NULL;

    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
    }

    return offsets;
}

int* create_keys_array(int num_keys) {
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000;
    }

    return keys;
}

record* create_records_array(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }

    return records;
}

void free_all_memory(NFAPI_CRC_INDICATION_PDU_T* array, long* offsets, int* keys, record* records) {
    free(array);
    free(offsets);
    free(keys);
    free(records);
}
