['```javascript
function renderFooterScripts(scripts, isProduction, environment) {
    if (!Array.isArray(scripts)) {
        console.warn('Invalid input: scripts should be an array');
        return '';
    }

    let html = '';

    for (const script of scripts) {
        if (typeof script !== 'object' || script === null) {
            console.warn('Skipping invalid script object');
            continue;
        }

        const { key, value, id } = script;

        if (typeof key !== 'string' || typeof value !== 'string') {
            console.warn('Skipping script with missing or invalid key/value');
            continue;
        }

        let attributes = `src="${key}"`;

        if (!isProduction) {
            attributes += ' async';
        } else if (environment === "development") {
            attributes += ' defer';
        }

        if (id && typeof id === 'string') {
            attributes += ` id="${id}"`;
        }

        html += `<script ${attributes}></script>`;
    }

    return html;
}
