#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 10000
#define INITIAL_CAPACITY 10

typedef struct {
    int ue_id;
    int cell_id;
    int priority;
    int rx_tag;
    int rnti;
} UEContext;

typedef struct {
    UEContext *ue_contexts;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} UELockFreeList;

UELockFreeList* create_uelist() {
    UELockFreeList *list = (UELockFreeList*)malloc(sizeof(UELockFreeList));
    if (!list) return NULL;
    list->ue_contexts = (UEContext*)calloc(INITIAL_CAPACITY, sizeof(UEContext));
    if (!list->ue_contexts) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_uelist(UELockFreeList *list) {
    if (list) {
        free(list->ue_contexts);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_ue_context(UELockFreeList *list, UEContext *ue_context) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        UEContext *new_ues = (UEContext*)realloc(list->ue_contexts, new_capacity * sizeof(UEContext));
        if (!new_ues) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failure
        }
        list->ue_contexts = new_ues;
        list->capacity = new_capacity;
    }
    list->ue_contexts[list->size++] = *ue_context;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_ue_context(UELockFreeList *list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; ++i) {
        if (list->ue_contexts[i].rnti == rnti) {
            for (int j = i; j < list->size - 1; ++j) {
                list->ue_contexts[j] = list->ue_contexts[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // UE context not found
}

void iterate_ue_contexts(UELockFreeList *list, void (*callback)(UEContext*)) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; ++i) {
        callback(list->ue_contexts[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

// Custom hash function for RNTI
unsigned int rnti_hash(int rnti) {
    return rnti % MAX_UE_CONTEXTS;
}

// Function to fetch real-time cell status updates from external API
int fetch_cell_status(int cell_id, char *status) {
    // Simulate API call with a delay
    sleep(1);
    snprintf(status, 256, "Cell %d is active", cell_id);
    return 0;
}

// Function to persistently store UE context data in NoSQL database
int store_ue_context(UEContext *ue_context) {
    // Simulate database write with a delay
    sleep(1);
    printf("Stored UE Context: RNTI %d\n", ue_context->rnti);
    return 0;
}

// Example callback function for iterating over UE contexts
void print_ue_context(UEContext ue_context) {
    printf("UE ID: %d, Cell ID: %d, Priority: %d, RX Tag: %d, RNTI: %d\n",
           ue_context.ue_id, ue_context.cell_id, ue_context.priority,
           ue_context.rx_tag, ue_context.rnti);
}

int main() {
    UELockFreeList *list = create_uelist();
    if (!list) return 1;

    UEContext new_ue = {1, 101, 5, 12345, 6789};
    add_ue_context(list, &new_ue);

    iterate_ue_contexts(list, print_ue_context);

    remove_ue_context(list, 6789);

    destroy_uelist(list);
    return 0;
}
