#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NL_DU {
    int mac_entity_id;
    int sequence_number;
    int payload_length;
    char* payload;
} NL_DU;

typedef struct LinkedList {
    NL_DU* data;
    size_t size;
    size_t capacity;
} LinkedList;

void initLinkedList(LinkedList* list, size_t initial_capacity) {
    list->data = (NL_DU*)malloc(initial_capacity * sizeof(NL_DU));
    if (list->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
}

void freeLinkedList(LinkedList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->data[i].payload);
    }
    free(list->data);
}

void addNL_DU(LinkedList* list, int mac_entity_id, int sequence_number, int payload_length) {
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NL_DU* new_data = (NL_DU*)realloc(list->data, new_capacity * sizeof(NL_DU));
        if (new_data == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    NL_DU* nl_du = &list->data[list->size++];
    nl_du->mac_entity_id = mac_entity_id;
    nl_du->sequence_number = sequence_number;
    nl_du->payload_length = payload_length;
    nl_du->payload = (char*)malloc(payload_length);
    if (nl_du->payload == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Populate payload with random data
    for (int i = 0; i < payload_length; ++i) {
        nl_du->payload[i] = rand() % 256;
    }
}

void updateNL_DU(LinkedList* list, size_t index, int mac_entity_id, int sequence_number, int payload_length) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    NL_DU* nl_du = &list->data[index];
    free(nl_du->payload);
    nl_du->mac_entity_id = mac_entity_id;
    nl_du->sequence_number = sequence_number;
    nl_du->payload_length = payload_length;
    nl_du->payload = (char*)realloc(nl_du->payload, payload_length);
    if (nl_du->payload == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Populate payload with random data
    for (int i = 0; i < payload_length; ++i) {
        nl_du->payload[i] = rand() % 256;
    }
}

void deleteNL_DU(LinkedList* list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    free(list->data[index].payload);
    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;
}

void printLinkedList(LinkedList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        printf("NL_DU %zu: MAC-Entity-ID=%d, Sequence Number=%d, Payload Length=%d\n",
               i, list->data[i].mac_entity_id, list->data[i].sequence_number, list->data[i].payload_length);
    }
}

int main() {
    srand(time(NULL));
    LinkedList list;
    initLinkedList(&list, 10);

    addNL_DU(&list, 1, 100, 256);
    addNL_DU(&list, 2, 200, 512);
    updateNL_DU(&list, 0, 3, 300, 768);
    deleteNL_DU(&list, 1);

    printLinkedList(&list);

    freeLinkedList(&list);
    return 0;
}
